window.SPARK_QUESTION_BANK = {"title": "Spark合格演習室", "created": "2026-09-19", "version": "2.1", "updated": "2026-10-17", "assumptions": "PySpark 3.5.x; ANSI=false; UTC; required imports available unless stated", "exams": [{"id": "M1", "title": "本番形式模試 1", "questions": [{"id": "M1-01", "domain": "DataFrame", "topic": "schema-type-inspection", "objective": "DataFrameの型情報を取得する", "difficulty": "basic", "stem": "An engineer wants to inspect the declared type of the quantity column without collecting any data rows. Which expression accesses the DataType object from the DataFrame schema?", "options": ["df.schema()[\"quantity\"]", "df.collect()[0][\"quantity\"].dataType", "df.schema[\"quantity\"].dataType", "df.columns[\"quantity\"]"], "correct": 2, "explanation_ja": "DataFrame.schemaはStructTypeを返すプロパティであり、列名でStructFieldを選び、そのdataTypeから型を確認できる。行データをdriverへcollectする必要はない。columnsは列名のリストで型情報を含まず、schemaにはメソッド呼び出しの括弧を付けない点にも注意する。", "distractors_ja": ["schemaは呼び出すメソッドではなくプロパティである。", "collectで取得した値は通常Python値であり型定義のStructFieldではない。", "正答", "columnsは列名のリストで、文字列キーで型を取得できない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.schema.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C042", "exam": 1, "concept": "schema-types", "concept_label": "スキーマ・型の確認", "misconception_tags": ["確認ポイント：schemaは呼び出すメソッドではなくプロパティである。", "確認ポイント：collectで取得した値は通常Python値であり型定義のStructFieldではない。", "", "確認ポイント：columnsは列名のリストで、文字列キーで型を取得できない。"], "suggested_causes": ["api", "knowledge", "unknown", "api"], "stem_ja": "エンジニアは、データ行を収集せずに quantity 列に宣言されている型を確認したいと考えています。DataFrame のスキーマから DataType オブジェクトを取得する式はどれですか。", "options_ja": ["df.schema()[\"quantity\"]", "df.collect()[0][\"quantity\"].dataType", "df.schema[\"quantity\"].dataType", "df.columns[\"quantity\"]"]}, {"id": "M1-02", "domain": "Architecture", "topic": "Shuffle dependency", "objective": "shuffleとstage境界を理解する", "difficulty": "applied", "stem": "A job must bring records with the same aggregation key together from several upstream partitions. Which description best explains the resulting shuffle dependency?", "options": ["The driver must perform the entire aggregation in a Python loop", "Downstream processing depends on redistributed output from multiple upstream partitions", "Every downstream partition can always use only one unchanged upstream partition", "Spark must permanently overwrite the source files before aggregation"], "correct": 1, "explanation_ja": "複数パーティションに分散した同一キーを集める処理では、再分配された上流出力への依存が発生します。これがshuffleの基本です。shuffle境界はstageを考える手掛かりですが、ソースコード中のメソッド数だけで最終stage数を固定することはできません。", "distractors_ja": ["分散集約はdriverの全件Pythonループを必要としません。", "正答", "キーが上流に分散しているという条件と矛盾します。", "元ファイルの恒久的な上書きは不要です。"], "source_url": "https://spark.apache.org/docs/3.5.6/rdd-programming-guide.html", "validation": "公式資料照合・未実行", "author_id": "A025", "exam": 1, "concept": "shuffle-partitions", "concept_label": "shuffle・パーティション・スキュー", "misconception_tags": ["確認ポイント：分散集約はdriverの全件Pythonループを必要としません。", "", "確認ポイント：キーが上流に分散しているという条件と矛盾します。", "確認ポイント：元ファイルの恒久的な上書きは不要です。"], "suggested_causes": ["boundary", "unknown", "knowledge", "knowledge"], "stem_ja": "あるジョブでは、複数の上流パーティションから、同じ集約キーを持つレコードを集める必要があります。この処理によって生じるシャッフル依存関係を最も適切に説明しているものはどれですか。", "options_ja": ["ドライバーが Python のループで集約全体を実行する必要がある", "下流の処理は、複数の上流パーティションから再分配された出力に依存する", "どの下流パーティションも、常に変更されていない 1 つの上流パーティションだけを使用できる", "Spark は集約の前にソースファイルを恒久的に上書きする必要がある"]}, {"id": "M1-03", "domain": "Architecture", "topic": "Structured data module", "objective": "Spark SQLの役割を識別する", "difficulty": "basic", "stem": "A service needs schema-aware filtering, joins, and aggregations over Parquet data using either SQL text or Python column expressions. Which Spark module provides the central processing abstraction for this workload?", "options": ["MLlib model selection", "The Spark History Server", "The standalone cluster manager", "Spark SQL and DataFrames"], "correct": 3, "explanation_ja": "スキーマを持つ構造化データへのSQL・列式による処理はSpark SQLとDataFrameの中心的な用途です。入力の列構造や演算内容を把握できるため、最適化にも利用できます。資源管理、履歴表示、モデル評価はそれぞれ異なる役割であり、問いの処理APIではありません。", "distractors_ja": ["MLlibは機械学習のためのライブラリ。", "History Serverは実行履歴の閲覧に使う。", "cluster managerは資源割当を担い、SQLの表操作APIではない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-getting-started.html", "validation": "公式資料照合・未実行", "author_id": "A021", "exam": 1, "concept": "query-plans", "concept_label": "SQLエンジン・実行計画・AQE", "misconception_tags": ["確認ポイント：MLlibは機械学習のためのライブラリ。", "確認ポイント：History Serverは実行履歴の閲覧に使う。", "確認ポイント：cluster managerは資源割当を担い、SQLの表操作APIではない。", ""], "suggested_causes": ["knowledge", "knowledge", "api", "unknown"], "stem_ja": "あるサービスでは、SQL 文または Python の列式を使って、Parquet データに対してスキーマを考慮したフィルタリング、結合、集約を行う必要があります。このワークロードの中心となる処理の抽象化を提供する Spark モジュールはどれですか。", "options_ja": ["MLlib のモデル選択", "Spark History Server", "スタンドアロンのクラスター管理システム", "Spark SQL と DataFrame"]}, {"id": "M1-04", "domain": "Spark SQL", "topic": "グローバル一時ビュー", "objective": "別セッションからグローバルビューを参照する", "difficulty": "applied", "stem": "In an application using the default global temporary database, df.createGlobalTempView(\"live_inventory\") has completed. A second SparkSession in the same application must query the view. Which SQL reference should it use?", "options": ["SELECT * FROM temp.live_inventory", "SELECT * FROM global_temp.live_inventory", "SELECT * FROM default.live_inventory", "SELECT * FROM df.live_inventory"], "correct": 1, "explanation_ja": "既定のグローバル一時ビュー用データベースはglobal_tempである。同一アプリケーション内の別セッションからも、global_temp.live_inventoryと完全修飾して参照する。永続テーブルと異なり、寿命はアプリケーションに結び付く。", "distractors_ja": ["既定の予約データベース名はtempではない。", "正答", "defaultデータベースにこのビューが登録されるわけではない。", "Python変数名dfはデータベース名ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.createGlobalTempView.html", "validation": "公式資料照合・未実行", "author_id": "B018", "exam": 1, "concept": "sessions-views", "concept_label": "セッション・ビューの共有範囲", "misconception_tags": ["確認ポイント：既定の予約データベース名はtempではない。", "", "確認ポイント：defaultデータベースにこのビューが登録されるわけではない。", "確認ポイント：Python変数名dfはデータベース名ではない。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "既定のグローバル一時データベースを使用するアプリケーションで、df.createGlobalTempView(\"live_inventory\") の実行が完了しました。同じアプリケーション内の別の SparkSession から、このビューにクエリを実行する必要があります。どの SQL 参照を使用すべきですか。", "options_ja": ["SELECT * FROM temp.live_inventory", "SELECT * FROM global_temp.live_inventory", "SELECT * FROM default.live_inventory", "SELECT * FROM df.live_inventory"]}, {"id": "M1-05", "domain": "DataFrame", "topic": "projection-and-alias", "objective": "列の選択・計算・別名を組み合わせる", "difficulty": "basic", "stem": "A shipment DataFrame has columns parcel_id, grams, and warehouse. A downstream consumer requires exactly parcel_id and kilograms, where kilograms = grams / 1000.0. Which expression produces the required DataFrame?", "options": ["shipments.select(\"parcel_id\", \"grams / 1000.0 AS kilograms\")", "shipments.select(\"parcel_id\", (F.col(\"grams\") / 1000.0).alias(\"kilograms\"))", "shipments.drop(\"warehouse\").withColumn(\"kilograms\", F.col(\"grams\") / 1000.0)", "shipments.withColumnRenamed(\"grams\", \"kilograms\")"], "correct": 1, "explanation_ja": "selectは出力する列と列式を明示できる。gramsを1000.0で割った列式にaliasを付ければ、指定された2列だけが得られる。単なる改名では単位が変わらず、withColumnで追加するだけでは元のgramsも残る。selectに渡す文字列は通常、SQL式ではなく列名として扱われる。", "distractors_ja": ["selectの文字列は列名として解決される。SQL式ならselectExprを使う。", "正答", "gramsが残るため出力列が3列になる。", "名前だけが変わり、重量の換算も不要列の除去も行われない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.select.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C001", "exam": 1, "concept": "column-expressions", "concept_label": "列式・射影・列名操作", "misconception_tags": ["確認ポイント：selectの文字列は列名として解決される。SQL式ならselectExprを使う。", "", "確認ポイント：gramsが残るため出力列が3列になる。", "確認ポイント：名前だけが変わり、重量の換算も不要列の除去も行われない。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "配送の DataFrame には parcel_id、grams、warehouse の各列があります。後続の利用側では parcel_id と kilograms の 2 列だけが必要で、kilograms = grams / 1000.0 とします。必要な DataFrame を生成する式はどれですか。", "options_ja": ["shipments.select(\"parcel_id\", \"grams / 1000.0 AS kilograms\")", "shipments.select(\"parcel_id\", (F.col(\"grams\") / 1000.0).alias(\"kilograms\"))", "shipments.drop(\"warehouse\").withColumn(\"kilograms\", F.col(\"grams\") / 1000.0)", "shipments.withColumnRenamed(\"grams\", \"kilograms\")"]}, {"id": "M1-06", "domain": "DataFrame", "topic": "explode-cardinality", "objective": "配列展開後の行数を予測する", "difficulty": "applied", "stem": "df has (id, tags) rows (1, [\"a\", \"b\"]), (2, []), and (3, NULL). tags is array<string>. How many rows are produced by df.select(\"id\", F.explode(\"tags\"))?", "options": ["2", "3", "1", "4"], "correct": 0, "explanation_ja": "explodeは配列の要素ごとに1行を作る。最初の配列は2要素なので2行になり、空配列とNULL配列はこの関数では行を生成しない。親のidを常に少なくとも1行残したい要件ならexplode_outerを検討する。入力レコード数と展開後の件数は一致するとは限らない。", "distractors_ja": ["正答", "空配列またはNULL配列を1行として数えている。", "最初の配列の2要素がそれぞれ行になる。", "これはexplode_outerで各親を保持した場合の件数である。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.explode.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C028", "exam": 1, "concept": "nested-data", "concept_label": "配列・構造体・展開", "misconception_tags": ["", "確認ポイント：空配列またはNULL配列を1行として数えている。", "確認ポイント：最初の配列の2要素がそれぞれ行になる。", "確認ポイント：これはexplode_outerで各親を保持した場合の件数である。"], "suggested_causes": ["unknown", "boundary", "knowledge", "knowledge"], "stem_ja": "df には (id, tags) の行として (1, [\"a\", \"b\"])、(2, [])、(3, NULL) があります。tags の型は array<string> です。df.select(\"id\", F.explode(\"tags\")) は何行を生成しますか。", "options_ja": ["2", "3", "1", "4"]}, {"id": "M1-07", "domain": "DataFrame", "topic": "substring-index", "objective": "文字列関数の位置と長さを理解する", "difficulty": "basic", "stem": "For a string column code containing \"ZX3149\", what value does F.substring(\"code\", 3, 2) produce?", "options": ["\"31\"", "\"X3\"", "\"14\"", "\"314\""], "correct": 0, "explanation_ja": "substringの開始位置は1から数え、第3引数は終了位置ではなく長さである。ZX3149の3文字目は3で、そこから2文字を取るので31となる。Pythonの0始まりのスライスとは引数の意味が異なる。位置と長さをそれぞれ確認すると1文字ずれを避けられる。", "distractors_ja": ["正答", "開始位置3ではなく2から抽出している。", "0始まりの位置と混同している。", "指定されている長さは2文字である。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.substring.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C026", "exam": 1, "concept": "string-date-functions", "concept_label": "文字列・日付関数", "misconception_tags": ["", "確認ポイント：開始位置3ではなく2から抽出している。", "確認ポイント：0始まりの位置と混同している。", "確認ポイント：指定されている長さは2文字である。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "文字列列 code に \"ZX3149\" が格納されているとき、F.substring(\"code\", 3, 2) はどの値を生成しますか。", "options_ja": ["\"31\"", "\"X3\"", "\"14\"", "\"314\""]}, {"id": "M1-08", "domain": "Spark SQL", "topic": "パーティション発見とbasePath", "objective": "部分パスからパーティション列を復元する", "difficulty": "challenging", "stem": "A Parquet dataset has directories /warehouse/events/day=2026-08-01/ and day=2026-08-02/. The data files do not store day as a physical column. Which read of only the first day also discovers day as a partition column?", "options": ["spark.read.option(\"partitionBy\", \"day\").parquet(\"/warehouse/events/day=2026-08-01\")", "spark.read.option(\"basePath\", \"/warehouse/events\").parquet(\"/warehouse/events/day=2026-08-01\")", "spark.read.option(\"inferSchema\", False).parquet(\"/warehouse/events/day=2026-08-01\")", "spark.read.option(\"header\", True).parquet(\"/warehouse/events/day=2026-08-01\")"], "correct": 1, "explanation_ja": "パーティション列の発見にはディレクトリ階層を使う。末端ディレクトリだけを入力パスにする場合、basePathでデータセットのルートを指定すると、その下のday=...をパーティション列として解釈できる。", "distractors_ja": ["partitionByというReaderオプションではルートを指定できない。", "正答", "inferSchemaの指定ではパーティション探索の起点は変わらない。", "headerはディレクトリ階層の解析を変更しない。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-data-sources-parquet.html#partition-discovery", "validation": "公式資料照合・未実行", "author_id": "B007", "exam": 1, "concept": "file-read-schema", "concept_label": "ファイル読込・スキーマ・形式", "misconception_tags": ["確認ポイント：partitionByというReaderオプションではルートを指定できない。", "", "確認ポイント：inferSchemaの指定ではパーティション探索の起点は変わらない。", "確認ポイント：headerはディレクトリ階層の解析を変更しない。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "Parquet データセットには /warehouse/events/day=2026-08-01/ と day=2026-08-02/ のディレクトリがあります。データファイルには day が物理的な列として保存されていません。最初の日だけを読み込み、同時に day をパーティション列として検出する読み込み方法はどれですか。", "options_ja": ["spark.read.option(\"partitionBy\", \"day\").parquet(\"/warehouse/events/day=2026-08-01\")", "spark.read.option(\"basePath\", \"/warehouse/events\").parquet(\"/warehouse/events/day=2026-08-01\")", "spark.read.option(\"inferSchema\", False).parquet(\"/warehouse/events/day=2026-08-01\")", "spark.read.option(\"header\", True).parquet(\"/warehouse/events/day=2026-08-01\")"]}, {"id": "M1-09", "domain": "Spark SQL", "topic": "text出力", "objective": "textデータソースの単一文字列列制約を満たす", "difficulty": "applied", "stem": "DataFrame df has columns code STRING and amount INT. The target is plain text with one line per row, such as A9:17, and no CSV quoting or header. Which write satisfies the text data source schema requirement?", "options": ["df.write.text(path)", "df.select(\"amount\").write.text(path)", "df.select(concat_ws(\":\", col(\"code\"), col(\"amount\").cast(\"string\")).alias(\"value\")).write.text(path)", "df.write.option(\"header\", True).text(path)"], "correct": 2, "explanation_ja": "textライターへ渡すDataFrameは単一の文字列列である必要がある。必要な行の文字列表現を先に作り、1列にして保存する。この問題ではcodeとamountをコロンで結び、数値も文字列へ変換している。", "distractors_ja": ["2列のDataFrameはtext出力の制約を満たさない。", "単一列でもINTのままでは文字列型の条件を満たさない。", "正答", "headerオプションでは2列を1列に変換できない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameWriter.text.html", "validation": "公式資料照合・未実行", "author_id": "B026", "exam": 1, "concept": "file-write-layout", "concept_label": "保存モード・テーブル・配置", "misconception_tags": ["確認ポイント：2列のDataFrameはtext出力の制約を満たさない。", "確認ポイント：単一列でもINTのままでは文字列型の条件を満たさない。", "", "確認ポイント：headerオプションでは2列を1列に変換できない。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "DataFrame df には code STRING と amount INT の列があります。出力先では、A9:17 のように 1 行のレコードを 1 行のテキストで表し、CSV の引用符やヘッダーを含まないプレーンテキストが必要です。text データソースのスキーマ要件を満たす書き込みはどれですか。", "options_ja": ["df.write.text(path)", "df.select(\"amount\").write.text(path)", "df.select(concat_ws(\":\", col(\"code\"), col(\"amount\").cast(\"string\")).alias(\"value\")).write.text(path)", "df.write.option(\"header\", True).text(path)"]}, {"id": "M1-10", "domain": "Spark Connect", "topic": "Connect CLI", "objective": "Connect接続先のCLI指定を識別する", "difficulty": "applied", "stem": "A Spark Connect server is already listening at localhost with its default Connect port. The matching PySpark client dependencies are installed. Which documented command explicitly opens a Connect shell to that server?", "options": ["./bin/pyspark --connect-enabled localhost", "./bin/pyspark --deploy-mode remote", "./bin/pyspark --remote sc://localhost", "./bin/pyspark --master sc://localhost"], "correct": 2, "explanation_ja": "--remote sc://localhostはSpark Connectサーバーへ接続するPySpark shellの指定です。sc://はConnectの接続文字列として使います。classicの--masterやclient/clusterを指定する--deploy-modeとは用途が異なり、架空のconnect-enabledフラグへ置き換えることはできません。", "distractors_ja": ["そのCLIフラグは文書化されたConnect指定ではありません。", "remoteはclassic deploy modeの選択肢ではありません。", "正答", "Connectへの接続先指定は--remoteです。"], "source_url": "https://spark.apache.org/docs/3.5.6/spark-connect-overview.html", "validation": "公式資料照合・未実行", "author_id": "A045", "exam": 1, "concept": "connect-api", "concept_label": "Spark Connectの接続方法・制約", "misconception_tags": ["確認ポイント：そのCLIフラグは文書化されたConnect指定ではありません。", "確認ポイント：remoteはclassic deploy modeの選択肢ではありません。", "", "確認ポイント：Connectへの接続先指定は--remoteです。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "Spark Connect サーバーは、localhost の既定の Connect ポートですでに待ち受けています。対応する PySpark クライアントの依存ライブラリもインストール済みです。そのサーバーに接続する Connect シェルを明示的に開く、文書化されたコマンドはどれですか。", "options_ja": ["./bin/pyspark --connect-enabled localhost", "./bin/pyspark --deploy-mode remote", "./bin/pyspark --remote sc://localhost", "./bin/pyspark --master sc://localhost"]}, {"id": "M1-11", "domain": "Architecture", "topic": "Session lifecycle", "objective": "classic sessionのstopの影響を理解する", "difficulty": "applied", "stem": "Two classic SparkSessions in one application share the same SparkContext. One component calls s1.stop(). Why is it unsafe to assume that s2 can continue running new Spark jobs normally?", "options": ["Stopping the classic session stops its underlying shared SparkContext", "stop() silently changes s2 into a pandas DataFrame", "Every stopped session is automatically recreated before the next job", "stop() only clears s1's Python variable name"], "correct": 0, "explanation_ja": "classic SparkSessionのstopは基盤のSparkContextを停止します。newSessionなどでそのcontextを共有している場合、別sessionにも影響するため、個別sessionのローカル状態だけを解放すると考えてはいけません。ここではSpark Connectではなくclassicを明示しています。", "distractors_ja": ["正答", "sessionがpandasオブジェクトへ変換されることはありません。", "次のジョブ実行時の自動再作成は保証されません。", "Python変数を消すだけの操作ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.SparkSession.stop.html", "validation": "公式資料照合・未実行", "author_id": "A015", "exam": 1, "concept": "sessions-views", "concept_label": "セッション・ビューの共有範囲", "misconception_tags": ["", "確認ポイント：sessionがpandasオブジェクトへ変換されることはありません。", "確認ポイント：次のジョブ実行時の自動再作成は保証されません。", "確認ポイント：Python変数を消すだけの操作ではありません。"], "suggested_causes": ["unknown", "knowledge", "boundary", "knowledge"], "stem_ja": "1 つのアプリケーション内の 2 つの従来型 SparkSession が、同じ SparkContext を共有しています。あるコンポーネントが s1.stop() を呼び出します。この後も s2 が新しい Spark ジョブを正常に実行し続けられると考えるのが危険なのはなぜですか。", "options_ja": ["従来型セッションを停止すると、その基盤となる共有 SparkContext も停止するため", "stop() が通知せずに s2 を pandas DataFrame に変更するため", "停止したセッションはすべて、次のジョブの前に自動的に再作成されるため", "stop() は s1 の Python 変数名だけを消去するため"]}, {"id": "M1-12", "domain": "DataFrame", "topic": "approx-distinct-contract", "objective": "概算集約の精度契約を理解する", "difficulty": "applied", "stem": "A report uses F.approx_count_distinct(\"visitor_id\", rsd=0.02). Which statement best describes the meaning of this choice?", "options": ["It guarantees that every individual result is within exactly 2% of the true count.", "It estimates distinct values using a requested relative standard deviation; it does not promise an exact count.", "It always returns the exact distinct count because rsd is explicitly set.", "It returns exactly 2% of the true distinct count."], "correct": 1, "explanation_ja": "approx_count_distinctは異なる値の数を推定する集約であり、rsdは相対標準偏差に関する精度パラメータである。0.02を指定しても正確な件数や各回の絶対的な誤差上限を約束するものではない。許容する統計的誤差と計算資源のトレードオフとして理解する。", "distractors_ja": ["標準偏差の指定は全結果に対する厳密な誤差上限ではない。", "正答", "精度パラメータを指定しても概算である。", "2%は結果を縮小する係数ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.approx_count_distinct.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C053", "exam": 1, "concept": "aggregation", "concept_label": "集約・統計・近似値", "misconception_tags": ["確認ポイント：標準偏差の指定は全結果に対する厳密な誤差上限ではない。", "", "確認ポイント：精度パラメータを指定しても概算である。", "確認ポイント：2%は結果を縮小する係数ではない。"], "suggested_causes": ["boundary", "unknown", "knowledge", "knowledge"], "stem_ja": "あるレポートでは F.approx_count_distinct(\"visitor_id\", rsd=0.02) を使用しています。この選択の意味を最も適切に説明している記述はどれですか。", "options_ja": ["個々の結果がすべて、真の件数から厳密に 2% 以内に収まることを保証する。", "指定された相対標準偏差を使って異なる値の数を推定するものであり、正確な件数を保証するものではない。", "rsd が明示的に設定されているため、常に異なる値の正確な件数を返す。", "真の異なる値の件数の、ちょうど 2% に当たる値を返す。"]}, {"id": "M1-13", "domain": "Tuning", "topic": "Python worker memory", "objective": "executor JVM以外のメモリを考慮する", "difficulty": "challenging", "stem": "On YARN, a PySpark executor container is killed for exceeding its memory limit during a Python UDF workload. JVM heap usage is below spark.executor.memory, and spark.executor.pyspark.memory is not configured. Which area should the engineer also investigate?", "options": ["Only the size of shuffle files stored on local disk", "The assumption that all Python allocations are already inside the executor JVM heap", "Python worker and other non-JVM memory covered by executor memory overhead", "Only the value of spark.driver.memory"], "correct": 2, "explanation_ja": "PySparkではPython workerなどJVM heap以外にもメモリを使います。YARNのコンテナ制限に達した場合、JVM heapが上限未満でもmemory overhead側の消費を調べる必要があります。設定を増やす前に、どのプロセスが使っているかとコンテナ全体の使用量を確認します。", "distractors_ja": ["コンテナのメモリ超過という証拠に対し、ディスク上のサイズだけでは消費プロセスが分かりません。", "Python workerのメモリはexecutor JVM heapとは別に消費されます。", "正答", "killされたexecutorコンテナに対し、driverのheap設定だけを調べても原因を特定できません。"], "source_url": "https://spark.apache.org/docs/3.5.6/configuration.html", "validation": "公式資料照合・未実行", "author_id": "A059", "exam": 1, "concept": "memory-diagnostics", "concept_label": "メモリ・GC・診断", "misconception_tags": ["確認ポイント：コンテナのメモリ超過という証拠に対し、ディスク上のサイズだけでは消費プロセスが分かりません。", "確認ポイント：Python workerのメモリはexecutor JVM heapとは別に消費されます。", "", "確認ポイント：killされたexecutorコンテナに対し、driverのheap設定だけを調べても原因を特定できません。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "YARN 上で Python UDF ワークロードを実行しているとき、PySpark のエグゼキューターコンテナがメモリ制限を超えて強制終了しました。JVM ヒープの使用量は spark.executor.memory 未満で、spark.executor.pyspark.memory は設定されていません。エンジニアは、どの領域も調査すべきですか。", "options_ja": ["ローカルディスクに保存されたシャッフルファイルのサイズだけ", "Python のすべてのメモリ割り当てが、すでにエグゼキューターの JVM ヒープ内に含まれているという仮定", "エグゼキューターのメモリオーバーヘッドに含まれる、Python ワーカーなどの JVM 外のメモリ", "spark.driver.memory の値だけ"]}, {"id": "M1-14", "domain": "Pandas API", "topic": "Arrow transfer limits", "objective": "Arrow最適化の限界を理解する", "difficulty": "applied", "stem": "A team enables spark.sql.execution.arrow.pyspark.enabled before calling sdf.toPandas(). Which statement correctly describes this change?", "options": ["Arrow can optimize the transfer, but the resulting pandas DataFrame still must fit in driver memory", "Arrow guarantees that toPandas will never fail for any schema or dataset size", "Arrow removes the need for any compatible pandas and PyArrow libraries", "Arrow makes the returned pandas DataFrame permanently distributed across executors"], "correct": 0, "explanation_ja": "ArrowはSparkとpandas間のデータ転送を効率化できますが、toPandasの戻り値を分散データへ変更する機能ではありません。driverのメモリ制約は残ります。対応する型やライブラリの条件もあるので、最適化設定を有効にしただけで全規模・全スキーマの成功が保証されるわけではありません。", "distractors_ja": ["正答", "メモリや型などの制約は残ります。", "互換性のあるライブラリが必要です。", "結果はローカルpandas DataFrameです。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/user_guide/sql/arrow_pandas.html", "validation": "公式資料照合・未実行", "author_id": "A054", "exam": 1, "concept": "pandas-distributed", "concept_label": "pandas系APIの分散処理と収集", "misconception_tags": ["", "確認ポイント：メモリや型などの制約は残ります。", "確認ポイント：互換性のあるライブラリが必要です。", "確認ポイント：結果はローカルpandas DataFrameです。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "チームは sdf.toPandas() を呼び出す前に spark.sql.execution.arrow.pyspark.enabled を有効にします。この変更について正しく説明している記述はどれですか。", "options_ja": ["Arrow は転送を最適化できるが、結果の pandas DataFrame は引き続きドライバーのメモリに収まる必要がある", "Arrow は、どのようなスキーマやデータセットサイズでも toPandas が決して失敗しないことを保証する", "Arrow により、互換性のある pandas と PyArrow のライブラリが一切不要になる", "Arrow により、返される pandas DataFrame はエグゼキューター間に恒久的に分散される"]}, {"id": "M1-15", "domain": "DataFrame", "topic": "struct-field-update", "objective": "structの一部だけを更新する", "difficulty": "applied", "stem": "The non-null struct profile has fields city, postal_code, and country. Replace city with \"Osaka\" while preserving the other fields and keeping profile as a struct. Which expression is appropriate?", "options": ["df.withColumn(\"profile\", F.col(\"profile\").withField(\"city\", F.lit(\"Osaka\")))", "df.withColumn(\"profile.city\", F.lit(\"Osaka\"))", "df.withColumn(\"profile\", F.lit(\"Osaka\"))", "df.withColumnRenamed(\"profile\", \"city\")"], "correct": 0, "explanation_ja": "Column.withFieldはstruct内の指定フィールドを追加または置換し、ほかのフィールドを維持する。更新済みstructをprofileへ戻すことで出力構造も保てる。withColumnでprofile.cityという名前を直接指定する方法は、ネスト更新の指定ではなくドットを含むトップレベル列名として扱われる。", "distractors_ja": ["正答", "ネストしたcity更新ではなくドットを含むトップレベル列を作る。", "struct全体を文字列に置換し、ほかのフィールドが失われる。", "profileの名前を変えるだけで内部値は更新しない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.Column.withField.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C032", "exam": 1, "concept": "nested-data", "concept_label": "配列・構造体・展開", "misconception_tags": ["", "確認ポイント：ネストしたcity更新ではなくドットを含むトップレベル列を作る。", "確認ポイント：struct全体を文字列に置換し、ほかのフィールドが失われる。", "確認ポイント：profileの名前を変えるだけで内部値は更新しない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "NULL ではない構造体 profile には city、postal_code、country のフィールドがあります。他のフィールドを維持し、profile を構造体のまま保ちながら、city を \"Osaka\" に置き換えます。適切な式はどれですか。", "options_ja": ["df.withColumn(\"profile\", F.col(\"profile\").withField(\"city\", F.lit(\"Osaka\")))", "df.withColumn(\"profile.city\", F.lit(\"Osaka\"))", "df.withColumn(\"profile\", F.lit(\"Osaka\"))", "df.withColumnRenamed(\"profile\", \"city\")"]}, {"id": "M1-16", "domain": "Architecture", "topic": "Unpersist semantics", "objective": "キャッシュ解放の影響を理解する", "difficulty": "basic", "stem": "A DataFrame reports has been cached and fully materialized. The underlying source remains available. What does reports.unpersist(blocking=True) request?", "options": ["Replace every value in reports with null", "Stop all Spark applications using the cluster", "Remove its cached blocks and wait for removal to complete", "Delete the underlying source files permanently"], "correct": 2, "explanation_ja": "unpersistは、対象DataFrameの保存済みブロックをメモリやディスクから解放する操作です。blocking=Trueはその削除完了を待ちます。DataFrameの定義や元ファイルを削除する操作ではなく、必要なら後続のactionで元の計画から再計算できます。", "distractors_ja": ["行の値やスキーマを書き換えません。", "クラスタ全体や他のアプリケーションを停止しません。", "正答", "元の入力ファイルを削除する操作ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.unpersist.html", "validation": "公式資料照合・未実行", "author_id": "A012", "exam": 1, "concept": "cache-persist", "concept_label": "cache・persist・再利用", "misconception_tags": ["確認ポイント：行の値やスキーマを書き換えません。", "確認ポイント：クラスタ全体や他のアプリケーションを停止しません。", "", "確認ポイント：元の入力ファイルを削除する操作ではありません。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "DataFrame reports はキャッシュされ、すべてのデータが実体化されています。元のソースは引き続き利用できます。reports.unpersist(blocking=True) は何を要求しますか。", "options_ja": ["reports のすべての値を null に置き換える", "クラスターを使用しているすべての Spark アプリケーションを停止する", "そのキャッシュ済みブロックを削除し、削除の完了を待つ", "元のソースファイルを恒久的に削除する"]}, {"id": "M1-17", "domain": "DataFrame", "topic": "array-index-conventions", "objective": "配列参照APIの添字規則を区別する", "difficulty": "applied", "stem": "colors contains [\"red\", \"blue\", \"green\"]. What is returned by F.element_at(\"colors\", -1)?", "options": ["\"green\"", "NULL", "An error because every negative index is invalid", "\"red\""], "correct": 0, "explanation_ja": "element_atの配列添字は正数なら1始まりで、負数は末尾から数える。-1は最後の要素greenを指す。このAPIでは0は有効な配列位置ではない一方、負数は用途がある。getItemの0始まりの規則と混在させず、呼び出している関数の添字仕様を確認する。", "distractors_ja": ["正答", "-1は範囲内の有効な添字である。", "element_atは末尾からの負の添字をサポートする。", "末尾から1つ目はgreenであり先頭ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.element_at.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C030", "exam": 1, "concept": "nested-data", "concept_label": "配列・構造体・展開", "misconception_tags": ["", "確認ポイント：-1は範囲内の有効な添字である。", "確認ポイント：element_atは末尾からの負の添字をサポートする。", "確認ポイント：末尾から1つ目はgreenであり先頭ではない。"], "suggested_causes": ["unknown", "boundary", "knowledge", "knowledge"], "stem_ja": "colors には [\"red\", \"blue\", \"green\"] が格納されています。F.element_at(\"colors\", -1) は何を返しますか。", "options_ja": ["\"green\"", "NULL", "すべての負のインデックスは無効なのでエラーになる", "\"red\""]}, {"id": "M1-18", "domain": "DataFrame", "topic": "literal-column", "objective": "定数と列参照を区別する", "difficulty": "basic", "stem": "The DataFrame df contains only account_id and balance. An engineer must add a string column source with the value \"ledger\" on every row. Which expression is valid?", "options": ["df.withColumn(\"source\", \"ledger\")", "df.withColumnRenamed(\"ledger\", \"source\")", "df.withColumn(\"source\", F.col(\"ledger\"))", "df.withColumn(\"source\", F.lit(\"ledger\"))"], "correct": 3, "explanation_ja": "withColumnの第2引数にはColumn式が必要である。litはPythonの文字列を全行共通のリテラル列に変換する。一方colは既存列への参照なので、存在しないledgerを指定すると解決できない。withColumnRenamedは列名の変更であり、定数列を新しく作る機能ではない。", "distractors_ja": ["Python文字列をそのままColumn引数には渡せない。", "改名対象の列が存在せず、新規列も作られない。", "存在しないledger列を参照している。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.lit.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C002", "exam": 1, "concept": "column-expressions", "concept_label": "列式・射影・列名操作", "misconception_tags": ["確認ポイント：Python文字列をそのままColumn引数には渡せない。", "確認ポイント：改名対象の列が存在せず、新規列も作られない。", "確認ポイント：存在しないledger列を参照している。", ""], "suggested_causes": ["api", "knowledge", "knowledge", "unknown"], "stem_ja": "DataFrame df には account_id と balance の列だけがあります。エンジニアは、すべての行の値が \"ledger\" となる文字列列 source を追加する必要があります。有効な式はどれですか。", "options_ja": ["df.withColumn(\"source\", \"ledger\")", "df.withColumnRenamed(\"ledger\", \"source\")", "df.withColumn(\"source\", F.col(\"ledger\"))", "df.withColumn(\"source\", F.lit(\"ledger\"))"]}, {"id": "M1-19", "domain": "DataFrame", "topic": "summary-selected-statistics", "objective": "要約統計の出力を指定する", "difficulty": "basic", "stem": "A quality report needs only count, minimum, and maximum summary rows for the numeric column temperature. Which expression requests those statistics without requesting percentiles or a standard deviation?", "options": ["df.select(\"temperature\").groupBy(\"temperature\").count()", "df.select(\"temperature\").count(\"min\", \"max\")", "df.select(\"temperature\").summary()", "df.select(\"temperature\").summary(\"count\", \"min\", \"max\")"], "correct": 3, "explanation_ja": "summaryへ統計名を列挙すると必要な要約行だけを要求できる。引数なしのsummaryでは標準偏差や分位点など既定の統計も含まれる。DataFrame.countは行数を返す別のAPIであり統計名を受け取らない。groupByによる値別件数も列全体の要約とは異なる。", "distractors_ja": ["値ごとの件数であり、指定した3つの要約行を返さない。", "DataFrame.countは統計名の引数を受け取らない。", "既定のsummaryには不要な標準偏差や分位点も含まれる。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.summary.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C054", "exam": 1, "concept": "aggregation", "concept_label": "集約・統計・近似値", "misconception_tags": ["確認ポイント：値ごとの件数であり、指定した3つの要約行を返さない。", "確認ポイント：DataFrame.countは統計名の引数を受け取らない。", "確認ポイント：既定のsummaryには不要な標準偏差や分位点も含まれる。", ""], "suggested_causes": ["knowledge", "api", "knowledge", "unknown"], "stem_ja": "品質レポートでは、数値列 temperature について、件数、最小値、最大値の要約行だけが必要です。パーセンタイルや標準偏差を要求せずに、これらの統計量を要求する式はどれですか。", "options_ja": ["df.select(\"temperature\").groupBy(\"temperature\").count()", "df.select(\"temperature\").count(\"min\", \"max\")", "df.select(\"temperature\").summary()", "df.select(\"temperature\").summary(\"count\", \"min\", \"max\")"]}, {"id": "M1-20", "domain": "DataFrame", "topic": "grouped-aggregate-filter", "objective": "集約後の条件を集約結果に適用する", "difficulty": "applied", "stem": "sales has store and non-null numeric amount. Return stores whose total amount exceeds 500, with output columns store and total. Which expression meets the requirement?", "options": ["sales.filter(F.col(\"amount\") > 500).groupBy(\"store\").agg(F.sum(\"amount\").alias(\"total\"))", "sales.groupBy(\"store\").agg(F.sum(\"amount\").alias(\"total\")).filter(F.col(\"total\") > 500)", "sales.select(\"store\", F.sum(\"amount\").alias(\"total\")).filter(\"total > 500\")", "sales.groupBy(\"store\").agg(F.count(\"amount\").alias(\"total\")).filter(\"total > 500\")"], "correct": 1, "explanation_ja": "店舗別の合計で判定するため、groupByとsumで集約してからtotalをfilterする。集約前にamount>500で絞ると、少額の取引が合計に含まれなくなる。countは件数であり金額合計ではない。集約されないstoreと全体sumをselectだけで同時に指定する方法も要件を満たさない。", "distractors_ja": ["個々の取引に条件をかけ、店舗の合計対象を変えてしまう。", "正答", "storeをグループ化せずに集約関数と混在させている。", "amountの件数を数えており合計金額ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.groupBy.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C019", "exam": 1, "concept": "aggregation", "concept_label": "集約・統計・近似値", "misconception_tags": ["確認ポイント：個々の取引に条件をかけ、店舗の合計対象を変えてしまう。", "", "確認ポイント：storeをグループ化せずに集約関数と混在させている。", "確認ポイント：amountの件数を数えており合計金額ではない。"], "suggested_causes": ["knowledge", "unknown", "api", "knowledge"], "stem_ja": "sales には store と、NULL ではない数値列 amount があります。amount の合計が 500 を超える店舗を、store と total の列で返します。この要件を満たす式はどれですか。", "options_ja": ["sales.filter(F.col(\"amount\") > 500).groupBy(\"store\").agg(F.sum(\"amount\").alias(\"total\"))", "sales.groupBy(\"store\").agg(F.sum(\"amount\").alias(\"total\")).filter(F.col(\"total\") > 500)", "sales.select(\"store\", F.sum(\"amount\").alias(\"total\")).filter(\"total > 500\")", "sales.groupBy(\"store\").agg(F.count(\"amount\").alias(\"total\")).filter(\"total > 500\")"]}, {"id": "M1-21", "domain": "DataFrame", "topic": "join-alias-qualified-columns", "objective": "結合後の同名列を修飾する", "difficulty": "applied", "stem": "left_df has id and status; right_df also has id and status. An engineer needs id from the left and status from the right for matching IDs. Which expression avoids an ambiguous status reference?", "options": ["left_df.join(right_df, \"id\").select(\"id\", F.col(\"status\").alias(\"right_status\"))", "left_df.join(right_df, \"id\").drop(\"status\").select(\"id\", \"status\")", "left_df.alias(\"l\").join(right_df.alias(\"r\"), F.col(\"l.id\") == F.col(\"r.id\")).select(F.col(\"l.id\").alias(\"id\"), F.col(\"r.status\").alias(\"status\"))", "left_df.join(right_df, \"id\").select(\"id\", \"status\")"], "correct": 2, "explanation_ja": "左右のDataFrameにaliasを付け、l.idやr.statusのように修飾して参照すれば、どちらの列を出すか明確になる。結合キー以外に同名列がある場合、単なるstatusは曖昧である。曖昧な列参照にaliasを付けても参照元は決まらず、drop後には必要列自体が消える。", "distractors_ja": ["出力名を変えても元のstatus参照の曖昧さは解消しない。", "同名status列を除去してから存在しない列を選んでいる。", "正答", "左右にstatusが残るので列参照が曖昧になる。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.alias.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C015", "exam": 1, "concept": "joins", "concept_label": "結合条件・結合種類・行数", "misconception_tags": ["確認ポイント：出力名を変えても元のstatus参照の曖昧さは解消しない。", "確認ポイント：同名status列を除去してから存在しない列を選んでいる。", "", "確認ポイント：左右にstatusが残るので列参照が曖昧になる。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "left_df には id と status があり、right_df にも id と status があります。エンジニアは、ID が一致する行について、左側から id を、右側から status を取得する必要があります。status の参照が曖昧になるのを避ける式はどれですか。", "options_ja": ["left_df.join(right_df, \"id\").select(\"id\", F.col(\"status\").alias(\"right_status\"))", "left_df.join(right_df, \"id\").drop(\"status\").select(\"id\", \"status\")", "left_df.alias(\"l\").join(right_df.alias(\"r\"), F.col(\"l.id\") == F.col(\"r.id\")).select(F.col(\"l.id\").alias(\"id\"), F.col(\"r.status\").alias(\"status\"))", "left_df.join(right_df, \"id\").select(\"id\", \"status\")"]}, {"id": "M1-22", "domain": "DataFrame", "topic": "union-evolving-schema", "objective": "異なる列集合のDataFrameを統合する", "difficulty": "applied", "stem": "old_batch has columns [event_id, value]. new_batch has [value, event_id, region]. Corresponding columns have compatible types. Combine every row by column name and put NULL in region for old rows. Which expression is appropriate?", "options": ["old_batch.unionByName(new_batch, allowMissingColumns=True)", "old_batch.unionByName(new_batch)", "old_batch.join(new_batch, \"event_id\", \"full\")", "old_batch.union(new_batch)"], "correct": 0, "explanation_ja": "unionByNameは列名で対応付け、allowMissingColumns=Trueを指定すると片方だけにある列をNULLで補完する。列数や順序が違うバッチを縦に連結する意図に合う。指定を省くと欠けているregionが問題になり、full joinはイベントIDで横に対応付ける別の演算になる。", "distractors_ja": ["正答", "既定では欠けている列を許可しない。", "行の追加ではなくキーに基づく横結合になる。", "列数が異なり、そのまま位置ベースのunionはできない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.unionByName.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C017", "exam": 1, "concept": "sets-dedup", "concept_label": "集合演算・重複・列対応", "misconception_tags": ["", "確認ポイント：既定では欠けている列を許可しない。", "確認ポイント：行の追加ではなくキーに基づく横結合になる。", "確認ポイント：列数が異なり、そのまま位置ベースのunionはできない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "old_batch の列は [event_id, value]、new_batch の列は [value, event_id, region] です。対応する列の型には互換性があります。列名に基づいてすべての行を結合し、古い行の region には NULL を設定します。適切な式はどれですか。", "options_ja": ["old_batch.unionByName(new_batch, allowMissingColumns=True)", "old_batch.unionByName(new_batch)", "old_batch.join(new_batch, \"event_id\", \"full\")", "old_batch.union(new_batch)"]}, {"id": "M1-23", "domain": "Spark SQL", "topic": "appendと重複", "objective": "書き込みモードは重複排除ではないと理解する", "difficulty": "applied", "stem": "A nonempty DataFrame contains 25 rows. Its successful Parquet append is accidentally run twice against the same initially empty destination. There are no failed tasks or concurrent writers. How many rows are in the destination after both writes?", "options": ["0, because append requires an existing nonempty dataset.", "25, because append deduplicates identical rows.", "25, because Spark remembers the DataFrame object identity.", "50, because append does not deduplicate the repeated batch."], "correct": 3, "explanation_ja": "appendは内容を追加する操作であり、同一バッチの再実行を自動検知する仕組みではない。今回の条件では25行が2回保存される。再実行時の一意性が必要なパイプラインでは、保存モードとは別に冪等性を設計する。", "distractors_ja": ["appendは未作成の出力先にもデータを書き込める。", "通常のParquet appendに行単位の自動重複排除はない。", "Pythonのオブジェクト識別子は保存済みバッチ管理に使われない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameWriter.parquet.html", "validation": "公式資料照合・未実行", "author_id": "B011", "exam": 1, "concept": "file-write-layout", "concept_label": "保存モード・テーブル・配置", "misconception_tags": ["確認ポイント：appendは未作成の出力先にもデータを書き込める。", "確認ポイント：通常のParquet appendに行単位の自動重複排除はない。", "確認ポイント：Pythonのオブジェクト識別子は保存済みバッチ管理に使われない。", ""], "suggested_causes": ["knowledge", "boundary", "knowledge", "unknown"], "stem_ja": "空ではない DataFrame に 25 行あります。当初は空だった同じ出力先に対して、Parquet への追記が誤って 2 回実行され、どちらも成功しました。失敗したタスクや同時実行の書き込み処理はありません。2 回の書き込み後、出力先には何行ありますか。", "options_ja": ["0 行。append には、既存の空ではないデータセットが必要だから。", "25 行。append は同一行の重複を除去するから。", "25 行。Spark が DataFrame オブジェクトの同一性を記憶しているから。", "50 行。append は繰り返し書き込まれたバッチの重複を除去しないから。"]}, {"id": "M1-24", "domain": "Structured Streaming", "topic": "スライディングウィンドウ", "objective": "イベントが属する時間区間を計算する", "difficulty": "applied", "stem": "A query groups by window(\"event_ts\", \"10 minutes\", \"5 minutes\") with the default start offset. An event has timestamp 2026-08-01 12:07:00 UTC. Which windows include it? Window ends are exclusive.", "options": ["[12:00,12:10) and [12:05,12:15)", "[12:05,12:15) only", "[12:07,12:17) only", "[12:00,12:05) and [12:05,12:10)"], "correct": 0, "explanation_ja": "10分幅のウィンドウを5分ごとに開始するため、隣り合う区間は重なる。12:07は12:00開始と12:05開始の両方に含まれる。ウィンドウはイベントごとに任意の開始時刻で生成されるのではなく、指定した間隔に整列する。", "distractors_ja": ["正答", "幅がスライド間隔より長いため、前のウィンドウにも入る。", "既定オフセットでのウィンドウ開始は12:07ではない。", "示された区間は5分幅であり指定の10分幅ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.window.html", "validation": "公式資料照合・未実行", "author_id": "B044", "exam": 1, "concept": "stream-watermark", "concept_label": "イベント時刻・watermark・状態", "misconception_tags": ["", "確認ポイント：幅がスライド間隔より長いため、前のウィンドウにも入る。", "確認ポイント：既定オフセットでのウィンドウ開始は12:07ではない。", "確認ポイント：示された区間は5分幅であり指定の10分幅ではない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "あるクエリは、既定の開始オフセットで window(\"event_ts\", \"10 minutes\", \"5 minutes\") を使ってグループ化します。あるイベントのタイムスタンプは 2026-08-01 12:07:00 UTC です。このイベントを含むウィンドウはどれですか。ウィンドウの終了時刻は含みません。", "options_ja": ["[12:00,12:10) と [12:05,12:15)", "[12:05,12:15) のみ", "[12:07,12:17) のみ", "[12:00,12:05) と [12:05,12:10)"]}, {"id": "M1-25", "domain": "Structured Streaming", "topic": "ファイルシンクのモード", "objective": "クエリとシンクの両方の互換性を確認する", "difficulty": "applied", "stem": "A developer has a streaming aggregate that can produce updated result rows. They try .writeStream.format(\"parquet\").outputMode(\"update\").start(path). Which issue should they recognize?", "options": ["A checkpoint automatically makes every sink support all output modes.", "The query must rename its count column to value to enable update mode.", "Parquet cannot store numeric aggregate values.", "The built-in file sink supports append mode, not update mode for changing existing result rows."], "correct": 3, "explanation_ja": "outputModeはクエリが対応しているだけでなく、選んだシンクでも対応している必要がある。組み込みファイルシンクはappendを使うため、更新途中の集計行をupdateでそのまま追記型ファイルへ送る設計にはできない。", "distractors_ja": ["チェックポイントはシンクの更新機能を追加しない。", "列名を変えてもシンクとoutputModeの互換性は変わらない。", "Parquetは数値列を保存できる。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html#output-sinks", "validation": "公式資料照合・未実行", "author_id": "B054", "exam": 1, "concept": "stream-modes", "concept_label": "ストリーミング出力モード", "misconception_tags": ["確認ポイント：チェックポイントはシンクの更新機能を追加しない。", "確認ポイント：列名を変えてもシンクとoutputModeの互換性は変わらない。", "確認ポイント：Parquetは数値列を保存できる。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "開発者は、更新された結果行を生成する可能性があるストリーミング集約を作成しています。.writeStream.format(\"parquet\").outputMode(\"update\").start(path) を実行しようとしています。認識すべき問題はどれですか。", "options_ja": ["チェックポイントによって、すべてのシンクが自動的にすべての出力モードに対応する。", "update モードを有効にするには、クエリの count 列の名前を value に変更する必要がある。", "Parquet は数値の集約結果を保存できない。", "組み込みのファイルシンクが対応するのは append モードであり、既存の結果行を変更する update モードには対応しない。"]}, {"id": "M1-26", "domain": "Tuning", "topic": "increase-parallelism", "objective": "パーティションを増やして並列度を改善する", "difficulty": "applied", "stem": "A batch DataFrame has two partitions, but the next expensive row-wise transformation can use many available executor cores. The engineer wants to redistribute the data into 24 partitions before that transformation. Which operation directly meets this requirement?", "options": ["df.coalesce(24)", "df.withColumn(\"partition\", F.lit(24))", "df.limit(24)", "df.repartition(24)"], "correct": 3, "explanation_ja": "repartitionはshuffleでデータを再配分し、パーティション数を増やす用途にも使える。coalesceは通常、既存パーティションをまとめて減らす操作であり、この状況のように2から24へ増やす目的を満たさない。並列度を上げる効果と再配分のコストを合わせて判断する。", "distractors_ja": ["coalesceはこの指定で元の2パーティションを24へ増やせない。", "定数列を追加するだけで実行パーティション数を変えない。", "行数を制限する処理でパーティション再配分ではない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.repartition.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C055", "exam": 1, "concept": "shuffle-partitions", "concept_label": "shuffle・パーティション・スキュー", "misconception_tags": ["確認ポイント：coalesceはこの指定で元の2パーティションを24へ増やせない。", "確認ポイント：定数列を追加するだけで実行パーティション数を変えない。", "確認ポイント：行数を制限する処理でパーティション再配分ではない。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "バッチ DataFrame には 2 つのパーティションがありますが、次に行う計算負荷の高い行単位の変換では、利用可能な多数のエグゼキューターコアを活用できます。エンジニアは、この変換の前にデータを 24 パーティションに再分配したいと考えています。この要件を直接満たす操作はどれですか。", "options_ja": ["df.coalesce(24)", "df.withColumn(\"partition\", F.lit(24))", "df.limit(24)", "df.repartition(24)"]}, {"id": "M1-27", "domain": "Structured Streaming", "topic": "dropDuplicatesWithinWatermark", "objective": "イベント時刻をキーに含めず重複排除する", "difficulty": "applied", "stem": "In Spark 3.5, events is a streaming DataFrame with event_ts of TimestampType. duplicate deliveries share event_id but may have slightly different event_ts values. Their time spread is less than 30 minutes. Which expression deduplicates on event_id within a configured watermark horizon without adding event_ts to the key?", "options": ["events.withWatermark(\"event_id\", \"30 minutes\").dropDuplicatesWithinWatermark([\"event_ts\"])", "events.withWatermark(\"event_ts\", \"30 minutes\").dropDuplicatesWithinWatermark([\"event_id\"])", "events.withWatermark(\"event_ts\", \"30 minutes\").dropDuplicatesWithinWatermark([\"event_id\", \"event_ts\"])", "events.dropDuplicatesWithinWatermark([\"event_id\"])"], "correct": 1, "explanation_ja": "Spark 3.5のdropDuplicatesWithinWatermarkはイベント時刻列を重複判定キーに入れず、watermarkの範囲で重複を抑制できる。時刻が微妙に異なる再配送を同じevent_idで判定する今回の要件では、キーをevent_idだけにする。", "distractors_ja": ["watermarkを付ける時刻列と重複判定キーが逆である。", "正答", "時刻もキーに入れると時刻の違う再配送を別キーとして扱ってしまう。", "このAPIはwatermarkが設定されたストリーミングDataFrameで使う。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.dropDuplicatesWithinWatermark.html", "validation": "公式資料照合・未実行", "author_id": "B048", "exam": 1, "concept": "stream-watermark", "concept_label": "イベント時刻・watermark・状態", "misconception_tags": ["確認ポイント：watermarkを付ける時刻列と重複判定キーが逆である。", "", "確認ポイント：時刻もキーに入れると時刻の違う再配送を別キーとして扱ってしまう。", "確認ポイント：このAPIはwatermarkが設定されたストリーミングDataFrameで使う。"], "suggested_causes": ["boundary", "unknown", "boundary", "api"], "stem_ja": "Spark 3.5 で、events は TimestampType の event_ts を持つストリーミング DataFrame です。重複して配信されたイベントは同じ event_id を持ちますが、event_ts の値が少し異なる場合があります。その時刻の差は 30 分未満です。event_ts をキーに追加せずに、設定したウォーターマークの時間範囲内で event_id に基づいて重複を除去する式はどれですか。", "options_ja": ["events.withWatermark(\"event_id\", \"30 minutes\").dropDuplicatesWithinWatermark([\"event_ts\"])", "events.withWatermark(\"event_ts\", \"30 minutes\").dropDuplicatesWithinWatermark([\"event_id\"])", "events.withWatermark(\"event_ts\", \"30 minutes\").dropDuplicatesWithinWatermark([\"event_id\", \"event_ts\"])", "events.dropDuplicatesWithinWatermark([\"event_id\"])"]}, {"id": "M1-28", "domain": "DataFrame", "topic": "nested-struct-projection", "objective": "structのフィールドを取り出す", "difficulty": "basic", "stem": "customers has customer_id and a struct column profile with fields city and postal_code. Return exactly customer_id and a top-level column city. Which expression meets the requirement?", "options": ["customers.select(\"customer_id\", F.col(\"city\"))", "customers.withColumnRenamed(\"profile.city\", \"city\")", "customers.select(\"customer_id\", F.explode(\"profile\"))", "customers.select(\"customer_id\", F.col(\"profile.city\").alias(\"city\"))"], "correct": 3, "explanation_ja": "structの内部フィールドはprofile.cityのようなドット表記で参照でき、selectでトップレベルの出力列として投影する。cityは元のトップレベル列ではない。withColumnRenamedはこの指定で内部フィールドを抜き出す操作にはならず、explodeは配列やmapを対象とする関数である。", "distractors_ja": ["元のトップレベルにcity列は存在しない。", "内部フィールドの取り出しやトップレベルへの投影にはならない。", "structはexplodeが要求する配列またはmapではない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.Column.getField.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C031", "exam": 1, "concept": "nested-data", "concept_label": "配列・構造体・展開", "misconception_tags": ["確認ポイント：元のトップレベルにcity列は存在しない。", "確認ポイント：内部フィールドの取り出しやトップレベルへの投影にはならない。", "確認ポイント：structはexplodeが要求する配列またはmapではない。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "customers には customer_id と構造体列 profile があり、profile は city と postal_code のフィールドを持ちます。customer_id と、トップレベルの列 city の 2 列だけを返します。この要件を満たす式はどれですか。", "options_ja": ["customers.select(\"customer_id\", F.col(\"city\"))", "customers.withColumnRenamed(\"profile.city\", \"city\")", "customers.select(\"customer_id\", F.explode(\"profile\"))", "customers.select(\"customer_id\", F.col(\"profile.city\").alias(\"city\"))"]}, {"id": "M1-29", "domain": "Spark SQL", "topic": "カスタムパスの永続テーブル", "objective": "テーブル定義とデータの寿命を区別する", "difficulty": "challenging", "stem": "Using Spark's session catalog and a file data source, an engineer creates table sensor_archive with df.write.option(\"path\", \"/shared/sensor_archive\").saveAsTable(\"sensor_archive\"). What happens to the custom data path when DROP TABLE sensor_archive is later executed?", "options": ["The custom data path is always deleted with the table.", "The path is converted automatically into a global temporary view.", "The table metadata is removed, while the data at the custom path is retained.", "The data is copied into the driver before being deleted."], "correct": 2, "explanation_ja": "ファイルデータソースのsaveAsTableでカスタムpathを指定したテーブルは、DROP TABLEしてもその保存先のデータを保持する。既定の管理保存先を使う場合とは削除時の扱いが違うため、問題文のカタログと保存パスの前提を読む必要がある。", "distractors_ja": ["カスタムpathを指定した今回の条件ではデータを保持する。", "DROP TABLEは一時ビューへ変換する操作ではない。", "正答", "データをdriverへ退避する仕様ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-data-sources-load-save-functions.html#saving-to-persistent-tables", "validation": "公式資料照合・未実行", "author_id": "B036", "exam": 1, "concept": "file-write-layout", "concept_label": "保存モード・テーブル・配置", "misconception_tags": ["確認ポイント：カスタムpathを指定した今回の条件ではデータを保持する。", "確認ポイント：DROP TABLEは一時ビューへ変換する操作ではない。", "", "確認ポイント：データをdriverへ退避する仕様ではない。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "エンジニアは Spark のセッションカタログとファイルデータソースを使用し、df.write.option(\"path\", \"/shared/sensor_archive\").saveAsTable(\"sensor_archive\") でテーブル sensor_archive を作成します。その後 DROP TABLE sensor_archive を実行すると、このカスタムデータパスはどうなりますか。", "options_ja": ["カスタムデータパスは、常にテーブルと一緒に削除される。", "パスは自動的にグローバル一時ビューへ変換される。", "テーブルのメタデータは削除されるが、カスタムパスのデータは保持される。", "データは削除前にドライバーへコピーされる。"]}, {"id": "M1-30", "domain": "Spark SQL", "topic": "SQLでCSVビュー", "objective": "CREATE TEMPORARY VIEWのデータソース指定を使う", "difficulty": "applied", "stem": "A SQL-only script must register a header-bearing CSV path as a temporary view named raw_sites with columns site STRING and capacity INT. Which statement specifies the source, schema, and header correctly?", "options": ["CREATE TEMPORARY VIEW raw_sites USING parquet OPTIONS (path \"/landing/sites\", header \"true\")", "CREATE TEMPORARY VIEW raw_sites (site STRING, capacity INT) USING csv OPTIONS (path \"/landing/sites\", header \"true\")", "CREATE TABLE raw_sites AS CSV \"/landing/sites\" HEADER TRUE", "CREATE TEMPORARY VIEW raw_sites AS SELECT site, capacity FROM \"/landing/sites\""], "correct": 1, "explanation_ja": "データソースから一時ビューを作る場合はUSING csvとOPTIONSで入力の場所・形式オプションを指定できる。列定義も明示すればcapacityをINTとして扱える。通常の文字列リテラルをFROM句に置くだけではファイル参照にならない。", "distractors_ja": ["CSVファイルをParquetとして指定している。", "正答", "示されたCREATE TABLE構文は有効なデータソース指定ではない。", "文字列パスだけではSpark SQLのテーブル参照にならない。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-ref-syntax-ddl-create-table-datasource.html", "validation": "公式資料照合・未実行", "author_id": "B031", "exam": 1, "concept": "file-read-schema", "concept_label": "ファイル読込・スキーマ・形式", "misconception_tags": ["確認ポイント：CSVファイルをParquetとして指定している。", "", "確認ポイント：示されたCREATE TABLE構文は有効なデータソース指定ではない。", "確認ポイント：文字列パスだけではSpark SQLのテーブル参照にならない。"], "suggested_causes": ["knowledge", "unknown", "api", "knowledge"], "stem_ja": "SQL だけで構成されたスクリプトで、ヘッダー付き CSV のパスを、site STRING と capacity INT の列を持つ一時ビュー raw_sites として登録する必要があります。ソース、スキーマ、ヘッダーを正しく指定している文はどれですか。", "options_ja": ["CREATE TEMPORARY VIEW raw_sites USING parquet OPTIONS (path \"/landing/sites\", header \"true\")", "CREATE TEMPORARY VIEW raw_sites (site STRING, capacity INT) USING csv OPTIONS (path \"/landing/sites\", header \"true\")", "CREATE TABLE raw_sites AS CSV \"/landing/sites\" HEADER TRUE", "CREATE TEMPORARY VIEW raw_sites AS SELECT site, capacity FROM \"/landing/sites\""]}, {"id": "M1-31", "domain": "Architecture", "topic": "Cache eligibility", "objective": "複数actionでの計算再利用を理解する", "difficulty": "applied", "stem": "A deterministic batch transformation is expensive and its unchanged result is used by three separate actions. No persistence has been requested. Which statement is correct?", "options": ["The first action always writes the result to a permanent table", "A second action is prohibited on the same DataFrame", "Assigning the DataFrame to a Python variable guarantees its rows are already cached", "Spark may recompute the transformation for later actions; explicitly persisting the reusable result can avoid repeated work"], "correct": 3, "explanation_ja": "Python変数が保持するのはDataFrameを表すオブジェクトであり、計算済み全行が自動で永続化される保証ではありません。複数actionで同じ高コスト結果を使う場合はpersistやcacheを検討します。ただし実際の効果は保存コスト、容量、再利用回数にも依存します。", "distractors_ja": ["actionで永続テーブルが自動作成されるわけではありません。", "同じDataFrameに複数actionを実行できます。", "変数への代入はキャッシュ実体化の保証ではありません。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/rdd-programming-guide.html", "validation": "公式資料照合・未実行", "author_id": "A036", "exam": 1, "concept": "cache-persist", "concept_label": "cache・persist・再利用", "misconception_tags": ["確認ポイント：actionで永続テーブルが自動作成されるわけではありません。", "確認ポイント：同じDataFrameに複数actionを実行できます。", "確認ポイント：変数への代入はキャッシュ実体化の保証ではありません。", ""], "suggested_causes": ["knowledge", "knowledge", "boundary", "unknown"], "stem_ja": "ある決定的なバッチ変換は計算コストが高く、その変更されていない結果が 3 つの別々のアクションで使用されます。永続化は要求されていません。正しい記述はどれですか。", "options_ja": ["最初のアクションが、常に結果を永続テーブルに書き込む", "同じ DataFrame に対して 2 回目のアクションを実行することは禁止されている", "DataFrame を Python 変数に代入すると、その行がすでにキャッシュされていることが保証される", "Spark は後のアクションで変換を再計算する場合があり、再利用する結果を明示的に永続化すれば、作業の繰り返しを避けられる"]}, {"id": "M1-32", "domain": "Tuning", "topic": "データスキューの診断", "objective": "少数の極端に重いタスクを見分ける", "difficulty": "applied", "stem": "In a shuffle join stage, 199 tasks finish in seconds, while one task reads hundreds of times more shuffle data and runs for minutes. CPU capacity is otherwise available. Which diagnosis is most consistent with these measurements?", "options": ["A skewed key distribution has created a disproportionately large shuffle partition.", "Each task is reading exactly the same amount of shuffle data; the metric difference is expected.", "The input has too many uniformly small partitions, which explains this single much larger shuffle input.", "The driver has serialized every task, so all partitions must take the same time."], "correct": 0, "explanation_ja": "少数のタスクにシャッフル入力が集中している測定値は、キーの偏りによるパーティションの不均衡を示す。タスク時間だけでなく入力量も確認すると、全体的な資源不足と区別しやすい。対策は偏ったキーやAQEのスキュー対応を調査して選ぶ。", "distractors_ja": ["正答", "入力データ量が大きく異なるという観測に反する。", "均等で小さいpartitionでは1つだけ巨大なshuffle入力を説明できない。", "多数のtaskは速く完了しており、全task直列化の説明と合わない。"], "source_url": "https://spark.apache.org/docs/3.5.6/web-ui.html#stage-detail", "validation": "公式資料照合・未実行", "author_id": "B056", "exam": 1, "concept": "shuffle-partitions", "concept_label": "shuffle・パーティション・スキュー", "misconception_tags": ["", "確認ポイント：入力データ量が大きく異なるという観測に反する。", "確認ポイント：均等で小さいpartitionでは1つだけ巨大なshuffle入力を説明できない。", "確認ポイント：多数のtaskは速く完了しており、全task直列化の説明と合わない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "シャッフル結合のステージで、199 個のタスクは数秒で完了しますが、1 個のタスクは他の数百倍のシャッフルデータを読み込み、数分かかります。それ以外には CPU の余力があります。これらの測定結果に最も整合する診断はどれですか。", "options_ja": ["キー分布の偏りによって、極端に大きなシャッフルパーティションができている。", "各タスクはまったく同量のシャッフルデータを読み込んでおり、指標の差は想定どおりである。", "入力に均等に小さいパーティションが多すぎるため、この 1 つのシャッフル入力だけがはるかに大きくなっている。", "ドライバーがすべてのタスクを直列化したため、すべてのパーティションは同じ時間を要するはずである。"]}, {"id": "M1-33", "domain": "Architecture", "topic": "Action result", "objective": "actionの戻り値を識別する", "difficulty": "basic", "stem": "A developer needs the total number of rows in a batch DataFrame orders as a Python integer. Which expression requests that computation and returns the required value?", "options": ["orders.limit(1)", "orders.select('*')", "orders.count()", "orders.filter(lit(True))"], "correct": 2, "explanation_ja": "countはDataFrame全体の行数を求め、その結果を整数として返します。select、filter、limitはDataFrameを返す変換であり、行数を整数として得る操作ではありません。戻り値がDataFrameかローカルな値かを見分けるとactionを識別しやすくなります。", "distractors_ja": ["最大1行のDataFrameを定義するだけです。", "全列を選択するDataFrameが返り、件数の整数ではありません。", "正答", "条件に従って行を残すDataFrameが返ります。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.count.html", "validation": "公式資料照合・未実行", "author_id": "A008", "exam": 1, "concept": "execution-model", "concept_label": "遅延評価・action・実行単位", "misconception_tags": ["確認ポイント：最大1行のDataFrameを定義するだけです。", "確認ポイント：全列を選択するDataFrameが返り、件数の整数ではありません。", "", "確認ポイント：条件に従って行を残すDataFrameが返ります。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "開発者は、バッチ DataFrame orders の総行数を Python の整数として取得する必要があります。その計算を要求し、必要な値を返す式はどれですか。", "options_ja": ["orders.limit(1)", "orders.select('*')", "orders.count()", "orders.filter(lit(True))"]}, {"id": "M1-34", "domain": "Pandas API", "topic": "Spark to pandas-on-Spark", "objective": "分散状態を保ったAPI変換を選ぶ", "difficulty": "applied", "stem": "A Spark DataFrame sdf has a unique key column record_id. A developer wants a pandas-on-Spark DataFrame using record_id as its index, without collecting all rows into local pandas. Which expression matches the requirement?", "options": ["sdf.toPandas(index_col='record_id')", "sdf.pandas_api(index_col='record_id')", "sdf.toPandas().set_index('record_id')", "sdf.collect().set_index('record_id')"], "correct": 1, "explanation_ja": "pandas_api(index_col=...)はSpark DataFrameをpandas-on-Sparkの表現へ変換し、指定列をインデックスに使えます。toPandasはローカルpandasへの全件収集を伴うため、今回の条件を満たしません。Pandas API on Sparkと通常のpandasをAPI名で区別します。", "distractors_ja": ["toPandasはその引数を取らず、分散状態も保ちません。", "正答", "ローカルpandasへ全件収集するため条件を満たしません。", "collectの戻り値はPythonリストでset_indexはありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.pandas_api.html", "validation": "公式資料照合・未実行", "author_id": "A048", "exam": 1, "concept": "pandas-distributed", "concept_label": "pandas系APIの分散処理と収集", "misconception_tags": ["確認ポイント：toPandasはその引数を取らず、分散状態も保ちません。", "", "確認ポイント：ローカルpandasへ全件収集するため条件を満たしません。", "確認ポイント：collectの戻り値はPythonリストでset_indexはありません。"], "suggested_causes": ["api", "unknown", "boundary", "api"], "stem_ja": "Spark DataFrame sdf には、一意のキー列 record_id があります。開発者は、すべての行をローカルの pandas に収集せずに、record_id をインデックスとする pandas-on-Spark DataFrame を作成したいと考えています。この要件に合う式はどれですか。", "options_ja": ["sdf.toPandas(index_col='record_id')", "sdf.pandas_api(index_col='record_id')", "sdf.toPandas().set_index('record_id')", "sdf.collect().set_index('record_id')"]}, {"id": "M1-35", "domain": "Architecture", "topic": "Immutable DataFrame", "objective": "変換後の元DataFrameを判断する", "difficulty": "applied", "stem": "A batch DataFrame base has columns id and amount. The developer runs:\n\nadjusted = base.withColumn('amount', col('amount') + 5)\n\nNo variable is reassigned afterward. What does base represent?", "options": ["A Python list containing the modified rows", "An empty DataFrame because its rows moved to adjusted", "The modified DataFrame because withColumn mutates base in place", "The original DataFrame with the original amount expression"], "correct": 3, "explanation_ja": "withColumnは列を追加・置換した新しいDataFrameを返します。戻り値をadjustedへ代入しても、baseが示す元のDataFrameの式を破壊的に変更するわけではありません。変換と変数への再代入を区別すると、連鎖したコードの挙動を正しく追えます。", "distractors_ja": ["Pythonリストへの変換は行われません。", "元DataFrameから行を移動させる操作ではありません。", "withColumnは新しいDataFrameを返します。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.withColumn.html", "validation": "公式資料照合・未実行", "author_id": "A017", "exam": 1, "concept": "column-expressions", "concept_label": "列式・射影・列名操作", "misconception_tags": ["確認ポイント：Pythonリストへの変換は行われません。", "確認ポイント：元DataFrameから行を移動させる操作ではありません。", "確認ポイント：withColumnは新しいDataFrameを返します。", ""], "suggested_causes": ["api", "knowledge", "api", "unknown"], "stem_ja": "バッチ DataFrame base には id と amount の列があります。開発者は次のコードを実行します。\n\nadjusted = base.withColumn('amount', col('amount') + 5)\n\nその後、どの変数にも再代入していません。base は何を表していますか。", "options_ja": ["変更された行を含む Python のリスト", "行が adjusted に移動したため、空になった DataFrame", "withColumn が base をその場で変更するため、変更後の DataFrame", "元の amount の式を持つ、元の DataFrame"]}, {"id": "M1-36", "domain": "Spark SQL", "topic": "saveAsTableの列名解決", "objective": "列順が異なるDataFrameを安全に追加する", "difficulty": "applied", "stem": "An existing Parquet table measures has columns (sensor STRING, status STRING). Incoming has the same names and types but column order (status, sensor). Which append uses column names to match the existing table schema?", "options": ["incoming.write.option(\"header\", True).insertInto(\"measures\")", "incoming.write.mode(\"append\").insertInto(\"measures\")", "incoming.write.mode(\"append\").saveAsTable(\"measures\")", "incoming.write.mode(\"overwrite\").saveAsTable(\"measures\")"], "correct": 2, "explanation_ja": "saveAsTableのappendは既存テーブルの列名を使って対応付けるため、同じ名前・型で列順だけが異なる場合に利用できる。insertIntoは位置で対応するため、この例ではセンサーと状態の値を取り違える危険がある。", "distractors_ja": ["headerオプションでinsertIntoの列解決方式は変わらない。", "insertIntoは列名ではなく列位置で対応する。", "正答", "overwriteは既存行を保持して追加する要件に合わない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameWriter.saveAsTable.html", "validation": "公式資料照合・未実行", "author_id": "B013", "exam": 1, "concept": "file-write-layout", "concept_label": "保存モード・テーブル・配置", "misconception_tags": ["確認ポイント：headerオプションでinsertIntoの列解決方式は変わらない。", "確認ポイント：insertIntoは列名ではなく列位置で対応する。", "", "確認ポイント：overwriteは既存行を保持して追加する要件に合わない。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "既存の Parquet テーブル measures には (sensor STRING, status STRING) の列があります。incoming は同じ列名と型を持ちますが、列の順序は (status, sensor) です。列名を使って既存テーブルのスキーマに対応付ける追記方法はどれですか。", "options_ja": ["incoming.write.option(\"header\", True).insertInto(\"measures\")", "incoming.write.mode(\"append\").insertInto(\"measures\")", "incoming.write.mode(\"append\").saveAsTable(\"measures\")", "incoming.write.mode(\"overwrite\").saveAsTable(\"measures\")"]}, {"id": "M1-37", "domain": "Structured Streaming", "topic": "処理時間トリガー", "objective": "トリガー指定の正しいAPIを選ぶ", "difficulty": "basic", "stem": "An engineer wants a micro-batch processing-time trigger with a requested interval of 250 milliseconds. Which writer configuration is valid in Spark 3.5?", "options": [".trigger(continuous=\"250 milliseconds\", once=True)", ".trigger(interval=250)", ".trigger(processingTime=250)", ".trigger(processingTime=\"250 milliseconds\")"], "correct": 3, "explanation_ja": "processingTimeには時間単位を含む間隔文字列を渡す。ミリ秒単位も指定できるが、指定間隔は処理時間を保証するものではない。continuousやonceは別のトリガー方式であり、複数方式を同時指定する使い方はしない。", "distractors_ja": ["トリガー方式を同時に複数指定できない。", "intervalという名前の引数はこのAPIにない。", "processingTimeには時間文字列を渡す。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.ss/api/pyspark.sql.streaming.DataStreamWriter.trigger.html", "validation": "公式資料照合・未実行", "author_id": "B050", "exam": 1, "concept": "stream-lifecycle", "concept_label": "ストリーム入力・開始・停止・trigger", "misconception_tags": ["確認ポイント：トリガー方式を同時に複数指定できない。", "確認ポイント：intervalという名前の引数はこのAPIにない。", "確認ポイント：processingTimeには時間文字列を渡す。", ""], "suggested_causes": ["knowledge", "api", "knowledge", "unknown"], "stem_ja": "エンジニアは、要求間隔が 250 ミリ秒の、処理時間に基づくマイクロバッチトリガーを設定したいと考えています。Spark 3.5 で有効なライター設定はどれですか。", "options_ja": [".trigger(continuous=\"250 milliseconds\", once=True)", ".trigger(interval=250)", ".trigger(processingTime=250)", ".trigger(processingTime=\"250 milliseconds\")"]}, {"id": "M1-38", "domain": "Spark SQL", "topic": "JDBC書き込み並列数", "objective": "接続数を制限する設定を選ぶ", "difficulty": "applied", "stem": "A DataFrame has 40 partitions, but the database team permits at most 5 concurrent connections for this JDBC write. Which writer option directly limits the write parallelism to at most 5 partitions?", "options": [".option(\"batchsize\", 5)", ".option(\"queryTimeout\", 5)", ".option(\"numPartitions\", 5)", ".option(\"fetchsize\", 5)"], "correct": 2, "explanation_ja": "JDBCのnumPartitionsは読み書きの並列数と同時接続数の上限に関係する。書き込み元のパーティションが上限より多い場合は減らして書く。batchsizeは1回の挿入バッチの行数であり、同時接続の上限とは異なる。", "distractors_ja": ["batchsizeは挿入バッチの行数を指定する。", "queryTimeoutは文実行の待ち時間である。", "正答", "fetchsizeは主に読み取り時の取得行数の設定である。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameWriter.jdbc.html", "validation": "公式資料照合・未実行", "author_id": "B025", "exam": 1, "concept": "jdbc", "concept_label": "JDBC引数・分割・接続数", "misconception_tags": ["確認ポイント：batchsizeは挿入バッチの行数を指定する。", "確認ポイント：queryTimeoutは文実行の待ち時間である。", "", "確認ポイント：fetchsizeは主に読み取り時の取得行数の設定である。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "DataFrame には 40 個のパーティションがありますが、データベースチームは、この JDBC 書き込みに対して同時接続を最大 5 本までしか許可していません。書き込みの並列度を最大 5 パーティションに直接制限するライターオプションはどれですか。", "options_ja": [".option(\"batchsize\", 5)", ".option(\"queryTimeout\", 5)", ".option(\"numPartitions\", 5)", ".option(\"fetchsize\", 5)"]}, {"id": "M1-39", "domain": "Spark SQL", "topic": "ビューと保存", "objective": "一時ビューは永続データコピーではないと理解する", "difficulty": "basic", "stem": "An engineer calls filtered.createOrReplaceTempView(\"audit_preview\"). No write action is executed. Which conclusion is valid?", "options": ["A Parquet copy is immediately written to the warehouse directory.", "A SQL name for the DataFrame is registered; the call does not create a persistent table containing a copied dataset.", "The input dataset is deleted after the temporary view is registered.", "The complete DataFrame is collected into a Python list on the driver."], "correct": 1, "explanation_ja": "一時ビューの登録はSQLからDataFrameを参照するための名前付けである。保存アクション、collect、入力削除を意味しない。将来のセッションや別アプリケーションでも必要なデータは、要件に合う永続化方法を別に選ぶ。", "distractors_ja": ["一時ビュー登録はParquetへの保存操作ではない。", "正答", "入力データを削除する機能はない。", "collectを実行するAPIではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.createTempView.html", "validation": "公式資料照合・未実行", "author_id": "B020", "exam": 1, "concept": "sessions-views", "concept_label": "セッション・ビューの共有範囲", "misconception_tags": ["確認ポイント：一時ビュー登録はParquetへの保存操作ではない。", "", "確認ポイント：入力データを削除する機能はない。", "確認ポイント：collectを実行するAPIではない。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "api"], "stem_ja": "エンジニアは filtered.createOrReplaceTempView(\"audit_preview\") を呼び出します。書き込みアクションは実行していません。妥当な結論はどれですか。", "options_ja": ["Parquet 形式のコピーが、直ちにウェアハウスディレクトリへ書き込まれる。", "DataFrame の SQL 名が登録される。この呼び出しで、コピーされたデータセットを含む永続テーブルが作成されるわけではない。", "一時ビューの登録後、入力データセットが削除される。", "DataFrame 全体が、ドライバー上の Python のリストに収集される。"]}, {"id": "M1-40", "domain": "Spark Connect", "topic": "Cluster deployment", "objective": "cluster modeのdriver配置を理解する", "difficulty": "applied", "stem": "A supported cluster manager runs a classic Spark job submitted from a gateway. The requirement is for the cluster manager to launch the driver inside the cluster, rather than running the driver in the submitting gateway process. Which deployment mode matches this requirement?", "options": ["local[1] as the master", "Client deployment mode", "DataFrame cache mode", "Cluster deployment mode"], "correct": 3, "explanation_ja": "cluster deploy modeではdriverがクラスタ内部で起動されます。client deploy modeでは送信側にdriverがあり、その稼働や接続性が処理に関係します。ここではdriverの配置場所を問うており、executorの数やDataFrameの保存レベルを選ぶ問題ではありません。", "distractors_ja": ["local実行は要求しているクラスタ内driver配置ではありません。", "client modeではdriverが送信側で動作します。", "cacheはdeploy modeではありません。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/submitting-applications.html", "validation": "公式資料照合・未実行", "author_id": "A043", "exam": 1, "concept": "cluster-resources", "concept_label": "driver・executor・並列資源", "misconception_tags": ["確認ポイント：local実行は要求しているクラスタ内driver配置ではありません。", "確認ポイント：client modeではdriverが送信側で動作します。", "確認ポイント：cacheはdeploy modeではありません。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "対応するクラスター管理システムが、ゲートウェイから送信された従来型 Spark ジョブを実行します。要件は、送信元のゲートウェイプロセス内でドライバーを実行するのではなく、クラスター管理システムがクラスター内でドライバーを起動することです。この要件に合うデプロイモードはどれですか。", "options_ja": ["master として local[1] を指定する", "client デプロイモード", "DataFrame のキャッシュモード", "cluster デプロイモード"]}, {"id": "M1-41", "domain": "Structured Streaming", "topic": "foreachBatchの再実行", "objective": "外部書き込みの冪等性を設計する", "difficulty": "challenging", "stem": "A foreachBatch callback inserts its rows into an external database. A failure can occur after the insert but before the streaming commit is recorded. What design helps avoid duplicate effects when that batch is retried?", "options": ["Delete the checkpoint on every restart to enable exactly-once delivery.", "Use batch_id with a transactional or idempotent write protocol that skips an already committed batch.", "Assume foreachBatch callbacks can never run again for the same batch.", "Generate a new random primary key for every retry of every row."], "correct": 1, "explanation_ja": "foreachBatchの外部処理は再試行され得るため、同じbatch_idの効果を重複させない設計が必要である。書き込みと処理済み記録を一貫して扱うことが重要で、batch_idを受け取るだけで任意の外部システムに自動的な一回限り保証が付くわけではない。", "distractors_ja": ["チェックポイント削除は進捗を失わせ、重複防止にならない。", "正答", "同じバッチが再実行される可能性を無視している。", "ランダムキーは再試行を別データとして追加しやすくする。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.ss/api/pyspark.sql.streaming.DataStreamWriter.foreachBatch.html", "validation": "公式資料照合・未実行", "author_id": "B052", "exam": 1, "concept": "stream-reliability", "concept_label": "ストリーム再開・再実行の保証", "misconception_tags": ["確認ポイント：チェックポイント削除は進捗を失わせ、重複防止にならない。", "", "確認ポイント：同じバッチが再実行される可能性を無視している。", "確認ポイント：ランダムキーは再試行を別データとして追加しやすくする。"], "suggested_causes": ["boundary", "unknown", "knowledge", "knowledge"], "stem_ja": "foreachBatch コールバックが、受け取った行を外部データベースに挿入します。挿入後、ストリーミングのコミットが記録される前に障害が発生する可能性があります。そのバッチを再試行するときに、処理の効果が重複することを避けるのに役立つ設計はどれですか。", "options_ja": ["再起動のたびにチェックポイントを削除し、厳密に 1 回の配信を有効にする。", "batch_id を、トランザクションまたは冪等な書き込みプロトコルと組み合わせて使い、すでにコミット済みのバッチをスキップする。", "foreachBatch コールバックは同じバッチについて二度と実行されないと仮定する。", "各行を再試行するたびに、新しいランダムな主キーを生成する。"]}, {"id": "M1-42", "domain": "Architecture", "topic": "Garbage collection concept", "objective": "GCとキャッシュを区別する", "difficulty": "basic", "stem": "An executor JVM spends time in garbage collection. What is the primary purpose of JVM garbage collection in this context?", "options": ["Reclaim memory occupied by objects that are no longer reachable", "Split skewed shuffle partitions so that every task finishes together", "Increase the JVM heap beyond the configured container memory limit", "Move all frequently used DataFrame rows into a larger permanent cache"], "correct": 0, "explanation_ja": "GCは、到達不能になったオブジェクトのメモリを回収するJVMの仕組みです。shuffleの偏りを直したりCPUを増やしたりする機能ではありません。参照され続ける大量オブジェクトや高い生成頻度は、GC負荷やメモリ不足を考える手掛かりになります。", "distractors_ja": ["正答", "skew対策とは役割が異なる。", "GCが設定された物理・container資源を増やすことはない。", "GCは参照されるcacheを永久保持するための処理ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/tuning.html", "validation": "公式資料照合・未実行", "author_id": "A033", "exam": 1, "concept": "memory-diagnostics", "concept_label": "メモリ・GC・診断", "misconception_tags": ["", "確認ポイント：skew対策とは役割が異なる。", "確認ポイント：GCが設定された物理・container資源を増やすことはない。", "確認ポイント：GCは参照されるcacheを永久保持するための処理ではない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "エグゼキューターの JVM がガベージコレクションに時間を費やしています。この状況における JVM のガベージコレクションの主な目的は何ですか。", "options_ja": ["到達できなくなったオブジェクトが占有しているメモリを回収する", "偏りのあるシャッフルパーティションを分割して、すべてのタスクが同時に完了するようにする", "JVM ヒープを、設定されたコンテナのメモリ制限を超えて増やす", "頻繁に使用する DataFrame の行をすべて、より大きな永続キャッシュへ移動する"]}, {"id": "M1-43", "domain": "DataFrame", "topic": "when-default", "objective": "条件分岐に一致しない行を予測する", "difficulty": "applied", "stem": "df contains non-null integer units values [0, 4]. An engineer computes F.when(F.col(\"units\") > 0, F.lit(\"active\")).alias(\"state\") without otherwise(). What state values correspond to units 0 and 4, respectively?", "options": ["NULL and \"active\"", "\"active\" and \"active\"", "\"inactive\" and \"active\"", "An exception for units = 0"], "correct": 0, "explanation_ja": "whenの条件に一致する行には指定値が入り、一致しない行はotherwiseがなければNULLになる。暗黙にinactiveやfalseという値が設定されるわけではない。条件の境界である0を例に結果を追うと、正の値だけactiveとなることと、既定値の指定漏れを同時に確認できる。", "distractors_ja": ["正答", "units=0は正の条件を満たさない。", "otherwiseがないためinactiveという文字列は生成されない。", "条件不成立は通常NULLになり、例外にはならない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.when.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C021", "exam": 1, "concept": "null-semantics", "concept_label": "NULL・欠損値の扱い", "misconception_tags": ["", "確認ポイント：units=0は正の条件を満たさない。", "確認ポイント：otherwiseがないためinactiveという文字列は生成されない。", "確認ポイント：条件不成立は通常NULLになり、例外にはならない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "boundary"], "stem_ja": "df の整数列 units には、NULL ではない値 [0, 4] があります。エンジニアは otherwise() を付けずに F.when(F.col(\"units\") > 0, F.lit(\"active\")).alias(\"state\") を計算します。units が 0 と 4 のとき、それぞれに対応する state の値は何ですか。", "options_ja": ["NULL と \"active\"", "\"active\" と \"active\"", "\"inactive\" と \"active\"", "units = 0 で例外が発生する"]}, {"id": "M1-44", "domain": "Tuning", "topic": "Inspect cached scan", "objective": "実行計画でキャッシュ利用を確認する", "difficulty": "applied", "stem": "After persisting a reusable DataFrame, a developer inspects a downstream query plan and sees InMemoryTableScan. Which conclusion is best supported by this plan node?", "options": ["Every source file has been permanently deleted", "Every partition is guaranteed to be resident in RAM at this instant", "The plan is reading from Spark SQL's cached relation representation", "The query has been converted into a single-threaded local pandas operation"], "correct": 2, "explanation_ja": "InMemoryTableScanは、計画がキャッシュされた関係を読む形になっていることを示します。名前だけから、全パーティションが現時点でRAMへ完全常駐しているとは断定できません。保存レベルや実体化状況は別に確認し、計画表示が示す範囲を超えて推測しないようにします。", "distractors_ja": ["キャッシュ利用は元ファイル削除を意味しません。", "ディスク保存や未実体化などもあるためRAM常駐の保証ではありません。", "正答", "ローカルpandasへの変換を示すノードではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.cache.html", "validation": "公式資料照合・未実行", "author_id": "A058", "exam": 1, "concept": "cache-persist", "concept_label": "cache・persist・再利用", "misconception_tags": ["確認ポイント：キャッシュ利用は元ファイル削除を意味しません。", "確認ポイント：ディスク保存や未実体化などもあるためRAM常駐の保証ではありません。", "", "確認ポイント：ローカルpandasへの変換を示すノードではありません。"], "suggested_causes": ["knowledge", "boundary", "unknown", "knowledge"], "stem_ja": "再利用する DataFrame を永続化した後、開発者が後続のクエリプランを調べると InMemoryTableScan が見つかりました。このプランノードから最もよく裏付けられる結論はどれですか。", "options_ja": ["すべてのソースファイルが恒久的に削除されている", "この時点で、すべてのパーティションが RAM 内に存在することが保証される", "このプランは Spark SQL のキャッシュされたリレーション表現から読み込んでいる", "クエリが、単一スレッドのローカル pandas 操作に変換されている"]}, {"id": "M1-45", "domain": "Architecture", "topic": "Recomputation after loss", "objective": "lineageによる障害復旧を理解する", "difficulty": "applied", "stem": "A persisted RDD was built with deterministic transformations from an unchanged, accessible distributed file. One executor fails and its only copies of some cached partitions are lost. What can Spark normally do to obtain those partitions again?", "options": ["Recompute the missing partitions using the recorded dependencies and available input", "Recover them from the driver's automatic copy of every row", "Require the user to rewrite every transformation as SQL", "Skip the missing partitions and report a complete result"], "correct": 0, "explanation_ja": "元データと必要な依存関係が利用できれば、Sparkは失われたパーティションを再計算できます。キャッシュは元データの永続バックアップと同義ではなく、driverが全行のコピーを持つわけでもありません。問題の復旧条件を満たすことが前提です。", "distractors_ja": ["正答", "driverに全データが自動複製される仕組みではありません。", "復旧のためにAPIをSQLへ書き換える必要はありません。", "欠損分を無視すると正しい完全な結果になりません。"], "source_url": "https://spark.apache.org/docs/3.5.6/rdd-programming-guide.html", "validation": "公式資料照合・未実行", "author_id": "A006", "exam": 1, "concept": "fault-checkpoint", "concept_label": "再計算・checkpoint・耐障害性", "misconception_tags": ["", "確認ポイント：driverに全データが自動複製される仕組みではありません。", "確認ポイント：復旧のためにAPIをSQLへ書き換える必要はありません。", "確認ポイント：欠損分を無視すると正しい完全な結果になりません。"], "suggested_causes": ["unknown", "knowledge", "api", "knowledge"], "stem_ja": "永続化された RDD は、変更されておらずアクセス可能な分散ファイルから、決定的な変換によって作成されました。1 つのエグゼキューターで障害が発生し、一部のキャッシュ済みパーティションの唯一のコピーが失われました。これらのパーティションを再び取得するために、Spark は通常何ができますか。", "options_ja": ["記録された依存関係と利用可能な入力を使って、失われたパーティションを再計算する", "ドライバーが全行について自動的に保持しているコピーから復元する", "すべての変換を SQL で書き直すようユーザーに要求する", "失われたパーティションをスキップして、完全な結果として報告する"]}]}, {"id": "M2", "title": "本番形式模試 2", "questions": [{"id": "M2-01", "domain": "Tuning", "topic": "partition-sort-scope", "objective": "局所ソートと全体ソートの保証を区別する", "difficulty": "challenging", "stem": "A batch export only requires records to be ordered by event_ts within each existing partition; no global ordering across partitions is needed. Which operation expresses exactly that local sorting requirement?", "options": ["df.repartition(\"event_ts\")", "df.orderBy(\"event_ts\")", "df.sortWithinPartitions(\"event_ts\")", "df.coalesce(1)"], "correct": 2, "explanation_ja": "sortWithinPartitionsは各パーティションの内部で指定列を並べる。全体をまたぐ順序が不要な設問に対して、必要な範囲のソートを明示できる。orderByは全体順序を求める演算であり要求より強い。repartitionやcoalesceは配置や分割数を変える操作で、時刻順そのものを保証しない。", "distractors_ja": ["同じキーで配置しても各パーティションの内部順序は保証しない。", "orderByは全体順序まで要求し、指定された局所ソートだけの操作ではない。", "正答", "1パーティションにしても時刻順のソートにはならない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.sortWithinPartitions.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C060", "exam": 2, "concept": "windows-order", "concept_label": "ウィンドウ関数・順序", "misconception_tags": ["確認ポイント：同じキーで配置しても各パーティションの内部順序は保証しない。", "確認ポイント：orderByは全体順序まで要求し、指定された局所ソートだけの操作ではない。", "", "確認ポイント：1パーティションにしても時刻順のソートにはならない。"], "suggested_causes": ["boundary", "knowledge", "unknown", "boundary"], "stem_ja": "あるバッチエクスポートでは、既存の各パーティション内でレコードを event_ts 順に並べることだけが必要で、パーティションをまたぐ全体の並び順は不要です。このローカルなソート要件を正確に表す操作はどれですか。", "options_ja": ["df.repartition(\"event_ts\")", "df.orderBy(\"event_ts\")", "df.sortWithinPartitions(\"event_ts\")", "df.coalesce(1)"]}, {"id": "M2-02", "domain": "DataFrame", "topic": "left-semi-membership", "objective": "右側の存在確認だけを行う結合を選ぶ", "difficulty": "applied", "stem": "orders contains order_id, customer_id, and amount. approved contains customer_id and may have duplicate customer IDs. Return all original order rows whose customer_id appears in approved, preserving each order's multiplicity without adding approved columns. Which join type is appropriate?", "options": ["inner", "left_semi", "left", "cross"], "correct": 1, "explanation_ja": "left_semiは右側に一致する行が存在する左行だけを返し、出力列は左側に限定する。右側に同じキーが複数あっても通常のinner joinのように左行をその件数分増殖させない。左側にもともと重複がある場合、それを勝手に1行にまとめる処理でもない。", "distractors_ja": ["右側キーの重複に応じてorder行が増える可能性がある。", "正答", "不承認の顧客を持つ左行も残る。", "キーの一致を問わず直積を作る。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.join.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C011", "exam": 2, "concept": "joins", "concept_label": "結合条件・結合種類・行数", "misconception_tags": ["確認ポイント：右側キーの重複に応じてorder行が増える可能性がある。", "", "確認ポイント：不承認の顧客を持つ左行も残る。", "確認ポイント：キーの一致を問わず直積を作る。"], "suggested_causes": ["boundary", "unknown", "knowledge", "knowledge"], "stem_ja": "orders には order_id、customer_id、amount があり、approved には customer_id があります。approved には顧客 ID の重複が含まれる可能性があります。customer_id が approved に存在する元の注文行をすべて返し、各注文の出現数を維持して、approved の列は追加しません。適切な結合の種類はどれですか。", "options_ja": ["inner", "left_semi", "left", "cross"]}, {"id": "M2-03", "domain": "DataFrame", "topic": "udf-sql-registration", "objective": "Python関数をSQLから呼べるように登録する", "difficulty": "applied", "stem": "A Python function normalize_code returns a string. The engineer must call it in spark.sql as normalize_code(code) against a temporary view. Which step registers that SQL function name with its return type?", "options": ["df.createOrReplaceTempView(\"normalize_code\")", "spark.sql.register(\"normalize_code\", normalize_code)", "spark.udf.register(\"normalize_code\", normalize_code, StringType())", "F.udf.register(\"normalize_code\", normalize_code, StringType())"], "correct": 2, "explanation_ja": "SparkSessionのudf.registerでSQL名、Python関数、戻り値型を対応付けると、そのセッションのSQL式から名前で呼べる。DataFrameの一時ビュー登録は表への名前付けであり関数登録ではない。functions.udfでColumn用のUDFを作ることと、SQLの名前空間への登録も区別する。", "distractors_ja": ["表のビュー名を登録してもSQL関数にはならない。", "SparkSession.sqlはクエリ実行用メソッドでregisterを持たない。", "正答", "functions.udfは関数であり、そのregisterメソッドを使う形ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.UDFRegistration.register.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C052", "exam": 2, "concept": "python-udfs", "concept_label": "Python UDFの定義と制約", "misconception_tags": ["確認ポイント：表のビュー名を登録してもSQL関数にはならない。", "確認ポイント：SparkSession.sqlはクエリ実行用メソッドでregisterを持たない。", "", "確認ポイント：functions.udfは関数であり、そのregisterメソッドを使う形ではない。"], "suggested_causes": ["api", "api", "unknown", "api"], "stem_ja": "Python 関数 normalize_code は文字列を返します。エンジニアは、一時ビューを対象に、spark.sql 内で normalize_code(code) としてこの関数を呼び出す必要があります。この SQL 関数名を戻り値の型とともに登録する操作はどれですか。", "options_ja": ["df.createOrReplaceTempView(\"normalize_code\")", "spark.sql.register(\"normalize_code\", normalize_code)", "spark.udf.register(\"normalize_code\", normalize_code, StringType())", "F.udf.register(\"normalize_code\", normalize_code, StringType())"]}, {"id": "M2-04", "domain": "Architecture", "topic": "Unified SQL engine", "objective": "SQLとDataFrameの共通基盤を理解する", "difficulty": "applied", "stem": "A team expresses the same supported relational operation once with spark.sql and once with DataFrame methods. Which architectural statement is correct?", "options": ["Both interfaces use Spark SQL's execution engine and optimization infrastructure", "SQL queries must first convert every row to a local pandas object", "SQL always executes on the driver while DataFrame methods execute on workers", "DataFrame methods cannot use query optimization"], "correct": 0, "explanation_ja": "Spark SQLとDataFrame APIは、構造化データ処理の共通実行基盤と最適化機構を使います。表現方法が違うだけで必ず片方がdriver専用になったり、片方で最適化が無効になったりはしません。ただし、異なる式や条件では生成される計画が異なる場合があります。", "distractors_ja": ["正答", "ローカルpandasへの全件変換は必要ありません。", "どちらも分散実行され得ます。", "DataFrameもクエリ最適化の対象です。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-programming-guide.html", "validation": "公式資料照合・未実行", "author_id": "A020", "exam": 2, "concept": "query-plans", "concept_label": "SQLエンジン・実行計画・AQE", "misconception_tags": ["", "確認ポイント：ローカルpandasへの全件変換は必要ありません。", "確認ポイント：どちらも分散実行され得ます。", "確認ポイント：DataFrameもクエリ最適化の対象です。"], "suggested_causes": ["unknown", "boundary", "knowledge", "knowledge"], "stem_ja": "チームは、サポートされている同じリレーショナル操作を、一方では spark.sql で、もう一方では DataFrame のメソッドで記述します。アーキテクチャについて正しい記述はどれですか。", "options_ja": ["どちらのインターフェイスも、Spark SQL の実行エンジンと最適化基盤を使用する", "SQL クエリは、最初にすべての行をローカルの pandas オブジェクトへ変換する必要がある", "SQL は常にドライバー上で実行され、DataFrame メソッドはワーカー上で実行される", "DataFrame メソッドはクエリ最適化を利用できない"]}, {"id": "M2-05", "domain": "DataFrame", "topic": "except-all-multiplicity", "objective": "差集合の重複数を予測する", "difficulty": "challenging", "stem": "a and b each have one integer column k. a contains [2, 2, 2, 7], while b contains [2, 2, 9]. Which multiset is returned by a.exceptAll(b)? Ignore row order.", "options": ["[2, 7]", "[7]", "[9]", "[2, 2, 2, 7]"], "correct": 0, "explanation_ja": "exceptAllは各値の出現数について右側の件数を左側から差し引き、残る行を返す。2は3件から2件を引いて1件、7は1件残る。右側にしかない9は結果に含まれない。重複を除いた差集合を返すsubtractとは、同じ値が何行残るかという点が異なる。", "distractors_ja": ["正答", "重複を無視した差集合の結果でありexceptAllではない。", "左側から右側を差し引くので右側固有の9は返さない。", "右側の2が2件ある分を差し引く必要がある。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.exceptAll.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C018", "exam": 2, "concept": "sets-dedup", "concept_label": "集合演算・重複・列対応", "misconception_tags": ["", "確認ポイント：重複を無視した差集合の結果でありexceptAllではない。", "確認ポイント：左側から右側を差し引くので右側固有の9は返さない。", "確認ポイント：右側の2が2件ある分を差し引く必要がある。"], "suggested_causes": ["unknown", "boundary", "knowledge", "knowledge"], "stem_ja": "a と b は、それぞれ整数列 k を 1 つ持ちます。a には [2, 2, 2, 7]、b には [2, 2, 9] が含まれています。a.exceptAll(b) が返す多重集合はどれですか。行の順序は無視してください。", "options_ja": ["[2, 7]", "[7]", "[9]", "[2, 2, 2, 7]"]}, {"id": "M2-06", "domain": "Spark SQL", "topic": "Reader.schemaのDDL", "objective": "DDL文字列で型を固定する", "difficulty": "basic", "stem": "The input is newline-delimited JSON with fields employee_id and hired_on. Non-null hired_on values use yyyy-MM-dd, such as 2026-07-09. The required types are STRING and DATE, respectively. Which expression supplies an explicit schema to the reader?", "options": ["spark.read.option(\"header\", \"employee_id,hired_on\").json(path)", "spark.read.json(path).schema(\"employee_id STRING, hired_on DATE\")", "spark.read.schema([\"employee_id\", \"hired_on\"]).json(path)", "spark.read.schema(\"employee_id STRING, hired_on DATE\").json(path)"], "correct": 3, "explanation_ja": "DataFrameReader.schemaはStructTypeまたはDDL形式の型定義文字列を受け取る。列名のリストだけでは各列の型を指定できない。読み取った後のDataFrame.schemaはスキーマを返すプロパティであり、このように呼び出す変更メソッドではない。", "distractors_ja": ["JSONのheaderオプションで列型を宣言できない。", "DataFrame.schemaはこの形で型変更するメソッドではない。", "Reader.schemaには列名だけのPythonリストを渡さない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameReader.schema.html", "validation": "公式資料照合・未実行", "author_id": "B028", "exam": 2, "concept": "file-read-schema", "concept_label": "ファイル読込・スキーマ・形式", "misconception_tags": ["確認ポイント：JSONのheaderオプションで列型を宣言できない。", "確認ポイント：DataFrame.schemaはこの形で型変更するメソッドではない。", "確認ポイント：Reader.schemaには列名だけのPythonリストを渡さない。", ""], "suggested_causes": ["knowledge", "api", "api", "unknown"], "stem_ja": "入力は employee_id と hired_on のフィールドを持つ改行区切りの JSON です。hired_on の NULL ではない値は、2026-07-09 のような yyyy-MM-dd 形式です。必要な型は、それぞれ STRING と DATE です。リーダーに明示的なスキーマを指定する式はどれですか。", "options_ja": ["spark.read.option(\"header\", \"employee_id,hired_on\").json(path)", "spark.read.json(path).schema(\"employee_id STRING, hired_on DATE\")", "spark.read.schema([\"employee_id\", \"hired_on\"]).json(path)", "spark.read.schema(\"employee_id STRING, hired_on DATE\").json(path)"]}, {"id": "M2-07", "domain": "DataFrame", "topic": "explicit-null-sort", "objective": "NULL配置を明示した並べ替えを行う", "difficulty": "basic", "stem": "Sort tasks by deadline ascending, but place NULL deadlines after all known deadlines. Which sort expression explicitly implements this ordering?", "options": ["tasks.orderBy(F.col(\"deadline\").asc_nulls_first())", "tasks.orderBy(F.col(\"deadline\").asc_nulls_last())", "tasks.orderBy(F.col(\"deadline\").desc_nulls_last())", "tasks.orderBy(F.col(\"deadline\").isNull().desc())"], "correct": 1, "explanation_ja": "asc_nulls_lastは非NULL値を昇順で並べ、NULLを最後に配置する。日付の昇降順とNULLの配置は別々の要件として確認する。isNullだけでソートしても既知の日付間の昇順は定まらず、descを使えば日付順が逆になるため、明示的な専用メソッドが要件を直接表す。", "distractors_ja": ["NULLが先頭になり要件に反する。", "正答", "既知の日付が降順になる。", "NULL判定しか並べず、日付自体の昇順を保証しない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.Column.asc_nulls_last.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C046", "exam": 2, "concept": "null-semantics", "concept_label": "NULL・欠損値の扱い", "misconception_tags": ["確認ポイント：NULLが先頭になり要件に反する。", "", "確認ポイント：既知の日付が降順になる。", "確認ポイント：NULL判定しか並べず、日付自体の昇順を保証しない。"], "suggested_causes": ["boundary", "unknown", "knowledge", "boundary"], "stem_ja": "tasks を deadline の昇順で並べます。ただし、deadline が NULL の行は、期限が判明しているすべての行よりも後ろに配置します。この並び順を明示的に実装するソート式はどれですか。", "options_ja": ["tasks.orderBy(F.col(\"deadline\").asc_nulls_first())", "tasks.orderBy(F.col(\"deadline\").asc_nulls_last())", "tasks.orderBy(F.col(\"deadline\").desc_nulls_last())", "tasks.orderBy(F.col(\"deadline\").isNull().desc())"]}, {"id": "M2-08", "domain": "Spark SQL", "topic": "SQL集計とnull", "objective": "COUNT(*)とCOUNT列を区別する", "difficulty": "applied", "stem": "View tickets contains exactly three rows with priority values: \"high\", NULL, and \"low\". What does SELECT COUNT(*) AS total, COUNT(priority) AS tagged FROM tickets return?", "options": ["total=2, tagged=3", "total=2, tagged=2", "total=3, tagged=2", "total=3, tagged=3"], "correct": 2, "explanation_ja": "COUNT(*)はnullを含む行も行として数える。一方でCOUNT(priority)はpriorityの非null値を数えるため、結果は3と2になる。空文字列とnullも同じではなく、集計対象の式が何かを確認して判断する。", "distractors_ja": ["行数と非null値数の関係が逆である。", "COUNT(*)はpriorityがnullの行も数える。", "正答", "COUNT(priority)はnull値を数えない。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-ref-null-semantics.html", "validation": "公式資料照合・未実行", "author_id": "B032", "exam": 2, "concept": "null-semantics", "concept_label": "NULL・欠損値の扱い", "misconception_tags": ["確認ポイント：行数と非null値数の関係が逆である。", "確認ポイント：COUNT(*)はpriorityがnullの行も数える。", "", "確認ポイント：COUNT(priority)はnull値を数えない。"], "suggested_causes": ["boundary", "boundary", "unknown", "boundary"], "stem_ja": "ビュー tickets には、priority の値が \"high\"、NULL、\"low\" である、ちょうど 3 行があります。SELECT COUNT(*) AS total, COUNT(priority) AS tagged FROM tickets は何を返しますか。", "options_ja": ["total=2, tagged=3", "total=2, tagged=2", "total=3, tagged=2", "total=3, tagged=3"]}, {"id": "M2-09", "domain": "Architecture", "topic": "Local checkpoint reliability", "objective": "local checkpointと耐障害性を区別する", "difficulty": "challenging", "stem": "A batch job replaces a reliable checkpoint with localCheckpoint() to reduce checkpoint I/O. Which tradeoff must the developer understand?", "options": ["Local checkpoints are merely temporary view names and store no data", "Local checkpoints use executor caching storage and do not offer the same reliability as a checkpoint on durable storage", "Local checkpoints always create three copies in an external object store", "Local checkpoints guarantee that losing every executor has no effect"], "correct": 1, "explanation_ja": "localCheckpointはexecutor上のキャッシュ機構を利用するため、耐久ストレージへ保存するcheckpointと同等の信頼性を持ちません。論理計画を切り詰める利点と、保存先が失われるリスクを分けて考えます。速度だけで置き換えを判断すると復旧要件を満たせない場合があります。", "distractors_ja": ["計算データを保存する操作です。", "正答", "外部オブジェクトストアへ自動で3複製する仕様ではありません。", "executor上のデータが失われると影響し得ます。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.localCheckpoint.html", "validation": "公式資料照合・未実行", "author_id": "A032", "exam": 2, "concept": "fault-checkpoint", "concept_label": "再計算・checkpoint・耐障害性", "misconception_tags": ["確認ポイント：計算データを保存する操作です。", "", "確認ポイント：外部オブジェクトストアへ自動で3複製する仕様ではありません。", "確認ポイント：executor上のデータが失われると影響し得ます。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "あるバッチジョブは、チェックポイントの I/O を減らすために、信頼性の高いチェックポイントを localCheckpoint() に置き換えます。開発者が理解しておくべきトレードオフはどれですか。", "options_ja": ["ローカルチェックポイントは単なる一時ビュー名であり、データを保存しない", "ローカルチェックポイントはエグゼキューターのキャッシュストレージを使い、耐久性のあるストレージ上のチェックポイントと同じ信頼性は提供しない", "ローカルチェックポイントは、常に外部オブジェクトストアに 3 つのコピーを作成する", "ローカルチェックポイントは、すべてのエグゼキューターが失われても影響がないことを保証する"]}, {"id": "M2-10", "domain": "Structured Streaming", "topic": "AvailableNow", "objective": "利用可能データを処理して終了する", "difficulty": "applied", "stem": "A daily job must use streaming checkpoints to process all files available when it starts, allow multiple micro-batches when needed, and then terminate. Which trigger is designed for this pattern?", "options": ["Omit trigger configuration so the query stops after its first batch.", ".trigger(processingTime=\"1 day\")", ".trigger(continuous=\"1 second\")", ".trigger(availableNow=True)"], "correct": 3, "explanation_ja": "AvailableNowは開始時に利用可能な入力を必要に応じて複数のマイクロバッチで処理して終了する用途に合う。processingTimeを1日にしても処理後の自動終了にはならない。既定トリガーも継続実行なので、終了条件とは区別する。", "distractors_ja": ["既定では1バッチ後に自動停止しない。", "1日間隔の継続実行であり、今回の処理終了条件とは違う。", "継続処理方式であり、利用可能入力だけを処理して終了する指定ではない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.ss/api/pyspark.sql.streaming.DataStreamWriter.trigger.html", "validation": "公式資料照合・未実行", "author_id": "B051", "exam": 2, "concept": "stream-lifecycle", "concept_label": "ストリーム入力・開始・停止・trigger", "misconception_tags": ["確認ポイント：既定では1バッチ後に自動停止しない。", "確認ポイント：1日間隔の継続実行であり、今回の処理終了条件とは違う。", "確認ポイント：継続処理方式であり、利用可能入力だけを処理して終了する指定ではない。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "日次ジョブで、ストリーミングのチェックポイントを使って、開始時に利用可能なすべてのファイルを処理する必要があります。必要に応じて複数のマイクロバッチを使用でき、処理後は終了する必要があります。このパターンのために設計されたトリガーはどれですか。", "options_ja": ["トリガー設定を省略し、最初のバッチの後にクエリが停止するようにする。", ".trigger(processingTime=\"1 day\")", ".trigger(continuous=\"1 second\")", ".trigger(availableNow=True)"]}, {"id": "M2-11", "domain": "Pandas API", "topic": "Grouped aggregate pandas UDF", "objective": "Pandas集約UDFの呼出しを理解する", "difficulty": "applied", "stem": "values has columns team and score, with score containing non-null doubles. pandas is imported as pd. Given the function below, which expression computes one custom score mean per team?\n\n@pandas_udf('double')\ndef custom_mean(s: pd.Series) -> float:\n    return float(s.mean())", "options": ["values.groupBy('team').agg(custom_mean(col('score')).alias('mean_score'))", "values.groupBy('team').select(custom_mean('score'))", "values.agg(custom_mean('score')).groupBy('team')", "values.select(custom_mean('team', 'score').alias('mean_score'))"], "correct": 0, "explanation_ja": "Seriesを受け取りスカラーを返すPandas UDFをグループごとの集約として使うには、groupByの後でaggに適用します。関数の引数はscoreの1列です。集約で失われたteamを後からgroupByしたり、GroupedDataへselectしたりする記述は目的に合いません。", "distractors_ja": ["正答", "GroupedDataにはそのselectによる集約形式はありません。", "先に全体集約するとteam列が結果に残りません。", "定義は1引数なのに2列を渡し、team別集約にもなっていません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.GroupedData.agg.html", "validation": "公式資料照合・未実行", "author_id": "A053", "exam": 2, "concept": "pandas-udfs", "concept_label": "pandas UDF・バッチ・グループ", "misconception_tags": ["", "確認ポイント：GroupedDataにはそのselectによる集約形式はありません。", "確認ポイント：先に全体集約するとteam列が結果に残りません。", "確認ポイント：定義は1引数なのに2列を渡し、team別集約にもなっていません。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "api"], "stem_ja": "values には team と score の列があり、score には NULL ではない double 型の値が格納されています。pandas は pd としてインポートされています。次の関数を使って、チームごとに score の独自の平均値を 1 つ計算する式はどれですか。\n\n@pandas_udf('double')\ndef custom_mean(s: pd.Series) -> float:\n    return float(s.mean())", "options_ja": ["values.groupBy('team').agg(custom_mean(col('score')).alias('mean_score'))", "values.groupBy('team').select(custom_mean('score'))", "values.agg(custom_mean('score')).groupBy('team')", "values.select(custom_mean('team', 'score').alias('mean_score'))"]}, {"id": "M2-12", "domain": "DataFrame", "topic": "isin-column-expression", "objective": "複数値への一致判定を正しく書く", "difficulty": "basic", "stem": "Keep shipments whose non-null service is either \"express\" or \"overnight\". Which expression creates the intended Spark column predicate?", "options": ["F.col(\"service\").isin(\"express\", \"overnight\")", "F.col(\"service\") in [\"express\", \"overnight\"]", "F.col(\"service\") == [\"express\", \"overnight\"]", "F.col(\"service\").contains(\"express|overnight\")"], "correct": 0, "explanation_ja": "isinは列の値が指定した候補のいずれかに一致するかを表すColumn条件を作る。PythonのinはSparkの各行を分散評価する演算ではない。containsは文字列の部分一致であり、縦棒を候補区切りとして解釈する正規表現や集合への所属判定にはならない。", "distractors_ja": ["正答", "Pythonのinは各行に対するSparkの所属条件を生成しない。", "列とPythonリストの等値比較は候補ごとの一致判定ではない。", "縦棒を含む文字列の部分一致になり、候補集合の判定ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.Column.isin.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C023", "exam": 2, "concept": "column-expressions", "concept_label": "列式・射影・列名操作", "misconception_tags": ["", "確認ポイント：Pythonのinは各行に対するSparkの所属条件を生成しない。", "確認ポイント：列とPythonリストの等値比較は候補ごとの一致判定ではない。", "確認ポイント：縦棒を含む文字列の部分一致になり、候補集合の判定ではない。"], "suggested_causes": ["unknown", "knowledge", "api", "knowledge"], "stem_ja": "NULL ではない service の値が \"express\" または \"overnight\" である配送行を残します。意図した Spark の列条件式を作成する式はどれですか。", "options_ja": ["F.col(\"service\").isin(\"express\", \"overnight\")", "F.col(\"service\") in [\"express\", \"overnight\"]", "F.col(\"service\") == [\"express\", \"overnight\"]", "F.col(\"service\").contains(\"express|overnight\")"]}, {"id": "M2-13", "domain": "Spark Connect", "topic": "Connect request protocol", "objective": "Connectの要求通信を理解する", "difficulty": "basic", "stem": "A Python client uses Spark Connect to select columns and filter a remote DataFrame. What does the client send to the Spark Connect server to describe these operations?", "options": ["JVM bytecode that the Python client has compiled for each executor", "A finalized physical plan that the server is forbidden to optimize", "The complete source dataset in a Python pickle for every select call", "Unresolved logical plans encoded with Protocol Buffers and transported using gRPC"], "correct": 3, "explanation_ja": "Spark ConnectのクライアントはDataFrame操作を未解決の論理計画として表現し、Protocol BuffersとgRPCを使ってサーバーへ送ります。サーバー側で解析・最適化・実行が進みます。クライアントが最終物理計画を確定して押し付ける構造ではありません。", "distractors_ja": ["Pythonクライアントがexecutor向けJVMコードを毎回作る説明は誤りです。", "サーバー側の最適化が行われます。", "各select呼出しで元データ全体を転送する方式ではありません。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/spark-connect-overview.html", "validation": "公式資料照合・未実行", "author_id": "A037", "exam": 2, "concept": "connect-protocol", "concept_label": "Spark Connectの構成・通信", "misconception_tags": ["確認ポイント：Pythonクライアントがexecutor向けJVMコードを毎回作る説明は誤りです。", "確認ポイント：サーバー側の最適化が行われます。", "確認ポイント：各select呼出しで元データ全体を転送する方式ではありません。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "Python クライアントが Spark Connect を使用して、リモートの DataFrame の列を選択し、行をフィルタリングします。これらの操作を記述するために、クライアントは Spark Connect サーバーへ何を送信しますか。", "options_ja": ["Python クライアントがエグゼキューターごとにコンパイルした JVM バイトコード", "サーバーが最適化することを禁止された、確定済みの物理プラン", "select を呼び出すたびに、Python の pickle 形式にしたソースデータセット全体", "Protocol Buffers でエンコードされ、gRPC で転送される未解決の論理プラン"]}, {"id": "M2-14", "domain": "Architecture", "topic": "Collect result location", "objective": "collect後のデータ所在を判断する", "difficulty": "basic", "stem": "A small batch DataFrame is evaluated with rows = df.collect(). What is rows in classic PySpark?", "options": ["A list containing one executor process per partition", "A local Python list of Row objects returned to the driver", "A permanently registered Spark SQL table", "A new distributed DataFrame with the same partitioning"], "correct": 1, "explanation_ja": "collectはDataFrameの全行をRowオブジェクトのPythonリストとしてdriverへ返します。結果は分散DataFrameではありません。少量なら便利ですが、データ規模に関係なく安全に使えると考えるのは誤りで、driver側に全結果を保持できるか判断が必要です。", "distractors_ja": ["返るのはデータの行でありプロセスではありません。", "正答", "テーブル登録は行われません。", "collectの戻り値はDataFrameではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.collect.html", "validation": "公式資料照合・未実行", "author_id": "A029", "exam": 2, "concept": "driver-collection", "concept_label": "driverへの収集とメモリ", "misconception_tags": ["確認ポイント：返るのはデータの行でありプロセスではありません。", "", "確認ポイント：テーブル登録は行われません。", "確認ポイント：collectの戻り値はDataFrameではありません。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "小規模なバッチ DataFrame を rows = df.collect() で評価します。従来型 PySpark では rows は何ですか。", "options_ja": ["パーティションごとに 1 つのエグゼキュータープロセスを含むリスト", "ドライバーへ返された Row オブジェクトからなる、ローカルの Python リスト", "永続的に登録された Spark SQL テーブル", "同じパーティション構成を持つ、新しい分散 DataFrame"]}, {"id": "M2-15", "domain": "Architecture", "topic": "DataFrame cache default", "objective": "DataFrameの既定保存レベルを識別する", "difficulty": "basic", "stem": "In PySpark 3.5.x, an uncached batch DataFrame is persisted by calling df.cache() without specifying a storage level. Which named storage level is the default?", "options": ["DISK_ONLY", "MEMORY_AND_DISK_DESER", "MEMORY_ONLY", "OFF_HEAP"], "correct": 1, "explanation_ja": "PySpark 3.5系のDataFrame.cacheの既定はMEMORY_AND_DISK_DESERです。RDDのcacheに関する説明や、古い教材のMEMORY_ONLYという記述をそのままDataFrameへ当てはめないでください。保存レベルの問題では、対象APIとSparkバージョンを最初に確認します。", "distractors_ja": ["ディスクだけを使う既定ではありません。", "正答", "RDDの既定との混同に注意が必要です。", "off-heapを既定で選ぶ操作ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.cache.html", "validation": "公式資料照合・未実行", "author_id": "A010", "exam": 2, "concept": "cache-persist", "concept_label": "cache・persist・再利用", "misconception_tags": ["確認ポイント：ディスクだけを使う既定ではありません。", "", "確認ポイント：RDDの既定との混同に注意が必要です。", "確認ポイント：off-heapを既定で選ぶ操作ではありません。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "PySpark 3.5.x で、まだキャッシュされていないバッチ DataFrame に対し、ストレージレベルを指定せずに df.cache() を呼び出して永続化します。既定のストレージレベル名はどれですか。", "options_ja": ["DISK_ONLY", "MEMORY_AND_DISK_DESER", "MEMORY_ONLY", "OFF_HEAP"]}, {"id": "M2-16", "domain": "Spark Connect", "topic": "Connect unsupported APIs", "objective": "Connect移行時の非対応APIを識別する", "difficulty": "applied", "stem": "A classic PySpark application uses df.rdd.map(custom_function). The team is migrating to Spark Connect 3.5.x. What is the relevant compatibility concern?", "options": ["The RDD API is not supported by Spark Connect; the logic needs a supported API design", "The DataFrame select method is unavailable in all Spark Connect clients", "Spark Connect can execute only SQL strings, never DataFrame operations", "Renaming the Python variable rdd to dataframe makes the call supported"], "correct": 0, "explanation_ja": "Spark Connect 3.5系ではRDD APIとSparkContext APIは対応対象ではありません。DataFrame API中心へ処理を見直し、個々のAPIの対応表示を確認します。Python変数の名前変更ではAPIの種類は変わらず、RDD操作をそのまま使えるようにはなりません。", "distractors_ja": ["正答", "selectなど多くのDataFrame APIは対応しています。", "DataFrame APIはSpark Connectの中心的なインターフェースです。", "変数名を変更してもRDD APIの非対応は解消しません。"], "source_url": "https://spark.apache.org/docs/3.5.6/spark-connect-overview.html", "validation": "公式資料照合・未実行", "author_id": "A039", "exam": 2, "concept": "connect-api", "concept_label": "Spark Connectの接続方法・制約", "misconception_tags": ["", "確認ポイント：selectなど多くのDataFrame APIは対応しています。", "確認ポイント：DataFrame APIはSpark Connectの中心的なインターフェースです。", "確認ポイント：変数名を変更してもRDD APIの非対応は解消しません。"], "suggested_causes": ["unknown", "api", "api", "api"], "stem_ja": "従来型の PySpark アプリケーションで df.rdd.map(custom_function) を使用しています。チームは Spark Connect 3.5.x へ移行しています。関連する互換性上の懸念は何ですか。", "options_ja": ["Spark Connect は RDD API に対応していないため、対応する API を使った処理設計が必要である", "DataFrame の select メソッドは、どの Spark Connect クライアントでも利用できない", "Spark Connect は SQL 文字列だけを実行でき、DataFrame 操作は実行できない", "Python 変数 rdd の名前を dataframe に変更すれば、この呼び出しがサポートされる"]}, {"id": "M2-17", "domain": "DataFrame", "topic": "drop-multiple-columns", "objective": "複数の不要列を取り除く", "difficulty": "basic", "stem": "df contains order_id, raw_payload, debug_flag, and amount. Remove raw_payload and debug_flag and retain the other columns. Which call uses the DataFrame.drop API correctly?", "options": ["df.drop([\"raw_payload\", \"debug_flag\"])", "df.drop(\"raw_payload, debug_flag\")", "df.select(\"raw_payload\", \"debug_flag\")", "df.drop(\"raw_payload\", \"debug_flag\")"], "correct": 3, "explanation_ja": "dropは取り除く列名を可変長引数として受け取るため、2つの文字列を別々の引数として渡す。カンマを含む1本の文字列は単一の列名であり、列のリストという意味にはならない。selectは指定列を残す処理なので、この要件では残す列と削除する列の向きが逆になる。", "distractors_ja": ["dropに列名リストを単一引数として渡す形はこのAPIの指定方法ではない。", "カンマを含む単一の列名として扱われる。", "削除対象の2列だけを残してしまう。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.drop.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C045", "exam": 2, "concept": "column-expressions", "concept_label": "列式・射影・列名操作", "misconception_tags": ["確認ポイント：dropに列名リストを単一引数として渡す形はこのAPIの指定方法ではない。", "確認ポイント：カンマを含む単一の列名として扱われる。", "確認ポイント：削除対象の2列だけを残してしまう。", ""], "suggested_causes": ["api", "knowledge", "knowledge", "unknown"], "stem_ja": "df には order_id、raw_payload、debug_flag、amount が含まれています。raw_payload と debug_flag を削除し、それ以外の列を残します。DataFrame.drop API を正しく使用している呼び出しはどれですか。", "options_ja": ["df.drop([\"raw_payload\", \"debug_flag\"])", "df.drop(\"raw_payload, debug_flag\")", "df.select(\"raw_payload\", \"debug_flag\")", "df.drop(\"raw_payload\", \"debug_flag\")"]}, {"id": "M2-18", "domain": "DataFrame", "topic": "between-inclusive", "objective": "betweenの境界を理解する", "difficulty": "basic", "stem": "df has integer values [4, 5, 9, 10] in age. Which values remain after df.filter(F.col(\"age\").between(5, 9))? Ignore order.", "options": ["[5]", "[5, 9]", "[]", "[4, 5, 9, 10]"], "correct": 1, "explanation_ja": "Column.betweenは下限と上限を両方含む範囲条件であり、age>=5かつage<=9に相当する。そのため境界値5と9が残り、4と10が除外される。Pythonのrangeの上限が含まれないことと混同せず、SQLのBETWEENと同じ両端を含む比較として考える。", "distractors_ja": ["上限9も含まれる。", "正答", "両境界を除外する条件ではない。", "下限未満の4と上限超過の10は除外される。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.Column.between.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C022", "exam": 2, "concept": "column-expressions", "concept_label": "列式・射影・列名操作", "misconception_tags": ["確認ポイント：上限9も含まれる。", "", "確認ポイント：両境界を除外する条件ではない。", "確認ポイント：下限未満の4と上限超過の10は除外される。"], "suggested_causes": ["boundary", "unknown", "boundary", "boundary"], "stem_ja": "df の age には整数値 [4, 5, 9, 10] があります。df.filter(F.col(\"age\").between(5, 9)) の後に残る値はどれですか。順序は無視してください。", "options_ja": ["[5]", "[5, 9]", "[]", "[4, 5, 9, 10]"]}, {"id": "M2-19", "domain": "Structured Streaming", "topic": "クエリ状態と停止", "objective": "StreamingQueryの停止と待機を区別する", "difficulty": "basic", "stem": "A running StreamingQuery is stored in q. A shutdown handler must request termination of this query. Which call performs that request, rather than merely waiting for termination?", "options": ["q.lastProgress", "q.stop()", "q.awaitTermination()", "q.isActive"], "correct": 1, "explanation_ja": "stopは実行中のStreamingQueryを停止するためのメソッドである。awaitTerminationは終了を待機するもので、呼んだだけで停止を要求するわけではない。isActiveとlastProgressは状態を参照するための情報である。", "distractors_ja": ["直近の進捗情報を参照するプロパティである。", "正答", "終了待機であり、停止要求そのものではない。", "実行中かどうかを返すプロパティである。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.ss/api/pyspark.sql.streaming.StreamingQuery.stop.html", "validation": "公式資料照合・未実行", "author_id": "B046", "exam": 2, "concept": "stream-lifecycle", "concept_label": "ストリーム入力・開始・停止・trigger", "misconception_tags": ["確認ポイント：直近の進捗情報を参照するプロパティである。", "", "確認ポイント：終了待機であり、停止要求そのものではない。", "確認ポイント：実行中かどうかを返すプロパティである。"], "suggested_causes": ["api", "unknown", "knowledge", "api"], "stem_ja": "実行中の StreamingQuery が q に格納されています。シャットダウンハンドラーは、このクエリの終了を要求する必要があります。終了を待つだけではなく、終了を要求する呼び出しはどれですか。", "options_ja": ["q.lastProgress", "q.stop()", "q.awaitTermination()", "q.isActive"]}, {"id": "M2-20", "domain": "Spark SQL", "topic": "SQLの識別子", "objective": "ドットを含む列名を正しく引用する", "difficulty": "applied", "stem": "View telemetry has a top-level column literally named sensor.id, with no struct column named sensor. Which SQL selects that column?", "options": ["SELECT `sensor.id` FROM telemetry", "SELECT sensor[id] FROM telemetry", "SELECT sensor.id FROM telemetry", "SELECT 'sensor.id' FROM telemetry"], "correct": 0, "explanation_ja": "バッククォートは列名などの識別子を囲む。ドットも含めて引用すれば、sensorという構造体のidフィールドではなく、文字どおりsensor.idというトップレベル列を指定できる。単一引用符は文字列値を表すため別物である。", "distractors_ja": ["正答", "添字アクセスの形であり指定されたトップレベル列ではない。", "ドットが修飾名やフィールド参照として解釈される。", "各行に定数文字列を返し、対象列を取得しない。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-ref-identifier.html", "validation": "公式資料照合・未実行", "author_id": "B030", "exam": 2, "concept": "column-expressions", "concept_label": "列式・射影・列名操作", "misconception_tags": ["", "確認ポイント：添字アクセスの形であり指定されたトップレベル列ではない。", "確認ポイント：ドットが修飾名やフィールド参照として解釈される。", "確認ポイント：各行に定数文字列を返し、対象列を取得しない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "ビュー telemetry には、文字どおり sensor.id という名前のトップレベル列があり、sensor という名前の構造体列はありません。その列を選択する SQL はどれですか。", "options_ja": ["SELECT `sensor.id` FROM telemetry", "SELECT sensor[id] FROM telemetry", "SELECT sensor.id FROM telemetry", "SELECT 'sensor.id' FROM telemetry"]}, {"id": "M2-21", "domain": "DataFrame", "topic": "concat-ws-null", "objective": "区切り付き連結のNULL動作を予測する", "difficulty": "applied", "stem": "A row has first_name=\"Mira\", middle_name=NULL, and last_name=\"Chen\". What does F.concat_ws(\" \", \"first_name\", \"middle_name\", \"last_name\") return?", "options": ["\"Mira Chen\"", "\"Mira NULL Chen\"", "\"Mira  Chen\"", "NULL"], "correct": 0, "explanation_ja": "concat_wsは指定した区切りで非NULLの文字列を連結し、NULLの入力を読み飛ばす。そのためこの例では空の中間要素用の余分な区切りは入らず、Mira Chenになる。NULLと空文字列は同じではなく、空文字列が存在する場合の区切りの出方とは区別して考える。", "distractors_ja": ["正答", "NULLという文字列へ暗黙変換する動作ではない。", "NULLを空文字列の要素として保持している。", "concat_wsはNULL入力を飛ばして残りを連結する。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-ref-functions-builtin.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C027", "exam": 2, "concept": "string-date-functions", "concept_label": "文字列・日付関数", "misconception_tags": ["", "確認ポイント：NULLという文字列へ暗黙変換する動作ではない。", "確認ポイント：NULLを空文字列の要素として保持している。", "確認ポイント：concat_wsはNULL入力を飛ばして残りを連結する。"], "suggested_causes": ["unknown", "boundary", "boundary", "boundary"], "stem_ja": "ある行は first_name=\"Mira\"、middle_name=NULL、last_name=\"Chen\" です。F.concat_ws(\" \", \"first_name\", \"middle_name\", \"last_name\") は何を返しますか。", "options_ja": ["\"Mira Chen\"", "\"Mira NULL Chen\"", "\"Mira  Chen\"", "NULL"]}, {"id": "M2-22", "domain": "Tuning", "topic": "builtins-over-python-udf", "objective": "既存関数で表現できる変換を選ぶ", "difficulty": "applied", "stem": "A Python scalar UDF is used only to trim leading/trailing spaces and convert a string to lower case. Built-in functions have the required semantics for the data. Which rewrite removes the unnecessary Python UDF execution boundary?", "options": ["df.collect() and a Python for loop on the driver", "df.toPandas().assign(clean=lambda p: p.raw.str.strip().str.lower())", "df.withColumn(\"clean\", F.lower(F.trim(\"raw\")))", "df.withColumn(\"clean\", F.udf(lambda s: s.strip().lower(), StringType())(\"raw\"))"], "correct": 2, "explanation_ja": "同じ意味を組み込みのtrimとlowerで表せるなら、列式として構成することで通常のPython UDF呼び出しを避けられる。Sparkの式として最適化・実行でき、不要なPythonとの受け渡しを減らせる。driverへ全件を移す方法は分散処理の利点を失うため、要件に対する適切な置換ではない。", "distractors_ja": ["全件をdriverに取得するため元の目的を満たす改善ではない。", "全件をdriver側のpandasへ移しており分散DataFrame変換ではない。", "正答", "記述を短くしてもPython scalar UDFであることは変わらない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.udf.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C058", "exam": 2, "concept": "python-udfs", "concept_label": "Python UDFの定義と制約", "misconception_tags": ["確認ポイント：全件をdriverに取得するため元の目的を満たす改善ではない。", "確認ポイント：全件をdriver側のpandasへ移しており分散DataFrame変換ではない。", "", "確認ポイント：記述を短くしてもPython scalar UDFであることは変わらない。"], "suggested_causes": ["boundary", "boundary", "unknown", "knowledge"], "stem_ja": "Python のスカラー UDF が、文字列の先頭と末尾の空白を除去し、小文字に変換することだけに使われています。組み込み関数で、このデータに必要な処理の意味を満たせます。不要な Python UDF の実行境界をなくす書き換えはどれですか。", "options_ja": ["df.collect() と、ドライバー上の Python の for ループ", "df.toPandas().assign(clean=lambda p: p.raw.str.strip().str.lower())", "df.withColumn(\"clean\", F.lower(F.trim(\"raw\")))", "df.withColumn(\"clean\", F.udf(lambda s: s.strip().lower(), StringType())(\"raw\"))"]}, {"id": "M2-23", "domain": "Tuning", "topic": "Release unused cache", "objective": "不要キャッシュを解放して資源を使う", "difficulty": "applied", "stem": "A long-running application has finished every report that uses a cached batch DataFrame old_report. The source remains available, and later phases need memory for different data. Which change directly releases old_report's cached blocks while keeping the application running?", "options": ["Cache old_report again with another Python variable name", "Call spark.stop() before the later phases", "Call old_report.unpersist() after its final use", "Call old_report.alias('released')"], "correct": 2, "explanation_ja": "使い終えたDataFrameをunpersistすれば、キャッシュとして保持しているブロックを解放できます。長時間動くアプリケーションでは再利用が終わった保存データを残し続けないことが大切です。アプリケーション全体を止めたり、Python上の名前だけを変えたりする必要はありません。", "distractors_ja": ["別名を付けても不要な保存領域は解放されません。", "後続処理を続ける要件に反します。", "正答", "aliasはキャッシュを解放しません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.unpersist.html", "validation": "公式資料照合・未実行", "author_id": "A056", "exam": 2, "concept": "cache-persist", "concept_label": "cache・persist・再利用", "misconception_tags": ["確認ポイント：別名を付けても不要な保存領域は解放されません。", "確認ポイント：後続処理を続ける要件に反します。", "", "確認ポイント：aliasはキャッシュを解放しません。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "長時間実行するアプリケーションで、キャッシュ済みバッチ DataFrame old_report を使うすべてのレポートが完了しました。ソースは引き続き利用可能で、後のフェーズでは別のデータにメモリが必要です。アプリケーションを実行し続けながら old_report のキャッシュ済みブロックを直接解放する変更はどれですか。", "options_ja": ["別の Python 変数名を使って old_report を再びキャッシュする", "後のフェーズに入る前に spark.stop() を呼び出す", "最後の使用後に old_report.unpersist() を呼び出す", "old_report.alias('released') を呼び出す"]}, {"id": "M2-24", "domain": "DataFrame", "topic": "split-regex-delimiter", "objective": "正規表現の区切り文字をエスケープする", "difficulty": "applied", "stem": "The column route contains \"north|central|south\". Which expression produces the array [\"north\", \"central\", \"south\"] by treating the vertical bar as a literal delimiter?", "options": ["F.split(\"route\", \"-\")", "F.array(\"route\")", "F.split(\"route\", r\".\")", "F.split(\"route\", r\"\\|\")"], "correct": 3, "explanation_ja": "splitの区切りは正規表現として扱われる。縦棒は正規表現で特別な意味を持つので、リテラルとして使うにはエスケープしたパターンを渡す。raw文字列r\"\\|\"ならPython側のエスケープ処理との混同を減らせる。arrayは文字列全体を1要素に包むだけで分割しない。", "distractors_ja": ["ハイフンが含まれないので期待どおりに分割されない。", "文字列全体を1要素にするだけである。", "ドットは任意の1文字を表し、縦棒だけの分割にならない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.split.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C025", "exam": 2, "concept": "string-date-functions", "concept_label": "文字列・日付関数", "misconception_tags": ["確認ポイント：ハイフンが含まれないので期待どおりに分割されない。", "確認ポイント：文字列全体を1要素にするだけである。", "確認ポイント：ドットは任意の1文字を表し、縦棒だけの分割にならない。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "route列には\"north|central|south\"が格納されています。縦棒をリテラルの区切り文字として扱い、配列[\"north\", \"central\", \"south\"]を生成する式はどれですか。", "options_ja": ["F.split(\"route\", \"-\")", "F.array(\"route\")", "F.split(\"route\", r\".\")", "F.split(\"route\", r\"\\|\")"]}, {"id": "M2-25", "domain": "Architecture", "topic": "Write as action", "objective": "保存もactionであることを理解する", "difficulty": "applied", "stem": "A developer builds a transformed batch DataFrame and calls result.write.mode('overwrite').parquet(target). The call does not return all result rows to Python. Why can it still trigger distributed computation?", "options": ["Only collect can trigger distributed computation, so the write does no work", "Every transformation runs eagerly whenever a path variable exists", "An action may materialize results in an external sink instead of returning rows to the driver", "Writing Parquet converts the DataFrame to an RDD of local filenames first"], "correct": 2, "explanation_ja": "actionはdriverへ結果行を返す操作だけではありません。ファイルへのwriteも結果を実体化する要求であり、必要な分散計算が実行されます。戻り値が全行のリストでないことを理由に、writeを遅延変換だと判断しないことが重要です。", "distractors_ja": ["保存などcollect以外のactionもあります。", "パス変数の存在が変換を実行する理由ではありません。", "正答", "そのような必須変換手順はありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameWriter.parquet.html", "validation": "公式資料照合・未実行", "author_id": "A028", "exam": 2, "concept": "execution-model", "concept_label": "遅延評価・action・実行単位", "misconception_tags": ["確認ポイント：保存などcollect以外のactionもあります。", "確認ポイント：パス変数の存在が変換を実行する理由ではありません。", "", "確認ポイント：そのような必須変換手順はありません。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "開発者は変換を適用したバッチDataFrameを作成し、result.write.mode('overwrite').parquet(target)を呼び出します。この呼び出しは結果の全行をPythonに返しません。それでも分散計算を開始できるのはなぜですか。", "options_ja": ["分散計算を開始できるのはcollectだけなので、書き込みでは処理が行われない", "パス変数が存在すると、すべての変換が常に即時実行される", "アクションは行をドライバーに返す代わりに、外部シンクに結果を実体化する場合がある", "Parquetへの書き込みでは、最初にDataFrameをローカルファイル名のRDDに変換する"]}, {"id": "M2-26", "domain": "Structured Streaming", "topic": "ストリーミング入力", "objective": "明示スキーマでファイルストリームを作る", "difficulty": "applied", "stem": "New JSON Lines files arrive in /incoming/readings. The required schema is sensor STRING, event_ts TIMESTAMP, value DOUBLE. Schema inference for streaming file sources is not enabled. Which expression creates a streaming DataFrame?", "options": ["spark.readStream.json(\"/incoming/readings\").schema(\"sensor STRING, event_ts TIMESTAMP, value DOUBLE\")", "spark.readStream.option(\"inferSchema\", True).json(\"/incoming/readings\")", "spark.read.schema(\"sensor STRING, event_ts TIMESTAMP, value DOUBLE\").json(\"/incoming/readings\")", "spark.readStream.schema(\"sensor STRING, event_ts TIMESTAMP, value DOUBLE\").json(\"/incoming/readings\")"], "correct": 3, "explanation_ja": "継続入力を表すにはreadStreamを使い、読み取り前にschemaを指定する。readは既存ファイルを対象とするバッチDataFrameである。今回の条件ではファイルストリームのスキーマ推論は有効化されておらず、型を明示して安定させる。", "distractors_ja": ["読み取り後のschemaは呼び出して設定するメソッドではない。", "このReaderオプションだけで前提の設定を満たす明示スキーマにはならない。", "readなのでストリーミングDataFrameにならない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.ss/api/pyspark.sql.streaming.DataStreamReader.schema.html", "validation": "公式資料照合・未実行", "author_id": "B037", "exam": 2, "concept": "stream-lifecycle", "concept_label": "ストリーム入力・開始・停止・trigger", "misconception_tags": ["確認ポイント：読み取り後のschemaは呼び出して設定するメソッドではない。", "確認ポイント：このReaderオプションだけで前提の設定を満たす明示スキーマにはならない。", "確認ポイント：readなのでストリーミングDataFrameにならない。", ""], "suggested_causes": ["api", "knowledge", "knowledge", "unknown"], "stem_ja": "新しいJSON Linesファイルが/incoming/readingsに到着します。必要なスキーマはsensor STRING, event_ts TIMESTAMP, value DOUBLEです。ストリーミングファイルソースのスキーマ推論は有効になっていません。ストリーミングDataFrameを作成する式はどれですか。", "options_ja": ["spark.readStream.json(\"/incoming/readings\").schema(\"sensor STRING, event_ts TIMESTAMP, value DOUBLE\")", "spark.readStream.option(\"inferSchema\", True).json(\"/incoming/readings\")", "spark.read.schema(\"sensor STRING, event_ts TIMESTAMP, value DOUBLE\").json(\"/incoming/readings\")", "spark.readStream.schema(\"sensor STRING, event_ts TIMESTAMP, value DOUBLE\").json(\"/incoming/readings\")"]}, {"id": "M2-27", "domain": "Tuning", "topic": "driverへの全件収集", "objective": "collectによるdriverメモリ不足を防ぐ", "difficulty": "applied", "stem": "A distributed transformation succeeds, but calling result.collect() on a multi-gigabyte result exhausts driver memory. The actual requirement is to store the result for downstream processing. Which change most directly removes this collection bottleneck?", "options": ["Call result.repartition(1000).collect() so the Python list remains distributed.", "Write result to a distributed storage sink instead of collecting all rows into a driver-side list.", "Cache result and then collect the same complete result twice.", "Increase the executor count while still collecting every row into the same driver."], "correct": 1, "explanation_ja": "collectは全結果をdriver側のリストに集めるため、Executorを増やしても最終的なdriverの収容量は変わらない。保存が目的なら分散writeを使えば全件収集を避けられる。repartition後もcollectの戻り値はdriverに集まる。", "distractors_ja": ["collectのPythonリストはdriver側で作られる。", "正答", "キャッシュは全件収集のメモリ要件を解消しない。", "driverが保持する全結果のサイズは減らない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.collect.html", "validation": "公式資料照合・未実行", "author_id": "B058", "exam": 2, "concept": "driver-collection", "concept_label": "driverへの収集とメモリ", "misconception_tags": ["確認ポイント：collectのPythonリストはdriver側で作られる。", "", "確認ポイント：キャッシュは全件収集のメモリ要件を解消しない。", "確認ポイント：driverが保持する全結果のサイズは減らない。"], "suggested_causes": ["api", "unknown", "boundary", "knowledge"], "stem_ja": "分散変換は成功しますが、数GBの結果に対してresult.collect()を呼び出すと、ドライバーのメモリが不足します。実際の要件は、後続の処理用に結果を保存することです。この全件収集によるボトルネックを最も直接的に解消する変更はどれですか。", "options_ja": ["Pythonのリストが分散されたままになるように、result.repartition(1000).collect()を呼び出す。", "すべての行をドライバー側のリストに収集する代わりに、resultを分散ストレージのシンクに書き込む。", "resultをキャッシュしてから、同じ結果全体を2回collectする。", "すべての行を同じドライバーに収集することは維持し、エグゼキューター数を増やす。"]}, {"id": "M2-28", "domain": "Architecture", "topic": "Checkpoint lineage", "objective": "長い論理計画を短くする方法を識別する", "difficulty": "applied", "stem": "An iterative batch algorithm produces an increasingly long DataFrame logical plan. A reliable checkpoint directory is configured. Which operation specifically returns a DataFrame with a truncated logical plan backed by checkpoint files?", "options": ["df.checkpoint(eager=True)", "df.withColumnRenamed('id', 'id')", "df.alias('short_plan')", "df.printSchema()"], "correct": 0, "explanation_ja": "checkpointは計算結果をcheckpointディレクトリへ保存し、返すDataFrameの論理計画を切り詰められます。反復処理で計画が長大化した場面が代表例です。aliasや列名変更は新しい名前を付ける操作で、依存する計画全体をcheckpointへ置き換えるものではありません。", "distractors_ja": ["正答", "同名への変更では論理計画を切り詰めません。", "aliasは計画を永続checkpointへ置き換えません。", "printSchemaは型情報を表示するだけです。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.checkpoint.html", "validation": "公式資料照合・未実行", "author_id": "A031", "exam": 2, "concept": "fault-checkpoint", "concept_label": "再計算・checkpoint・耐障害性", "misconception_tags": ["", "確認ポイント：同名への変更では論理計画を切り詰めません。", "確認ポイント：aliasは計画を永続checkpointへ置き換えません。", "確認ポイント：printSchemaは型情報を表示するだけです。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "反復型のバッチアルゴリズムにより、DataFrameの論理計画が次第に長くなっています。信頼性のあるチェックポイントディレクトリは設定済みです。チェックポイントファイルを基盤とし、論理計画が切り詰められたDataFrameを返す操作はどれですか。", "options_ja": ["df.checkpoint(eager=True)", "df.withColumnRenamed('id', 'id')", "df.alias('short_plan')", "df.printSchema()"]}, {"id": "M2-29", "domain": "Tuning", "topic": "Garbage collection diagnosis", "objective": "GC負荷の根拠を調べる", "difficulty": "applied", "stem": "An executor shows high CPU usage but makes little task progress. The suspected cause is excessive JVM garbage collection. What evidence most directly tests that hypothesis?", "options": ["Only the size of the source files before filtering", "Executor GC time metrics and GC log records during the slow period", "Only the driver task-scheduling delay, ignoring executor JVM metrics", "Only the number of output partitions after the job has finished"], "correct": 1, "explanation_ja": "GCが原因かを調べるには、遅い時間帯のexecutorのGC時間やGCログを確認します。仮説に直接対応する測定値を集めてから、オブジェクト数やキャッシュ量などの対策を考えます。CPUが高いという観察だけでは、計算処理とGCのどちらに時間を使ったか確定できません。", "distractors_ja": ["入力サイズだけではGCがCPUを消費している証拠にならない。", "正答", "driverの遅延だけではexecutor内GCを特定できない。", "出力partition数だけでは実行中GC時間が分からない。"], "source_url": "https://spark.apache.org/docs/3.5.6/tuning.html", "validation": "公式資料照合・未実行", "author_id": "A057", "exam": 2, "concept": "memory-diagnostics", "concept_label": "メモリ・GC・診断", "misconception_tags": ["確認ポイント：入力サイズだけではGCがCPUを消費している証拠にならない。", "", "確認ポイント：driverの遅延だけではexecutor内GCを特定できない。", "確認ポイント：出力partition数だけでは実行中GC時間が分からない。"], "suggested_causes": ["knowledge", "unknown", "boundary", "knowledge"], "stem_ja": "あるエグゼキューターはCPU使用率が高い一方、タスク処理はほとんど進んでいません。JVMのガベージコレクションが過剰に発生していることが原因として疑われています。この仮説を最も直接的に検証する証拠はどれですか。", "options_ja": ["フィルター適用前のソースファイルのサイズだけ", "処理が遅い時間帯のエグゼキューターのGC時間メトリクスとGCログの記録", "エグゼキューターのJVMメトリクスを無視した、ドライバーのタスクスケジューリング遅延だけ", "ジョブが完了した後の出力パーティション数だけ"]}, {"id": "M2-30", "domain": "DataFrame", "topic": "union-position", "objective": "unionの列対応と重複保持を予測する", "difficulty": "applied", "stem": "a has integer columns [planned, actual] and row (6, 9). b has integer columns [actual, planned] and row (8, 5). What rows does a.union(b) contain, interpreted under output columns [planned, actual]? Ignore row order.", "options": ["Only (6, 9)", "(6, 9) and (5, 8)", "(6, 9) and (8, 5)", "An error solely because the column names have different orders"], "correct": 2, "explanation_ja": "DataFrame.unionは列名でなく列の位置を対応付ける。型が一致するこの例では右の第1列8がplanned、第2列5がactualになる。名前に従って対応させたいならunionByNameを用いる。またDataFrame.unionは重複行を自動削除しない点もSQLのUNIONとの混同に注意する。", "distractors_ja": ["右DataFrameの行も追加される。", "列名で対応するunionByNameの結果である。", "正答", "対応位置の型が一致しており、名前順だけでエラーにはならない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.union.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C016", "exam": 2, "concept": "sets-dedup", "concept_label": "集合演算・重複・列対応", "misconception_tags": ["確認ポイント：右DataFrameの行も追加される。", "確認ポイント：列名で対応するunionByNameの結果である。", "", "確認ポイント：対応位置の型が一致しており、名前順だけでエラーにはならない。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "aは整数列[planned, actual]を持ち、行は(6, 9)です。bは整数列[actual, planned]を持ち、行は(8, 5)です。a.union(b)の出力列を[planned, actual]として解釈すると、どの行が含まれますか。行の順序は無視してください。", "options_ja": ["(6, 9)だけ", "(6, 9)と(5, 8)", "(6, 9)と(8, 5)", "列名の順序が異なるという理由だけでエラーになる"]}, {"id": "M2-31", "domain": "Spark Connect", "topic": "Local mode threads", "objective": "local実行の範囲を理解する", "difficulty": "basic", "stem": "A developer runs a classic PySpark test with --master local[3]. What does this master setting request?", "options": ["Local execution using three worker threads on the local machine", "A remote cluster with three worker machines", "Client deployment with exactly three remote executors", "Three independent drivers, each using one machine"], "correct": 0, "explanation_ja": "local[3]は、ローカルマシン上で3ワーカースレッドを使う実行指定です。3台のworkerノードや3つのdriverを用意する意味ではありません。localという実行先の指定と、クラスタでdriverをどこに置くかを指定するdeploy modeを分けて理解します。", "distractors_ja": ["正答", "3台のリモートマシンを要求する指定ではありません。", "リモートexecutor数の指定ではありません。", "driverを3つ作る指定ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/submitting-applications.html", "validation": "公式資料照合・未実行", "author_id": "A042", "exam": 2, "concept": "cluster-resources", "concept_label": "driver・executor・並列資源", "misconception_tags": ["", "確認ポイント：3台のリモートマシンを要求する指定ではありません。", "確認ポイント：リモートexecutor数の指定ではありません。", "確認ポイント：driverを3つ作る指定ではありません。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "開発者が--master local[3]を指定してclassic PySparkのテストを実行します。このmaster設定は何を要求しますか。", "options_ja": ["ローカルマシン上の3つのワーカースレッドを使用するローカル実行", "3台のワーカーマシンで構成されるリモートクラスター", "リモートエグゼキューターをちょうど3個使用するクライアントデプロイ", "それぞれが1台のマシンを使用する、3つの独立したドライバー"]}, {"id": "M2-32", "domain": "Spark SQL", "topic": "JSON Lines", "objective": "JSONのレコード境界を理解する", "difficulty": "basic", "stem": "A file contains two lines:\n{\"sensor\":\"a\",\"value\":8}\n{\"sensor\":\"b\",\"value\":11}\nWith default JSON reader options, how many data rows does spark.read.json(path) produce?", "options": ["1 row containing an array", "2 rows", "One row for every Spark executor", "0 rows because multiLine must always be true"], "correct": 1, "explanation_ja": "この入力は各行が独立したJSONオブジェクトであるため、既定のJSON Lines形式として2行に読み取れる。ファイル数、JSONレコード数、Sparkのパーティション数は別の概念であり、Executor数が行数を決めることはない。", "distractors_ja": ["入力は1つの配列ではなく独立した2個のオブジェクトである。", "正答", "Executor数は入力レコード数を変更しない。", "既定の行単位JSONに合致している。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-data-sources-json.html", "validation": "公式資料照合・未実行", "author_id": "B004", "exam": 2, "concept": "file-read-schema", "concept_label": "ファイル読込・スキーマ・形式", "misconception_tags": ["確認ポイント：入力は1つの配列ではなく独立した2個のオブジェクトである。", "", "確認ポイント：Executor数は入力レコード数を変更しない。", "確認ポイント：既定の行単位JSONに合致している。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "ファイルには次の2行が含まれています。\n{\"sensor\":\"a\",\"value\":8}\n{\"sensor\":\"b\",\"value\":11}\nJSONリーダーのオプションが既定値の場合、spark.read.json(path)はデータ行を何行生成しますか。", "options_ja": ["配列を含む1行", "2行", "Sparkエグゼキューターごとに1行", "multiLineは常にtrueでなければならないため0行"]}, {"id": "M2-33", "domain": "Spark SQL", "topic": "ignore保存モード", "objective": "保存先がある場合だけ無視する", "difficulty": "basic", "stem": "A retry must leave an existing file dataset untouched and finish without an already-exists error. If the destination is absent, it should create it. Which save mode expresses this behavior?", "options": ["errorifexists", "ignore", "overwrite", "append"], "correct": 1, "explanation_ja": "ignoreは保存先がすでに存在する場合に今回の書き込みを行わず、存在しない場合は保存する。既存行と新規行を比較する重複排除機能ではないため、差分だけを取り込む用途とは区別する。", "distractors_ja": ["errorifexistsは既存時にエラーを返す。", "正答", "overwriteは既存データを置き換える。", "appendは存在する保存先にも新しい行を追加する。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameWriter.mode.html", "validation": "公式資料照合・未実行", "author_id": "B010", "exam": 2, "concept": "file-write-layout", "concept_label": "保存モード・テーブル・配置", "misconception_tags": ["確認ポイント：errorifexistsは既存時にエラーを返す。", "", "確認ポイント：overwriteは既存データを置き換える。", "確認ポイント：appendは存在する保存先にも新しい行を追加する。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "再試行時には、既存のファイルデータセットを変更せず、既存の保存先があることによるエラーを出さずに終了する必要があります。保存先が存在しない場合は、作成する必要があります。この動作を表す保存モードはどれですか。", "options_ja": ["errorifexists", "ignore", "overwrite", "append"]}, {"id": "M2-34", "domain": "Spark SQL", "topic": "ORC読み取り", "objective": "データソース指定とloadを使う", "difficulty": "basic", "stem": "A directory contains only valid ORC files. Which expression explicitly reads those files as ORC, regardless of the session's default data source?", "options": ["spark.read.format(\"csv\").option(\"inferSchema\", True).load(path)", "spark.read.format(\"json\").load(path)", "spark.read.format(\"orc\").load(path)", "spark.read.option(\"format\", \"orc\").parquet(path)"], "correct": 2, "explanation_ja": "format(\"orc\")は汎用リーダーが使用するデータソースを明示する。loadで指定パスを読むため、既定形式が変更されてもORCとして扱う。optionの任意のキーを付けることと、データソースを選ぶことは区別する。", "distractors_ja": ["CSVの型推論はORCバイナリの読み取りではない。", "JSONリーダーではORCファイルを正しく解析できない。", "正答", "parquetメソッドが選ぶリーダーはORCではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameReader.orc.html", "validation": "公式資料照合・未実行", "author_id": "B029", "exam": 2, "concept": "file-read-schema", "concept_label": "ファイル読込・スキーマ・形式", "misconception_tags": ["確認ポイント：CSVの型推論はORCバイナリの読み取りではない。", "確認ポイント：JSONリーダーではORCファイルを正しく解析できない。", "", "確認ポイント：parquetメソッドが選ぶリーダーはORCではない。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "api"], "stem_ja": "あるディレクトリには有効なORCファイルだけが格納されています。セッションの既定データソースに関係なく、これらのファイルをORCとして明示的に読み取る式はどれですか。", "options_ja": ["spark.read.format(\"csv\").option(\"inferSchema\", True).load(path)", "spark.read.format(\"json\").load(path)", "spark.read.format(\"orc\").load(path)", "spark.read.option(\"format\", \"orc\").parquet(path)"]}, {"id": "M2-35", "domain": "DataFrame", "topic": "cast-invalid-ansi-off", "objective": "型変換失敗時の設定依存を理解する", "difficulty": "applied", "stem": "spark.sql.ansi.enabled is false. A string column units contains [\"12\", \"oops\"]. What values result from F.col(\"units\").cast(\"int\"), in the same row correspondence?", "options": ["\"12\" and \"oops\"", "12 and 0", "The second value always raises a cast exception even with ANSI disabled.", "12 and NULL"], "correct": 3, "explanation_ja": "ANSIが無効という前提では、整数として解釈できない文字列のint変換はNULLになる。正常な12は整数12へ変換される。0への自動置換ではない。ANSI有効時のエラー動作とは区別が必要であり、設問では設定を明示して型変換の振る舞いを一意にしている。", "distractors_ja": ["castにより型変換が行われる。", "変換不能値を暗黙に0へ置換する仕様ではない。", "ANSI無効時のこの文字列変換ではNULLとなる。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-ref-ansi-compliance.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C043", "exam": 2, "concept": "schema-types", "concept_label": "スキーマ・型の確認", "misconception_tags": ["確認ポイント：castにより型変換が行われる。", "確認ポイント：変換不能値を暗黙に0へ置換する仕様ではない。", "確認ポイント：ANSI無効時のこの文字列変換ではNULLとなる。", ""], "suggested_causes": ["knowledge", "knowledge", "boundary", "unknown"], "stem_ja": "spark.sql.ansi.enabledはfalseです。文字列列unitsには[\"12\", \"oops\"]が格納されています。F.col(\"units\").cast(\"int\")によって得られる値は、元の行との対応順でどれですか。", "options_ja": ["\"12\"と\"oops\"", "12と0", "ANSIが無効でも、2番目の値では常にキャスト例外が発生する。", "12とNULL"]}, {"id": "M2-36", "domain": "Architecture", "topic": "Task partition relationship", "objective": "タスクとパーティションの関係を理解する", "difficulty": "applied", "stem": "A simple RDD map stage must process all 18 input partitions. No tasks fail and speculative execution is disabled. The application has only six available task slots. How many successful tasks are needed for this stage?", "options": ["108 tasks, because each slot processes every partition", "3 tasks, because 18 divided by 6 is 3", "6 tasks, because there are six slots", "18 tasks, scheduled across the available slots"], "correct": 3, "explanation_ja": "このmap stageでは各入力パーティションを処理するタスクが必要なので、成功タスクは18個です。6スロットは同時実行できる数を制約するもので、処理対象のパーティション数を6個に減らす設定ではありません。タスク総数と並列度を区別します。", "distractors_ja": ["各スロットが全パーティションを重複処理する必要はありません。", "3は理想条件で考えた実行の波の数であり、タスク数ではありません。", "スロット数は同時実行の上限で、タスク総数ではありません。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/rdd-programming-guide.html", "validation": "公式資料照合・未実行", "author_id": "A005", "exam": 2, "concept": "cluster-resources", "concept_label": "driver・executor・並列資源", "misconception_tags": ["確認ポイント：各スロットが全パーティションを重複処理する必要はありません。", "確認ポイント：3は理想条件で考えた実行の波の数であり、タスク数ではありません。", "確認ポイント：スロット数は同時実行の上限で、タスク総数ではありません。", ""], "suggested_causes": ["boundary", "knowledge", "boundary", "unknown"], "stem_ja": "単純なRDDのmapステージで、18個すべての入力パーティションを処理する必要があります。タスクは失敗せず、投機的実行は無効です。アプリケーションで利用可能なタスクスロットは6個だけです。このステージには、成功するタスクが何個必要ですか。", "options_ja": ["各スロットがすべてのパーティションを処理するため108個", "18を6で割ると3なので3個", "スロットが6個あるため6個", "利用可能なスロットに割り当てられる18個"]}, {"id": "M2-37", "domain": "Spark SQL", "topic": "CSVの既定型", "objective": "headerとinferSchemaを区別する", "difficulty": "basic", "stem": "A CSV file contains the header qty and the data lines 7 and 12. It is read with spark.read.option(\"header\", True).csv(path). No schema or inferSchema option is supplied. What is the type of qty?", "options": ["IntegerType", "DecimalType(38, 0)", "LongType", "StringType"], "correct": 3, "explanation_ja": "headerは先頭行を列名として扱う指定であり、データ型の推論を有効にする指定ではない。CSVでは明示スキーマもinferSchemaも使わない場合、qtyの値が数値に見えても文字列として読み込む。", "distractors_ja": ["CSVの値を見た整数型推論は有効になっていない。", "Decimalを選ぶ明示スキーマも推論設定もない。", "整数の範囲を見てLongにする処理は実行されない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-data-sources-csv.html", "validation": "公式資料照合・未実行", "author_id": "B002", "exam": 2, "concept": "file-read-schema", "concept_label": "ファイル読込・スキーマ・形式", "misconception_tags": ["確認ポイント：CSVの値を見た整数型推論は有効になっていない。", "確認ポイント：Decimalを選ぶ明示スキーマも推論設定もない。", "確認ポイント：整数の範囲を見てLongにする処理は実行されない。", ""], "suggested_causes": ["knowledge", "knowledge", "boundary", "unknown"], "stem_ja": "CSVファイルにはヘッダーqtyと、データ行7および12が含まれています。spark.read.option(\"header\", True).csv(path)で読み取ります。スキーマもinferSchemaオプションも指定していません。qtyの型は何ですか。", "options_ja": ["IntegerType", "DecimalType(38, 0)", "LongType", "StringType"]}, {"id": "M2-38", "domain": "Spark SQL", "topic": "実行分割と保存分割", "objective": "repartitionとWriter.partitionByを区別する", "difficulty": "applied", "stem": "An engineer writes sales.repartition(8, \"market\").write.parquet(path). The job succeeds, but the consumer expected directories such as market=west. Which change explicitly requests that directory layout?", "options": ["Sort the DataFrame by market before calling .write.parquet(path).", "Add .partitionBy(\"market\") to the DataFrameWriter before .parquet(path).", "Set spark.sql.shuffle.partitions to the number of markets.", "Replace repartition(8, \"market\") with coalesce(8)."], "correct": 1, "explanation_ja": "repartitionは処理時のデータ配置を変え、Writer.partitionByは保存先の列値別ディレクトリを指定する。市場列でシャッフルしただけではmarket=westという保存レイアウトを要求したことにはならない。両者の責務を分けて判断する。", "distractors_ja": ["行の整列だけではパーティションディレクトリを作らない。", "正答", "シャッフル数の設定だけでは保存レイアウトは変わらない。", "coalesceは列値別の保存ディレクトリを指定しない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameWriter.partitionBy.html", "validation": "公式資料照合・未実行", "author_id": "B008", "exam": 2, "concept": "file-write-layout", "concept_label": "保存モード・テーブル・配置", "misconception_tags": ["確認ポイント：行の整列だけではパーティションディレクトリを作らない。", "", "確認ポイント：シャッフル数の設定だけでは保存レイアウトは変わらない。", "確認ポイント：coalesceは列値別の保存ディレクトリを指定しない。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "エンジニアはsales.repartition(8, \"market\").write.parquet(path)で書き込みます。ジョブは成功しますが、利用側はmarket=westのようなディレクトリを想定していました。そのディレクトリ構成を明示的に要求する変更はどれですか。", "options_ja": [".write.parquet(path)を呼び出す前に、DataFrameをmarketでソートする。", ".parquet(path)の前に、DataFrameWriterに.partitionBy(\"market\")を追加する。", "spark.sql.shuffle.partitionsをmarketの種類数に設定する。", "repartition(8, \"market\")をcoalesce(8)に置き換える。"]}, {"id": "M2-39", "domain": "Architecture", "topic": "Task CPU capacity", "objective": "CPU設定からタスク同時実行数を求める", "difficulty": "applied", "stem": "An application has exactly four executors, each with six allocated CPU cores. Each task requires two CPU cores. There are enough runnable tasks, no other resource constraints, and no dynamic allocation. What is the maximum number of these tasks that can run simultaneously?", "options": ["4", "24", "48", "12"], "correct": 3, "explanation_ja": "各executorの6コアを、1タスク当たり2コアで割ると同時実行は3タスクです。executorが4個なので最大12タスクになります。物理マシンの総コア数ではなく、アプリケーションに割り当てられたコア数とタスクのCPU要求を使って計算します。", "distractors_ja": ["executorごとに複数タスクを並行実行できます。", "24は割当てコア数であり、1タスク2コアという条件を無視しています。", "タスク数の算出では必要コア数で割ります。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/configuration.html", "validation": "公式資料照合・未実行", "author_id": "A004", "exam": 2, "concept": "cluster-resources", "concept_label": "driver・executor・並列資源", "misconception_tags": ["確認ポイント：executorごとに複数タスクを並行実行できます。", "確認ポイント：24は割当てコア数であり、1タスク2コアという条件を無視しています。", "確認ポイント：タスク数の算出では必要コア数で割ります。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "アプリケーションにはエグゼキューターがちょうど4個あり、それぞれにCPUコアが6個割り当てられています。各タスクはCPUコアを2個必要とします。実行可能なタスクは十分にあり、ほかのリソース制約や動的割り当てはありません。これらのタスクを同時に実行できる最大数はいくつですか。", "options_ja": ["4", "24", "48", "12"]}, {"id": "M2-40", "domain": "Structured Streaming", "topic": "Updateモード", "objective": "変更のあった集計行を選ぶ", "difficulty": "applied", "stem": "A micro-batch aggregation maintains total quantity by product. Before a batch, P=10 and Q=7. The batch adds 3 units for P and no units for Q. Using update mode with a compatible sink, what is emitted?", "options": ["The row P=13 only", "The row P=3 only", "No row until a watermark closes every product", "The rows P=13 and Q=7"], "correct": 0, "explanation_ja": "updateは当該トリガーで更新された結果行を出力する。Pの現在値13が出力され、変更されていないQは含まれない。出力値は入力バッチの増分3そのものではなく、更新後の集計値である。", "distractors_ja": ["正答", "入力差分ではなく更新後の結果行を出力する。", "この非時間集計のupdate出力に最終確定を待つ条件はない。", "全結果を出すのはcompleteである。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.ss/api/pyspark.sql.streaming.DataStreamWriter.outputMode.html", "validation": "公式資料照合・未実行", "author_id": "B041", "exam": 2, "concept": "stream-modes", "concept_label": "ストリーミング出力モード", "misconception_tags": ["", "確認ポイント：入力差分ではなく更新後の結果行を出力する。", "確認ポイント：この非時間集計のupdate出力に最終確定を待つ条件はない。", "確認ポイント：全結果を出すのはcompleteである。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "マイクロバッチ集約で、商品ごとの合計数量を管理しています。あるバッチの前はP=10、Q=7です。そのバッチではPに3個が追加され、Qには何も追加されません。対応するシンクでupdateモードを使用すると、何が出力されますか。", "options_ja": ["P=13の行だけ", "P=3の行だけ", "ウォーターマークがすべての商品を確定させるまで行は出力されない", "P=13とQ=7の行"]}, {"id": "M2-41", "domain": "DataFrame", "topic": "latest-row-window", "objective": "同順位の解消条件まで含めて最新行を選ぶ", "difficulty": "challenging", "stem": "For each sensor_id, retain the row with the greatest event_ts; if timestamps tie, retain the greatest ingestion_seq. ingestion_seq is unique within each sensor. Which expression gives a deterministic result?\nw = Window.partitionBy(\"sensor_id\").orderBy(F.col(\"event_ts\").desc(), F.col(\"ingestion_seq\").desc())", "options": ["df.withColumn(\"rn\", F.row_number().over(w)).filter(\"rn = 1\").drop(\"rn\")", "df.orderBy(F.col(\"event_ts\").desc()).dropDuplicates([\"sensor_id\"])", "df.groupBy(\"sensor_id\").agg(F.first(\"event_ts\"), F.first(\"payload\"))", "df.withColumn(\"rn\", F.rank().over(Window.partitionBy(\"sensor_id\").orderBy(F.col(\"event_ts\").desc()))).filter(\"rn = 1\")"], "correct": 0, "explanation_ja": "指定されたwindowは時刻に加えて一意なingestion_seqで順序を確定する。row_numberの1を選べば各sensorにつき要件どおり1行になる。単にソートしてdropDuplicatesしても残る行は保証されず、時刻だけでrankを付ける方法では同時刻の行が複数残り得る。", "distractors_ja": ["正答", "dropDuplicatesは事前ソートの先頭行保持を保証しない。", "firstは指定された全順序に従う最新行選択を保証しない。", "event_tsだけのrankでは同時刻の複数行が1位になる。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.row_number.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C009", "exam": 2, "concept": "windows-order", "concept_label": "ウィンドウ関数・順序", "misconception_tags": ["", "確認ポイント：dropDuplicatesは事前ソートの先頭行保持を保証しない。", "確認ポイント：firstは指定された全順序に従う最新行選択を保証しない。", "確認ポイント：event_tsだけのrankでは同時刻の複数行が1位になる。"], "suggested_causes": ["unknown", "boundary", "boundary", "boundary"], "stem_ja": "sensor_idごとにevent_tsが最大の行を残します。タイムスタンプが同じ場合は、ingestion_seqが最大の行を残します。ingestion_seqは各センサー内で一意です。決定的な結果を得られる式はどれですか。\nw = Window.partitionBy(\"sensor_id\").orderBy(F.col(\"event_ts\").desc(), F.col(\"ingestion_seq\").desc())", "options_ja": ["df.withColumn(\"rn\", F.row_number().over(w)).filter(\"rn = 1\").drop(\"rn\")", "df.orderBy(F.col(\"event_ts\").desc()).dropDuplicates([\"sensor_id\"])", "df.groupBy(\"sensor_id\").agg(F.first(\"event_ts\"), F.first(\"payload\"))", "df.withColumn(\"rn\", F.rank().over(Window.partitionBy(\"sensor_id\").orderBy(F.col(\"event_ts\").desc()))).filter(\"rn = 1\")"]}, {"id": "M2-42", "domain": "Architecture", "topic": "Temporary view lifetime", "objective": "一時ビューの有効範囲を理解する", "difficulty": "basic", "stem": "A DataFrame creates a local temporary view with createOrReplaceTempView('daily_metrics'). What determines the lifetime of this local temporary view?", "options": ["The retention period of a Parquet file written automatically", "The number of available CPU cores", "The SparkSession that created it", "The lifetime of every future Spark application on the cluster"], "correct": 2, "explanation_ja": "createOrReplaceTempViewによるローカル一時ビューの寿命は、作成元のSparkSessionに結び付きます。テーブルファイルを自動保存した永続テーブルではありません。global temporary viewや永続テーブルと区別するため、設問のlocalという条件を確認します。", "distractors_ja": ["このAPIはParquetファイルを自動保存しません。", "CPUコア数はビューの寿命を決めません。", "正答", "将来の別アプリケーションまで残る永続オブジェクトではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.createOrReplaceTempView.html", "validation": "公式資料照合・未実行", "author_id": "A016", "exam": 2, "concept": "sessions-views", "concept_label": "セッション・ビューの共有範囲", "misconception_tags": ["確認ポイント：このAPIはParquetファイルを自動保存しません。", "確認ポイント：CPUコア数はビューの寿命を決めません。", "", "確認ポイント：将来の別アプリケーションまで残る永続オブジェクトではありません。"], "suggested_causes": ["api", "knowledge", "unknown", "knowledge"], "stem_ja": "DataFrameがcreateOrReplaceTempView('daily_metrics')でローカル一時ビューを作成します。このローカル一時ビューの存続期間を決めるものは何ですか。", "options_ja": ["自動的に書き込まれるParquetファイルの保持期間", "利用可能なCPUコア数", "ビューを作成したSparkSession", "今後クラスター上で実行されるすべてのSparkアプリケーションの存続期間"]}, {"id": "M2-43", "domain": "Pandas API", "topic": "Pandas UDF batches", "objective": "バッチ内集計と全体集計を区別する", "difficulty": "challenging", "stem": "A scalar pandas UDF subtracts s.mean() from each element of its input Series s. The developer expects the result to be centered using the mean of the entire distributed column. Why is that expectation unsafe?", "options": ["The Series contains only schema metadata, never values", "Spark automatically replaces s.mean() with a global SQL average", "Every input Series is guaranteed to contain the whole distributed column", "The Series is an internal batch, so its mean need not equal the mean of the entire column"], "correct": 3, "explanation_ja": "scalar Pandas UDFへ渡されるSeriesは内部バッチです。そのmeanはバッチ内の平均なので、全列の平均を使う処理とは一般に一致しません。全体統計量が必要なら、分散集約などで目的の統計量を求め、その意味を保つ方法で各行へ適用する必要があります。", "distractors_ja": ["Seriesにはバッチの実値が含まれます。", "Python内部のmeanを自動で全体SQL集約へ変更しません。", "全列を1つのSeriesとして渡す保証はありません。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/user_guide/sql/arrow_pandas.html", "validation": "公式資料照合・未実行", "author_id": "A052", "exam": 2, "concept": "pandas-udfs", "concept_label": "pandas UDF・バッチ・グループ", "misconception_tags": ["確認ポイント：Seriesにはバッチの実値が含まれます。", "確認ポイント：Python内部のmeanを自動で全体SQL集約へ変更しません。", "確認ポイント：全列を1つのSeriesとして渡す保証はありません。", ""], "suggested_causes": ["knowledge", "knowledge", "boundary", "unknown"], "stem_ja": "スカラーpandas UDFが、入力Seriesのsの各要素からs.mean()を引きます。開発者は、分散された列全体の平均を使って中心化した結果が得られると期待しています。その期待が安全でないのはなぜですか。", "options_ja": ["Seriesにはスキーマのメタデータだけが含まれ、値は含まれない", "Sparkがs.mean()を列全体に対するSQLの平均に自動的に置き換える", "各入力Seriesには、分散された列全体が必ず含まれる", "Seriesは内部バッチであるため、その平均が列全体の平均と一致するとは限らない"]}, {"id": "M2-44", "domain": "DataFrame", "topic": "fillna-dictionary", "objective": "列別のNULL置換を適用する", "difficulty": "basic", "stem": "inventory has string category and integer quantity. Missing categories must become \"unassigned\" and missing quantities must become 0, while existing values stay unchanged. Which expression meets both requirements?", "options": ["inventory.fillna(\"unassigned\")", "inventory.withColumn(\"quantity\", F.lit(0)).fillna(\"unassigned\")", "inventory.fillna({\"category\": \"unassigned\", \"quantity\": 0})", "inventory.fillna(0)"], "correct": 2, "explanation_ja": "fillnaに列名と置換値の辞書を渡すと、型の異なる列ごとに欠損時の値を指定できる。ここでは既存のcategoryとquantityは維持される。文字列だけのfillnaでは数値列を補えず、withColumnで定数を入れると欠損していないquantityまで0に上書きする。", "distractors_ja": ["文字列の欠損は補えるが数値quantityを0にできない。", "非NULLのquantityも0に変更してしまう。", "正答", "数値の欠損は補えるがcategoryの文字列を設定できない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.fillna.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C007", "exam": 2, "concept": "null-semantics", "concept_label": "NULL・欠損値の扱い", "misconception_tags": ["確認ポイント：文字列の欠損は補えるが数値quantityを0にできない。", "確認ポイント：非NULLのquantityも0に変更してしまう。", "", "確認ポイント：数値の欠損は補えるがcategoryの文字列を設定できない。"], "suggested_causes": ["knowledge", "boundary", "unknown", "knowledge"], "stem_ja": "inventoryには文字列型のcategoryと整数型のquantityがあります。欠損したcategoryは\"unassigned\"に、欠損したquantityは0にし、既存の値は変更しない必要があります。両方の要件を満たす式はどれですか。", "options_ja": ["inventory.fillna(\"unassigned\")", "inventory.withColumn(\"quantity\", F.lit(0)).fillna(\"unassigned\")", "inventory.fillna({\"category\": \"unassigned\", \"quantity\": 0})", "inventory.fillna(0)"]}, {"id": "M2-45", "domain": "Spark SQL", "topic": "バケット化とソート", "objective": "永続テーブルのバケット内整列を指定する", "difficulty": "applied", "stem": "A new persistent table must use 8 hash buckets on account_id, with rows sorted by event_ts within each bucket. Which DataFrameWriter call expresses both requirements?", "options": ["df.repartition(8, \"account_id\").write.saveAsTable(\"account_events\")", "df.write.partitionBy(\"account_id\").sortBy(\"event_ts\").saveAsTable(\"account_events\")", "df.write.bucketBy(8, \"account_id\").sortBy(\"event_ts\").saveAsTable(\"account_events\")", "df.write.bucketBy(8, \"event_ts\").sortBy(\"account_id\").saveAsTable(\"account_events\")"], "correct": 2, "explanation_ja": "bucketByの数と列がバケット配置を指定し、Writer.sortByがバケット内の整列列を指定する。repartitionだけではカタログにバケット情報を登録しない。partitionByは値別ディレクトリの指定であり、固定8バケットと異なる。", "distractors_ja": ["処理パーティション数とテーブルのバケット指定は別である。", "partitionByは固定数のハッシュバケットを作る指定ではない。", "正答", "バケット列と整列列が要件に対して逆である。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameWriter.sortBy.html", "validation": "公式資料照合・未実行", "author_id": "B015", "exam": 2, "concept": "file-write-layout", "concept_label": "保存モード・テーブル・配置", "misconception_tags": ["確認ポイント：処理パーティション数とテーブルのバケット指定は別である。", "確認ポイント：partitionByは固定数のハッシュバケットを作る指定ではない。", "", "確認ポイント：バケット列と整列列が要件に対して逆である。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "新しい永続テーブルでは、account_idを使った8個のハッシュバケットを使用し、各バケット内の行をevent_tsでソートする必要があります。両方の要件を表すDataFrameWriterの呼び出しはどれですか。", "options_ja": ["df.repartition(8, \"account_id\").write.saveAsTable(\"account_events\")", "df.write.partitionBy(\"account_id\").sortBy(\"event_ts\").saveAsTable(\"account_events\")", "df.write.bucketBy(8, \"account_id\").sortBy(\"event_ts\").saveAsTable(\"account_events\")", "df.write.bucketBy(8, \"event_ts\").sortBy(\"account_id\").saveAsTable(\"account_events\")"]}]}, {"id": "M3", "title": "本番形式模試 3", "questions": [{"id": "M3-01", "domain": "Structured Streaming", "topic": "チェックポイント", "objective": "再開に必要な進捗と状態を保存する", "difficulty": "basic", "stem": "A micro-batch query performs stateful aggregation and must resume after a driver restart. The source supports replay and the sink supports recovery. What should the engineer configure on the writer?", "options": ["Only a Python variable storing the most recent DataFrame.", "A unique checkpointLocation on reliable storage, reused when restarting this query.", "Only cache() on the streaming input, with no checkpoint.", "A new randomly generated checkpointLocation on every restart."], "correct": 1, "explanation_ja": "チェックポイントは読み取り進捗や状態を復旧に利用する。再起動時も同じクエリのチェックポイントを使う必要がある。driverの変数やキャッシュだけでは停止後の復旧情報を保持できず、毎回新しい場所に変えると以前の進捗を引き継げない。", "distractors_ja": ["Python変数はdriver再起動で失われる。", "正答", "キャッシュは永続的なストリーム復旧情報の代替ではない。", "新規チェックポイントは以前の進捗を引き継がない。"], "source_url": "https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html#recovering-from-failures-with-checkpointing", "validation": "公式資料照合・未実行", "author_id": "B045", "exam": 3, "concept": "stream-reliability", "concept_label": "ストリーム再開・再実行の保証", "misconception_tags": ["確認ポイント：Python変数はdriver再起動で失われる。", "", "確認ポイント：キャッシュは永続的なストリーム復旧情報の代替ではない。", "確認ポイント：新規チェックポイントは以前の進捗を引き継がない。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "マイクロバッチクエリが状態を保持する集約を行っており、ドライバーの再起動後に再開する必要があります。ソースは再読み取りに対応し、シンクは復旧に対応しています。エンジニアはライターに何を設定すべきですか。", "options_ja": ["最新のDataFrameを格納するPython変数だけ。", "信頼性のあるストレージ上の一意のcheckpointLocation。このクエリの再起動時にも同じ場所を使用する。", "チェックポイントを使わず、ストリーミング入力にcache()だけを適用する。", "再起動するたびに、ランダムに生成した新しいcheckpointLocationを指定する。"]}, {"id": "M3-02", "domain": "DataFrame", "topic": "running-total-rows-frame", "objective": "累積集約のwindow frameを指定する", "difficulty": "applied", "stem": "For each account, transaction_seq is unique and orders transactions. An engineer needs a cumulative sum including the current row and all earlier rows. Which frame should be added to Window.partitionBy(\"account\").orderBy(\"transaction_seq\")?", "options": [".rowsBetween(Window.unboundedPreceding, Window.currentRow)", ".rowsBetween(Window.unboundedPreceding, Window.unboundedFollowing)", ".rowsBetween(Window.currentRow, Window.unboundedFollowing)", ".rowsBetween(-1, 0)"], "correct": 0, "explanation_ja": "累積合計にはグループの先頭から現在行までをframeに含める。unboundedPrecedingとcurrentRowがその範囲を表す。現在行から末尾まででは逆向きの合計となり、-1から0では直前1行と現在行だけになる。全partitionを指定すると各行に同じグループ全体の合計が付く。", "distractors_ja": ["正答", "全取引の合計になり、行ごとに増える累積値ではない。", "現在から後続行を集計するため累積の向きが逆になる。", "直前1行と現在行だけで、それ以前を含めない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.Window.rowsBetween.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C040", "exam": 3, "concept": "windows-order", "concept_label": "ウィンドウ関数・順序", "misconception_tags": ["", "確認ポイント：全取引の合計になり、行ごとに増える累積値ではない。", "確認ポイント：現在から後続行を集計するため累積の向きが逆になる。", "確認ポイント：直前1行と現在行だけで、それ以前を含めない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "各account内でtransaction_seqは一意であり、トランザクションの順序を定めます。エンジニアは、現在の行とそれ以前のすべての行を含む累積合計を求める必要があります。Window.partitionBy(\"account\").orderBy(\"transaction_seq\")に追加すべきフレームはどれですか。", "options_ja": [".rowsBetween(Window.unboundedPreceding, Window.currentRow)", ".rowsBetween(Window.unboundedPreceding, Window.unboundedFollowing)", ".rowsBetween(Window.currentRow, Window.unboundedFollowing)", ".rowsBetween(-1, 0)"]}, {"id": "M3-03", "domain": "Structured Streaming", "topic": "Appendモード", "objective": "非集計クエリの新規行出力を判断する", "difficulty": "basic", "stem": "A streaming query only filters invalid records and selects three columns; it has no aggregation or other stateful operator. With the console sink, the requirement is to emit each newly produced result row. Which output mode fits directly?", "options": ["append", "overwrite", "complete", "ignore"], "correct": 0, "explanation_ja": "既存の結果行を更新しない選択・フィルターだけのクエリではappendで新しい行を出力できる。overwriteやignoreはバッチの保存モードと混同しやすいが、Structured StreamingのoutputModeとして使う名前ではない。", "distractors_ja": ["正答", "overwriteは有効なストリーミングoutputModeではない。", "completeは全結果テーブルを保持する集計向けであり、この非集計クエリには適さない。", "ignoreは有効なストリーミングoutputModeではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.ss/api/pyspark.sql.streaming.DataStreamWriter.outputMode.html", "validation": "公式資料照合・未実行", "author_id": "B039", "exam": 3, "concept": "stream-modes", "concept_label": "ストリーミング出力モード", "misconception_tags": ["", "確認ポイント：overwriteは有効なストリーミングoutputModeではない。", "確認ポイント：completeは全結果テーブルを保持する集計向けであり、この非集計クエリには適さない。", "確認ポイント：ignoreは有効なストリーミングoutputModeではない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "ストリーミングクエリは無効なレコードのフィルター除外と3列の選択だけを行い、集約やその他の状態を保持する演算子はありません。consoleシンクで、新しく生成された結果行をそれぞれ出力することが要件です。直接適合する出力モードはどれですか。", "options_ja": ["append", "overwrite", "complete", "ignore"]}, {"id": "M3-04", "domain": "Tuning", "topic": "Choose cache boundary", "objective": "再利用箇所と保存データ量からcache位置を選ぶ", "difficulty": "applied", "stem": "Ten reports all use the same costly normalization of an input table. Every report needs only valid rows and three columns, while the raw table has 180 columns. Which cache candidate most directly targets the shared work without retaining the unused raw columns?", "options": ["Each report's final result, when each final result is consumed only once", "Only the raw DataFrame with all 180 columns, regardless of downstream needs", "A different copy of the raw DataFrame for every report", "The normalized, filtered DataFrame projected to the three shared columns, before branching into reports"], "correct": 3, "explanation_ja": "共通処理後の必要な行・列へ絞った結果を保存すると、繰り返す正規化を再利用しつつ、不要な列の保存を避けられます。cacheの位置は再利用の共通点と保存量から判断します。最適な実行時間は実測が必要ですが、この選択肢が設問の共有処理と容量要件に直接対応します。", "distractors_ja": ["1回だけ使う最終結果の保存では共通の前処理を再利用できません。", "不要な多数列を保持し、共通の正規化処理も再利用できません。", "同じ不要データを複製して保存する方針です。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-performance-tuning.html", "validation": "公式資料照合・未実行", "author_id": "A060", "exam": 3, "concept": "cache-persist", "concept_label": "cache・persist・再利用", "misconception_tags": ["確認ポイント：1回だけ使う最終結果の保存では共通の前処理を再利用できません。", "確認ポイント：不要な多数列を保持し、共通の正規化処理も再利用できません。", "確認ポイント：同じ不要データを複製して保存する方針です。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "10個のレポートすべてで、入力テーブルに対する同じ高コストの正規化処理を使用しています。各レポートで必要なのは有効な行と3列だけですが、生のテーブルには180列あります。不要な元の列を保持せず、共有する処理を最も直接的に対象とするキャッシュ候補はどれですか。", "options_ja": ["各最終結果が1回しか利用されない場合の、各レポートの最終結果", "後続処理の要件に関係なく、180列すべてを含む生のDataFrameだけ", "レポートごとに別々に作成した、生のDataFrameのコピー", "レポートごとに処理が分岐する前の、正規化とフィルターを適用し、共有する3列だけを選択したDataFrame"]}, {"id": "M3-05", "domain": "DataFrame", "topic": "date-format-parse", "objective": "日付文字列を明示形式で解析する", "difficulty": "basic", "stem": "A string column service_day uses the format \"26/08/2026\". Which expression parses this value as a DateType representing 26 August 2026?", "options": ["F.substring(\"service_day\", 1, 10)", "F.to_date(\"service_day\", \"MM/dd/yyyy\")", "F.date_format(\"service_day\", \"dd/MM/yyyy\")", "F.to_date(\"service_day\", \"dd/MM/yyyy\")"], "correct": 3, "explanation_ja": "to_dateの第2引数には入力文字列に対応する日付パターンを指定する。この例は日/月/年なのでdd/MM/yyyyとなる。date_formatは日付時刻を文字列として整形するための関数であり、目的のDateTypeへの解析とは方向が異なる。型と入力の並びを合わせて選ぶ。", "distractors_ja": ["部分文字列はDateTypeへの変換を行わない。", "月と日の順序が逆で、26を月として解釈してしまう。", "date_formatは文字列の整形結果を返す関数である。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.to_date.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C034", "exam": 3, "concept": "string-date-functions", "concept_label": "文字列・日付関数", "misconception_tags": ["確認ポイント：部分文字列はDateTypeへの変換を行わない。", "確認ポイント：月と日の順序が逆で、26を月として解釈してしまう。", "確認ポイント：date_formatは文字列の整形結果を返す関数である。", ""], "suggested_causes": ["knowledge", "knowledge", "api", "unknown"], "stem_ja": "文字列列service_dayは\"26/08/2026\"という形式を使用しています。この値を2026年8月26日を表すDateTypeとして解析する式はどれですか。", "options_ja": ["F.substring(\"service_day\", 1, 10)", "F.to_date(\"service_day\", \"MM/dd/yyyy\")", "F.date_format(\"service_day\", \"dd/MM/yyyy\")", "F.to_date(\"service_day\", \"dd/MM/yyyy\")"]}, {"id": "M3-06", "domain": "DataFrame", "topic": "dropna-subset-threshold", "objective": "欠損行除去の対象列と閾値を指定する", "difficulty": "applied", "stem": "A contacts DataFrame has contact_id, email, phone, and notes. Retain a row when at least one of email or phone is non-null. Missing values in other columns must not affect the decision. Which expression meets the requirement?", "options": ["contacts.dropna(how=\"any\", subset=[\"email\", \"phone\"])", "contacts.dropna(thresh=1, subset=[\"email\", \"phone\"])", "contacts.dropna(thresh=1)", "contacts.dropna(how=\"all\")"], "correct": 1, "explanation_ja": "subsetで判定対象をemailとphoneに限定し、thresh=1でその中に非NULL値が1個以上ある行を残す。対象を指定しないとcontact_idやnotesも判定に使われ、連絡先が両方欠損した行まで残り得る。how=\"any\"は対象列に1つでも欠損がある行を落とすため厳しすぎる。", "distractors_ja": ["片方だけ連絡先がある行も除外される。", "正答", "contact_idが非NULLなら連絡先が両方NULLでも残る。", "全列がNULLの場合だけ削除するため対象が広すぎる。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.dropna.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C006", "exam": 3, "concept": "null-semantics", "concept_label": "NULL・欠損値の扱い", "misconception_tags": ["確認ポイント：片方だけ連絡先がある行も除外される。", "", "確認ポイント：contact_idが非NULLなら連絡先が両方NULLでも残る。", "確認ポイント：全列がNULLの場合だけ削除するため対象が広すぎる。"], "suggested_causes": ["knowledge", "unknown", "boundary", "boundary"], "stem_ja": "contacts DataFrameにはcontact_id、email、phone、notesがあります。emailまたはphoneの少なくとも一方が非NULLなら、その行を残します。ほかの列の欠損値は判定に影響してはいけません。この要件を満たす式はどれですか。", "options_ja": ["contacts.dropna(how=\"any\", subset=[\"email\", \"phone\"])", "contacts.dropna(thresh=1, subset=[\"email\", \"phone\"])", "contacts.dropna(thresh=1)", "contacts.dropna(how=\"all\")"]}, {"id": "M3-07", "domain": "Tuning", "topic": "AQEの実行時最適化", "objective": "実行時統計に基づく計画変更を理解する", "difficulty": "basic", "stem": "A SQL join starts with estimates that later prove inaccurate. After shuffle statistics become available, Spark adjusts the physical plan and combines small shuffle partitions. Which feature is responsible?", "options": ["Static partition pruning based only on predicates known before execution", "DataFrame cache materialization", "Adaptive Query Execution", "JDBC predicate pushdown"], "correct": 2, "explanation_ja": "AQEは実行時統計を利用して物理計画を調整する仕組みで、小さいシャッフルパーティションの統合や結合戦略の変更などを行う。SQLの実行前だけに働く固定的な最適化と、実行中の情報を使う最適化を区別する。", "distractors_ja": ["静的pruningは実行中のshuffle統計による計画変更ではない。", "cacheは中間結果の再利用であり、runtime統計によるjoin戦略調整とは別。", "正答", "JDBCへ述語を押す機能はこのshuffle処理の調整ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-performance-tuning.html#adaptive-query-execution", "validation": "公式資料照合・未実行", "author_id": "B055", "exam": 3, "concept": "query-plans", "concept_label": "SQLエンジン・実行計画・AQE", "misconception_tags": ["確認ポイント：静的pruningは実行中のshuffle統計による計画変更ではない。", "確認ポイント：cacheは中間結果の再利用であり、runtime統計によるjoin戦略調整とは別。", "", "確認ポイント：JDBCへ述語を押す機能はこのshuffle処理の調整ではない。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "SQL結合が、後に不正確だと判明する推定値を使って開始されます。シャッフルの統計情報が利用可能になると、Sparkは物理計画を調整し、小さいシャッフルパーティションを結合します。これを行う機能はどれですか。", "options_ja": ["実行前に判明している述語だけに基づく静的パーティションプルーニング", "DataFrameキャッシュの実体化", "適応型クエリ実行（Adaptive Query Execution）", "JDBCの述語プッシュダウン"]}, {"id": "M3-08", "domain": "Spark SQL", "topic": "SQL CTAS", "objective": "列で分割した永続テーブルを作成する", "difficulty": "applied", "stem": "The temporary view prepared_orders contains order_id, amount, and order_day. A new Parquet table must persist its current rows and use order_day as a storage partition column. Which SQL statement expresses this?", "options": ["CREATE TABLE order_archive USING parquet AS SELECT * FROM prepared_orders ORDER BY order_day", "CREATE TABLE order_archive USING parquet CLUSTERED BY (order_day) INTO 8 BUCKETS AS SELECT * FROM prepared_orders", "CREATE TABLE order_archive USING parquet PARTITIONED BY (order_day) AS SELECT * FROM prepared_orders", "CREATE TEMPORARY VIEW order_archive AS SELECT * FROM prepared_orders"], "correct": 2, "explanation_ja": "CTASはSELECT結果から永続テーブルを作成する。保存の列値別分割が要件ならPARTITIONED BYを指定する。ORDER BYは整列、CLUSTERED BYはバケット化であり、どちらも列値別パーティション指定と同じ意味ではない。", "distractors_ja": ["整列しても列値別パーティションレイアウトを指定したことにならない。", "固定数バケットへの分割であり要件の保存パーティションと異なる。", "正答", "一時ビューなので結果の永続保存にならない。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-ref-syntax-ddl-create-table-datasource.html", "validation": "公式資料照合・未実行", "author_id": "B034", "exam": 3, "concept": "file-write-layout", "concept_label": "保存モード・テーブル・配置", "misconception_tags": ["確認ポイント：整列しても列値別パーティションレイアウトを指定したことにならない。", "確認ポイント：固定数バケットへの分割であり要件の保存パーティションと異なる。", "", "確認ポイント：一時ビューなので結果の永続保存にならない。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "一時ビューprepared_ordersにはorder_id、amount、order_dayが含まれています。新しいParquetテーブルに現在の行を永続化し、order_dayをストレージのパーティション列として使用する必要があります。これを表すSQL文はどれですか。", "options_ja": ["CREATE TABLE order_archive USING parquet AS SELECT * FROM prepared_orders ORDER BY order_day", "CREATE TABLE order_archive USING parquet CLUSTERED BY (order_day) INTO 8 BUCKETS AS SELECT * FROM prepared_orders", "CREATE TABLE order_archive USING parquet PARTITIONED BY (order_day) AS SELECT * FROM prepared_orders", "CREATE TEMPORARY VIEW order_archive AS SELECT * FROM prepared_orders"]}, {"id": "M3-09", "domain": "Spark SQL", "topic": "overwriteの保証範囲", "objective": "通常ファイル保存とトランザクションを区別する", "difficulty": "challenging", "stem": "A team overwrites an ordinary Parquet directory using df.write.mode(\"overwrite\").parquet(path). They want readers to always see either the complete old version or the complete new version if the write fails. Which statement is correct about this save mode alone?", "options": ["It does not by itself provide that atomic transaction guarantee.", "It first creates a complete new version and atomically swaps it on every filesystem.", "It provides ACID transactions for every Hadoop-compatible filesystem.", "It preserves the old version indefinitely for automatic time travel."], "correct": 0, "explanation_ja": "通常のファイルデータソースの保存モードだけで、読者への原子的な切り替えや失敗時のロールバックは保証されない。overwriteという名前は置換の意図を示すが、トランザクション対応テーブル形式と同じ保証を意味しない。", "distractors_ja": ["正答", "常に原子的な交換をするという保証はない。", "save modeだけで全ファイルシステムにACIDは付かない。", "通常Parquetのoverwriteは履歴管理機能ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-data-sources-load-save-functions.html#save-modes", "validation": "公式資料照合・未実行", "author_id": "B012", "exam": 3, "concept": "file-write-layout", "concept_label": "保存モード・テーブル・配置", "misconception_tags": ["", "確認ポイント：常に原子的な交換をするという保証はない。", "確認ポイント：save modeだけで全ファイルシステムにACIDは付かない。", "確認ポイント：通常Parquetのoverwriteは履歴管理機能ではない。"], "suggested_causes": ["unknown", "boundary", "knowledge", "knowledge"], "stem_ja": "チームがdf.write.mode(\"overwrite\").parquet(path)を使って通常のParquetディレクトリを上書きします。書き込みが失敗した場合でも、読み取り側には常に完全な旧バージョンか完全な新バージョンのいずれかが見えるようにしたいと考えています。この保存モード単独について、正しい説明はどれですか。", "options_ja": ["このモードだけでは、そのような原子的トランザクションの保証は提供されない。", "どのファイルシステムでも、最初に完全な新バージョンを作成し、原子的に切り替える。", "すべてのHadoop互換ファイルシステムに対してACIDトランザクションを提供する。", "自動タイムトラベルのために、旧バージョンを無期限に保持する。"]}, {"id": "M3-10", "domain": "Tuning", "topic": "reduce-partitions-no-shuffle", "objective": "shuffleを避けてパーティションを減らす", "difficulty": "applied", "stem": "After filtering, a small batch DataFrame has 120 partitions. The engineer wants to reduce it to 12 partitions without introducing a shuffle, and accepts that the result may not be evenly balanced. Which operation fits?", "options": ["df.orderBy(\"region\")", "df.coalesce(12)", "df.repartition(12, \"region\")", "df.repartition(12)"], "correct": 1, "explanation_ja": "coalesceは既存パーティションをまとめることで、通常shuffleを追加せずに数を減らす。この設問では均等な再配分を要求していないので要件に合う。repartitionはデータを再配分するためshuffleを伴う。coalesceで極端に減らすと後続処理の並列度も下がる点は併せて理解する。", "distractors_ja": ["全体ソートはパーティション数だけを減らす処理ではない。", "正答", "キー指定をしてもrepartitionのshuffleは必要になる。", "repartitionはshuffleを伴う再配分である。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.coalesce.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C056", "exam": 3, "concept": "shuffle-partitions", "concept_label": "shuffle・パーティション・スキュー", "misconception_tags": ["確認ポイント：全体ソートはパーティション数だけを減らす処理ではない。", "", "確認ポイント：キー指定をしてもrepartitionのshuffleは必要になる。", "確認ポイント：repartitionはshuffleを伴う再配分である。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "フィルター適用後の小さいバッチDataFrameには120個のパーティションがあります。エンジニアは、シャッフルを発生させずにパーティション数を12個に減らしたいと考えており、結果が均等にならない可能性を許容しています。適した操作はどれですか。", "options_ja": ["df.orderBy(\"region\")", "df.coalesce(12)", "df.repartition(12, \"region\")", "df.repartition(12)"]}, {"id": "M3-11", "domain": "Spark Connect", "topic": "Client deployment", "objective": "client modeのdriver配置を理解する", "difficulty": "applied", "stem": "A developer submits a classic Spark application in client deployment mode from a gateway host. The executors run on remote worker nodes. Where does the driver run?", "options": ["In the submitting client process on the gateway", "In the distributed filesystem's NameNode process", "On a randomly chosen worker regardless of client mode", "Inside every executor simultaneously"], "correct": 0, "explanation_ja": "client deploy modeのdriverは、アプリケーションを送信したクライアント側で動作します。executorはクラスタ上で動いていても、driverまで必ずworker内にあるわけではありません。したがってworkerとdriverの通信経路や、送信側プロセスの維持も運用上の考慮点になります。", "distractors_ja": ["正答", "ファイルシステムの管理プロセスでは動きません。", "これはcluster側配置との混同です。", "driverが全executorへ複製される構造ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/submitting-applications.html", "validation": "公式資料照合・未実行", "author_id": "A044", "exam": 3, "concept": "cluster-resources", "concept_label": "driver・executor・並列資源", "misconception_tags": ["", "確認ポイント：ファイルシステムの管理プロセスでは動きません。", "確認ポイント：これはcluster側配置との混同です。", "確認ポイント：driverが全executorへ複製される構造ではありません。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "開発者がゲートウェイホストからクライアントデプロイモードでclassic Sparkアプリケーションを送信します。エグゼキューターはリモートのワーカーノード上で実行されます。ドライバーはどこで実行されますか。", "options_ja": ["ゲートウェイ上で送信を行うクライアントプロセス内", "分散ファイルシステムのNameNodeプロセス内", "クライアントモードに関係なく、ランダムに選ばれたワーカー上", "すべてのエグゼキューター内で同時に実行される"]}, {"id": "M3-12", "domain": "DataFrame", "topic": "lag-partition", "objective": "グループごとに直前行を参照する", "difficulty": "applied", "stem": "df has (account, month, amount) rows (\"A\", 1, 11), (\"A\", 2, 16), and (\"B\", 1, 30). Each account-month pair is unique. Using w = Window.partitionBy(\"account\").orderBy(\"month\"), what lag value is assigned to account B, month 1 by F.lag(\"amount\", 1).over(w)?", "options": ["11", "30", "NULL", "16"], "correct": 2, "explanation_ja": "lagはwindowのpartition内で指定順序の前の行を参照する。account=Bのグループには1行しかなく、直前行が存在しないため、既定値のNULLになる。account=Aの最終行は別partitionであるため参照しない。lagのoffsetはここでは月数ではなく行数を意味する。", "distractors_ja": ["account=Aの先頭行も参照対象外である。", "lagは現在行の値をそのまま返す関数ではない。", "正答", "別accountの行は同じwindow partitionに含まれない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.lag.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C038", "exam": 3, "concept": "windows-order", "concept_label": "ウィンドウ関数・順序", "misconception_tags": ["確認ポイント：account=Aの先頭行も参照対象外である。", "確認ポイント：lagは現在行の値をそのまま返す関数ではない。", "", "確認ポイント：別accountの行は同じwindow partitionに含まれない。"], "suggested_causes": ["knowledge", "api", "unknown", "knowledge"], "stem_ja": "dfの(account, month, amount)の行は(\"A\", 1, 11)、(\"A\", 2, 16)、(\"B\", 1, 30)です。accountとmonthの各組み合わせは一意です。w = Window.partitionBy(\"account\").orderBy(\"month\")を使用すると、F.lag(\"amount\", 1).over(w)によってaccount B、month 1の行に割り当てられるlag値は何ですか。", "options_ja": ["11", "30", "NULL", "16"]}, {"id": "M3-13", "domain": "DataFrame", "topic": "count-null-distinct", "objective": "行数・非NULL数・異なる値の数を区別する", "difficulty": "applied", "stem": "df contains values [\"x\", \"x\", NULL, \"y\"] in the column tag. What values are returned by this aggregation, in the displayed column order?\ndf.agg(F.count(\"*\").alias(\"rows\"), F.count(\"tag\").alias(\"present\"), F.countDistinct(\"tag\").alias(\"unique\"))", "options": ["(3, 3, 2)", "(4, 4, 3)", "(4, 3, 2)", "(4, 3, 3)"], "correct": 2, "explanation_ja": "count(\"*\")は全行を数えるため4、count(\"tag\")はNULLを除外して3となる。countDistinctもこの単一列ではNULLを数えず、xとyの2値を数える。重複の除去とNULLの除外は別の処理であり、何を数える集約かを列ごとに追うと判断しやすい。", "distractors_ja": ["count(\"*\")はNULLを持つ行も含める。", "列を数えるcountとcountDistinctではNULLを除外する。", "正答", "単一列countDistinctはNULLを1種類として数えない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.count.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C005", "exam": 3, "concept": "null-semantics", "concept_label": "NULL・欠損値の扱い", "misconception_tags": ["確認ポイント：count(\"*\")はNULLを持つ行も含める。", "確認ポイント：列を数えるcountとcountDistinctではNULLを除外する。", "", "確認ポイント：単一列countDistinctはNULLを1種類として数えない。"], "suggested_causes": ["boundary", "boundary", "unknown", "boundary"], "stem_ja": "dfのtag列には[\"x\", \"x\", NULL, \"y\"]が格納されています。次の集約が返す値は、表示されている列の順序でどれですか。\ndf.agg(F.count(\"*\").alias(\"rows\"), F.count(\"tag\").alias(\"present\"), F.countDistinct(\"tag\").alias(\"unique\"))", "options_ja": ["(3, 3, 2)", "(4, 4, 3)", "(4, 3, 2)", "(4, 3, 3)"]}, {"id": "M3-14", "domain": "Spark SQL", "topic": "一時ビュー登録", "objective": "DataFrameをSQLから参照する", "difficulty": "basic", "stem": "A notebook has a DataFrame named rejected. A SQL report in the same SparkSession must query it as rejected_events, replacing a previous local temporary view of that name if necessary. Which statement is appropriate?", "options": ["rejected.createOrReplaceTempView(\"rejected_events\")", "rejected.createTempView(\"rejected_events\")", "rejected.write.mode(\"append\").saveAsTable(\"rejected_events\")", "spark.sql(\"SELECT * FROM rejected\")"], "correct": 0, "explanation_ja": "Pythonの変数名は自動でSQLのテーブル名にならない。createOrReplaceTempViewでSQL名を登録すると、同一SparkSessionのSQLから参照でき、既存の同名一時ビューも置き換えられる。データの永続保存は要件に含まれない。", "distractors_ja": ["正答", "createTempViewは同名ビューがあると置換せずエラーになる。", "永続テーブルへの追記であり、一時ビューの置換ではない。", "Python変数rejectedをそのままSQL名として解決することはできない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.createOrReplaceTempView.html", "validation": "公式資料照合・未実行", "author_id": "B016", "exam": 3, "concept": "sessions-views", "concept_label": "セッション・ビューの共有範囲", "misconception_tags": ["", "確認ポイント：createTempViewは同名ビューがあると置換せずエラーになる。", "確認ポイント：永続テーブルへの追記であり、一時ビューの置換ではない。", "確認ポイント：Python変数rejectedをそのままSQL名として解決することはできない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "ノートブックにrejectedというDataFrameがあります。同じSparkSession内のSQLレポートからrejected_eventsとしてクエリできるようにし、必要であれば同名の既存のローカル一時ビューを置き換える必要があります。適切な文はどれですか。", "options_ja": ["rejected.createOrReplaceTempView(\"rejected_events\")", "rejected.createTempView(\"rejected_events\")", "rejected.write.mode(\"append\").saveAsTable(\"rejected_events\")", "spark.sql(\"SELECT * FROM rejected\")"]}, {"id": "M3-15", "domain": "DataFrame", "topic": "json-string-to-struct", "objective": "JSON文字列をスキーマ付きで解析する", "difficulty": "applied", "stem": "payload is a string column containing JSON objects such as {\"attempt\": 2, \"ok\": true}. Which expression creates a struct column parsed with integer attempt and boolean ok fields?", "options": ["df.withColumn(\"parsed\", F.col(\"payload\").cast(\"string\"))", "df.withColumn(\"parsed\", F.from_json(\"payload\", \"attempt INT, ok BOOLEAN\"))", "df.withColumn(\"parsed\", F.to_json(\"payload\"))", "df.withColumn(\"parsed\", F.struct(\"payload\"))"], "correct": 1, "explanation_ja": "from_jsonはJSON文字列を指定したスキーマで解析し、ここではattemptとokを持つstructにする。to_jsonはstructなどをJSON文字列へ変換する逆方向の処理である。struct(\"payload\")は文字列をフィールドとして包むだけで、JSON内部のキーや型を解釈するわけではない。", "distractors_ja": ["文字列のままでJSONの各フィールドを解析しない。", "正答", "to_jsonは構造化した値をJSON文字列へ変換する逆方向の関数である。", "payload文字列を含むstructになるだけで内部JSONを展開しない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.from_json.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C033", "exam": 3, "concept": "nested-data", "concept_label": "配列・構造体・展開", "misconception_tags": ["確認ポイント：文字列のままでJSONの各フィールドを解析しない。", "", "確認ポイント：to_jsonは構造化した値をJSON文字列へ変換する逆方向の関数である。", "確認ポイント：payload文字列を含むstructになるだけで内部JSONを展開しない。"], "suggested_causes": ["knowledge", "unknown", "api", "knowledge"], "stem_ja": "payloadは、{\"attempt\": 2, \"ok\": true}のようなJSONオブジェクトを含む文字列列です。attemptを整数型、okをブール型のフィールドとして解析した構造体列を作成する式はどれですか。", "options_ja": ["df.withColumn(\"parsed\", F.col(\"payload\").cast(\"string\"))", "df.withColumn(\"parsed\", F.from_json(\"payload\", \"attempt INT, ok BOOLEAN\"))", "df.withColumn(\"parsed\", F.to_json(\"payload\"))", "df.withColumn(\"parsed\", F.struct(\"payload\"))"]}, {"id": "M3-16", "domain": "DataFrame", "topic": "inner-join-multiplicity", "objective": "結合キーの重複による行数を予測する", "difficulty": "applied", "stem": "left_df has key values [4, 4, 9]. right_df has key values [4, 4, 4, 8]. All keys are non-null. How many rows result from left_df.join(right_df, \"key\", \"inner\")?", "options": ["3", "7", "6", "2"], "correct": 2, "explanation_ja": "inner joinは一致する行の組み合わせをすべて作る。key=4は左に2行、右に3行あるので2×3で6行になる。9と8には相手がなく残らない。joinはキーの重複を自動的に排除しないため、一致するキーの種類数と結果の行数を混同しないことが重要である。", "distractors_ja": ["右の一致行だけを数えており、左側の重複を反映していない。", "入力行数の和ではなく一致する組み合わせを数える。", "正答", "左の一致行だけを数えており、右側の重複を反映していない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.join.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C010", "exam": 3, "concept": "joins", "concept_label": "結合条件・結合種類・行数", "misconception_tags": ["確認ポイント：右の一致行だけを数えており、左側の重複を反映していない。", "確認ポイント：入力行数の和ではなく一致する組み合わせを数える。", "", "確認ポイント：左の一致行だけを数えており、右側の重複を反映していない。"], "suggested_causes": ["boundary", "knowledge", "unknown", "boundary"], "stem_ja": "left_dfのkey値は[4, 4, 9]で、right_dfのkey値は[4, 4, 4, 8]です。すべてのキーは非NULLです。left_df.join(right_df, \"key\", \"inner\")によって何行が得られますか。", "options_ja": ["3", "7", "6", "2"]}, {"id": "M3-17", "domain": "Architecture", "topic": "Cluster manager", "objective": "資源割当ての担当を識別する", "difficulty": "basic", "stem": "Two Spark applications request executor resources from the same YARN cluster. Which component is responsible for allocating cluster resources across the applications?", "options": ["A task scheduler running independently on each worker for all applications", "The cluster manager", "The SQL optimizer inside the requesting application", "The first executor allocated to each application"], "correct": 1, "explanation_ja": "YARNなどのcluster managerは、複数のアプリケーションが使うクラスタ資源を割り当てます。driverによるアプリケーション内の処理管理とは責務が異なります。DataFrame、パーサー、accumulatorはいずれもクラスタ全体の資源管理機構ではありません。", "distractors_ja": ["各workerが独立に全アプリ資源を調整する構成ではない。", "正答", "SQL optimizerは実行計画を最適化する。cluster全体の資源割当とは別。", "executorは割り当てられたtaskを実行する。"], "source_url": "https://spark.apache.org/docs/3.5.6/cluster-overview.html", "validation": "公式資料照合・未実行", "author_id": "A003", "exam": 3, "concept": "cluster-resources", "concept_label": "driver・executor・並列資源", "misconception_tags": ["確認ポイント：各workerが独立に全アプリ資源を調整する構成ではない。", "", "確認ポイント：SQL optimizerは実行計画を最適化する。cluster全体の資源割当とは別。", "確認ポイント：executorは割り当てられたtaskを実行する。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "2つのSparkアプリケーションが、同じYARNクラスターにエグゼキューターのリソースを要求します。アプリケーション間でクラスターのリソースを割り当てる責任を持つコンポーネントはどれですか。", "options_ja": ["すべてのアプリケーションを対象として、各ワーカー上で独立して動作するタスクスケジューラー", "クラスターマネージャー", "要求元アプリケーション内のSQLオプティマイザー", "各アプリケーションに最初に割り当てられたエグゼキューター"]}, {"id": "M3-18", "domain": "Pandas API", "topic": "Scalar pandas UDF cardinality", "objective": "scalar Pandas UDFの行数制約を理解する", "difficulty": "applied", "stem": "A Series-to-Series scalar pandas UDF receives a batch of 500 values. Its Python function filters out negative values and returns a Series of length 430. What is wrong with this design?", "options": ["Every pandas UDF must return exactly one scalar, regardless of its declared form", "A scalar pandas UDF must return exactly the size of the entire distributed DataFrame", "Pandas UDFs are not allowed to operate on numeric data", "This scalar UDF form must return the same number of values as its input batch; row filtering should be expressed separately"], "correct": 3, "explanation_ja": "Series→Seriesのscalar Pandas UDFは入力バッチと同じ行数を返す必要があります。行を除外したいならDataFrame.filterなどで別に表現します。グループ集約やmapInPandasなどは異なる形式・契約を持つため、すべてのPandas関連APIを同じ行数ルールで考えないでください。", "distractors_ja": ["単一値を返す集約形式とは異なります。", "処理対象は内部バッチであり全DataFrameではありません。", "数値データにも利用できます。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.pandas_udf.html", "validation": "公式資料照合・未実行", "author_id": "A050", "exam": 3, "concept": "pandas-udfs", "concept_label": "pandas UDF・バッチ・グループ", "misconception_tags": ["確認ポイント：単一値を返す集約形式とは異なります。", "確認ポイント：処理対象は内部バッチであり全DataFrameではありません。", "確認ポイント：数値データにも利用できます。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "SeriesからSeriesへのスカラーpandas UDFが、500個の値を含むバッチを受け取ります。そのPython関数は負の値をフィルター除外し、長さ430のSeriesを返します。この設計の問題は何ですか。", "options_ja": ["すべてのpandas UDFは、宣言された形式に関係なく、スカラーをちょうど1個返す必要がある", "スカラーpandas UDFは、分散DataFrame全体のサイズと同じ数の値を返す必要がある", "pandas UDFで数値データを処理することは禁止されている", "この形式のスカラーUDFは入力バッチと同じ数の値を返す必要があり、行のフィルタリングは別に記述すべきである"]}, {"id": "M3-19", "domain": "Architecture", "topic": "Dataset language support", "objective": "PythonのDataFrameとtyped Datasetを区別する", "difficulty": "basic", "stem": "A Java example uses Dataset<Customer> with compile-time typed objects. Which statement correctly guides a developer porting the job to PySpark 3.5.x?", "options": ["PySpark provides the DataFrame API, but not the Java/Scala typed Dataset API", "Typed Datasets are required before Python can query structured data", "PySpark supports Dataset<Customer> with identical Python syntax", "Using Python type hints automatically creates a typed Spark Dataset"], "correct": 0, "explanation_ja": "Sparkのtyped Dataset APIはJavaとScalaで利用でき、PySparkではDataFrame APIを使います。Pythonの型ヒントを付けるだけでJavaのDataset<Customer>と同じコンパイル時型検査が得られるわけではありません。構造化データはPySpark DataFrameで扱えます。", "distractors_ja": ["正答", "Python DataFrameで構造化データを処理できます。", "Javaのジェネリック型構文をそのままPythonへ移せません。", "Python型ヒントはtyped Datasetを作る機能ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-programming-guide.html", "validation": "公式資料照合・未実行", "author_id": "A019", "exam": 3, "concept": "query-plans", "concept_label": "SQLエンジン・実行計画・AQE", "misconception_tags": ["", "確認ポイント：Python DataFrameで構造化データを処理できます。", "確認ポイント：Javaのジェネリック型構文をそのままPythonへ移せません。", "確認ポイント：Python型ヒントはtyped Datasetを作る機能ではありません。"], "suggested_causes": ["unknown", "knowledge", "api", "knowledge"], "stem_ja": "Javaの例では、コンパイル時に型が定まるオブジェクトを持つDataset<Customer>を使用しています。このジョブをPySpark 3.5.xに移植する開発者への説明として正しいものはどれですか。", "options_ja": ["PySparkはDataFrame APIを提供するが、Java/Scalaの型付きDataset APIは提供しない", "Pythonで構造化データをクエリするには、あらかじめ型付きDatasetが必要である", "PySparkは同じPython構文でDataset<Customer>をサポートする", "Pythonの型ヒントを使用すると、型付きSpark Datasetが自動的に作成される"]}, {"id": "M3-20", "domain": "DataFrame", "topic": "null-handling-in-udf", "objective": "UDF内部でNULL入力を安全に扱う", "difficulty": "applied", "stem": "A scalar Python UDF receives a nullable string and must return its length, or 0 for NULL. Which Python function body is safe for both valid strings and NULL inputs?", "options": ["return len(s)", "return s.length()", "return len(s) if s != \"NULL\" else 0", "return 0 if s is None else len(s)"], "correct": 3, "explanation_ja": "PySparkの通常のPython UDFへ渡るSQL NULLはPythonのNoneとして扱う。Noneにlenを呼ぶと失敗するため、関数内で先に分岐させる。文字列\"NULL\"は欠損値そのものではない。外側の条件式だけに短絡評価を期待するより、UDF自体が許容入力を安全に処理する形にする。", "distractors_ja": ["Noneに対してlenを呼ぶとPython例外になる。", "PythonのstrやNoneにはこのlengthメソッドがない。", "Noneは文字列NULLとは等しくないためlen(None)へ進む。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.udf.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C051", "exam": 3, "concept": "python-udfs", "concept_label": "Python UDFの定義と制約", "misconception_tags": ["確認ポイント：Noneに対してlenを呼ぶとPython例外になる。", "確認ポイント：PythonのstrやNoneにはこのlengthメソッドがない。", "確認ポイント：Noneは文字列NULLとは等しくないためlen(None)へ進む。", ""], "suggested_causes": ["knowledge", "api", "boundary", "unknown"], "stem_ja": "スカラーPython UDFがNULLを許容する文字列を受け取り、その長さを返す必要があります。NULLの場合は0を返します。有効な文字列とNULLの両方の入力に対して安全なPython関数の本体はどれですか。", "options_ja": ["return len(s)", "return s.length()", "return len(s) if s != \"NULL\" else 0", "return 0 if s is None else len(s)"]}, {"id": "M3-21", "domain": "Structured Streaming", "topic": "Completeモード", "objective": "各トリガーの全集計結果を選ぶ", "difficulty": "applied", "stem": "A running count by city has current results Oslo=5 and Bern=2. The next micro-batch contains one Oslo record and no Bern records. With complete mode and the console sink, which result rows are emitted for that batch?", "options": ["Oslo=6 only", "Bern=2 only", "Oslo=1 only", "Oslo=6 and Bern=2"], "correct": 3, "explanation_ja": "completeはそのトリガー時点の結果テーブル全体を出力する。新規入力がなかったBernも結果として残るため出力される。新しく入力された行、更新された集計行、全集計行という3つの範囲を区別すると判断できる。", "distractors_ja": ["変更された行だけの出力はupdateの考え方である。", "変更の有無にかかわらず全結果なのでOsloも必要である。", "入力差分の件数であり現在の集計結果ではない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.ss/api/pyspark.sql.streaming.DataStreamWriter.outputMode.html", "validation": "公式資料照合・未実行", "author_id": "B040", "exam": 3, "concept": "stream-modes", "concept_label": "ストリーミング出力モード", "misconception_tags": ["確認ポイント：変更された行だけの出力はupdateの考え方である。", "確認ポイント：変更の有無にかかわらず全結果なのでOsloも必要である。", "確認ポイント：入力差分の件数であり現在の集計結果ではない。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "都市ごとの累積件数の現在の結果はOslo=5、Bern=2です。次のマイクロバッチにはOsloのレコードが1件あり、Bernのレコードはありません。completeモードとconsoleシンクを使用すると、このバッチでどの結果行が出力されますか。", "options_ja": ["Oslo=6だけ", "Bern=2だけ", "Oslo=1だけ", "Oslo=6とBern=2"]}, {"id": "M3-22", "domain": "Architecture", "topic": "Driver responsibilities", "objective": "driverとexecutorの役割を区別する", "difficulty": "basic", "stem": "A production Spark application has one driver and several executors. A user starts an action from the application's main program. Which component coordinates the execution of tasks for that application?", "options": ["The driver", "The cluster manager, by scheduling every row-level transformation", "The external shuffle service", "The executor that owns the largest input partition"], "correct": 0, "explanation_ja": "driverはアプリケーションの処理を管理し、計算をタスクとしてexecutorへ割り当てます。executorは割り当てられた処理を実行する側です。クラスタ全体の資源割当てと、アプリケーション内のタスク実行管理を区別して理解しましょう。", "distractors_ja": ["正答", "cluster managerは資源割当を担い、アプリ内のtask調整はdriverが担う。", "shuffle serviceはtask全体の調整役ではない。", "入力partitionの大きさによって調整役のexecutorが選ばれる仕組みではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/cluster-overview.html", "validation": "公式資料照合・未実行", "author_id": "A001", "exam": 3, "concept": "cluster-resources", "concept_label": "driver・executor・並列資源", "misconception_tags": ["", "確認ポイント：cluster managerは資源割当を担い、アプリ内のtask調整はdriverが担う。", "確認ポイント：shuffle serviceはtask全体の調整役ではない。", "確認ポイント：入力partitionの大きさによって調整役のexecutorが選ばれる仕組みではない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "本番用Sparkアプリケーションには、1つのドライバーと複数のエグゼキューターがあります。ユーザーがアプリケーションのメインプログラムからアクションを開始します。このアプリケーションのタスク実行を調整するコンポーネントはどれですか。", "options_ja": ["ドライバー", "行単位のすべての変換をスケジューリングするクラスターマネージャー", "外部シャッフルサービス", "最大の入力パーティションを持つエグゼキューター"]}, {"id": "M3-23", "domain": "Architecture", "topic": "Task closure isolation", "objective": "executor内変更とdriver変数を区別する", "difficulty": "applied", "stem": "In a cluster-mode classic PySpark application, a function passed to an RDD foreach appends values to a normal Python list captured from the driver. What should the developer expect when inspecting the original driver list afterward?", "options": ["All task-side appends are atomically merged into the driver list", "Task-side changes do not provide a reliable way to update the original driver list", "The list is automatically persisted as a Delta table", "The list automatically becomes a Spark accumulator"], "correct": 1, "explanation_ja": "タスクへ渡された通常のPython変数は、driverの同じメモリ領域を共有する同期変数ではありません。executor内のコピーに対する変更をdriverへ確実に反映する設計はできません。分散結果は適切な集約や収集、用途に合う共有変数を使って扱います。", "distractors_ja": ["通常のリストの変更が自動で原子的にマージされる保証はありません。", "正答", "Deltaテーブルへの保存は実行されません。", "accumulatorへの自動変換は行われません。"], "source_url": "https://spark.apache.org/docs/3.5.6/rdd-programming-guide.html", "validation": "公式資料照合・未実行", "author_id": "A030", "exam": 3, "concept": "cluster-resources", "concept_label": "driver・executor・並列資源", "misconception_tags": ["確認ポイント：通常のリストの変更が自動で原子的にマージされる保証はありません。", "", "確認ポイント：Deltaテーブルへの保存は実行されません。", "確認ポイント：accumulatorへの自動変換は行われません。"], "suggested_causes": ["api", "unknown", "knowledge", "knowledge"], "stem_ja": "クラスターモードのclassic PySparkアプリケーションで、RDDのforeachに渡した関数が、ドライバーからキャプチャした通常のPythonリストに値を追加します。その後、元のドライバーのリストを確認すると、開発者はどのような結果を想定すべきですか。", "options_ja": ["タスク側でのすべての追加が、原子的にドライバーのリストへ統合される", "タスク側での変更は、元のドライバーのリストを確実に更新する方法にはならない", "リストがDeltaテーブルとして自動的に永続化される", "リストが自動的にSparkアキュムレーターになる"]}, {"id": "M3-24", "domain": "DataFrame", "topic": "scalar-udf-return-type", "objective": "Python UDFの戻り値型を指定する", "difficulty": "applied", "stem": "A custom Python function classify(n) returns an integer category for every input integer. The function cannot be replaced by built-in expressions. Which definition declares the intended Spark return type before applying it to df.units?", "options": ["classify_udf = F.udf(classify, IntegerType())", "classify_udf = IntegerType(classify)", "classify_udf = F.lit(classify)", "classify_udf = F.udf(classify, StringType())"], "correct": 0, "explanation_ja": "通常のPython UDFを作る際は、udfへPython関数とSparkの戻り値型を渡す。関数が返すPython値と宣言型を対応させることが重要で、この例ではIntegerTypeが適切である。型オブジェクトに関数を渡してもUDFにはならず、litもPython関数を分散適用するための仕組みではない。", "distractors_ja": ["正答", "DataTypeの生成はUDFの登録や変換ではない。", "litは関数を各行へ適用するUDFを作成しない。", "要求されている整数の出力型と一致しない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.udf.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C050", "exam": 3, "concept": "python-udfs", "concept_label": "Python UDFの定義と制約", "misconception_tags": ["", "確認ポイント：DataTypeの生成はUDFの登録や変換ではない。", "確認ポイント：litは関数を各行へ適用するUDFを作成しない。", "確認ポイント：要求されている整数の出力型と一致しない。"], "suggested_causes": ["unknown", "api", "api", "knowledge"], "stem_ja": "カスタムPython関数classify(n)は、すべての整数入力に対して整数のカテゴリを返します。この関数は組み込みの式では置き換えられません。df.unitsに適用する前に、意図したSparkの戻り値の型を宣言する定義はどれですか。", "options_ja": ["classify_udf = F.udf(classify, IntegerType())", "classify_udf = IntegerType(classify)", "classify_udf = F.lit(classify)", "classify_udf = F.udf(classify, StringType())"]}, {"id": "M3-25", "domain": "Tuning", "topic": "Executorログ", "objective": "失敗したExecutorのstderrを調べる", "difficulty": "applied", "stem": "A stage repeatedly fails on executor 7 with an out-of-memory message. Executor log links are available in the Spark UI. Which investigation is most directly relevant?", "options": ["Inspect only the Storage tab and conclude that no cached blocks means no executor memory pressure.", "Inspect only the driver stdout and assume executor memory is identical to driver memory.", "Raise the SQL shuffle partition count without inspecting the failed task or its memory usage.", "Open the failed executor/task log links and inspect stderr and memory-related errors around the failure time."], "correct": 3, "explanation_ja": "失敗したタスクやExecutorに対応するログを、失敗時刻と合わせて確認する。driverとExecutorは別プロセスなので、Executor側のメモリ障害を調べるには該当stderrなどが直接の証拠になる。構成変更は原因を絞ってから行う。", "distractors_ja": ["実行用メモリやPythonなどもありcache量だけでは判断できない。", "executor障害のログを直接確認する必要がありdriverだけでは不十分。", "設定変更の前に障害場所と原因を確認すべき。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/web-ui.html#executors-tab", "validation": "公式資料照合・未実行", "author_id": "B057", "exam": 3, "concept": "memory-diagnostics", "concept_label": "メモリ・GC・診断", "misconception_tags": ["確認ポイント：実行用メモリやPythonなどもありcache量だけでは判断できない。", "確認ポイント：executor障害のログを直接確認する必要がありdriverだけでは不十分。", "確認ポイント：設定変更の前に障害場所と原因を確認すべき。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "あるステージがエグゼキューター7上で、メモリ不足のメッセージとともに繰り返し失敗します。Spark UIにはエグゼキューターログへのリンクがあります。最も直接的に関連する調査はどれですか。", "options_ja": ["Storageタブだけを確認し、キャッシュされたブロックがなければエグゼキューターのメモリ負荷もないと結論づける。", "ドライバーのstdoutだけを確認し、エグゼキューターのメモリはドライバーのメモリと同じだとみなす。", "失敗したタスクやそのメモリ使用量を調べずに、SQLのシャッフルパーティション数を増やす。", "失敗したエグゼキューターやタスクのログリンクを開き、失敗時刻の前後のstderrとメモリ関連エラーを調べる。"]}, {"id": "M3-26", "domain": "Spark SQL", "topic": "JDBC引数", "objective": "接続プロパティを正しい引数で渡す", "difficulty": "applied", "stem": "jdbc_url is a valid JDBC URL, and props is a dictionary containing user, password, and driver. Which call reads the table public.devices without attempting partition-column configuration?", "options": ["spark.read.jdbc(url=jdbc_url, query=\"public.devices\", properties=props)", "spark.read.jdbc(url=jdbc_url, table=\"public.devices\", column=props)", "spark.read.jdbc(jdbc_url, \"public.devices\", props)", "spark.read.jdbc(url=jdbc_url, table=\"public.devices\", properties=props)"], "correct": 3, "explanation_ja": "DataFrameReader.jdbcでは接続辞書をproperties引数に渡す。3番目の位置引数は分割列columnなので、辞書をその位置に渡すと接続設定にはならない。形式が似たformat(\"jdbc\")のoption群とも引数名を混同しない。", "distractors_ja": ["jdbcメソッドの引数はtableでありqueryではない。", "columnは分割する列名を受け取り、接続辞書は受け取らない。", "第3位置引数はpropertiesではなくcolumnである。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameReader.jdbc.html", "validation": "公式資料照合・未実行", "author_id": "B021", "exam": 3, "concept": "jdbc", "concept_label": "JDBC引数・分割・接続数", "misconception_tags": ["確認ポイント：jdbcメソッドの引数はtableでありqueryではない。", "確認ポイント：columnは分割する列名を受け取り、接続辞書は受け取らない。", "確認ポイント：第3位置引数はpropertiesではなくcolumnである。", ""], "suggested_causes": ["api", "knowledge", "api", "unknown"], "stem_ja": "jdbc_urlは有効なJDBC URLで、propsはuser、password、driverを含む辞書です。パーティション列の設定を試みずにpublic.devicesテーブルを読み取る呼び出しはどれですか。", "options_ja": ["spark.read.jdbc(url=jdbc_url, query=\"public.devices\", properties=props)", "spark.read.jdbc(url=jdbc_url, table=\"public.devices\", column=props)", "spark.read.jdbc(jdbc_url, \"public.devices\", props)", "spark.read.jdbc(url=jdbc_url, table=\"public.devices\", properties=props)"]}, {"id": "M3-27", "domain": "Pandas API", "topic": "Grouped pandas memory", "objective": "グループ単位pandas処理のメモリを判断する", "difficulty": "challenging", "stem": "A batch job uses df.groupBy('account_id').applyInPandas(func, schema). One account contains most of the dataset. The developer lowers spark.sql.execution.arrow.maxRecordsPerBatch and expects that account's group to be split safely into small independent calls. What is the correct assessment?", "options": ["Only driver memory matters because grouped processing never runs on workers", "applyInPandas always performs partial aggregation before Python sees a group", "That setting does not split a group for applyInPandas; the whole group must fit in memory for the grouped call", "The setting guarantees exactly one row per group call"], "correct": 2, "explanation_ja": "groupBy後のapplyInPandasでは、1グループのデータがまとめてメモリへロードされます。ArrowのmaxRecordsPerBatchを下げてもグループを分割する制御にはならないため、極端に大きいキーはメモリ不足の原因になります。入力グループの大きさを設計段階で確認します。", "distractors_ja": ["worker側のメモリが重要です。", "任意の関数に対して自動で部分集約を行う保証はありません。", "正答", "1行ずつの呼出しを保証する設定ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.GroupedData.applyInPandas.html", "validation": "公式資料照合・未実行", "author_id": "A051", "exam": 3, "concept": "pandas-udfs", "concept_label": "pandas UDF・バッチ・グループ", "misconception_tags": ["確認ポイント：worker側のメモリが重要です。", "確認ポイント：任意の関数に対して自動で部分集約を行う保証はありません。", "", "確認ポイント：1行ずつの呼出しを保証する設定ではありません。"], "suggested_causes": ["knowledge", "api", "unknown", "boundary"], "stem_ja": "バッチジョブがdf.groupBy('account_id').applyInPandas(func, schema)を使用しています。1つのアカウントがデータセットの大部分を占めています。開発者はspark.sql.execution.arrow.maxRecordsPerBatchを小さくし、そのアカウントのグループが小さい独立した呼び出しに安全に分割されることを期待しています。正しい評価はどれですか。", "options_ja": ["グループ単位の処理はワーカー上で実行されないため、ドライバーのメモリだけが問題になる", "applyInPandasは、Pythonにグループが渡される前に必ず部分集約を行う", "この設定はapplyInPandasのグループを分割しない。グループ単位の呼び出しでは、グループ全体がメモリに収まる必要がある", "この設定により、グループ単位の呼び出しごとに必ず1行だけが渡される"]}, {"id": "M3-28", "domain": "Structured Streaming", "topic": "watermarkなしの重複排除", "objective": "バッチをまたぐ状態の増大を理解する", "difficulty": "applied", "stem": "A never-ending stream has an unbounded number of unique event_id values. The query calls dropDuplicates([\"event_id\"]) without a watermark. Why can its state keep growing?", "options": ["dropDuplicates compares rows only within each individual micro-batch.", "Every distinct key automatically expires after one trigger.", "It must remember previously seen keys across triggers to suppress future duplicates without a time bound.", "dropDuplicates without a watermark converts the stream into a finite batch."], "correct": 2, "explanation_ja": "ストリームのdropDuplicatesはバッチをまたいで既出キーを記憶する。watermarkがなく時間範囲も限定されない場合、将来届く重複を判定するため状態が増大し得る。バッチDataFrameでの重複排除と同じ有限入力だと考えないことが重要である。", "distractors_ja": ["ストリーミングの重複排除はトリガーをまたいで状態を持つ。", "watermarkなしで1トリガー後に自動失効する仕様ではない。", "正答", "無限入力が自動的に有限入力へ変わることはない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.dropDuplicates.html", "validation": "公式資料照合・未実行", "author_id": "B047", "exam": 3, "concept": "stream-watermark", "concept_label": "イベント時刻・watermark・状態", "misconception_tags": ["確認ポイント：ストリーミングの重複排除はトリガーをまたいで状態を持つ。", "確認ポイント：watermarkなしで1トリガー後に自動失効する仕様ではない。", "", "確認ポイント：無限入力が自動的に有限入力へ変わることはない。"], "suggested_causes": ["boundary", "knowledge", "unknown", "knowledge"], "stem_ja": "終了しないストリームがあり、一意なevent_id値の数には上限がありません。クエリはウォーターマークなしでdropDuplicates([\"event_id\"])を呼び出します。その状態が増え続ける可能性があるのはなぜですか。", "options_ja": ["dropDuplicatesは、個々のマイクロバッチ内の行だけを比較する。", "それぞれの異なるキーは、1回のトリガー後に自動的に期限切れになる。", "時間の制限なく将来の重複を抑制するために、過去に出現したキーをトリガーをまたいで記憶しておく必要がある。", "ウォーターマークなしのdropDuplicatesは、ストリームを有限のバッチに変換する。"]}, {"id": "M3-29", "domain": "DataFrame", "topic": "empty-dataframe-schema", "objective": "空DataFrameに明示スキーマを与える", "difficulty": "basic", "stem": "A program must create an empty DataFrame with columns batch_id INT and comment STRING before any records arrive. Which expression reliably provides those column types?", "options": ["spark.createDataFrame([None], \"batch_id INT, comment STRING\")", "spark.createDataFrame([], \"batch_id INT, comment STRING\")", "spark.createDataFrame([], [\"batch_id\", \"comment\"])", "spark.createDataFrame([])"], "correct": 1, "explanation_ja": "空の入力には型を推論するレコードがないため、列名だけでなく型を含む明示スキーマを渡す必要がある。DDL形式の文字列を指定すれば、0行でも目的の2列と型を持つDataFrameを作れる。Noneを1要素入れることは空DataFrameの作成とは異なり、行構造も指定スキーマに合わない。", "distractors_ja": ["Noneという要素を入れる方法は0行の入力ではない。", "正答", "列名だけでは空入力に対してデータ型を決められない。", "空入力からは列型を推論できない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.SparkSession.createDataFrame.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C041", "exam": 3, "concept": "schema-types", "concept_label": "スキーマ・型の確認", "misconception_tags": ["確認ポイント：Noneという要素を入れる方法は0行の入力ではない。", "", "確認ポイント：列名だけでは空入力に対してデータ型を決められない。", "確認ポイント：空入力からは列型を推論できない。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "プログラムは、レコードが到着する前にbatch_id INTとcomment STRINGの列を持つ空のDataFrameを作成する必要があります。これらの列の型を確実に設定する式はどれですか。", "options_ja": ["spark.createDataFrame([None], \"batch_id INT, comment STRING\")", "spark.createDataFrame([], \"batch_id INT, comment STRING\")", "spark.createDataFrame([], [\"batch_id\", \"comment\"])", "spark.createDataFrame([])"]}, {"id": "M3-30", "domain": "Structured Streaming", "topic": "SQLによるストリーム変換", "objective": "ストリーミング性を保ったSQL処理を判断する", "difficulty": "applied", "stem": "events is a streaming DataFrame. It is registered as a local temporary view incoming_events. The engineer runs clean = spark.sql(\"SELECT sensor, value FROM incoming_events WHERE value >= 0\"). How should clean normally be executed as a continuing pipeline?", "options": ["Convert the SQL text to an RDD before any streaming sink can be used.", "Use clean.writeStream with a supported sink and call start().", "Use clean.collect() once to fetch all future events.", "Use clean.write.mode(\"append\").parquet(path) as an ordinary finite batch."], "correct": 1, "explanation_ja": "ストリーミングDataFrameを参照するSQLの選択・フィルター結果もストリーミングとして扱う。継続実行はwriteStreamで出力を構成してstartする。SQLを使ったことだけで無限入力が通常の有限バッチへ変わるわけではない。", "distractors_ja": ["Structured StreamingのSQL処理にRDD変換は必須ではない。", "正答", "無限の将来データを1回のcollectで取得することはできない。", "ストリーミング結果を通常のバッチwriteとして実行しない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.isStreaming.html", "validation": "公式資料照合・未実行", "author_id": "B053", "exam": 3, "concept": "stream-lifecycle", "concept_label": "ストリーム入力・開始・停止・trigger", "misconception_tags": ["確認ポイント：Structured StreamingのSQL処理にRDD変換は必須ではない。", "", "確認ポイント：無限の将来データを1回のcollectで取得することはできない。", "確認ポイント：ストリーミング結果を通常のバッチwriteとして実行しない。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "eventsはストリーミングDataFrameです。ローカル一時ビューincoming_eventsとして登録されています。エンジニアがclean = spark.sql(\"SELECT sensor, value FROM incoming_events WHERE value >= 0\")を実行します。通常、cleanを継続的なパイプラインとして実行するにはどうすべきですか。", "options_ja": ["ストリーミングシンクを使用する前に、SQLテキストをRDDに変換する。", "サポートされているシンクを指定してclean.writeStreamを使用し、start()を呼び出す。", "将来のすべてのイベントを取得するために、clean.collect()を1回使用する。", "通常の有限バッチとしてclean.write.mode(\"append\").parquet(path)を使用する。"]}, {"id": "M3-31", "domain": "Architecture", "topic": "New session isolation", "objective": "newSessionの共有範囲を識別する", "difficulty": "applied", "stem": "A classic SparkSession s1 creates s2 = s1.newSession(). Which pair is shared between s1 and s2?", "options": ["Registered session UDFs and all session SQL settings", "Session-local temporary views and SQL configuration", "SparkContext and table cache", "Python local variables and an independent executor pool per session"], "correct": 2, "explanation_ja": "newSessionではSQL設定、一時ビュー、登録UDFのセッション状態が分かれます。一方でSparkContextとテーブルキャッシュは共有されます。新しいsessionを作ることと、まったく独立したSparkアプリケーションを起動することの違いが問われています。", "distractors_ja": ["セッション登録UDFとSQL設定も分離されます。", "これらはnewSessionで分離されるセッション状態です。", "正答", "sessionごとに独立したexecutorプールを作る意味ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.SparkSession.newSession.html", "validation": "公式資料照合・未実行", "author_id": "A014", "exam": 3, "concept": "sessions-views", "concept_label": "セッション・ビューの共有範囲", "misconception_tags": ["確認ポイント：セッション登録UDFとSQL設定も分離されます。", "確認ポイント：これらはnewSessionで分離されるセッション状態です。", "", "確認ポイント：sessionごとに独立したexecutorプールを作る意味ではありません。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "classic SparkSessionのs1からs2 = s1.newSession()を作成します。s1とs2の間で共有される組み合わせはどれですか。", "options_ja": ["登録済みのセッションUDFと、すべてのセッションSQL設定", "セッションローカルの一時ビューとSQL設定", "SparkContextとテーブルキャッシュ", "Pythonのローカル変数と、セッションごとに独立したエグゼキュータープール"]}, {"id": "M3-32", "domain": "Spark SQL", "topic": "JDBC分割境界", "objective": "分割幅と行フィルターを区別する", "difficulty": "challenging", "stem": "A JDBC read partitions on numeric id with lowerBound=100, upperBound=200, and numPartitions=4. The underlying table also contains id=20 and id=900. No WHERE predicate is supplied. Which statement is correct?", "options": ["Rows outside the bounds are replaced with null rows.", "Only rows satisfying 100 <= id < 200 are read.", "The read always fails because the bounds must exactly match MIN(id) and MAX(id).", "The bounds determine partition strides; rows outside 100 through 200 are not excluded merely by these bounds."], "correct": 3, "explanation_ja": "JDBCのlowerBoundとupperBoundは読み取り分割の幅を決める値であり、取得範囲を制限するWHERE条件ではない。特定範囲だけ必要ならSQL側などでフィルターを指定する。境界値と抽出条件の役割を取り違えないことが重要である。", "distractors_ja": ["範囲外の値をnullに置換する仕様はない。", "分割境界を行の絞り込み条件と誤解している。", "最小・最大値との完全一致は必須条件ではない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-data-sources-jdbc.html", "validation": "公式資料照合・未実行", "author_id": "B022", "exam": 3, "concept": "jdbc", "concept_label": "JDBC引数・分割・接続数", "misconception_tags": ["確認ポイント：範囲外の値をnullに置換する仕様はない。", "確認ポイント：分割境界を行の絞り込み条件と誤解している。", "確認ポイント：最小・最大値との完全一致は必須条件ではない。", ""], "suggested_causes": ["boundary", "boundary", "knowledge", "unknown"], "stem_ja": "JDBC読み取りで数値型のidを基準にパーティションを分割し、lowerBound=100、upperBound=200、numPartitions=4を指定します。元のテーブルにはid=20とid=900も含まれています。WHERE述語は指定されていません。正しい説明はどれですか。", "options_ja": ["境界の範囲外にある行は、nullの行に置き換えられる。", "100 <= id < 200を満たす行だけが読み取られる。", "境界はMIN(id)とMAX(id)に完全に一致しなければならないため、読み取りは必ず失敗する。", "境界はパーティション分割の幅を決める。100から200の範囲外にある行は、この境界を指定しただけでは除外されない。"]}, {"id": "M3-33", "domain": "DataFrame", "topic": "null-safe-join", "objective": "NULL同士も一致させる条件を使う", "difficulty": "applied", "stem": "Both a and b contain a nullable code column. A reconciliation rule treats two NULL codes as a match, as well as equal non-null codes. Which join condition implements that rule?", "options": ["a.code.eqNullSafe(b.code)", "a.code != b.code", "a.code == b.code", "a.code.isNull() & b.code.isNull()"], "correct": 0, "explanation_ja": "eqNullSafeは両方NULLのときtrue、片方だけNULLならfalse、非NULL同士では等値を返す。そのため通常の等値とNULL同士の対応を1つの条件で扱える。通常の==ではNULLを含む比較がunknownとなる。NULL判定だけの条件では非NULLで同じ値の組み合わせを取りこぼす。", "distractors_ja": ["正答", "等しい値ではなく異なる値を選ぶ条件になる。", "通常の等値比較ではNULL同士が一致扱いにならない。", "非NULLで等しいコードの組を除外してしまう。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.Column.eqNullSafe.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C014", "exam": 3, "concept": "joins", "concept_label": "結合条件・結合種類・行数", "misconception_tags": ["", "確認ポイント：等しい値ではなく異なる値を選ぶ条件になる。", "確認ポイント：通常の等値比較ではNULL同士が一致扱いにならない。", "確認ポイント：非NULLで等しいコードの組を除外してしまう。"], "suggested_causes": ["unknown", "knowledge", "boundary", "boundary"], "stem_ja": "aとbの両方に、NULLを許容するcode列があります。照合ルールでは、等しい非NULLのコード同士だけでなく、両方がNULLのコードも一致として扱います。このルールを実装する結合条件はどれですか。", "options_ja": ["a.code.eqNullSafe(b.code)", "a.code != b.code", "a.code == b.code", "a.code.isNull() & b.code.isNull()"]}, {"id": "M3-34", "domain": "Spark SQL", "topic": "パーティション保存とファイル数", "objective": "ディレクトリ数とファイル数を区別する", "difficulty": "applied", "stem": "A successful write uses df.write.partitionBy(\"region\").parquet(path). No file-count controls are used, and many tasks contain rows for region='east'. Which output assumption is safe?", "options": ["There must be exactly one data file for each region.", "The number of data files must equal the number of distinct regions.", "All rows for all regions must be stored in a single sorted data file.", "The east rows are stored under a region=east partition directory, which can contain multiple data files."], "correct": 3, "explanation_ja": "partitionByは列値別の保存ディレクトリを作る指定であり、各ディレクトリを必ず1ファイルにする指定ではない。同じ値を持つ行が複数タスクから書かれれば複数ファイルになり得る。論理パーティションと物理ファイルを分けて考える。", "distractors_ja": ["partitionByだけで1値1ファイルとは保証されない。", "値の種類数だけで物理ファイル数は決まらない。", "列値別レイアウトと単一の全体ソートファイルは異なる。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameWriter.partitionBy.html", "validation": "公式資料照合・未実行", "author_id": "B033", "exam": 3, "concept": "file-write-layout", "concept_label": "保存モード・テーブル・配置", "misconception_tags": ["確認ポイント：partitionByだけで1値1ファイルとは保証されない。", "確認ポイント：値の種類数だけで物理ファイル数は決まらない。", "確認ポイント：列値別レイアウトと単一の全体ソートファイルは異なる。", ""], "suggested_causes": ["boundary", "knowledge", "knowledge", "unknown"], "stem_ja": "df.write.partitionBy(\"region\").parquet(path)による書き込みが成功します。ファイル数の制御は使用しておらず、多くのタスクにregion='east'の行が含まれています。出力について確実に言えることはどれですか。", "options_ja": ["regionごとにデータファイルが必ずちょうど1個存在する。", "データファイルの数は、異なるregionの数と必ず等しくなる。", "すべてのregionのすべての行が、ソートされた1つのデータファイルに必ず格納される。", "eastの行はregion=eastのパーティションディレクトリの下に保存され、その中には複数のデータファイルが存在する場合がある。"]}, {"id": "M3-35", "domain": "Architecture", "topic": "Disk-only persistence", "objective": "要件に合う保存レベルを選ぶ", "difficulty": "applied", "stem": "A reusable intermediate result should be persisted to executor disks without retaining its cached blocks in executor memory. Which storage level most directly expresses that requirement?", "options": ["StorageLevel.MEMORY_ONLY", "StorageLevel.NONE", "StorageLevel.DISK_ONLY", "StorageLevel.MEMORY_AND_DISK_DESER"], "correct": 2, "explanation_ja": "キャッシュブロックをディスクのみに保存したい要件にはDISK_ONLYを選びます。MEMORY_AND_DISK系はメモリも利用するため、今回の「メモリには保持しない」という条件と一致しません。保存レベルは計算時に必要な作業メモリをゼロにする設定ではありません。", "distractors_ja": ["メモリを利用する保存レベルです。", "永続化しない設定では再利用の保存要件を満たしません。", "正答", "メモリとディスクの両方を利用します。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/api/pyspark.StorageLevel.DISK_ONLY.html", "validation": "公式資料照合・未実行", "author_id": "A011", "exam": 3, "concept": "cache-persist", "concept_label": "cache・persist・再利用", "misconception_tags": ["確認ポイント：メモリを利用する保存レベルです。", "確認ポイント：永続化しない設定では再利用の保存要件を満たしません。", "", "確認ポイント：メモリとディスクの両方を利用します。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "再利用する中間結果をエグゼキューターのディスクに永続化し、キャッシュされたブロックはエグゼキューターのメモリに保持しないようにする必要があります。この要件を最も直接的に表すストレージレベルはどれですか。", "options_ja": ["StorageLevel.MEMORY_ONLY", "StorageLevel.NONE", "StorageLevel.DISK_ONLY", "StorageLevel.MEMORY_AND_DISK_DESER"]}, {"id": "M3-36", "domain": "Spark Connect", "topic": "Connect session builder", "objective": "remote接続の正しいAPIを選ぶ", "difficulty": "applied", "stem": "A compatible Spark Connect server is already running at analytics.example:15002. No active SparkSession exists in the Python client process. Which call explicitly creates a session connected to that endpoint?", "options": ["SparkSession.builder.remote('sc://analytics.example:15002').getOrCreate()", "SparkSession.builder.config('spark.connect.enabled', 'analytics.example:15002').getOrCreate()", "SparkSession.builder.master('sc://analytics.example:15002').getOrCreate()", "SparkSession.builder.appName('sc://analytics.example:15002').getOrCreate()"], "correct": 0, "explanation_ja": "Spark Connectの接続先はbuilder.remoteにsc://形式で指定します。masterはclassic Sparkの実行先指定、appNameは名称設定であり、この接続先指定の代用ではありません。存在しない有効化設定にホスト名を入れるだけでConnect sessionが作れるわけでもありません。", "distractors_ja": ["正答", "その設定を接続APIとして利用する仕様はありません。", "masterはSpark Connectのremote指定の代わりではありません。", "appNameはアプリケーション名であり接続先ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.SparkSession.builder.remote.html", "validation": "公式資料照合・未実行", "author_id": "A038", "exam": 3, "concept": "connect-api", "concept_label": "Spark Connectの接続方法・制約", "misconception_tags": ["", "確認ポイント：その設定を接続APIとして利用する仕様はありません。", "確認ポイント：masterはSpark Connectのremote指定の代わりではありません。", "確認ポイント：appNameはアプリケーション名であり接続先ではありません。"], "suggested_causes": ["unknown", "api", "knowledge", "knowledge"], "stem_ja": "互換性のあるSpark Connectサーバーがanalytics.example:15002ですでに稼働しています。PythonクライアントプロセスにはアクティブなSparkSessionがありません。このエンドポイントに接続するセッションを明示的に作成する呼び出しはどれですか。", "options_ja": ["SparkSession.builder.remote('sc://analytics.example:15002').getOrCreate()", "SparkSession.builder.config('spark.connect.enabled', 'analytics.example:15002').getOrCreate()", "SparkSession.builder.master('sc://analytics.example:15002').getOrCreate()", "SparkSession.builder.appName('sc://analytics.example:15002').getOrCreate()"]}, {"id": "M3-37", "domain": "Architecture", "topic": "Allocated cores", "objective": "ノード数と割当て資源を区別する", "difficulty": "applied", "stem": "A cluster has five worker machines. This application currently has three executors, each allocated four cores. Assume one CPU per task and no other limits. How many task CPU slots does the application currently have?", "options": ["12", "3", "20", "5"], "correct": 0, "explanation_ja": "このアプリケーションに割り当てられたexecutorは3個で、各4コアなので12スロットです。workerが5台あることから全台のCPUをこのアプリケーションが利用できるとは判断できません。設問ではクラスタの規模と実際の割当て資源を分けて読み取ります。", "distractors_ja": ["正答", "executorごとの4コアを考慮する必要があります。", "5台すべてに4コアが割り当てられたという条件ではありません。", "マシン数はタスクスロット数ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.6/configuration.html", "validation": "公式資料照合・未実行", "author_id": "A035", "exam": 3, "concept": "cluster-resources", "concept_label": "driver・executor・並列資源", "misconception_tags": ["", "確認ポイント：executorごとの4コアを考慮する必要があります。", "確認ポイント：5台すべてに4コアが割り当てられたという条件ではありません。", "確認ポイント：マシン数はタスクスロット数ではありません。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "クラスターには5台のワーカーマシンがあります。このアプリケーションには現在3個のエグゼキューターがあり、それぞれに4コアが割り当てられています。タスクごとに1個のCPUを使用し、ほかの制限はないとします。アプリケーションが現在持つタスク用のCPUスロットはいくつですか。", "options_ja": ["12", "3", "20", "5"]}, {"id": "M3-38", "domain": "DataFrame", "topic": "ordered-top-n-collect", "objective": "小さい結果を順序付きでdriverへ取得する", "difficulty": "applied", "stem": "df has unique non-null integer ticket_id values. Retrieve the three smallest IDs as a Python list of Row objects. Which expression directly guarantees that result?", "options": ["df.select(\"ticket_id\").orderBy(\"ticket_id\").show(3)", "df.select(\"ticket_id\").limit(3).orderBy(\"ticket_id\").collect()", "df.select(\"ticket_id\").collect()[:3]", "df.select(\"ticket_id\").orderBy(\"ticket_id\").limit(3).collect()"], "correct": 3, "explanation_ja": "まず全体をticket_idで昇順にし、その先頭3行をlimitしてcollectすれば、最小の3つをPythonのRowリストとして取得できる。limitを先に適用すると任意の3行を選んでから並べることになる。showは表示操作で戻り値がRowリストではない点も区別する。", "distractors_ja": ["showは表示してNoneを返し、Rowリストを返さない。", "先に任意の3行へ限定するので全体の最小3件とは限らない。", "DataFrameの行順は未指定であり最小の3件とは限らない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.orderBy.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C047", "exam": 3, "concept": "windows-order", "concept_label": "ウィンドウ関数・順序", "misconception_tags": ["確認ポイント：showは表示してNoneを返し、Rowリストを返さない。", "確認ポイント：先に任意の3行へ限定するので全体の最小3件とは限らない。", "確認ポイント：DataFrameの行順は未指定であり最小の3件とは限らない。", ""], "suggested_causes": ["api", "knowledge", "knowledge", "unknown"], "stem_ja": "dfには、一意で非NULLの整数型ticket_id値があります。最小の3つのIDを、RowオブジェクトのPythonリストとして取得します。その結果を直接保証する式はどれですか。", "options_ja": ["df.select(\"ticket_id\").orderBy(\"ticket_id\").show(3)", "df.select(\"ticket_id\").limit(3).orderBy(\"ticket_id\").collect()", "df.select(\"ticket_id\").collect()[:3]", "df.select(\"ticket_id\").orderBy(\"ticket_id\").limit(3).collect()"]}, {"id": "M3-39", "domain": "Architecture", "topic": "Parallelism limit", "objective": "パーティション数と利用可能CPUを区別する", "difficulty": "applied", "stem": "A stage has four runnable partitions and the application has 32 idle one-CPU task slots. There are no failures or speculative attempts. Why can this stage still have at most four tasks running at once?", "options": ["One partition is processed by eight ordinary tasks in parallel to fill all slots", "There are only four partitions to process in this stage", "SQL stages are limited to four concurrent tasks regardless of partition count", "Spark creates a new input partition for every idle CPU slot automatically"], "correct": 1, "explanation_ja": "利用可能なCPUが多くても、そのstageに実行対象パーティションが4個しかなければ、通常は4タスクまでです。資源の数と処理を分割した数の両方が並列度を制約します。空きスロットが存在するだけで、既存stageの各パーティションが自動で細分化されるとは限りません。", "distractors_ja": ["通常のtask処理では1partitionの入力を複数の独立taskへ自動分割しない。", "正答", "4という固定のSQL同時実行上限はない。", "空きCPUがあるだけではこのstageの入力partition数は増えない。"], "source_url": "https://spark.apache.org/docs/3.5.6/tuning.html", "validation": "公式資料照合・未実行", "author_id": "A027", "exam": 3, "concept": "cluster-resources", "concept_label": "driver・executor・並列資源", "misconception_tags": ["確認ポイント：通常のtask処理では1partitionの入力を複数の独立taskへ自動分割しない。", "", "確認ポイント：4という固定のSQL同時実行上限はない。", "確認ポイント：空きCPUがあるだけではこのstageの入力partition数は増えない。"], "suggested_causes": ["knowledge", "unknown", "boundary", "knowledge"], "stem_ja": "あるステージには実行可能なパーティションが4個あり、アプリケーションには1個のCPUを使用する空きタスクスロットが32個あります。失敗も投機的実行もありません。それでも、このステージで同時に実行できるタスクが最大4個なのはなぜですか。", "options_ja": ["すべてのスロットを埋めるために、1つのパーティションを8個の通常のタスクが並列で処理する", "このステージで処理するパーティションは4個しかない", "SQLステージでは、パーティション数に関係なく同時タスク数が4個に制限される", "Sparkが空いているCPUスロットごとに、新しい入力パーティションを自動的に作成する"]}, {"id": "M3-40", "domain": "Spark SQL", "topic": "既定の保存モード", "objective": "既存パスへの書き込み動作を判断する", "difficulty": "basic", "stem": "The path /exports/daily already contains a valid Parquet dataset. A batch executes df.write.parquet(\"/exports/daily\") with no mode specified. Assuming normal permissions, what is the expected result?", "options": ["Spark removes the destination because overwrite is the default.", "Spark appends the new rows because append is the default.", "The write raises an error because the destination already exists.", "Spark silently skips the write because ignore is the default."], "correct": 2, "explanation_ja": "通常のDataFrameWriterでは既定の保存モードはerror、または同義のerrorifexistsである。既存パスに対して成功させたい場合は、追加・置換・無視のどれを求めるかを決め、modeを明示する必要がある。", "distractors_ja": ["既定動作は既存データの置換ではない。", "appendは明示する保存モードである。", "正答", "ignoreも明示する必要がある。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameWriter.mode.html", "validation": "公式資料照合・未実行", "author_id": "B009", "exam": 3, "concept": "file-write-layout", "concept_label": "保存モード・テーブル・配置", "misconception_tags": ["確認ポイント：既定動作は既存データの置換ではない。", "確認ポイント：appendは明示する保存モードである。", "", "確認ポイント：ignoreも明示する必要がある。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "/exports/dailyには、有効なParquetデータセットがすでに存在します。バッチがmodeを指定せずにdf.write.parquet(\"/exports/daily\")を実行します。通常の権限があるとした場合、想定される結果はどれですか。", "options_ja": ["既定値はoverwriteなので、Sparkが保存先を削除する。", "既定値はappendなので、Sparkが新しい行を追加する。", "保存先がすでに存在するため、書き込みでエラーが発生する。", "既定値はignoreなので、Sparkが通知せずに書き込みをスキップする。"]}, {"id": "M3-41", "domain": "Spark SQL", "topic": "ファイルへの直接SQL", "objective": "プロバイダー付きパス参照を使う", "difficulty": "applied", "stem": "The Spark 3.5 environment has a compatible Delta Lake connector configured. No table or view has been registered for /archive/shipments, which is a valid Delta table directory. Which SQL query directly counts rows in its current snapshot?", "options": ["SELECT COUNT(*) FROM \"/archive/shipments\" USING delta", "SELECT COUNT(*) FROM path(\"/archive/shipments\", \"delta\")", "SELECT COUNT(*) FROM delta.`/archive/shipments`", "SELECT COUNT(*) FROM `/archive/shipments`.delta"], "correct": 2, "explanation_ja": "対応するDelta Lake connectorを設定した環境では、deltaに続けてバッククォートで囲んだパスを指定し、現在のDelta tableをSQLで直接参照できる。元のParquet data filesだけを直接読む方法とは区別し、Deltaの論理的な現在のsnapshotを対象にする。", "distractors_ja": ["FROM句の直接パス参照の構文ではない。", "このpath関数を使う構文ではない。", "正答", "providerとパスの順序が逆である。"], "source_url": "https://docs.delta.io/delta-batch/#read-a-table", "validation": "Delta Lake公式資料照合・Spark未実行", "author_id": "B019", "exam": 3, "concept": "file-read-schema", "concept_label": "ファイル読込・スキーマ・形式", "misconception_tags": ["確認ポイント：FROM句の直接パス参照の構文ではない。", "確認ポイント：このpath関数を使う構文ではない。", "", "確認ポイント：providerとパスの順序が逆である。"], "suggested_causes": ["api", "api", "unknown", "knowledge"], "stem_ja": "Spark 3.5環境には、互換性のあるDelta Lakeコネクターが設定されています。有効なDeltaテーブルディレクトリである/archive/shipmentsに対し、テーブルやビューは登録されていません。その現在のスナップショットの行数を直接数えるSQLクエリはどれですか。", "options_ja": ["SELECT COUNT(*) FROM \"/archive/shipments\" USING delta", "SELECT COUNT(*) FROM path(\"/archive/shipments\", \"delta\")", "SELECT COUNT(*) FROM delta.`/archive/shipments`", "SELECT COUNT(*) FROM `/archive/shipments`.delta"]}, {"id": "M3-42", "domain": "Spark SQL", "topic": "JDBC predicates分割", "objective": "述語を使う並列読み取りを選ぶ", "difficulty": "applied", "stem": "The database column territory is STRING. An engineer wants two JDBC input partitions, one for territory='north' and one for all other non-null territories. Which call expresses these two database predicates directly?", "options": ["spark.read.jdbc(jdbc_url, \"accounts\", properties=props).sort(\"territory\")", "spark.read.jdbc(jdbc_url, \"accounts\", properties=props).coalesce(2)", "spark.read.jdbc(jdbc_url, \"accounts\", column=\"territory\", lowerBound=\"a\", upperBound=\"z\", numPartitions=2, properties=props)", "spark.read.jdbc(jdbc_url, \"accounts\", predicates=[\"territory = 'north'\", \"territory <> 'north'\"], properties=props)"], "correct": 3, "explanation_ja": "jdbcのpredicatesにはデータベースのWHERE句に使える条件のリストを渡し、それぞれを入力パーティションにできる。列範囲分割とは異なり文字列条件も指定できる。この例ではnullを対象外とする条件が問題文で明示されている。", "distractors_ja": ["読後のsortは入力のJDBC述語分割を設定しない。", "読後のcoalesceは指定述語によるJDBC並列取得ではない。", "範囲分割のpartitionColumnには文字列列を使えない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameReader.jdbc.html", "validation": "公式資料照合・未実行", "author_id": "B023", "exam": 3, "concept": "jdbc", "concept_label": "JDBC引数・分割・接続数", "misconception_tags": ["確認ポイント：読後のsortは入力のJDBC述語分割を設定しない。", "確認ポイント：読後のcoalesceは指定述語によるJDBC並列取得ではない。", "確認ポイント：範囲分割のpartitionColumnには文字列列を使えない。", ""], "suggested_causes": ["knowledge", "knowledge", "api", "unknown"], "stem_ja": "データベースのterritory列はSTRING型です。エンジニアはJDBC入力を2つのパーティションに分け、一方をterritory='north'、もう一方をそれ以外のすべての非NULLのterritoryにしたいと考えています。この2つのデータベース述語を直接表す呼び出しはどれですか。", "options_ja": ["spark.read.jdbc(jdbc_url, \"accounts\", properties=props).sort(\"territory\")", "spark.read.jdbc(jdbc_url, \"accounts\", properties=props).coalesce(2)", "spark.read.jdbc(jdbc_url, \"accounts\", column=\"territory\", lowerBound=\"a\", upperBound=\"z\", numPartitions=2, properties=props)", "spark.read.jdbc(jdbc_url, \"accounts\", predicates=[\"territory = 'north'\", \"territory <> 'north'\"], properties=props)"]}, {"id": "M3-43", "domain": "Architecture", "topic": "Session reuse", "objective": "getOrCreateの既存session再利用を理解する", "difficulty": "applied", "stem": "In a classic PySpark process, a valid default SparkSession already exists. A library calls SparkSession.builder.getOrCreate() with no additional settings. What should the library expect?", "options": ["All temporary views are automatically dropped", "Every existing executor is restarted", "The existing valid SparkSession can be returned", "A separate Spark application is always created"], "correct": 2, "explanation_ja": "getOrCreateは利用可能な既存SparkSessionがあればそれを返し、なければ作成します。呼ぶたびに独立したアプリケーションやクラスタを作るメソッドではありません。ライブラリ側が独立したSQL設定や一時ビュー空間を必要とするなら、この再利用動作を考慮します。", "distractors_ja": ["既存の一時ビューを自動削除しません。", "executorを必ず再起動する操作ではありません。", "正答", "常に新規作成するという説明が誤りです。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.SparkSession.builder.getOrCreate.html", "validation": "公式資料照合・未実行", "author_id": "A013", "exam": 3, "concept": "sessions-views", "concept_label": "セッション・ビューの共有範囲", "misconception_tags": ["確認ポイント：既存の一時ビューを自動削除しません。", "確認ポイント：executorを必ず再起動する操作ではありません。", "", "確認ポイント：常に新規作成するという説明が誤りです。"], "suggested_causes": ["knowledge", "boundary", "unknown", "boundary"], "stem_ja": "classic PySparkプロセスには、有効な既定のSparkSessionがすでに存在します。ライブラリが追加設定なしでSparkSession.builder.getOrCreate()を呼び出します。ライブラリはどのような動作を想定すべきですか。", "options_ja": ["すべての一時ビューが自動的に削除される", "既存のすべてのエグゼキューターが再起動される", "既存の有効なSparkSessionが返されることがある", "別のSparkアプリケーションが必ず作成される"]}, {"id": "M3-44", "domain": "DataFrame", "topic": "regex-extraction", "objective": "正規表現のグループを抽出する", "difficulty": "applied", "stem": "A non-null reference column contains values such as \"INV-742-EU\". Extract the digit sequence as a string using the capturing group in r\"INV-([0-9]+)-[A-Z]+\". Which expression returns \"742\" for this example?", "options": ["F.regexp_extract(\"reference\", r\"INV-([0-9]+)-[A-Z]+\", 0)", "F.regexp_extract(\"reference\", r\"INV-([0-9]+)-[A-Z]+\", 1)", "F.regexp_replace(\"reference\", r\"[0-9]+\", \"\")", "F.split(\"reference\", \"-\").getItem(0)"], "correct": 1, "explanation_ja": "regexp_extractの第3引数は抽出するキャプチャグループ番号で、1は最初の括弧に対応する。0を指定するとマッチ全体INV-742-EUを取り出す。ここで必要なのは数値型への変換ではなく文字列742である。抽出、置換、区切りによる分割を区別して選ぶ。", "distractors_ja": ["グループ0は一致全体を返す。", "正答", "数字を取り出すのではなく削除する。", "0番目の要素はINVである。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.regexp_extract.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C024", "exam": 3, "concept": "string-date-functions", "concept_label": "文字列・日付関数", "misconception_tags": ["確認ポイント：グループ0は一致全体を返す。", "", "確認ポイント：数字を取り出すのではなく削除する。", "確認ポイント：0番目の要素はINVである。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "非NULLのreference列には\"INV-742-EU\"などの値が含まれています。r\"INV-([0-9]+)-[A-Z]+\"のキャプチャグループを使って、数字の並びを文字列として抽出します。この例で\"742\"を返す式はどれですか。", "options_ja": ["F.regexp_extract(\"reference\", r\"INV-([0-9]+)-[A-Z]+\", 0)", "F.regexp_extract(\"reference\", r\"INV-([0-9]+)-[A-Z]+\", 1)", "F.regexp_replace(\"reference\", r\"[0-9]+\", \"\")", "F.split(\"reference\", \"-\").getItem(0)"]}, {"id": "M3-45", "domain": "DataFrame", "topic": "rename-missing-column", "objective": "存在しない列の改名を予測する", "difficulty": "applied", "stem": "df has exactly the columns [record_id, source_name]. What are the columns of df.withColumnRenamed(\"source\", \"origin\")?", "options": ["[record_id, origin]", "[record_id, source_name]", "[record_id, source_name, origin]", "The call always raises an exception for a missing source column."], "correct": 1, "explanation_ja": "withColumnRenamedは元の列名が存在しない場合、列構造を変更しない。ここで存在するのはsource_nameでありsourceではないため、結果の列名は元のままとなる。打ち間違いが例外で発見されるとは限らないので、改名処理後にcolumnsやschemaを確認する習慣が有効である。", "distractors_ja": ["source_nameは指定したsourceとは別の列名である。", "正答", "改名操作は存在しない列を新規追加しない。", "存在しない旧名の改名はno-opと定義されている。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.withColumnRenamed.html", "validation": "公式API資料参照・設問と選択肢の静的確認済み・Spark未実行", "author_id": "C044", "exam": 3, "concept": "column-expressions", "concept_label": "列式・射影・列名操作", "misconception_tags": ["確認ポイント：source_nameは指定したsourceとは別の列名である。", "", "確認ポイント：改名操作は存在しない列を新規追加しない。", "確認ポイント：存在しない旧名の改名はno-opと定義されている。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "dfの列は[record_id, source_name]だけです。df.withColumnRenamed(\"source\", \"origin\")の列は何ですか。", "options_ja": ["[record_id, origin]", "[record_id, source_name]", "[record_id, source_name, origin]", "元の列が存在しないため、この呼び出しは必ず例外を発生させる。"]}]}, {"id": "M4", "title": "本番形式模試 4（2026年10月改訂）", "questions": [{"id": "M4-01", "domain": "DataFrame", "topic": "NOTとNULLのフィルター", "concept": "filter-three-valued-logic", "stem": "Three rows have status values 'active', 'cancelled', and NULL. Which status values remain after df.filter(~(F.col('status') == 'cancelled'))?", "stem_ja": "3行のstatusは'active'、'cancelled'、NULLです。df.filter(~(F.col('status') == 'cancelled'))の後、どのstatusが残りますか？", "options": ["Only 'active'.", "Only NULL.", "'active' and NULL.", "All three values."], "options_ja": ["activeだけ。", "NULLだけ。", "activeとNULL。", "3つ全て。"], "correct": 0, "explanation_ja": "NULLを通常の値と比較すると結果はUNKNOWNです。それをNOTで反転してもUNKNOWNのままで、filterはtrueの行だけを残します。NULLも残したい場合はisNullとのORなどを明示します。", "distractors_ja": ["正答", "NULL行は条件がtrueにならず除外され、active行は残ります。", "NULLの比較はfalseではなくUNKNOWNなので、NOTしてもtrueになりません。", "cancelledは等価条件がtrueなので、否定後はfalseとなり除外されます。"], "source_url": "https://spark.apache.org/docs/3.5.7/sql-ref-null-semantics.html#logical-operators", "validation": "2026-10-17 ApacheのNOT(NULL)およびWHERE条件の仕様と照合。静的確認済み、Spark実行未検証。", "author_id": "M4R-D05", "exam": 4, "objective": "NOTとNULLのフィルター", "concept_label": "NOTとNULLのフィルター", "difficulty": "applied", "misconception_tags": ["", "NULL行は条件がtrueにならず除外され、active行は残ります。", "NULLの比較はfalseではなくUNKNOWNなので、NOTしてもtrueになりません。", "cancelledは等価条件がtrueなので、否定後はfalseとなり除外されます。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"]}, {"id": "M4-02", "domain": "Spark SQL", "topic": "jdbc-bounds-not-filter", "concept": "jdbc-bounds-not-filter", "stem": "A JDBC table has exactly four rows with numeric ticket_id values -5, 25, 75, and 140. A successful Spark JDBC read uses partitionColumn=\"ticket_id\", lowerBound=0, upperBound=100, and numPartitions=2. No WHERE clause or DataFrame filter is applied. The source does not change during the read. Which ticket_id values are returned, ignoring order?", "options": ["The read fails because some values are outside the bounds.", "-5, 25, 75", "-5, 25, 75, 140", "25, 75"], "correct": 2, "stem_ja": "JDBCテーブルには、数値型ticket_idが-5、25、75、140である4行だけがあります。SparkのJDBC読取りでpartitionColumn=\"ticket_id\"、lowerBound=0、upperBound=100、numPartitions=2を指定し、正常に読み取ります。WHERE句もDataFrameのfilterも使わず、読取り中に元データは変わりません。行順を無視すると、返されるticket_idは？", "options_ja": ["範囲外の値があるため読取りが失敗する。", "-5、25、75", "-5、25、75、140", "25、75"], "explanation_ja": "JDBCのlowerBoundとupperBoundは、並列読取りを分割する幅の計算に使います。取得対象をその範囲に制限するフィルタではありません。この条件では4行すべてを取得します。0以上100未満だけが必要なら、実際のSQL条件やDataFrameのfilterで絞り込みます。", "distractors_ja": ["このbounds指定は列値の妥当性検査ではなく、範囲外の値だけを理由にエラーにはなりません。", "upperBoundだけがフィルタとして働くわけでもありません。140の行も取得されます。", "正答", "boundsをWHERE条件のように扱っています。範囲外の行も読み取られます。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-data-sources-jdbc.html", "validation": "2026-10-17 Apache公式JDBCのpartitionColumn・bounds・numPartitions仕様を照合。独自作問・静的確認済み。外部DB実行未検証。", "author_id": "M4R-S07", "exam": 4, "objective": "jdbc-bounds-not-filter", "concept_label": "jdbc-bounds-not-filter", "difficulty": "applied", "misconception_tags": ["このbounds指定は列値の妥当性検査ではなく、範囲外の値だけを理由にエラーにはなりません。", "upperBoundだけがフィルタとして働くわけでもありません。140の行も取得されます。", "", "boundsをWHERE条件のように扱っています。範囲外の行も読み取られます。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"]}, {"id": "M4-03", "domain": "DataFrame", "topic": "正規表現抽出の不一致", "concept": "regexp-extract-empty", "stem": "code contains 'ID-407' in row 1 and 'OTHER' in row 2. Evaluate F.regexp_extract('code', r'^ID-(\\d+)$', 1). What are the results for the two rows?", "stem_ja": "codeは行1で'ID-407'、行2で'OTHER'です。F.regexp_extract('code',r'^ID-(\\d+)$',1)を評価すると、2行の結果はどうなりますか？", "options": ["'407' and NULL.", "'ID-407' and 'OTHER'.", "407 and 0, both as integers.", "'407' and the empty string ''."], "options_ja": ["文字列407とNULL。", "元の文字列ID-407とOTHER。", "整数407と整数0。", "文字列407と空文字列''。"], "correct": 3, "explanation_ja": "第1キャプチャグループは数字部分なので407を文字列で返します。入力が正規表現に一致しない場合は空文字列であり、NULLではありません。数値型が必要なら別途castします。", "distractors_ja": ["非NULLの入力が不一致の場合、このAPIはNULLではなく空文字列を返します。", "元の入力をそのまま返す処理ではなく、第1グループを抽出します。", "結果は文字列です。不一致を数値0へ自動変換することもありません。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.functions.regexp_extract.html", "validation": "2026-10-17 Apache regexp_extractのグループ番号・不一致時の空文字列を照合。静的確認済み、Spark実行未検証。", "author_id": "M4R-D08", "exam": 4, "objective": "正規表現抽出の不一致", "concept_label": "正規表現抽出の不一致", "difficulty": "applied", "misconception_tags": ["非NULLの入力が不一致の場合、このAPIはNULLではなく空文字列を返します。", "元の入力をそのまま返す処理ではなく、第1グループを抽出します。", "結果は文字列です。不一致を数値0へ自動変換することもありません。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-04", "domain": "Spark SQL", "topic": "managed-external-drop", "concept": "managed-external-drop", "stem": "Using the standard Spark session catalog, two ordinary Parquet tables are created successfully. managed_events uses saveAsTable with no custom path. external_events uses option(\"path\", external_path).saveAsTable, with a separate custom path. Both tables are then dropped with DROP TABLE. Which outcome is expected? Assume no catalog-specific retention behavior.", "options": ["Both catalog entries and both datasets are removed.", "Only managed_events is removed; DROP TABLE cannot remove an external table's catalog entry.", "Both catalog entries are removed; managed_events data is removed, while external_events data remains at external_path.", "Both catalog entries are removed, but both datasets remain."], "correct": 2, "stem_ja": "標準のSparkセッションカタログで、通常のParquetテーブルを2つ正常に作成します。managed_eventsは独自パスを指定せずsaveAsTableで作成し、external_eventsは別の独自パスをoption(\"path\", external_path).saveAsTableで指定します。その後、両方をDROP TABLEで削除します。カタログ固有のデータ保持動作がない場合、結果はどうなりますか？", "options_ja": ["両方のカタログ登録と両方のデータが削除される。", "managed_eventsだけが削除される。外部テーブルのカタログ登録はDROP TABLEで削除できない。", "両方のカタログ登録が消え、managed_eventsのデータは削除されるが、external_eventsのデータはexternal_pathに残る。", "両方のカタログ登録は消えるが、両方のデータが残る。"], "explanation_ja": "この標準Sparkの条件では、独自パスのないテーブルはwarehouse内の管理対象データを使い、DROP時にデータも削除されます。独自パスを指定した外部テーブルは、登録を削除してもそのパスのデータを残します。ここで問うのは通常のSparkデータソース表の管理範囲です。", "distractors_ja": ["独自パスに保存した外部テーブルのデータまで削除する条件ではありません。", "外部テーブルもDROP TABLEでカタログ登録を削除できます。残るのは外部パスのデータです。", "正答", "独自パスのない管理テーブルでは、warehouse内のデータも削除されます。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-data-sources-load-save-functions.html#saving-to-persistent-tables", "validation": "2026-10-17 Apache公式の独自path有無とDROP時のデータ保持を照合。標準Sparkセッションカタログの通常Parquetを明示。独自作問・静的確認済み。Spark実行未検証。", "author_id": "M4R-S02", "exam": 4, "objective": "managed-external-drop", "concept_label": "managed-external-drop", "difficulty": "applied", "misconception_tags": ["独自パスに保存した外部テーブルのデータまで削除する条件ではありません。", "外部テーブルもDROP TABLEでカタログ登録を削除できます。残るのは外部パスのデータです。", "", "独自パスのない管理テーブルでは、warehouse内のデータも削除されます。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"]}, {"id": "M4-05", "domain": "Spark Connect", "topic": "connect-remote-column-resolution", "concept": "connect-server-analysis-unresolved-plan", "stem": "A Spark Connect client sends an unresolved logical plan that selects delivered_at from a remote table. The table actually contains delivery_ts, not delivered_at. Which component resolves the reference against the table schema and detects this problem during query analysis?", "options": ["The server-side Spark analyzer, using the remote table's schema.", "The client's pandas library, after all table rows have been collected locally.", "The Apache Arrow decoder, by checking the names of returned result batches.", "The cluster manager, while allocating executor memory."], "correct": 0, "stem_ja": "Spark Connectクライアントが、リモートテーブルからdelivered_atを選択する未解決の論理計画を送信します。実際のテーブルにはdelivery_tsという列があり、delivered_atはありません。クエリ解析時にテーブルのスキーマと照合して列参照を解決し、この問題を検出するのはどの構成要素ですか？", "options_ja": ["リモートテーブルのスキーマを使う、サーバー側のSparkアナライザー。", "テーブルの全行をローカルへ収集した後の、クライアント側のpandasライブラリ。", "返された結果バッチの列名を確認するApache Arrowデコーダー。", "Executorのメモリーを割り当てる際のクラスターマネージャー。"], "explanation_ja": "ConnectクライアントはDataFrame操作を未解決の論理計画として送る。サーバー側でSparkの論理計画へ変換され、通常の解析・最適化・実行の処理へ進む。存在するテーブルや列への解決はその解析の役割なので、存在しないdelivered_atはサーバー側の解析で問題になる。結果転送のArrowや、計算資源を管理するクラスターマネージャーの役割ではない。", "distractors_ja": ["正答", "列参照を検証するためにテーブルの全行をpandasへ集める必要はない。", "Arrowは主に結果の転送形式として使われる。列参照の解決は結果が作られる前の解析で行う。", "クラスターマネージャーは計算資源を割り当てる。SQLの列名を解決する構成要素ではない。"], "source_url": "https://spark.apache.org/docs/3.5.7/spark-connect-overview.html#how-spark-connect-works", "validation": "2026-10-17 Apache Spark公式Connect Overviewの未解決論理計画、サーバー側変換と通常のSpark処理を照合。すべてのAPIエラーがactionまで遅延するとは主張せず、送信された計画の列解決場所に限定。静的確認済み、Connect実行未検証。", "author_id": "M4R-C01", "exam": 4, "objective": "connect-remote-column-resolution", "concept_label": "connect-remote-column-resolution", "difficulty": "applied", "misconception_tags": ["", "列参照を検証するためにテーブルの全行をpandasへ集める必要はない。", "Arrowは主に結果の転送形式として使われる。列参照の解決は結果が作られる前の解析で行う。", "クラスターマネージャーは計算資源を割り当てる。SQLの列名を解決する構成要素ではない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"]}, {"id": "M4-06", "domain": "Architecture", "topic": "SQLとDataFrameの実行基盤", "concept": "query-plans", "stem": "A developer rewrites a filter and grouped aggregation from Spark SQL text to equivalent built-in DataFrame expressions. Both queries use the same input and settings. Which statement best describes their optimization?", "stem_ja": "Spark SQLのフィルターとグループ集計を、同じ意味の組込みDataFrame式へ書き換えます。入力・設定は同じです。最適化について最も適切な説明は？", "options": ["Equivalent syntax guarantees identical measured runtime for every execution.", "Both interfaces use Spark SQL's planning and optimization; choosing DataFrame syntax alone does not guarantee a faster plan.", "Only SQL text can be optimized; DataFrame filters always scan all columns.", "The DataFrame version bypasses Spark SQL's optimizer and runs every row in a Python loop."], "options_ja": ["同じ意味の構文なら毎回の実測時間が必ず一致する。", "両方ともSpark SQLの計画・最適化を使う。DataFrame構文を選ぶだけでは高速化を保証しない。", "SQL文だけが最適化対象で、DataFrameフィルターは必ず全列を読む。", "DataFrame版は最適化を迂回し、全行をPythonループで処理する。"], "correct": 1, "distractors_ja": ["同じ意味でも資源やキャッシュ状態などで実測時間は変わり得ます。", "正答", "DataFrame操作も計画・最適化の対象です。", "組込みDataFrame式を使うことは、行ごとのPython UDF実行と同じではありません。"], "explanation_ja": "SQL文とDataFrame APIは、構造化データを処理するSpark SQLの異なる入口です。構文の好みだけで性能を決めず、実行計画と測定結果で判断します。\n\n英文の読み取り：equivalent built-in expressions＝同じ意味の組込み式。Python UDFへ置換したという条件ではありません。", "source_url": "https://spark.apache.org/docs/3.5.7/sql-programming-guide.html", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-A05", "exam": 4, "objective": "SQLとDataFrameの実行基盤", "concept_label": "SQLとDataFrameの実行基盤", "difficulty": "applied", "misconception_tags": ["同じ意味でも資源やキャッシュ状態などで実測時間は変わり得ます。", "", "DataFrame操作も計画・最適化の対象です。", "組込みDataFrame式を使うことは、行ごとのPython UDF実行と同じではありません。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"]}, {"id": "M4-07", "domain": "Pandas API", "topic": "local-pandas-to-pandas-on-spark", "concept": "pandas-to-distributed-api-conversion", "stem": "A small pandas DataFrame pdf already fits in local memory. An engineer wants a pandas-on-Spark DataFrame so that subsequent supported pandas-like operations use Spark. With import pyspark.pandas as ps and import pandas as pd, which expression directly creates the required object?", "options": ["pdf.copy()", "spark.createDataFrame(pdf)", "pd.DataFrame(pdf)", "ps.from_pandas(pdf)"], "correct": 3, "stem_ja": "小さなpandas DataFrameであるpdfは、既にローカルメモリーに収まっています。エンジニアは、以後のサポート対象のpandas風操作をSparkで処理するため、pandas-on-Spark DataFrameが必要です。import pyspark.pandas as psとimport pandas as pdが実行済みの場合、必要なオブジェクトを直接作る式はどれですか？", "options_ja": ["pdf.copy()：pandas DataFrameをコピーする。", "spark.createDataFrame(pdf)：Spark SQLのDataFrameを作る。", "pd.DataFrame(pdf)：pandas DataFrameを作る。", "ps.from_pandas(pdf)：pandasからpandas-on-Sparkのオブジェクトを作る。"], "explanation_ja": "ps.from_pandasはローカルのpandas DataFrameをpandas-on-Spark DataFrameへ変換する。spark.createDataFrameもSparkへ渡す操作だが、返すのはSpark SQLのDataFrameであり、この設問が求めるpandas-on-Spark DataFrameとはAPIが異なる。逆方向のto_pandasは全データをローカルへ収集する。転送を高速化するArrowを使っても、通常のpandasオブジェクトの操作が自動的に分散実行へ変わるわけではない。", "distractors_ja": ["コピー後もローカルのpandas DataFrame。実行エンジンの切替えではない。", "Spark SQLのDataFrameになる。pandas API on Sparkを使うには、さらにpandas_apiなどによる変換が必要。", "pdは通常のpandasであり、作られるオブジェクトはSparkを使うpandas-on-Spark DataFrameではない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/user_guide/pandas_on_spark/pandas_pyspark.html", "validation": "2026-10-17 Apache Spark公式From/to pandas and PySpark DataFramesでfrom_pandas、to_pandas、pandas_apiの型と変換方向を照合。初期pdfはローカルメモリーに収まると明記。静的確認済み、Spark実行未検証。", "author_id": "M4R-P01", "exam": 4, "objective": "local-pandas-to-pandas-on-spark", "concept_label": "local-pandas-to-pandas-on-spark", "difficulty": "applied", "misconception_tags": ["コピー後もローカルのpandas DataFrame。実行エンジンの切替えではない。", "Spark SQLのDataFrameになる。pandas API on Sparkを使うには、さらにpandas_apiなどによる変換が必要。", "pdは通常のpandasであり、作られるオブジェクトはSparkを使うpandas-on-Spark DataFrameではない。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-08", "domain": "Architecture", "topic": "shuffleのデータ移動", "concept": "shuffle-partitions", "stem": "Records with the same customer key are spread across many input partitions. A grouped aggregation must combine those records. Which cost is specifically associated with the required shuffle?", "stem_ja": "同じcustomerキーの行が多数の入力パーティションに分散しています。グループ集計のために行をまとめます。必要となるshuffleに特有のコストは？", "options": ["Permanently changing the schema of the original source files.", "Sending the entire original dataset to the browser rendering the notebook.", "Renaming Python variables without moving data.", "Redistributing intermediate data between partitions, potentially using serialization, network transfer, and disk I/O."], "options_ja": ["元ファイルのスキーマを恒久変更する操作。", "入力全体をノートブックの表示ブラウザへ送る操作。", "データを移動せずPython変数名を変える操作。", "中間データの再分配に伴うシリアライズ、ネットワーク転送、ディスクI/Oなど。"], "correct": 3, "distractors_ja": ["元の保存済みスキーマを変更する必要はありません。", "分散shuffleの保存・転送先を表示ブラウザと混同しています。", "shuffleは変数名変更ではありません。", "正答"], "explanation_ja": "shuffleは再分配を伴うため、narrowな処理とは異なるコストがあります。ただし全てのgroupByが常に同じ費用になるわけではなく、データ分布や既存分割、最適化に依存します。\n\n英文の読み取り：specifically associated＝その処理に伴うコストを聞いています。最終結果の画面表示とは別です。", "source_url": "https://spark.apache.org/docs/3.5.7/rdd-programming-guide.html#shuffle-operations", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-A08", "exam": 4, "objective": "shuffleのデータ移動", "concept_label": "shuffleのデータ移動", "difficulty": "applied", "misconception_tags": ["元の保存済みスキーマを変更する必要はありません。", "分散shuffleの保存・転送先を表示ブラウザと混同しています。", "shuffleは変数名変更ではありません。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-09", "domain": "Spark SQL", "topic": "register-existing-python-udf", "concept": "register-existing-python-udf", "stem": "This Python UDF has already been created:\n\nfrom pyspark.sql import functions as F\nfrom pyspark.sql.types import IntegerType\nsafe_length = F.udf(lambda x: 0 if x is None else len(x), IntegerType())\n\nThe SQL name text_len is not registered yet. Which statement correctly registers this existing UDF so SELECT text_len(note) FROM notes can use its declared integer return type?", "options": ["text_len = safe_length", "spark.udf.register(\"text_len\", safe_length)", "spark.udf.register(\"text_len\", safe_length, IntegerType())", "spark.udf.register(\"safe_length\", safe_length)"], "correct": 1, "stem_ja": "次のPython UDFはすでに作成済みです。\n\nfrom pyspark.sql import functions as F\nfrom pyspark.sql.types import IntegerType\nsafe_length = F.udf(lambda x: 0 if x is None else len(x), IntegerType())\n\nSQL名text_lenは未登録です。SELECT text_len(note) FROM notesで宣言済みの整数戻り値型を使えるよう、この既存UDFを正しく登録する文は？", "options_ja": ["Python変数text_lenにsafe_lengthを代入する。", "spark.udf.register(\"text_len\", safe_length)を呼ぶ。", "spark.udf.register(\"text_len\", safe_length, IntegerType())を呼ぶ。", "spark.udf.register(\"safe_length\", safe_length)を呼ぶ。"], "explanation_ja": "作成済みのUDFをregisterへ渡す場合、戻り値型はそのUDF自身から引き継がれます。指定するのはSQLで使う名前とUDFです。通常のPython関数を登録する場合とは異なり、既存UDFと一緒に第3引数returnTypeを指定しません。Python変数への代入だけではSQL関数名を登録できません。", "distractors_ja": ["Python側の変数名を増やすだけで、Spark SQLにtext_lenは登録されません。", "正答", "既存UDFを渡す場合はreturnTypeを別途指定できません。型はsafe_lengthにすでに設定されています。", "登録名がsafe_lengthなので、要求されたtext_lenというSQL名を利用できません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.UDFRegistration.register.html", "validation": "2026-10-17 Apache公式UDFRegistration.registerの既存UDFの場合のreturnType制約を照合。独自作問・静的確認済み。Spark実行未検証。", "author_id": "M4R-S06", "exam": 4, "objective": "register-existing-python-udf", "concept_label": "register-existing-python-udf", "difficulty": "applied", "misconception_tags": ["Python側の変数名を増やすだけで、Spark SQLにtext_lenは登録されません。", "", "既存UDFを渡す場合はreturnTypeを別途指定できません。型はsafe_lengthにすでに設定されています。", "登録名がsafe_lengthなので、要求されたtext_lenというSQL名を利用できません。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"]}, {"id": "M4-10", "domain": "Architecture", "topic": "localCheckpointの耐障害性", "concept": "fault-checkpoint", "stem": "A pipeline uses the DataFrame returned by localCheckpoint(eager=True) to truncate a long plan. Later, its only copy of a needed checkpoint block is lost with an executor. For future runs, the team requires recovery across executor loss. Which change should be made while the data is still available?", "stem_ja": "パイプラインはlocalCheckpoint(eager=True)が返すDataFrameを使って長い計画を短縮します。その後、必要なチェックポイントブロックの唯一のコピーがExecutorとともに失われました。今後の実行ではExecutor喪失後も復旧できるようにしたい場合、データがまだ利用できる段階で行う変更は？", "options": ["Increase the driver log level; logging replicates local checkpoint blocks.", "Configure a reliable shared checkpoint directory and use the DataFrame returned by checkpoint(eager=True).", "Call printSchema after localCheckpoint so lost data blocks can be recreated from the schema.", "Use localCheckpoint(eager=False), because lazy local checkpoints are automatically durable."], "options_ja": ["Driverのログレベルを上げ、チェックポイントブロックを複製する。", "信頼できる共有チェックポイント先を設定し、checkpoint(eager=True)の戻り値を利用する。", "printSchemaを呼び、失われたデータをスキーマから再作成する。", "localCheckpoint(eager=False)ならローカルの保存が自動で耐久化する。"], "correct": 1, "distractors_ja": ["ログレベルはデータブロックの複製を設定しません。", "正答", "スキーマは行のデータそのものを保存していません。", "eagerは作成時期を変える指定で、ローカル保存を耐久化しません。"], "explanation_ja": "localCheckpointはExecutor側のキャッシュ機構を利用するため、信頼できる共有保存先へ書くcheckpointと同じ耐障害性ではありません。今後の実行では、データが利用できるうちに共有保存先へのcheckpointを作り、その戻り値を使います。設定を後から変えるだけで、すでに失った唯一のデータを復元できるという意味ではありません。\n\n英文の読み取り：for future runs / while the data is still available＝今後の実行に備え、データがあるうちに対処する条件です。", "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.localCheckpoint.html", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-A09", "exam": 4, "objective": "localCheckpointの耐障害性", "concept_label": "localCheckpointの耐障害性", "difficulty": "applied", "misconception_tags": ["ログレベルはデータブロックの複製を設定しません。", "", "スキーマは行のデータそのものを保存していません。", "eagerは作成時期を変える指定で、ローカル保存を耐久化しません。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"]}, {"id": "M4-11", "domain": "Tuning", "topic": "終了済みアプリの実行履歴", "concept": "memory-diagnostics", "stem": "A Spark application has finished, so its live web UI is no longer available. The team wants to inspect that run's stages and task metrics later through the History Server. What needed to be configured for the run?", "stem_ja": "Sparkアプリは終了し、稼働中のWeb UIにはアクセスできません。後からHistory Serverでその実行のステージとタスク指標を調べたい場合、その実行に必要だった設定は？", "options": ["Enable Spark event logging and write event logs to a location readable by the History Server.", "Call printSchema before each action; schemas contain task durations.", "Call cache on every DataFrame; cached rows automatically contain the complete execution history.", "Set spark.sql.shuffle.partitions to the number of executor cores."], "options_ja": ["Sparkイベントログを有効にし、History Serverから読める場所へログを保存する。", "各action前にprintSchemaを呼び、タスク所要時間をスキーマに保存する。", "全DataFrameをcacheし、全実行履歴を行データへ自動保存する。", "shuffleパーティション数をExecutorのコア数に合わせる。"], "correct": 0, "distractors_ja": ["正答", "スキーマは列の型・構造でありタスク時間の履歴ではありません。", "cacheは行データの再利用でありイベントログの代わりではありません。", "分割数の変更は過去の実行記録を保存しません。"], "explanation_ja": "終了したアプリの監視には、実行時に保存したイベントログをHistory Serverが読む構成を用います。ライブのSpark UIが見えることと、終了後も履歴が残ることは別です。\n\n英文の読み取り：has finished / later＝実行中ではなく終了後の調査です。", "source_url": "https://spark.apache.org/docs/3.5.7/monitoring.html#viewing-after-the-fact", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-T02", "exam": 4, "objective": "終了済みアプリの実行履歴", "concept_label": "終了済みアプリの実行履歴", "difficulty": "applied", "misconception_tags": ["", "スキーマは列の型・構造でありタスク時間の履歴ではありません。", "cacheは行データの再利用でありイベントログの代わりではありません。", "分割数の変更は過去の実行記録を保存しません。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"]}, {"id": "M4-12", "domain": "Pandas API", "topic": "scalar-pandas-udf-batch-local-sequence", "concept": "scalar-pandas-udf-internal-batch-scope", "stem": "An engineer applies this scalar pandas UDF to a large distributed DataFrame and expects a unique ID for every row:\n\n@pandas_udf(\"long\")\ndef row_id(s: pd.Series) -> pd.Series:\n    return pd.Series(range(len(s)), dtype=\"int64\")\n\nWhy does this not guarantee globally unique IDs?", "options": ["Spark always passes the entire DataFrame to one invocation and randomly duplicates the output IDs.", "A scalar pandas UDF must return exactly one value for the entire input Series.", "The function runs on internal batches, so each invocation restarts the sequence at zero.", "Declaring the return type as long forces every output value to become zero."], "correct": 2, "stem_ja": "エンジニアは次のスカラーpandas UDFを大きな分散DataFrameに適用し、各行に一意なIDが付くことを期待しています。\n\n@pandas_udf(\"long\")\ndef row_id(s: pd.Series) -> pd.Series:\n    return pd.Series(range(len(s)), dtype=\"int64\")\n\nこの処理でDataFrame全体のIDの一意性が保証されないのはなぜですか？", "options_ja": ["Sparkは必ずDataFrame全体を一度の呼出しに渡し、出力IDをランダムに複製するため。", "スカラーpandas UDFは、入力Series全体に対して値を必ず一つだけ返す必要があるため。", "関数は内部バッチごとに動き、呼び出されるたびに連番がゼロから始まるため。", "戻り値の型をlongと宣言すると、すべての出力値が強制的にゼロになるため。"], "explanation_ja": "SeriesからSeriesを返すスカラーpandas UDFでは、sは列全体とは限らず、一度の関数呼出しに渡された内部バッチ。range(len(s))は各呼出しでゼロから作り直されるので、複数バッチや複数パーティションの間で同じIDが生じ得る。入力と同じ長さのSeriesを返すという契約は満たしており、問題は出力行数ではなく、連番の対象範囲がDataFrame全体ではないこと。", "distractors_ja": ["入力Seriesは内部バッチ単位。SparkがIDをランダムに複製するのではなく、コード自身が呼出しごとに同じ番号を作る。", "スカラーpandas UDFのSeries-to-Series形式では、入力と同じ長さのSeriesを返す。全体を一つに集約する形式とは異なる。", "正答", "longは値のデータ型であり、すべての値をゼロへ変える指定ではない。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.functions.pandas_udf.html", "validation": "2026-10-17 Apache Spark公式pandas_udfのSeries-to-Series出力長条件と入力が内部バッチである旨を照合。出力dtypeをint64で明示し、型変換の曖昧さを除外。実際のバッチ数や並び順は断定しない。静的確認済み、Spark実行未検証。", "author_id": "M4R-P02", "exam": 4, "objective": "scalar-pandas-udf-batch-local-sequence", "concept_label": "scalar-pandas-udf-batch-local-sequence", "difficulty": "applied", "misconception_tags": ["入力Seriesは内部バッチ単位。SparkがIDをランダムに複製するのではなく、コード自身が呼出しごとに同じ番号を作る。", "スカラーpandas UDFのSeries-to-Series形式では、入力と同じ長さのSeriesを返す。全体を一つに集約する形式とは異なる。", "", "longは値のデータ型であり、すべての値をゼロへ変える指定ではない。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"]}, {"id": "M4-13", "domain": "DataFrame", "topic": "小数の型変換と表示文字列", "concept": "cast-decimal-type", "stem": "price_text contains valid values such as '7.25' and '0.50', all representable as DECIMAL(10,2). The output must have that numeric Spark type, not formatted text. Which expression fits?", "stem_ja": "price_textには'7.25'や'0.50'など、有効で全てDECIMAL(10,2)に収まる値が入っています。出力は表示用文字列ではなく、そのSpark数値型にする必要があります。適切な式はどれですか？", "options": ["F.format_number(F.col('price_text').cast('double'), 2)", "F.lit('decimal(10,2)')", "F.col('price_text').cast('decimal(10,2)')", "F.col('price_text').cast('double')"], "options_ja": ["doubleへ変換した値を小数2桁の文字列に整形する。", "decimal(10,2)という文字列定数を作る。", "price_text列をdecimal(10,2)型にcastする。", "price_text列をdouble型にcastする。"], "correct": 2, "explanation_ja": "castはSparkのデータ型を指定して変換します。小数2桁で表示するformat_numberは文字列を返すため、DecimalTypeが必要という条件とは異なります。doubleも数値ですが、指定された固定小数点型ではありません。", "distractors_ja": ["見た目を小数2桁にしても、結果の型は文字列です。", "型の名前を書いた文字列を返すだけで、入力値を変換しません。", "正答", "DoubleTypeでありDECIMAL(10,2)という型要件を満たしません。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.Column.cast.html", "validation": "2026-10-17 Apache Column.cast、DecimalType、format_number仕様を照合。無効文字列・桁あふれ・丸め差を設問から除外。静的確認済み、Spark実行未検証。", "author_id": "M4R-D11", "exam": 4, "objective": "小数の型変換と表示文字列", "concept_label": "小数の型変換と表示文字列", "difficulty": "applied", "misconception_tags": ["見た目を小数2桁にしても、結果の型は文字列です。", "型の名前を書いた文字列を返すだけで、入力値を変換しません。", "", "DoubleTypeでありDECIMAL(10,2)という型要件を満たしません。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"]}, {"id": "M4-14", "domain": "Spark Connect", "topic": "connect-public-plan-inspection", "concept": "connect-no-private-jvm-access", "stem": "A diagnostic helper uses df._jdf.queryExecution() to inspect a query plan in classic PySpark. After migration to Spark Connect, the private JVM access is unavailable. Which replacement uses a supported public API to display logical and physical plans without collecting the result rows?", "options": ["Call df.collect(), then access _jdf on the returned list.", "Access the driver JVM through spark.sparkContext._jvm instead.", "Call df.explain(mode=\"extended\").", "Enable Arrow, then keep using df._jdf.queryExecution()."], "correct": 2, "stem_ja": "Classic PySparkの診断用ヘルパーが、クエリ計画を調べるためにdf._jdf.queryExecution()を使っています。Spark Connectへ移行すると、この非公開のJVMアクセスが使えなくなりました。結果の行を収集せず、論理計画と物理計画を表示するためのサポートされた公開APIへの置き換えはどれですか？", "options_ja": ["df.collect()を呼び、返されたリストの_jdfにアクセスする。", "代わりにspark.sparkContext._jvmからドライバーのJVMへアクセスする。", "df.explain(mode=\"extended\")を呼ぶ。", "Arrowを有効にして、df._jdf.queryExecution()をそのまま使う。"], "explanation_ja": "explainのextendedモードは論理計画と物理計画を表示し、Spark Connectにも対応する。ConnectのPythonクライアントはドライバーJVMをPy4Jで直接操作する構造ではないため、_jdfのような非公開フィールドに依存したコードは置き換える。Arrowを有効にしてもこの境界は変わらず、SparkContext経由のJVMアクセスも解決策にならない。", "distractors_ja": ["collectは結果行をPythonのリストへ収集する。このリストにDataFrameのJVM計画オブジェクトはなく、行を収集しないという条件も満たさない。", "ConnectクライアントからSparkContextを経由してドライバーJVMへ直接アクセスすることもサポートされない。", "正答", "Arrowはデータ転送に関する仕組みで、ドライバーJVMへの非公開アクセスを復活させない。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.explain.html", "validation": "2026-10-17 Apache Spark公式explain APIのextendedとConnect対応を照合。非公開JVMフィールド・SparkContext非対応はSpark 4.0.1 Connect Overviewの説明でも確認。バージョン限定の内部実装を正答に使わない。静的確認済み、Connect実行未検証。", "author_id": "M4R-C02", "exam": 4, "objective": "connect-public-plan-inspection", "concept_label": "connect-public-plan-inspection", "difficulty": "applied", "misconception_tags": ["collectは結果行をPythonのリストへ収集する。このリストにDataFrameのJVM計画オブジェクトはなく、行を収集しないという条件も満たさない。", "ConnectクライアントからSparkContextを経由してドライバーJVMへ直接アクセスすることもサポートされない。", "", "Arrowはデータ転送に関する仕組みで、ドライバーJVMへの非公開アクセスを復活させない。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"]}, {"id": "M4-15", "domain": "DataFrame", "topic": "NULLを含むanti join", "concept": "anti-join-null", "stem": "left has (row_id, k) rows [('a', NULL), ('b', 5), ('c', 9)]. right has k values [NULL, 5]. Which row_id values remain after left.join(right, left.k == right.k, 'left_anti')? Ignore order.", "stem_ja": "leftの(row_id,k)は[('a',NULL),('b',5),('c',9)]です。rightのkは[NULL,5]です。left.join(right,left.k == right.k,'left_anti')の後、どのrow_idが残りますか？ 順序は無視します。", "options": ["['a', 'c']", "['c']", "[]", "['b']"], "options_ja": ["aとcが残る。", "cだけが残る。", "どの行も残らない。", "bだけが残る。"], "correct": 0, "explanation_ja": "left_antiは右に一致がない左行を残します。通常の==ではNULL同士もtrueにならないためaは残り、5が一致するbは除かれ、右に9がないcも残ります。NULL同士を一致扱いにするeqNullSafeとは結果が異なります。", "distractors_ja": ["正答", "通常の==でNULL同士が一致すると誤解しています。aも残ります。", "右に一致しない行は残ります。特に9は右に存在しません。", "bは右に一致するためanti joinでは除外されます。"], "source_url": "https://spark.apache.org/docs/3.5.7/sql-ref-null-semantics.html", "validation": "2026-10-17 Apache NULL SemanticsとDataFrame.joinを照合。NULL非安全な等価条件を明記。静的確認済み、Spark実行未検証。", "author_id": "M4R-D01", "exam": 4, "objective": "NULLを含むanti join", "concept_label": "NULLを含むanti join", "difficulty": "applied", "misconception_tags": ["", "通常の==でNULL同士が一致すると誤解しています。aも残ります。", "右に一致しない行は残ります。特に9は右に存在しません。", "bは右に一致するためanti joinでは除外されます。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"]}, {"id": "M4-16", "domain": "DataFrame", "topic": "Windowの行範囲と累計", "concept": "window-running-sum", "stem": "Within each account, seq uniquely orders transactions. Build a running sum from the first transaction through the current one, inclusive. Which frame belongs on Window.partitionBy('account').orderBy('seq') before using F.sum('amount').over(w)?", "stem_ja": "各account内でseqは取引の順序を一意に決めます。最初の取引から現在の取引まで、現在行も含む累計を作ります。F.sum('amount').over(w)を使う前に、Window.partitionBy('account').orderBy('seq')へ付ける範囲指定はどれですか？", "options": [".rowsBetween(Window.currentRow, Window.unboundedFollowing)", ".rowsBetween(Window.unboundedPreceding, Window.unboundedFollowing)", ".rowsBetween(Window.unboundedPreceding, Window.currentRow)", ".rowsBetween(-1, Window.currentRow)"], "options_ja": ["現在行から末尾までを含める。", "先頭から末尾まで全行を含める。", "先頭から現在行までを含める。", "1行前から現在行までを含める。"], "correct": 2, "explanation_ja": "unboundedPrecedingはグループの先頭、currentRowは現在行を示し、両端を含みます。例えばamountが順に[5,2,8]なら累計は[5,7,15]です。seqが一意なので同順序内での行順の曖昧さもありません。", "distractors_ja": ["過去方向の累計ではなく、現在から未来側を合計します。", "各行で同じグループ総計となり、現在位置までの累計ではありません。", "正答", "直前と現在の最大2行だけで、3行目以降は先頭からの累計になりません。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.Window.rowsBetween.html", "validation": "2026-10-17 Apache Window.rowsBetweenの両端包含・相対範囲と照合。順序列を一意と明記。静的確認済み、Spark実行未検証。", "author_id": "M4R-D09", "exam": 4, "objective": "Windowの行範囲と累計", "concept_label": "Windowの行範囲と累計", "difficulty": "applied", "misconception_tags": ["過去方向の累計ではなく、現在から未来側を合計します。", "各行で同じグループ総計となり、現在位置までの累計ではありません。", "", "直前と現在の最大2行だけで、3行目以降は先頭からの累計になりません。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"]}, {"id": "M4-17", "domain": "Structured Streaming", "topic": "independent-query-checkpoints", "concept": "checkpoint-directory-query-isolation", "stem": "Two independent streaming queries will run concurrently. They read the same source but apply different transformations and write to different destinations. Each must recover its own progress after a restart. Which checkpoint design meets this requirement?", "options": ["Give each query a new empty checkpoint directory on every restart.", "Use one checkpoint directory and give the queries different queryName values.", "Use one checkpoint directory and give the queries different processing-time intervals.", "Give each query its own durable checkpoint directory and reuse only that query's directory when it restarts."], "correct": 3, "stem_ja": "独立した二つのストリーミングクエリを同時に実行します。同じソースを読みますが、変換内容と書込み先は異なります。それぞれが再起動後に自分の処理進捗を復元できる必要があります。この要件を満たすチェックポイントの設計はどれですか？", "options_ja": ["再起動のたびに、それぞれのクエリへ新しい空のチェックポイントディレクトリを割り当てる。", "一つのチェックポイントディレクトリを共有し、queryNameを別々にする。", "一つのチェックポイントディレクトリを共有し、処理時間トリガーの間隔を別々にする。", "クエリごとに別々の永続的なチェックポイントディレクトリを割り当て、再起動ではそのクエリ自身のディレクトリだけを再利用する。"], "explanation_ja": "チェックポイントにはそのクエリの進捗や復旧に必要な情報が保存される。独立して同時実行するクエリ同士では保存先を分け、それぞれの再起動時に自分のチェックポイントへ戻る。queryNameやトリガー間隔を変えても、同じディレクトリ内に別々の復旧履歴が自動作成されるわけではない。毎回空のディレクトリを使うと、それまでの進捗に基づく復旧ができない。", "distractors_ja": ["新しい空のチェックポイントには前回の進捗がないため、要求された復元にならない。", "表示用のクエリ名を変えても、共有したチェックポイントの進捗やクエリ識別情報は分離されない。", "実行間隔の違いは進捗保存先の分離にならない。同時実行によるチェックポイントの競合を解決しない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.7/structured-streaming-programming-guide.html#recovering-from-failures-with-checkpointing", "validation": "2026-10-17 Apache Spark公式Guideのチェックポイントによる進捗復旧、configuration.htmlのstopActiveRunOnRestart、cloud-integration.htmlの並行クエリでのcheckpoint共有禁止を照合。特定の例外や障害結果は断定しない。静的確認済み、並行実行未検証。", "author_id": "M4R-R03", "exam": 4, "objective": "independent-query-checkpoints", "concept_label": "independent-query-checkpoints", "difficulty": "applied", "misconception_tags": ["新しい空のチェックポイントには前回の進捗がないため、要求された復元にならない。", "表示用のクエリ名を変えても、共有したチェックポイントの進捗やクエリ識別情報は分離されない。", "実行間隔の違いは進捗保存先の分離にならない。同時実行によるチェックポイントの競合を解決しない。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-18", "domain": "Spark SQL", "topic": "not-in-null-list", "concept": "not-in-null-list", "stem": "View candidates contains integer ids 1, 2, and 3. View blocked contains integer ids 2 and NULL. Which ids does this query return?\n\nSELECT id FROM candidates\nWHERE id NOT IN (SELECT id FROM blocked)", "options": ["1, 2, and 3", "2 only", "1 and 3", "No rows"], "correct": 3, "stem_ja": "ビューcandidatesには整数idが1、2、3の行があり、ビューblockedには整数idが2、NULLの行があります。次のクエリはどのidを返しますか？\n\nSELECT id FROM candidates\nWHERE id NOT IN (SELECT id FROM blocked)", "options_ja": ["1、2、3", "2だけ", "1と3", "0行"], "explanation_ja": "id=2はINがTRUEなのでNOT INはFALSEです。1と3は2とは異なりますが、比較先にNULLがあるためNOT INはUNKNOWNになります。WHEREはTRUEの行だけを残すので、結果は0行です。通常の『2だけ除外する』結果が必要なら、例えばサブクエリでWHERE id IS NOT NULLを付けてからNOT INを使います。", "distractors_ja": ["WHEREがTRUEになる行がないので、全行を返すことはありません。", "2はblockedに一致するため、NOT INでは除外されます。", "比較先のNULLを無視した結果です。NOT INでは一致しない値でもUNKNOWNになり、WHEREを通りません。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-ref-null-semantics.html#innot-in-subquery", "validation": "2026-10-17 Apache公式NULL semanticsのIN/NOT INとWHEREを照合。三値論理で各入力値を静的追跡。独自作問。Spark実行未検証。", "author_id": "M4R-S09", "exam": 4, "objective": "not-in-null-list", "concept_label": "not-in-null-list", "difficulty": "applied", "misconception_tags": ["WHEREがTRUEになる行がないので、全行を返すことはありません。", "2はblockedに一致するため、NOT INでは除外されます。", "比較先のNULLを無視した結果です。NOT INでは一致しない値でもUNKNOWNになり、WHEREを通りません。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-19", "domain": "Tuning", "topic": "coalesceによる過度な直列化", "concept": "shuffle-partitions", "stem": "A large batch DataFrame has 120 partitions. To obtain one output file, a developer applies coalesce(1) before an expensive transformation and write. The final stage now uses one long-running task. Which change best restores parallel processing when a single output file is no longer required?", "stem_ja": "大きなバッチDataFrameが120パーティションあります。出力を1ファイルにするため重い変換と書込みの前にcoalesce(1)を適用したところ、最後のステージは長時間の1タスクになりました。1ファイルの要件がなくなった場合、並列性の回復に最も適した変更は？", "options": ["Keep coalesce(1) and rename the output column to partition_id.", "Replace coalesce(1) with limit(1), preserving every input row.", "Keep coalesce(1) and increase executor count; its one partition must then run in all executors simultaneously.", "Remove the unnecessary coalesce(1), retaining an appropriate number of partitions for the transformation and write."], "options_ja": ["coalesce(1)のまま出力列名をpartition_idへ変える。", "limit(1)に置換し、全入力行を保持する。", "coalesce(1)のままExecutor数を増やせば、その1パーティションが全Executorで同時実行される。", "不要なcoalesce(1)を外し、変換・書込みに適切な分割数を保つ。"], "correct": 3, "distractors_ja": ["列名はタスクの分割数を指定しません。", "limit(1)は最大1行に減らす処理で、全行を保持しません。", "通常の1パーティションの処理を、Executor追加だけで全体へ分割できるわけではありません。", "正答"], "explanation_ja": "coalesce(1)は並列性を大きく制限し得ます。出力ファイル数の要件と処理性能を両方考え、今回は不要になった1分割の指定を外します。必要なら適切な再分割を検討します。\n\n英文の読み取り：no longer required＝以前の1ファイル要件がなくなったことが判断の鍵です。", "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.coalesce.html", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-T04", "exam": 4, "objective": "coalesceによる過度な直列化", "concept_label": "coalesceによる過度な直列化", "difficulty": "applied", "misconception_tags": ["列名はタスクの分割数を指定しません。", "limit(1)は最大1行に減らす処理で、全行を保持しません。", "通常の1パーティションの処理を、Executor追加だけで全体へ分割できるわけではありません。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-20", "domain": "Tuning", "topic": "パーティションごとの処理偏り", "concept": "shuffle-partitions", "stem": "A shuffle stage has 80 tasks. Seventy-nine finish quickly, but one processes far more input bytes and runs for several minutes. CPU utilization falls as the other tasks finish. Which diagnosis should be investigated first?", "stem_ja": "shuffleステージの80タスクのうち79はすぐ終わりますが、1つだけ入力バイト数が大幅に多く、数分かかります。他タスクが終わるとCPU利用率も低下します。最初に調べるべき診断は？", "options": ["The cluster has too few partitions because exactly 80 is always below Spark's required minimum.", "Every task is necessarily waiting for the driver to collect the whole dataset.", "The task durations prove that all source records are duplicated.", "Uneven data distribution creates a large straggler partition."], "options_ja": ["Sparkには80より大きい必須最小分割数があるため分割不足である。", "全タスクが必ずDriverの全データcollectを待っている。", "処理時間から全入力行の重複が証明できる。", "データの偏りによって大きな遅延パーティションができている。"], "correct": 3, "distractors_ja": ["固定の必須最小80超というルールはありません。", "collectを行うという条件はなく、この観測から断定できません。", "入力の重複有無は処理時間だけでは分かりません。", "正答"], "explanation_ja": "タスク間の入力サイズと所要時間を比較してskewを疑います。単にExecutorを増やしても大きな1パーティションがそのままなら改善しない可能性があります。キー分布や実行計画を調べます。\n\n英文の読み取り：one / far more bytes＝全体的な遅さか、1つに偏った遅さかを区別します。", "source_url": "https://spark.apache.org/docs/3.5.7/web-ui.html#stage-detail", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-T01", "exam": 4, "objective": "パーティションごとの処理偏り", "concept_label": "パーティションごとの処理偏り", "difficulty": "applied", "misconception_tags": ["固定の必須最小80超というルールはありません。", "collectを行うという条件はなく、この観測から断定できません。", "入力の重複有無は処理時間だけでは分かりません。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-21", "domain": "Tuning", "topic": "列の読み取り削減", "concept": "file-read-schema", "stem": "A Parquet dataset contains 150 columns. A report uses only account_id and amount, with a filter on amount. Which change gives Spark the clearest opportunity to avoid reading unneeded column data?", "stem_ja": "Parquetデータセットに150列あります。レポートに必要なのはaccount_idとamountのみで、amountの条件で絞ります。不要な列データの読取りを避ける機会をSparkへ与える変更は？", "options": ["Call repartition without projecting columns, then collect every column.", "Select the two required columns and express the filter with built-in DataFrame operations before collecting results.", "Convert all rows to a Python list before applying the filter.", "Collect all 150 columns and then drop 148 columns in Python."], "options_ja": ["列を選ばずrepartitionして全列をcollectする。", "必要な2列をselectし、組込みDataFrame操作で絞ってから結果を取得する。", "全行をPythonリストへ変換してから条件を適用する。", "150列をcollectしてからPythonで148列を落とす。"], "correct": 1, "distractors_ja": ["分割変更だけでは出力対象の列が減りません。", "正答", "全行収集後のフィルターはSparkの読取り最適化に使えません。", "全列を転送した後では、その読取りを避けられません。"], "explanation_ja": "Parquetは列指向形式です。必要な列を計画に示すことでcolumn pruningを利用できます。条件のpushdown可否や効果はデータソース・式・設定にも依存するため、実行計画で確認します。\n\n英文の読み取り：only two columns / before collecting＝取得後に捨てるのではなく、必要な情報を先に計画へ示します。", "source_url": "https://spark.apache.org/docs/3.5.7/sql-performance-tuning.html", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-T03", "exam": 4, "objective": "列の読み取り削減", "concept_label": "列の読み取り削減", "difficulty": "applied", "misconception_tags": ["分割変更だけでは出力対象の列が減りません。", "", "全行収集後のフィルターはSparkの読取り最適化に使えません。", "全列を転送した後では、その読取りを避けられません。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"]}, {"id": "M4-22", "domain": "DataFrame", "topic": "組込み式でPython UDFを置き換える", "concept": "builtin-absolute-difference", "stem": "actual and target contain finite, non-NULL doubles, and their subtraction cannot overflow. Compute the absolute difference for each row using built-in Spark expressions, without a Python UDF or local collection. Which expression fits?", "stem_ja": "actualとtargetは有限のNULLなしdouble値で、減算によるオーバーフローもありません。Python UDFやローカルへの収集を使わず、Sparkの組込み式で各行の差の絶対値を計算します。適切な式はどれですか？", "options": ["F.abs(F.col('actual') - F.col('target'))", "F.udf(lambda a, t: abs(a - t), 'double')('actual', 'target')", "F.abs(F.col('actual')) - F.abs(F.col('target'))", "F.col('actual') - F.col('target')"], "options_ja": ["actualからtargetを引いた差に、組込みabsを適用する。", "Python関数absを使うPython UDFで計算する。", "actualとtargetのそれぞれの絶対値を求めてから引く。", "actualからtargetを引くだけにする。"], "correct": 0, "explanation_ja": "必要なのはabs(actual - target)です。各値を別々に絶対値へ変えてから引く式とは一般に一致しません。F.absとColumn演算で表せるので、Python UDFの実行境界を追加する必要もありません。", "distractors_ja": ["正答", "値の計算自体はできますが、Python UDFを使わないという条件に反します。", "例えばactual=-3、target=2なら1となり、正しい絶対差5になりません。", "actualがtargetより小さいと負の値になり、絶対差ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.functions.abs.html", "validation": "2026-10-17 Apache functions.absとColumn演算の仕様を照合。NaN・NULL・無限大・overflowは前提で除外。静的確認済み、Spark実行未検証。", "author_id": "M4R-D14", "exam": 4, "objective": "組込み式でPython UDFを置き換える", "concept_label": "組込み式でPython UDFを置き換える", "difficulty": "applied", "misconception_tags": ["", "値の計算自体はできますが、Python UDFを使わないという条件に反します。", "例えばactual=-3、target=2なら1となり、正しい絶対差5になりません。", "actualがtargetより小さいと負の値になり、絶対差ではありません。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"]}, {"id": "M4-23", "domain": "DataFrame", "topic": "unionの重複保持", "concept": "union-duplicates", "stem": "a and b have the same single string column and schema. a contains ['x', 'x', 'y']; b contains ['x', 'z']. What does a.union(b) contain, ignoring order?", "stem_ja": "aとbは同じスキーマの文字列1列を持ちます。aの値は['x','x','y']、bは['x','z']です。a.union(b)の結果はどうなりますか？ 順序は無視します。", "options": ["Three rows: 'x', 'y', and 'z' appear once each.", "Two rows: only the values found in both inputs remain.", "Five rows: 'x' appears three times, and 'y' and 'z' once each.", "The call fails because duplicate values occur in both inputs."], "options_ja": ["3行。x、y、zが各1回現れる。", "2行。両方の入力に存在する値だけが残る。", "5行。xが3回、yとzが各1回現れる。", "両入力に重複値があるため失敗する。"], "correct": 2, "explanation_ja": "DataFrame.unionは入力の行を重複も含めて連結します。SQLのUNION DISTINCTのような重複排除は自動では行いません。必要ならdistinctなどを別途指定します。", "distractors_ja": ["distinctを実行した結果と混同しています。", "共通要素の抽出はunionの役割ではありません。", "正答", "同じスキーマの行に重複があることはunionのエラー原因ではありません。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.union.html", "validation": "2026-10-17 Apache DataFrame.unionの重複保持仕様と照合。静的確認済み、Spark実行未検証。", "author_id": "M4R-D02", "exam": 4, "objective": "unionの重複保持", "concept_label": "unionの重複保持", "difficulty": "applied", "misconception_tags": ["distinctを実行した結果と混同しています。", "共通要素の抽出はunionの役割ではありません。", "", "同じスキーマの行に重複があることはunionのエラー原因ではありません。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"]}, {"id": "M4-24", "domain": "DataFrame", "topic": "区切り文字列と完全一致トークン", "concept": "split-array-contains", "stem": "tags is a non-null string of comma-separated, lowercase tokens with no spaces. Keep rows containing the exact token 'red', including 'blue,red', but excluding 'infrared,green'. Which filter condition fits?", "stem_ja": "tagsは小文字のトークンをカンマで区切ったNULLなしの文字列で、空白はありません。完全一致するトークンredを含む行を残します。blue,redは含め、infrared,greenは除外する条件はどれですか？", "options": ["F.array_contains(F.split('tags', ','), 'red')", "F.col('tags') == 'red'", "F.array_contains(F.split('tags', ','), 'infrared')", "F.col('tags').contains('red')"], "options_ja": ["カンマで配列に分け、その要素にredが含まれるかを判定する。", "文字列全体がredと等しいかを判定する。", "カンマで分けた配列にinfraredが含まれるかを判定する。", "文字列全体に部分文字列redがあるかを判定する。"], "correct": 0, "explanation_ja": "splitで個々のトークンを配列要素にし、array_containsで要素として一致するredを探します。文字列のcontainsではinfrared内のredにも一致してしまいます。", "distractors_ja": ["正答", "blue,redのように他のトークンも含む行を落とします。", "検索するトークンが逆であり、redを含む必要条件を表していません。", "部分一致なので除外すべきinfrared,greenも残します。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.functions.array_contains.html", "validation": "2026-10-17 Apache splitとarray_containsを照合。空白・大小文字・NULLを設問条件で固定。静的確認済み、Spark実行未検証。", "author_id": "M4R-D06", "exam": 4, "objective": "区切り文字列と完全一致トークン", "concept_label": "区切り文字列と完全一致トークン", "difficulty": "applied", "misconception_tags": ["", "blue,redのように他のトークンも含む行を落とします。", "検索するトークンが逆であり、redを含む必要条件を表していません。", "部分一致なので除外すべきinfrared,greenも残します。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"]}, {"id": "M4-25", "domain": "Spark SQL", "topic": "saveastable-name-matching", "concept": "saveastable-name-matching", "stem": "The existing Parquet table device_state has columns (device_id STRING, state STRING) and contains one row ('d1', 'ready'). incoming has columns (state STRING, device_id STRING), in that order, and contains ('offline', 'd2'). The following write succeeds. Which rows are now in the table, shown as (device_id, state)?\n\nincoming.write.mode(\"append\").saveAsTable(\"device_state\")", "options": ["Only ('d2', 'offline')", "('d1', 'ready') and ('offline', 'd2')", "Only ('d1', 'ready')", "('d1', 'ready') and ('d2', 'offline')"], "correct": 3, "stem_ja": "既存のParquetテーブルdevice_stateの列順は(device_id STRING, state STRING)で、('d1', 'ready')の1行があります。incomingの列順は(state STRING, device_id STRING)で、('offline', 'd2')の1行があります。次の書込みが成功した後、テーブルの行を(device_id, state)の順で示すとどうなりますか？\n\nincoming.write.mode(\"append\").saveAsTable(\"device_state\")", "options_ja": ["('d2', 'offline')だけ", "('d1', 'ready')と('offline', 'd2')", "('d1', 'ready')だけ", "('d1', 'ready')と('d2', 'offline')"], "explanation_ja": "saveAsTableのappendは、入力の列名を使って既存表の列に対応させます。incomingの1列目はstateなのでofflineはstateへ、2列目のd2はdevice_idへ入ります。appendなので既存行も残ります。列位置で対応するinsertIntoとの違いです。", "distractors_ja": ["appendは既存のd1の行を削除しません。", "これは入力の列位置をそのまま対応させた結果です。saveAsTableのappendは列名で対応します。", "ignoreではなくappendなので、新しい行も追加されます。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameWriter.saveAsTable.html", "validation": "2026-10-17 Apache公式saveAsTableのappend時の列名対応を照合。独自作問・静的確認済み。Spark実行未検証。", "author_id": "M4R-S01", "exam": 4, "objective": "saveastable-name-matching", "concept_label": "saveastable-name-matching", "difficulty": "applied", "misconception_tags": ["appendは既存のd1の行を削除しません。", "これは入力の列位置をそのまま対応させた結果です。saveAsTableのappendは列名で対応します。", "ignoreではなくappendなので、新しい行も追加されます。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-26", "domain": "Structured Streaming", "topic": "sliding-window-aggregate-results", "concept": "sliding-window-overlap-counts", "stem": "A new streaming query starts with empty aggregation state. Its first micro-batch contains exactly two events, at 11:02 and 11:07 UTC on the same day. It computes events.groupBy(F.window(\"event_ts\", \"10 minutes\", \"5 minutes\")).count(), using the default window alignment and UTC session time zone. What are the (window start, count) rows in the Complete-mode output after that batch, sorted by window start?", "options": ["(10:55, 1), (11:00, 2), (11:05, 1)", "(11:00, 1), (11:05, 1)", "(11:00, 2), (11:05, 1)", "(10:55, 2), (11:00, 2), (11:05, 2)"], "correct": 0, "stem_ja": "新しいストリーミングクエリは、集計状態が空の状態から開始します。最初のマイクロバッチには、同じ日のUTC 11:02と11:07のイベントが1件ずつ、合計2件だけ含まれます。既定のウィンドウ開始位置とUTCのセッションタイムゾーンを使い、events.groupBy(F.window(\"event_ts\", \"10 minutes\", \"5 minutes\")).count()を計算します。このバッチの後にCompleteモードで出力される（ウィンドウ開始時刻, 件数）を、開始時刻順に並べるとどうなりますか？", "options_ja": ["（10:55開始, 1件）、（11:00開始, 2件）、（11:05開始, 1件）", "（11:00開始, 1件）、（11:05開始, 1件）", "（11:00開始, 2件）、（11:05開始, 1件）", "（10:55開始, 2件）、（11:00開始, 2件）、（11:05開始, 2件）"], "explanation_ja": "10分幅の窓を5分ごとに開始するため、窓は重なる。11:02は[10:55, 11:05)と[11:00, 11:10)に入り、11:07は[11:00, 11:10)と[11:05, 11:15)に入る。その結果、開始時刻ごとの件数は1、2、1になる。Completeモードはその時点の集計結果全体を出す。窓が重なる場合、出力件数の合計が元のイベント数より大きくても誤りではない。", "distractors_ja": ["正答", "5分ごとに開始することを5分幅の重ならない窓と取り違えている。指定された窓幅は10分。", "11:02を含む10:55開始の窓を見落としている。最初のイベントより前に開始した窓にも、そのイベントは入る。", "11:07は10:55開始の窓には入らず、11:02は11:05開始の窓には入らない。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.functions.window.html", "validation": "2026-10-17 Apache Spark公式window APIの窓幅・slide・開始を含み終了を含まない区間・epoch基準を照合。Complete出力はStructured Streaming Guideで照合。2イベントの所属窓を独立に列挙して確認。静的確認済み、Spark実行未検証。", "author_id": "M4R-R01", "exam": 4, "objective": "sliding-window-aggregate-results", "concept_label": "sliding-window-aggregate-results", "difficulty": "applied", "misconception_tags": ["", "5分ごとに開始することを5分幅の重ならない窓と取り違えている。指定された窓幅は10分。", "11:02を含む10:55開始の窓を見落としている。最初のイベントより前に開始した窓にも、そのイベントは入る。", "11:07は10:55開始の窓には入らず、11:02は11:05開始の窓には入らない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"]}, {"id": "M4-27", "domain": "Spark SQL", "topic": "partition-and-bucket-table", "concept": "partition-and-bucket-table", "stem": "Using a standard Spark session catalog that supports bucketed Parquet tables, events has columns region, customer_id, and event_time. A new persistent table must use region directories, declare 8 hash buckets by customer_id, and sort within each bucket by event_time. Which writer satisfies these requirements? All referenced columns are valid.", "options": ["events.write.partitionBy(\"customer_id\").bucketBy(8, \"region\").sortBy(\"event_time\").format(\"parquet\").saveAsTable(\"event_archive\")", "events.repartition(8, \"customer_id\").write.partitionBy(\"region\").format(\"parquet\").saveAsTable(\"event_archive\")", "events.write.partitionBy(\"region\").bucketBy(8, \"customer_id\").sortBy(\"event_time\").format(\"parquet\").saveAsTable(\"event_archive\")", "events.write.partitionBy(\"region\").bucketBy(8, \"customer_id\").format(\"parquet\").saveAsTable(\"event_archive\")"], "correct": 2, "stem_ja": "bucket化したParquetテーブルをサポートする標準Sparkセッションカタログを使います。eventsにはregion、customer_id、event_time列があります。新しい永続テーブルは、region別のディレクトリを使い、customer_idのハッシュで8バケットを定義し、各バケット内をevent_timeでソートする必要があります。参照列がすべて有効な場合、要件を満たすwriterは？", "options_ja": ["customer_idでpartitionByし、regionで8バケット、event_timeでsortByしてParquetテーブルを保存する。", "customer_idで8分割へrepartitionし、regionでpartitionByしてParquetテーブルを保存する。", "regionでpartitionBy、customer_idで8バケット、event_timeでsortByを指定してParquetテーブルを保存する。", "regionでpartitionBy、customer_idで8バケットを指定して保存するが、sortByは指定しない。"], "explanation_ja": "partitionByはディレクトリの分割キー、bucketByはテーブルのバケット数とハッシュキー、sortByはバケット内のソート列を指定します。これらはsaveAsTableで組み合わせられます。repartitionだけではテーブルのバケット定義になりません。8バケットの定義と、物理ファイルが必ず8個だけ作られるという保証は別です。", "distractors_ja": ["ディレクトリのキーとバケットのキーが逆です。", "repartitionは実行上の分割を変えますが、bucketByのテーブル定義や要求されたソートを指定しません。", "正答", "ディレクトリとバケットの指定は正しいですが、event_timeのソートを指定していません。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-data-sources-load-save-functions.html#bucketing-sorting-and-partitioning", "validation": "2026-10-17 Apache公式Bucketing, Sorting and Partitioningを照合。bucketed Parquet対応の標準Sparkセッションカタログに限定。独自作問・静的確認済み。Spark実行未検証。", "author_id": "M4R-S08", "exam": 4, "objective": "partition-and-bucket-table", "concept_label": "partition-and-bucket-table", "difficulty": "applied", "misconception_tags": ["ディレクトリのキーとバケットのキーが逆です。", "repartitionは実行上の分割を変えますが、bucketByのテーブル定義や要求されたソートを指定しません。", "", "ディレクトリとバケットの指定は正しいですが、event_timeのソートを指定していません。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"]}, {"id": "M4-28", "domain": "Spark SQL", "topic": "reader-explicit-parquet-schema", "concept": "reader-explicit-parquet-schema", "stem": "path contains valid Parquet files with account_id stored as STRING and amount as DOUBLE. A requirement is to explicitly pass the matching schema to the reader and explicitly select Parquet, regardless of the default data source. Which code satisfies both requirements?", "options": ["spark.read.schema(\"account_id STRING, amount DOUBLE\").format(\"parquet\").load(path)", "spark.read.schema(\"account_id STRING, amount DOUBLE\").load(path)", "spark.read.option(\"header\", True).format(\"parquet\").load(path)", "spark.read.schema(\"account_id STRING, amount DOUBLE\").format(\"csv\").load(path)"], "correct": 0, "stem_ja": "pathには、account_idをSTRING、amountをDOUBLEとして保存した有効なParquetファイルがあります。既定のデータソース形式にかかわらず、対応するスキーマをreaderに明示的に渡し、Parquet形式も明示的に選ぶ必要があります。両方を満たすコードは？", "options_ja": ["schema(\"account_id STRING, amount DOUBLE\")とformat(\"parquet\")を指定して読む。", "対応するスキーマを指定するが、formatを指定せずload(path)で読む。", "header=TrueとParquet形式を指定して読む。スキーマ指定はしない。", "対応するスキーマを指定し、format(\"csv\")として読む。"], "explanation_ja": "DataFrameReader.schemaはStructTypeまたはDDL形式の文字列で入力スキーマを受け取ります。format(\"parquet\")は使用するreaderを明示します。Parquetは自身のメタデータからスキーマを取得できますが、この問題の要件は呼出し側が明示的にスキーマを渡すことです。スキーマ指定は、任意の不一致型を自動変換できるという意味ではありません。", "distractors_ja": ["正答", "loadは形式を省略すると既定のデータソースを使うため、既定値に依存せずParquetを明示する要件を満たしません。", "headerオプションは入力スキーマを明示的に渡す操作ではありません。", "ファイルはParquetであり、CSV readerの指定は要件に合いません。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameReader.schema.html", "validation": "2026-10-17 Apache公式DataFrameReader.schemaとGeneric Load/Saveを照合。物理型と指定型が一致する条件に限定。独自作問・静的確認済み。Spark実行未検証。", "author_id": "M4R-S04", "exam": 4, "objective": "reader-explicit-parquet-schema", "concept_label": "reader-explicit-parquet-schema", "difficulty": "applied", "misconception_tags": ["", "loadは形式を省略すると既定のデータソースを使うため、既定値に依存せずParquetを明示する要件を満たしません。", "headerオプションは入力スキーマを明示的に渡す操作ではありません。", "ファイルはParquetであり、CSV readerの指定は要件に合いません。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"]}, {"id": "M4-29", "domain": "DataFrame", "topic": "na.fillの型とsubset", "concept": "fillna-type-subset", "stem": "df has age INT and postal_code STRING. In one row both values are NULL. What are that row's values after df.na.fill(0, subset=['age', 'postal_code'])?", "stem_ja": "dfのageはINT、postal_codeはSTRINGです。ある行では両方ともNULLです。df.na.fill(0,subset=['age','postal_code'])の後、その行の値はどうなりますか？", "options": ["The call fails because subset contains a string column.", "age=0, postal_code='0'", "age=NULL, postal_code=NULL", "age=0, postal_code=NULL"], "options_ja": ["subsetに文字列列があるため失敗する。", "age=0、postal_code='0'。", "両方ともNULLのまま。", "age=0、postal_code=NULL。"], "correct": 3, "explanation_ja": "単一の数値0を指定したfillでは、型が合う数値列が対象です。subsetに含まれていても、型が合わない文字列列は無視されます。列別の異なる補完値が必要なら辞書で明示します。", "distractors_ja": ["型が合わないsubsetの列は無視され、この理由だけで処理全体は失敗しません。", "数値0が自動的に文字列'0'へ変換されて全列に使われるわけではありません。", "ageは値と型が対応しているため補完されます。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.fillna.html", "validation": "2026-10-17 Apache fillna/na.fillの型不一致列を無視する仕様を照合。明示スキーマで曖昧さを排除。静的確認済み、Spark実行未検証。", "author_id": "M4R-D04", "exam": 4, "objective": "na.fillの型とsubset", "concept_label": "na.fillの型とsubset", "difficulty": "applied", "misconception_tags": ["型が合わないsubsetの列は無視され、この理由だけで処理全体は失敗しません。", "数値0が自動的に文字列'0'へ変換されて全列に使われるわけではありません。", "ageは値と型が対応しているため補完されます。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-30", "domain": "Structured Streaming", "topic": "query-output-mode-sink-compatibility", "concept": "streaming-output-mode-compatibility", "stem": "In classic Spark Structured Streaming, events is a streaming DataFrame and lookup is a static DataFrame. Neither has a watermark. All referenced columns and required paths are valid. Which query, output mode, and sink combination is supported?", "options": ["A count grouped only by customer_id; Update mode; standard Parquet file sink.", "An inner join of events with lookup; Append mode; console sink.", "A filter on events with no aggregation; Complete mode; console sink.", "A count grouped only by customer_id; Append mode; console sink."], "correct": 1, "stem_ja": "Classic SparkのStructured Streamingで、eventsはストリーミングDataFrame、lookupは静的なDataFrameです。どちらにもウォーターマークは設定されていません。参照する列と必要なパスはすべて有効です。クエリ、出力モード、保存先の組合せとしてサポートされるものはどれですか？", "options_ja": ["customer_idだけでグループ化した件数集計。Updateモード。標準のParquetファイル出力。", "eventsとlookupの内部結合。Appendモード。console出力。", "集計を含まないeventsのフィルター処理。Completeモード。console出力。", "customer_idだけでグループ化した件数集計。Appendモード。console出力。"], "explanation_ja": "ストリームと静的DataFrameの内部結合はAppendで出力でき、consoleもAppendをサポートする。一方、終了が確定しないcustomer_idごとの集計をAppendで出すことはできない。Completeは集計結果全体を出すモードで、集計のないフィルターだけのクエリには使えない。Updateに対応する集計であっても、標準のParquetファイルsinkはAppend専用なので組み合わせられない。演算と保存先の両方についてモードの対応を確認する。", "distractors_ja": ["集計はUpdateに対応するが、標準ParquetファイルsinkがUpdateに対応しない。", "正答", "Completeは集計のないクエリには対応しない。console自体がCompleteに対応することだけでは不十分。", "今後のイベントで同じcustomer_idの件数が変わり得る。ウォーターマークで完了する時刻窓もなく、Appendでは出せない。"], "source_url": "https://spark.apache.org/docs/3.5.7/structured-streaming-programming-guide.html#output-modes", "validation": "2026-10-17 Apache Spark公式Structured Streaming Guideのstream-static join、Output Modes、Output Sinksの対応表を照合。Classic、静的結合先、ウォーターマークなし、標準Parquetを明記して唯一の正解を確認。静的確認済み、ストリーム実行未検証。", "author_id": "M4R-R02", "exam": 4, "objective": "query-output-mode-sink-compatibility", "concept_label": "query-output-mode-sink-compatibility", "difficulty": "applied", "misconception_tags": ["集計はUpdateに対応するが、標準ParquetファイルsinkがUpdateに対応しない。", "", "Completeは集計のないクエリには対応しない。console自体がCompleteに対応することだけでは不十分。", "今後のイベントで同じcustomer_idの件数が変わり得る。ウォーターマークで完了する時刻窓もなく、Appendでは出せない。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"]}, {"id": "M4-31", "domain": "DataFrame", "topic": "2種類のcoalesce", "concept": "coalesce-expression-vs-partitions", "stem": "df is a nonempty batch DataFrame with 12 partitions and two string columns. Consider:\n\nresult = df.select(F.coalesce('nickname', 'legal_name').alias('label')).coalesce(3)\n\nWhich statement describes the two coalesce calls?", "stem_ja": "dfは12パーティションを持つ空でないバッチDataFrameで、文字列列が2つあります。次の2つのcoalesce呼び出しの説明はどれですか？\n\nresult = df.select(F.coalesce('nickname', 'legal_name').alias('label')).coalesce(3)", "options": ["The first call concatenates the two strings, and the second keeps only three rows.", "The function chooses the first non-NULL value per row; the DataFrame method reduces the partition count without selecting only three rows.", "Both calls change partition counts; neither computes a label value.", "Both calls replace NULL values, and 3 becomes the replacement value for every label."], "options_ja": ["最初は2文字列を連結し、後の呼び出しは3行だけを残す。", "関数は各行の最初の非NULL値を選び、DataFrameメソッドは行を3件に絞ることなくパーティション数を減らす。", "両方ともパーティション数を変えるだけで、labelの値は計算しない。", "両方ともNULL補完であり、3が全labelの補完値になる。"], "correct": 1, "explanation_ja": "名前は同じでも対象が違います。F.coalesceは列式で、nicknameがNULLならlegal_nameを使います。両方NULLなら結果もNULLです。DataFrame.coalesce(3)はパーティションの削減で、limit(3)ではありません。", "distractors_ja": ["文字列連結ではなく最初の非NULL値を選びます。3行に制限する処理もありません。", "正答", "F.coalesceはColumnを返し、行ごとのlabel値を決めます。", "DataFrame.coalesceの整数は補完値ではなくパーティション数です。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.functions.coalesce.html", "validation": "2026-10-17 Apache functions.coalesceとDataFrame.coalesceを照合。初期パーティション数は要求数より多いと明記。静的確認済み、Spark実行未検証。", "author_id": "M4R-D12", "exam": 4, "objective": "2種類のcoalesce", "concept_label": "2種類のcoalesce", "difficulty": "applied", "misconception_tags": ["文字列連結ではなく最初の非NULL値を選びます。3行に制限する処理もありません。", "", "F.coalesceはColumnを返し、行ごとのlabel値を決めます。", "DataFrame.coalesceの整数は補完値ではなくパーティション数です。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"]}, {"id": "M4-32", "domain": "Architecture", "topic": "unpersist後のDataFrame", "concept": "cache-persist", "stem": "A deterministic batch DataFrame derived from available source files has been cached and materialized. The developer calls df.unpersist(), then later calls df.count(). No other cached copy is available. What should be expected?", "stem_ja": "利用可能な入力ファイルから作った決定的なバッチDataFrameをcacheし、実体化しました。df.unpersist()の後にdf.count()を呼びます。他のキャッシュコピーはありません。想定される動作は？", "options": ["unpersist removes the schema and makes the DataFrame invalid.", "The DataFrame remains usable; Spark can recompute its rows from the source and transformations.", "count must return zero because cached blocks were removed.", "unpersist deletes the source files, so count must fail."], "options_ja": ["unpersistがスキーマを消すためDataFrameは無効になる。", "DataFrameは引き続き利用でき、入力と変換から再計算できる。", "キャッシュブロックを削除したのでcountは必ず0になる。", "unpersistが入力ファイルを削除するためcountは失敗する。"], "correct": 1, "distractors_ja": ["キャッシュを解除してもDataFrameのスキーマは消えません。", "正答", "キャッシュの有無は論理的な行数を0へ変更しません。", "unpersistは入力データソースを削除しません。"], "explanation_ja": "cacheは計算済みデータの再利用のための仕組みです。unpersistで保持を解除してもDataFrameを再び評価できます。この問題では再計算に必要な入力が残ることを明示しています。\n\n英文の読み取り：available source files＝再計算に使える元入力がある条件。cache削除と元データ削除を区別します。", "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.unpersist.html", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-A04", "exam": 4, "objective": "unpersist後のDataFrame", "concept_label": "unpersist後のDataFrame", "difficulty": "applied", "misconception_tags": ["キャッシュを解除してもDataFrameのスキーマは消えません。", "", "キャッシュの有無は論理的な行数を0へ変更しません。", "unpersistは入力データソースを削除しません。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"]}, {"id": "M4-33", "domain": "DataFrame", "topic": "subset重複排除と選択行の保証", "concept": "dedup-order-guarantee", "stem": "A batch DataFrame has two readings for each device_id, with different recorded_at values. An engineer runs df.dropDuplicates(['device_id']) and expects the latest reading for every device. Which assessment is correct?", "stem_ja": "バッチDataFrameには各device_idにつき2件の測定値があり、recorded_atは異なります。df.dropDuplicates(['device_id'])で各機器の最新測定値が残ると期待しています。正しい判断はどれですか？", "options": ["The row with the largest recorded_at is always retained automatically.", "One row per device is retained, but this call does not guarantee that it is the latest reading.", "Only devices whose two rows are identical in every column remain.", "Both readings remain because their recorded_at values differ."], "options_ja": ["recorded_atが最大の行が自動的に必ず残る。", "機器ごとに1行は残るが、この呼び出しは最新の測定値を残す保証を持たない。", "全列が同一の2行を持つ機器だけが残る。", "recorded_atが違うので両方の測定値が残る。"], "correct": 1, "explanation_ja": "subsetは重複と見なす列を指定するだけで、どの行を優先するかは指定しません。最新行が必要なら時刻で並べるWindowとrow_numberなどで選択基準を表します。単に重複が消えることと最新行が選ばれることを分けて判断します。", "distractors_ja": ["時刻列を指定していない処理が、自動で最新時刻を選ぶことは保証されません。", "正答", "subset以外の列が一致する必要はなく、重複のない機器も除外されません。", "重複判定はdevice_idだけなので、他列が違っても1行になります。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.dropDuplicates.html", "validation": "2026-10-17 Apache dropDuplicatesのsubset契約と照合。最新行選択が保証に含まれないことを判断する独自問題。静的確認済み。", "author_id": "M4R-D03", "exam": 4, "objective": "subset重複排除と選択行の保証", "concept_label": "subset重複排除と選択行の保証", "difficulty": "applied", "misconception_tags": ["時刻列を指定していない処理が、自動で最新時刻を選ぶことは保証されません。", "", "subset以外の列が一致する必要はなく、重複のない機器も除外されません。", "重複判定はdevice_idだけなので、他列が違っても1行になります。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"]}, {"id": "M4-34", "domain": "DataFrame", "topic": "sampleの件数保証", "concept": "sample-fraction-guarantee", "stem": "df has exactly 1,000 rows with unique row IDs. An engineer calls df.sample(withReplacement=False, fraction=0.2, seed=17) and requires exactly 200 rows. Which assessment is correct?", "stem_ja": "dfは一意な行IDを持つちょうど1,000行です。df.sample(withReplacement=False,fraction=0.2,seed=17)で、ちょうど200行を得たいと考えています。正しい判断はどれですか？", "options": ["withReplacement=False automatically rounds the result count to exactly 200.", "The sample always returns the first 200 rows in row-ID order.", "The fixed seed guarantees both exactly 200 rows and a new set of rows on every run.", "The requested fraction does not guarantee exactly 200 rows, even with a fixed seed."], "options_ja": ["withReplacement=Falseが結果件数をちょうど200行へ自動調整する。", "行ID順で先頭200行が必ず返る。", "seed固定により、ちょうど200行かつ毎回異なる行集合が保証される。", "seedを固定しても、指定割合がちょうど200行を保証するわけではない。"], "correct": 3, "explanation_ja": "sampleのfractionは抽出割合の指定で、総件数に割合を掛けた正確な行数を保証しません。seedは乱数の条件を固定する指定で、件数を固定する指定ではありません。without replacementは同じ入力行を繰り返し抽出しないという意味です。", "distractors_ja": ["重複抽出の有無と、正確な件数の調整は別です。", "sampleは行ID順の先頭取得ではなく、orderByとlimitも指定されていません。", "seedは正確な件数を保証せず、毎回異なる集合を強制する指定でもありません。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.sample.html", "validation": "2026-10-17 Apache sampleの厳密な割合非保証を照合。特定seedの実件数は予測しない設問。静的確認済み。", "author_id": "M4R-D13", "exam": 4, "objective": "sampleの件数保証", "concept_label": "sampleの件数保証", "difficulty": "applied", "misconception_tags": ["重複抽出の有無と、正確な件数の調整は別です。", "sampleは行ID順の先頭取得ではなく、orderByとlimitも指定されていません。", "seedは正確な件数を保証せず、毎回異なる集合を強制する指定でもありません。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-35", "domain": "Architecture", "topic": "GCと使用中オブジェクト", "concept": "memory-diagnostics", "stem": "An executor still needs a large JVM object held by live strong references. The application expects garbage collection to free this object while keeping those references valid. Which statement is correct?", "stem_ja": "Executorは、有効な強参照で保持されている大きなJVMオブジェクトを引き続き必要としています。その参照を維持したまま、GCがそのオブジェクトを解放すると期待しています。正しい説明は？", "options": ["GC guarantees that all cached and referenced values are removed whenever memory is low.", "GC cannot reclaim an object that is still strongly reachable and needed merely because memory is low.", "GC moves the object to the driver and rewrites all references automatically.", "GC increases the configured executor heap until every reachable object fits."], "options_ja": ["GCはメモリ不足時に参照中のキャッシュ値を必ず全削除する。", "メモリ不足だけを理由に、まだ強参照で到達可能で必要なオブジェクトをGCは回収できない。", "GCはオブジェクトをDriverへ移して参照を自動更新する。", "GCは全オブジェクトが収まるまでExecutorヒープ上限を増やす。"], "correct": 1, "distractors_ja": ["必要な値を任意に削除することはできません。", "正答", "分散プロセス間への移動はGCの機能ではありません。", "GCは設定済みヒープ上限を拡張しません。"], "explanation_ja": "GCで不要オブジェクトを回収しても、生存データそのものがメモリに収まらなければ解決しません。データ表現、パーティション、保持量、資源設定などを見直す問題です。\n\n英文の読み取り：live strong references＝まだ有効な強参照で保持されている。不要になったオブジェクトとは違います。", "source_url": "https://spark.apache.org/docs/3.5.7/tuning.html#garbage-collection-tuning", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-A06", "exam": 4, "objective": "GCと使用中オブジェクト", "concept_label": "GCと使用中オブジェクト", "difficulty": "applied", "misconception_tags": ["必要な値を任意に削除することはできません。", "", "分散プロセス間への移動はGCの機能ではありません。", "GCは設定済みヒープ上限を拡張しません。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"]}, {"id": "M4-36", "domain": "Structured Streaming", "topic": "await-termination-timeout-control-flow", "concept": "wait-timeout-does-not-stop-query", "stem": "For an active StreamingQuery q, q.awaitTermination(5) returns False without raising an exception. An engineer assumes the five-second timeout has stopped the query. Which correction is appropriate?", "options": ["False confirms that q was stopped successfully when the five seconds expired.", "False means q failed, but awaitTermination always suppresses the failure exception.", "The wait timed out without observing termination; the call did not stop q. Use q.stop() if the query should be stopped.", "Calling q.awaitTermination(5) a second time will automatically stop q after five more seconds."], "correct": 2, "stem_ja": "実行中のStreamingQueryであるqに対してq.awaitTermination(5)を呼んだところ、例外を送出せずFalseが返りました。エンジニアは、5秒のタイムアウトによってクエリが停止したと考えています。適切な訂正はどれですか？", "options_ja": ["Falseは、5秒経過時にqが正常に停止されたことを示す。", "Falseはqの失敗を示すが、awaitTerminationは失敗の例外を常に抑止する。", "終了を確認しないまま待機がタイムアウトしただけで、この呼出しはqを停止していない。停止させたい場合はq.stop()を使う。", "q.awaitTermination(5)をもう一度呼べば、さらに5秒後にqが自動的に停止する。"], "explanation_ja": "awaitTerminationのtimeoutは、呼出し元が終了を待つ時間の上限。時間内に終了しなければFalseを返すが、クエリの停止命令にはならない。停止を要求する操作はstop。クエリが例外で終了した場合にはawaitTerminationもその例外を送出する。なおFalseの返却後に別の原因でクエリが終了する可能性までは否定できず、ここで判断できるのはこの待機呼出し自体が停止操作ではないこと。", "distractors_ja": ["Falseは指定時間内の終了を確認できなかったことを表す。正常停止を示す値ではない。", "クエリが例外で終了した場合は例外が送出される。Falseを失敗通知として扱うのは誤り。", "正答", "待機を繰り返しても停止命令には変わらない。各呼出しは終了を待つだけ。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.ss/api/pyspark.sql.streaming.StreamingQuery.awaitTermination.html", "validation": "2026-10-17 Apache Spark公式awaitTermination APIのtimeout、bool返値、StreamingQueryExceptionおよびstopの例を照合。返却後も永続的に実行中であるとは断定しない。静的確認済み、実行未検証。", "author_id": "M4R-R05", "exam": 4, "objective": "await-termination-timeout-control-flow", "concept_label": "await-termination-timeout-control-flow", "difficulty": "applied", "misconception_tags": ["Falseは指定時間内の終了を確認できなかったことを表す。正常停止を示す値ではない。", "クエリが例外で終了した場合は例外が送出される。Falseを失敗通知として扱うのは誤り。", "", "待機を繰り返しても停止命令には変わらない。各呼出しは終了を待つだけ。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"]}, {"id": "M4-37", "domain": "Structured Streaming", "topic": "available-now-bounded-run", "concept": "available-now-source-target", "stem": "A file-source query uses maxFilesPerTrigger=2 and trigger(availableNow=True). At startup it identifies six new files to process. A seventh file arrives only after the source has fixed this run's available-data target. Assume valid files, a persistent checkpoint, and successful processing. Which behavior is expected?", "options": ["It processes only two files, then stops permanently because AvailableNow allows only one micro-batch.", "It must ignore maxFilesPerTrigger and process the six files in one micro-batch.", "It processes the six targeted files over multiple micro-batches and stops; a later run using the same checkpoint can process the seventh file.", "It keeps waiting for future files indefinitely, just like a processingTime trigger."], "correct": 2, "stem_ja": "ファイルをソースとするクエリがmaxFilesPerTrigger=2とtrigger(availableNow=True)を使います。開始時点で、新たに処理する6個のファイルを認識しました。今回の実行で処理するデータの対象をソースが確定した後に、7個目のファイルが到着します。ファイルは有効で、チェックポイントは永続的に保存され、処理は成功するものとします。想定される動作はどれですか？", "options_ja": ["AvailableNowではマイクロバッチを1回しか実行できないため、2個だけ処理して以後は処理できなくなる。", "maxFilesPerTriggerを必ず無視し、6個すべてを一つのマイクロバッチで処理する。", "対象となった6個を複数のマイクロバッチで処理して終了する。同じチェックポイントを使う後の実行では7個目を処理できる。", "processingTimeトリガーと同様に、将来到着するファイルを無期限に待ち続ける。"], "explanation_ja": "AvailableNowは開始時点で利用可能な対象データを処理し終えると終了する。ソースの上限設定に従って複数のマイクロバッチへ分けられるため、maxFilesPerTrigger=2は『今回の実行全体で2個まで』という意味ではない。対象確定後に到着した7個目は、今回の処理対象に追加入力され続けるものではなく、次の実行で読み取れる。同じチェックポイントを維持することで前回までの進捗を引き継ぐ。", "distractors_ja": ["AvailableNowは必要に応じて複数バッチを実行する。ファイル数の上限は各マイクロバッチに適用される。", "AvailableNowはmaxFilesPerTriggerのようなソース設定に応じて処理を分割できる。1バッチへの強制ではない。", "正答", "一定間隔で継続実行するprocessingTimeと、対象データを処理し終えたら終了するAvailableNowを混同している。"], "source_url": "https://spark.apache.org/docs/3.5.7/structured-streaming-programming-guide.html#triggers", "validation": "2026-10-17 Apache Spark公式GuideのAvailable-now、maxFilesPerTrigger、固定間隔トリガーの仕様を照合。ファイル到着と開始の競合を避けるため、7個目はソースの処理対象確定後と明記。余分な空バッチの有無や総バッチ数は問わない。静的確認済み、実行未検証。", "author_id": "M4R-R04", "exam": 4, "objective": "available-now-bounded-run", "concept_label": "available-now-bounded-run", "difficulty": "applied", "misconception_tags": ["AvailableNowは必要に応じて複数バッチを実行する。ファイル数の上限は各マイクロバッチに適用される。", "AvailableNowはmaxFilesPerTriggerのようなソース設定に応じて処理を分割できる。1バッチへの強制ではない。", "", "一定間隔で継続実行するprocessingTimeと、対象データを処理し終えたら終了するAvailableNowを混同している。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"]}, {"id": "M4-38", "domain": "Spark SQL", "topic": "write-duplicate-error", "concept": "write-duplicate-error", "stem": "A batch writes ordinary Parquet files to output_path. If that path already exists, the existing files must remain unchanged and the write must raise an error so the scheduler detects a duplicate run. Which mode should be used in df.write.mode(...).parquet(output_path)?", "options": ["ignore", "errorifexists", "overwrite", "append"], "correct": 1, "stem_ja": "バッチで通常のParquetファイルをoutput_pathに保存します。そのパスがすでに存在する場合、既存ファイルを変更せず、スケジューラが重複実行を検知できるよう書込みをエラーにする必要があります。df.write.mode(...).parquet(output_path)で指定するモードは？", "options_ja": ["ignore", "errorifexists", "overwrite", "append"], "explanation_ja": "errorifexistsは保存先が存在するとエラーにします。ignoreも既存データを変更しませんが、書込みを何もせず正常に終えるため、重複をエラーとして検知する要件を満たしません。『変更しない』に加えて『失敗として知らせる』という条件を確認します。", "distractors_ja": ["既存データは保護しますが、書込みを黙ってスキップするため、要求されたエラーになりません。", "正答", "既存データを置換してしまいます。", "既存データに行を追加してしまいます。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-data-sources-load-save-functions.html#save-modes", "validation": "2026-10-17 Apache公式Save Modesを照合。独自作問・静的確認済み。Spark実行未検証。", "author_id": "M4R-S03", "exam": 4, "objective": "write-duplicate-error", "concept_label": "write-duplicate-error", "difficulty": "applied", "misconception_tags": ["既存データは保護しますが、書込みを黙ってスキップするため、要求されたエラーになりません。", "", "既存データを置換してしまいます。", "既存データに行を追加してしまいます。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"]}, {"id": "M4-39", "domain": "Architecture", "topic": "アプリ間のキャッシュ分離", "concept": "cache-persist", "stem": "Two independent Spark applications run on the same cluster. Application A caches a DataFrame in its executors. Application B reads the same source with the same transformations. Which statement is correct about reusing A's cached blocks?", "stem_ja": "独立した2つのSparkアプリケーションが同じクラスタ上で動作しています。Aは自分のExecutorでDataFrameをcacheしました。Bが同じデータソースに同じ変換を行う場合、Aのキャッシュブロックの再利用について正しい説明は？", "options": ["B does not automatically share A's executor cache; the applications have separate executor processes.", "B can reuse the blocks by increasing its own driver memory.", "B automatically shares the blocks because the source path is identical.", "B automatically shares the blocks if both applications use the same DataFrame variable name."], "options_ja": ["BはAのExecutorキャッシュを自動共有しない。アプリごとにExecutorプロセスが分かれる。", "BのDriverメモリを増やせばAのブロックを再利用できる。", "入力パスが同じなのでBは自動共有できる。", "DataFrame変数名が同じならBは自動共有できる。"], "correct": 0, "distractors_ja": ["正答", "Driverメモリを増やす設定は他アプリのExecutorキャッシュを共有しません。", "同じ入力元は同じキャッシュの所有者を意味しません。", "Pythonの変数名はアプリをまたぐキャッシュ識別子ではありません。"], "explanation_ja": "各Sparkアプリケーションは自分のExecutorプロセスを持ちます。アプリをまたいでデータを共有したければ、両者から読める保存先などを使います。これは同一アプリ内の複数セッションの共有とは別です。\n\n英文の読み取り：independent applications＝独立したアプリ。同じクラスタという条件だけでキャッシュ共有とは判断しません。", "source_url": "https://spark.apache.org/docs/3.5.7/cluster-overview.html#components", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-A01", "exam": 4, "objective": "アプリ間のキャッシュ分離", "concept_label": "アプリ間のキャッシュ分離", "difficulty": "applied", "misconception_tags": ["", "Driverメモリを増やす設定は他アプリのExecutorキャッシュを共有しません。", "同じ入力元は同じキャッシュの所有者を意味しません。", "Pythonの変数名はアプリをまたぐキャッシュ識別子ではありません。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"]}, {"id": "M4-40", "domain": "Architecture", "topic": "変換内のaccumulatorと再実行", "concept": "execution-model", "stem": "An RDD transformation increments an accumulator for every processed record. The transformation may be recomputed after a stage retry. The application uses the accumulator as an exact billing count. What is the main problem with this design?", "stem_ja": "RDDの変換処理内で各レコードについてaccumulatorを増やしています。ステージの再試行でその変換が再計算される可能性があります。この値を厳密な課金件数に使う設計の主な問題は？", "options": ["An accumulator automatically deduplicates updates using the business key.", "The driver is unable to read an accumulator after a successful action.", "Accumulators can store only strings, so a count is unsupported.", "Updates inside transformations may be applied more than once when work is recomputed."], "options_ja": ["accumulatorは業務キーによって更新を自動重複排除する。", "action成功後もDriverはaccumulatorを読めない。", "accumulatorは文字列だけを保存するため件数を扱えない。", "変換内の更新は再計算時に複数回反映される可能性がある。"], "correct": 3, "distractors_ja": ["業務キーによる重複排除が自動で付く機構ではありません。", "最終値を読むのはDriverです。", "数値の加算はaccumulatorの基本用途です。", "正答"], "explanation_ja": "accumulatorは実行状況の集計には便利ですが、変換内の副作用を業務レコードの厳密な件数と同一視できません。課金に必要な件数は、重複の定義を決めたDataFrame/RDDの集計結果などとして求めます。\n\n英文の読み取り：transformation / recomputed / exact＝変換が再計算されても厳密な値が必要、という条件です。", "source_url": "https://spark.apache.org/docs/3.5.7/rdd-programming-guide.html#accumulators", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-A03", "exam": 4, "objective": "変換内のaccumulatorと再実行", "concept_label": "変換内のaccumulatorと再実行", "difficulty": "applied", "misconception_tags": ["業務キーによる重複排除が自動で付く機構ではありません。", "最終値を読むのはDriverです。", "数値の加算はaccumulatorの基本用途です。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-41", "domain": "DataFrame", "topic": "結合後の同名列の修飾", "concept": "join-qualified-columns", "stem": "orders and customers both contain status. They are aliased as o and c and joined using o.customer_id == c.customer_id. From joined, return only o.status as order_status and c.status as customer_status. Which select is unambiguous?", "stem_ja": "ordersとcustomersには両方ともstatus列があります。それぞれoとcという別名を付け、o.customer_id == c.customer_idで結合しました。joinedから、o.statusをorder_status、c.statusをcustomer_statusとして2列だけ取り出す曖昧さのないselectはどれですか？", "options": ["joined.select(F.col('o.status').alias('order_status'), F.col('c.status').alias('customer_status'))", "joined.select(F.col('o.status').alias('order_status'), F.col('o.status').alias('customer_status'))", "joined.select(F.lit('o.status').alias('order_status'), F.lit('c.status').alias('customer_status'))", "joined.select(F.col('status').alias('order_status'), F.col('status').alias('customer_status'))"], "options_ja": ["o.statusとc.statusをそれぞれ修飾して参照し、別々の出力名を付ける。", "両方ともo.statusを参照し、異なる出力名を付ける。", "o.statusとc.statusという文字列定数を作り、出力名を付ける。", "両方とも修飾なしのstatusを参照し、異なる出力名を付ける。"], "correct": 0, "explanation_ja": "同名列が複数ある場合、出所の別名で修飾します。出力のaliasだけ変えても、入力のstatusがどちらかという曖昧さは解消しません。litは列参照を作りません。", "distractors_ja": ["正答", "customer_statusにも注文側の値を入れるため要件を満たしません。", "各行のstatus値ではなく、文字列o.statusとc.statusを全行に入れます。", "statusが2つあるため入力参照が曖昧です。aliasは参照元の選択を代行しません。"], "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.join.html", "validation": "2026-10-17 Apache DataFrame.joinの別名付き参照例とColumn.aliasを照合。静的確認済み、Spark実行未検証。", "author_id": "M4R-D10", "exam": 4, "objective": "結合後の同名列の修飾", "concept_label": "結合後の同名列の修飾", "difficulty": "applied", "misconception_tags": ["", "customer_statusにも注文側の値を入れるため要件を満たしません。", "各行のstatus値ではなく、文字列o.statusとc.statusを全行に入れます。", "statusが2つあるため入力参照が曖昧です。aliasは参照元の選択を代行しません。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"]}, {"id": "M4-42", "domain": "Architecture", "topic": "task.cpusを含む同時実行数", "concept": "cluster-resources", "stem": "An ordinary, non-barrier CPU-only stage has 18 partitions. Three executors are available, each with 4 cores. This stage uses spark.task.cpus=2. Dynamic allocation and speculation are off; there are no failures, other jobs, or other resource limits. What is the maximum number of tasks from this stage that can run concurrently?", "stem_ja": "通常の非barrierステージが18パーティションあり、CPUだけを使います。Executorは3個で各4コア、このステージではspark.task.cpus=2を使います。動的割当と投機的実行はOFFで、失敗・他ジョブ・他資源制限はありません。このステージのタスクの最大同時実行数は？", "options": ["24", "12", "18", "6"], "options_ja": ["24タスク", "12タスク", "18タスク", "6タスク"], "correct": 3, "distractors_ja": ["1タスクに必要なコア数を掛けるのではなく、割り当て可能なコア数を割ります。", "コア合計は12ですが、今回は1タスクが2コアの割当を要求します。", "18は処理対象のパーティション数で、同時実行可能数ではありません。", "正答"], "explanation_ja": "最大同時実行数は3×floor(4/2)=6です。18パーティションは成功タスクの総数に対応します。6タスクずつ実行できても、各タスクの所要時間が同じとは限りません。\n\n英文の読み取り：concurrently＝同時に。partition数、合計コア数、1タスクの要求コア数を分けます。", "source_url": "https://spark.apache.org/docs/3.5.7/configuration.html#scheduling", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-A02", "exam": 4, "objective": "task.cpusを含む同時実行数", "concept_label": "task.cpusを含む同時実行数", "difficulty": "applied", "misconception_tags": ["1タスクに必要なコア数を掛けるのではなく、割り当て可能なコア数を割ります。", "コア合計は12ですが、今回は1タスクが2コアの割当を要求します。", "18は処理対象のパーティション数で、同時実行可能数ではありません。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"]}, {"id": "M4-43", "domain": "Architecture", "topic": "Driverへの収集量", "concept": "driver-collection", "stem": "A DataFrame contains hundreds of millions of finite numeric readings. Python code collects every row and then computes a single average. The collected data exceeds driver memory. Which change most directly avoids transferring all raw readings to the driver? F denotes pyspark.sql.functions.", "stem_ja": "DataFrameには数億件の有限な数値があり、Pythonで全行をcollectしてから平均1つを計算しています。全データがDriverメモリを超えます。全生データをDriverへ転送することを直接避ける変更は？Fはpyspark.sql.functionsを指します。", "options": ["Increase executor memory only and keep the full collect.", "Compute df.agg(F.avg(\"reading\").alias(\"mean\")).first()[\"mean\"].", "Call df.coalesce(1).collect() and average the returned rows in Python.", "Call df.repartition(200).collect() and average the returned rows in Python."], "options_ja": ["Executorメモリだけ増やし、全行collectを続ける。", "df.agg(F.avg(\"reading\").alias(\"mean\")).first()[\"mean\"]を使う。", "1パーティションにしてから全行をcollectする。", "200パーティションにしてから全行をcollectする。"], "correct": 1, "distractors_ja": ["問題となっているDriverへの収集量は減りません。", "正答", "1パーティションでも最終的に全行をDriverへ集めます。", "パーティション数を変えても、collectで全行をDriverへ集めます。"], "explanation_ja": "分散集約で結果を小さくしてから取得します。DriverとExecutorは別の役割なので、Executorだけを増強してもDriverに全データを置く問題は解消しません。\n\n英文の読み取り：single average / all raw readings＝必要なのは平均1つであり全行ではない、という対比です。", "source_url": "https://spark.apache.org/docs/3.5.7/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.collect.html", "validation": "2026-10-17 Apache一次資料との静的照合。Spark実行未検証。", "author_id": "M4R-A07", "exam": 4, "objective": "Driverへの収集量", "concept_label": "Driverへの収集量", "difficulty": "applied", "misconception_tags": ["問題となっているDriverへの収集量は減りません。", "", "1パーティションでも最終的に全行をDriverへ集めます。", "パーティション数を変えても、collectで全行をDriverへ集めます。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"]}, {"id": "M4-44", "domain": "Spark SQL", "topic": "global-temp-view-lifetime", "concept": "global-temp-view-lifetime", "stem": "In a standard classic Spark application, spark1 registers df with createOrReplaceGlobalTempView(\"live_alerts\"). spark2 = spark1.newSession() then queries global_temp.live_alerts. Later, the entire application terminates. A new application starts with the same persistent metastore but does not recreate the view. Which statement is correct?", "options": ["spark2 can query the view; the new application cannot resolve that global temporary view.", "spark2 cannot query the view, but the new application can.", "Neither can query the view because every temporary view is private to its creating session.", "Both spark2 and the new application can query the view because it is stored permanently."], "correct": 0, "stem_ja": "標準的なclassic Sparkアプリケーションで、spark1がdfをcreateOrReplaceGlobalTempView(\"live_alerts\")で登録します。続いてspark2 = spark1.newSession()がglobal_temp.live_alertsを照会します。その後アプリケーション全体が終了し、同じ永続メタストアを使う新しいアプリケーションが起動しますが、ビューは再作成しません。正しい説明は？", "options_ja": ["spark2では照会できるが、新しいアプリケーションではそのグローバル一時ビューを解決できない。", "spark2では照会できないが、新しいアプリケーションでは照会できる。", "すべての一時ビューは作成したセッション専用なので、どちらも照会できない。", "永続保存されるため、spark2でも新しいアプリケーションでも照会できる。"], "explanation_ja": "グローバル一時ビューは同一Sparkアプリケーションのセッション間で共有され、global_tempというデータベース名を付けて参照します。寿命はアプリケーションの終了までです。同じメタストアを使っても、別アプリケーションに永続テーブルのように引き継がれるわけではありません。", "distractors_ja": ["正答", "共有される範囲が逆です。同一アプリケーションのspark2からは利用できます。", "ローカル一時ビューとグローバル一時ビューを混同しています。", "globalという名前でも永続保存ではなく、アプリケーションの終了時に失われます。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-getting-started.html#global-temporary-view", "validation": "2026-10-17 Apache公式Global Temporary Viewの共有範囲・寿命を照合。classic Sparkアプリケーションの条件を明示。独自作問・静的確認済み。Spark実行未検証。", "author_id": "M4R-S05", "exam": 4, "objective": "global-temp-view-lifetime", "concept_label": "global-temp-view-lifetime", "difficulty": "applied", "misconception_tags": ["", "共有される範囲が逆です。同一アプリケーションのspark2からは利用できます。", "ローカル一時ビューとグローバル一時ビューを混同しています。", "globalという名前でも永続保存ではなく、アプリケーションの終了時に失われます。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"]}, {"id": "M4-45", "domain": "DataFrame", "topic": "Mapの値取得と存在しないキー", "concept": "map-lookup-missing-key", "stem": "settings has type MAP<STRING,STRING>. Row 1 contains {'region':'APAC','tier':'basic'}; row 2 contains only {'tier':'basic'}. What does F.element_at('settings', F.lit('region')) return for rows 1 and 2?", "stem_ja": "settingsはMAP<STRING,STRING>です。行1は{'region':'APAC','tier':'basic'}、行2は{'tier':'basic'}だけを持ちます。F.element_at('settings',F.lit('region'))は行1と行2で何を返しますか？", "options": ["'region' and 'region'.", "'APAC' and 'basic'.", "'APAC' and NULL.", "The entire query fails because row 2 has no region key."], "options_ja": ["どちらもregionという文字列。", "APACとbasic。", "APACとNULL。", "行2にregionキーがないためクエリ全体が失敗する。"], "correct": 2, "explanation_ja": "Mapへのelement_atは指定キーに対応する値を返し、キーがなければNULLを返します。Mapは配列とは異なり、存在しないキーの代わりに次の要素を選ぶことはありません。", "distractors_ja": ["検索キーそのものではなく、対応する値を取り出す式です。", "regionがない場合にtierの値へ自動フォールバックはしません。", "正答", "Mapにキーがない場合はNULLです。配列インデックスの範囲外エラーと混同しないでください。"], "source_url": "https://spark.apache.org/docs/3.5.7/sql-ref-functions-builtin.html#map-functions", "validation": "2026-10-17 Apache element_at(map,key)の不存在キーがNULLとなる仕様を照合。配列インデックスと区別。静的確認済み、Spark実行未検証。", "author_id": "M4R-D07", "exam": 4, "objective": "Mapの値取得と存在しないキー", "concept_label": "Mapの値取得と存在しないキー", "difficulty": "applied", "misconception_tags": ["検索キーそのものではなく、対応する値を取り出す式です。", "regionがない場合にtierの値へ自動フォールバックはしません。", "", "Mapにキーがない場合はNULLです。配列インデックスの範囲外エラーと混同しないでください。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"]}], "minutes": 90}], "variants": [{"id": "T001", "domain": "DataFrame", "topic": "NULL補完と平均の分母", "objective": "NULLを除外する集計と0補完後の集計を比較する", "difficulty": "applied", "stem": "A quality report reads a nullable integer column delay with the three values 10, NULL, and 2. It calculates:\n\ndf.agg(F.avg('delay').alias('observed'), F.avg(F.coalesce(F.col('delay'), F.lit(0))).alias('zero_filled'))\n\nWhat are the two numeric results (observed, zero_filled)?", "options": ["(6.0, 4.0)", "(4.0, 4.0)", "(6.0, 6.0)", "(NULL, 4.0)"], "correct": 0, "explanation_ja": "avgはNULLを分母から除外するので12÷2=6となる。coalesceでNULLを0へ置き換えた列では3行が集計対象となり12÷3=4となる。欠損補完は結果の意味も変える。", "distractors_ja": ["正答", "元のavgはNULL行を分母に含めない。", "0補完後の行も平均の分母に含まれる。", "NULLが1行あっても既知値の平均は計算できる。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-ref-null-semantics.html", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "null-semantics", "concept_label": "NULL・欠損値の扱い", "misconception_tags": ["", "確認ポイント：元のavgはNULL行を分母に含めない。", "確認ポイント：0補完後の行も平均の分母に含まれる。", "確認ポイント：NULLが1行あっても既知値の平均は計算できる。"], "suggested_causes": ["unknown", "boundary", "boundary", "boundary"], "stem_ja": "品質レポートが、NULLを許容する整数列delayから10、NULL、2の3つの値を読み取ります。次の計算を行います。\n\ndf.agg(F.avg('delay').alias('observed'), F.avg(F.coalesce(F.col('delay'), F.lit(0))).alias('zero_filled'))\n\n2つの数値結果(observed, zero_filled)はどれですか？", "options_ja": ["(6.0, 4.0)", "(4.0, 4.0)", "(6.0, 6.0)", "(NULL, 4.0)"]}, {"id": "T002", "domain": "DataFrame", "topic": "NULL結合と重複の組合せ", "objective": "NULL安全な結合の行数を計算する", "difficulty": "applied", "stem": "DataFrame a has one nullable integer key column with rows NULL, 1, and 1. DataFrame b has keys NULL and 1. Compare these two inner joins:\n\nordinary = a.join(b, a.key == b.key, 'inner')\nsafe = a.join(b, a.key.eqNullSafe(b.key), 'inner')\n\nWhat are (ordinary.count(), safe.count())?", "options": ["(2, 2)", "(2, 3)", "(1, 2)", "(3, 3)"], "correct": 1, "explanation_ja": "通常の等号ではNULL同士が一致せず、左の2つの1が右の1に一致して2行となる。eqNullSafeはNULL同士も一致するため1行増えて3行となる。結合は重複キーを自動除去しない。", "distractors_ja": ["eqNullSafeではNULL同士が一致する。", "正答", "結合前の重複キーは自動的に1行へまとめられない。", "通常の等号でNULL同士は一致しない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.Column.eqNullSafe.html", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "joins", "concept_label": "結合条件・結合種類・行数", "misconception_tags": ["確認ポイント：eqNullSafeではNULL同士が一致する。", "", "確認ポイント：結合前の重複キーは自動的に1行へまとめられない。", "確認ポイント：通常の等号でNULL同士は一致しない。"], "suggested_causes": ["boundary", "unknown", "boundary", "boundary"], "stem_ja": "DataFrameのaにはNULLを許容する整数のkey列が1つあり、行の値はNULL、1、1です。DataFrameのbのキーはNULLと1です。次の2つの内部結合を比較します。\n\nordinary = a.join(b, a.key == b.key, 'inner')\nsafe = a.join(b, a.key.eqNullSafe(b.key), 'inner')\n\n(ordinary.count(), safe.count())はどれですか？", "options_ja": ["(2, 2)", "(2, 3)", "(1, 2)", "(3, 3)"]}, {"id": "T003", "domain": "DataFrame", "topic": "直前1行を含む移動合計", "objective": "rowsBetweenの相対的境界をコードに適用する", "difficulty": "applied", "stem": "df has columns account STRING, seq INT, and debit INT. All rows have account='A', with (seq, debit) values (1, 3), (2, 8), (3, 2); seq is unique within this account. An engineer defines:\n\nw = Window.partitionBy('account').orderBy('seq').rowsBetween(-1, 0)\nout = df.withColumn('rolling', F.sum('debit').over(w))\n\nWhat are the rolling values in ascending seq order?", "options": ["[0, 3, 8]", "[11, 13, 10]", "[3, 11, 10]", "[3, 11, 13]"], "correct": 2, "explanation_ja": "rowsBetween(-1,0)は各行の直前1行から現在行までを含む。先頭では現在行だけ、2行目では3+8、3行目では8+2を集計する。先頭からの累積合計とは異なる。", "distractors_ja": ["現在行も範囲に含む。", "後続行は範囲に含まれない。", "正答", "これは先頭から現在行までの累積合計。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.Window.rowsBetween.html", "validation": "公式API資料でrowsBetweenの両端包含・相対境界を再確認。スキーマと順序の前提を明記・Spark未実行", "concept": "windows-order", "concept_label": "ウィンドウ関数・順序", "misconception_tags": ["確認ポイント：現在行も範囲に含む。", "確認ポイント：後続行は範囲に含まれない。", "", "確認ポイント：これは先頭から現在行までの累積合計。"], "suggested_causes": ["boundary", "boundary", "unknown", "boundary"], "stem_ja": "dfにはaccount STRING、seq INT、debit INTの各列があります。すべての行でaccount='A'となり、(seq, debit)の値は(1, 3)、(2, 8)、(3, 2)です。このアカウント内でseqは一意です。エンジニアが次のように定義します。\n\nw = Window.partitionBy('account').orderBy('seq').rowsBetween(-1, 0)\nout = df.withColumn('rolling', F.sum('debit').over(w))\n\nseqの昇順でのrollingの値はどれですか？", "options_ja": ["[0, 3, 8]", "[11, 13, 10]", "[3, 11, 10]", "[3, 11, 13]"]}, {"id": "T004", "domain": "DataFrame", "topic": "名前対応のunionと欠損補完", "objective": "不足列と列順の異なるデータを統合する", "difficulty": "applied", "stem": "legacy has schema (id INT, amount INT) and row (7, 30). fresh has schema (currency STRING, amount INT, id INT) and row ('EUR', 40, 8). The program runs:\n\nlegacy.unionByName(fresh, allowMissingColumns=True).fillna({'currency': 'USD'}).select('id', 'amount', 'currency')\n\nIgnoring row order, which rows result?", "options": ["(7, 30, NULL) and (8, 40, 'EUR')", "(7, 30, 'USD') and (8, 40, 'USD')", "The different input column counts always cause an analysis error", "(7, 30, 'USD') and (8, 40, 'EUR')"], "correct": 3, "explanation_ja": "unionByNameは列名で対応付ける。不足しているcurrencyにはNULLが入り、その行だけfillnaでUSDへ変わる。既存のEURはNULLではないので上書きされない。", "distractors_ja": ["fillnaの対象にcurrencyを指定しているのでNULLは補完される。", "fillnaは既存の非NULL値を置き換えない。", "allowMissingColumns=Trueで不足列を許可している。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.unionByName.html", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "sets-dedup", "concept_label": "集合演算・重複・列対応", "misconception_tags": ["確認ポイント：fillnaの対象にcurrencyを指定しているのでNULLは補完される。", "確認ポイント：fillnaは既存の非NULL値を置き換えない。", "確認ポイント：allowMissingColumns=Trueで不足列を許可している。", ""], "suggested_causes": ["api", "boundary", "api", "unknown"], "stem_ja": "legacyはスキーマ(id INT, amount INT)と行(7, 30)を持ちます。freshはスキーマ(currency STRING, amount INT, id INT)と行('EUR', 40, 8)を持ちます。プログラムが次を実行します。\n\nlegacy.unionByName(fresh, allowMissingColumns=True).fillna({'currency': 'USD'}).select('id', 'amount', 'currency')\n\n行の順序を無視した場合、結果の行はどれですか？", "options_ja": ["(7, 30, NULL)と(8, 40, 'EUR')", "(7, 30, 'USD')と(8, 40, 'USD')", "入力の列数が異なるため、必ず解析エラーになります", "(7, 30, 'USD')と(8, 40, 'EUR')"]}, {"id": "T005", "domain": "DataFrame", "topic": "配列展開後のCOUNT", "objective": "空配列の保持とCOUNTの違いを組み合わせる", "difficulty": "applied", "stem": "The schema is id INT, skus ARRAY<STRING>. The rows are (1, []) and (2, [NULL, 'X']). The program runs:\n\nexpanded = df.select('id', F.explode_outer('skus').alias('sku'))\nresult = expanded.groupBy('id').agg(F.count('*').alias('rows'), F.count('sku').alias('known'))\n\nWhich (id, rows, known) results are produced?", "options": ["(1, 1, 0) and (2, 2, 1)", "(2, 2, 1) only", "(1, 1, 1) and (2, 2, 2)", "(1, 0, 0) and (2, 1, 1)"], "correct": 0, "explanation_ja": "explode_outerは空配列でもsku=NULLの1行を残す。count(*)はすべての行を数えるがcount(sku)は非NULLのみを数える。したがってid=1は1行・既知値0、id=2は2行・既知値1。", "distractors_ja": ["正答", "空配列を消すのはexplodeの動作。", "count(sku)はNULLを数えない。", "配列内のNULL要素も展開後の行として残る。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.explode_outer.html", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "nested-data", "concept_label": "配列・構造体・展開", "misconception_tags": ["", "確認ポイント：空配列を消すのはexplodeの動作。", "確認ポイント：count(sku)はNULLを数えない。", "確認ポイント：配列内のNULL要素も展開後の行として残る。"], "suggested_causes": ["unknown", "api", "boundary", "boundary"], "stem_ja": "スキーマはid INT, skus ARRAY<STRING>です。行は(1, [])と(2, [NULL, 'X'])です。プログラムが次を実行します。\n\nexpanded = df.select('id', F.explode_outer('skus').alias('sku'))\nresult = expanded.groupBy('id').agg(F.count('*').alias('rows'), F.count('sku').alias('known'))\n\n生成される(id, rows, known)の結果はどれですか？", "options_ja": ["(1, 1, 0)と(2, 2, 1)", "(2, 2, 1)のみ", "(1, 1, 1)と(2, 2, 2)", "(1, 0, 0)と(2, 1, 1)"]}, {"id": "T006", "domain": "DataFrame", "topic": "表示用日付とDateType", "objective": "date_formatの返却型を理解して適切に変換する", "difficulty": "applied", "stem": "ts is a TimestampType column. A developer prepares partition_day with F.date_format('ts', 'yyyy-MM-dd'). A schema check requires partition_day to have DateType rather than StringType. Which expression directly produces the required date column from ts?", "options": ["F.col('ts').cast('string')", "F.to_date('ts')", "F.date_format('ts', 'yyyy-MM-dd')", "F.concat_ws('-', F.year('ts'), F.month('ts'), F.dayofmonth('ts'))"], "correct": 1, "explanation_ja": "date_formatは日付らしい表示でもStringTypeを返す。日付型が要件ならto_dateでDateTypeにする。文字列の見た目とスキーマ上の型を区別する。", "distractors_ja": ["stringへのcastは要件と逆の変換。", "正答", "date_formatの結果型はStringType。", "文字列連結はDateTypeへの変換にならない。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.date_format.html", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "string-date-functions", "concept_label": "文字列・日付関数", "misconception_tags": ["確認ポイント：stringへのcastは要件と逆の変換。", "", "確認ポイント：date_formatの結果型はStringType。", "確認ポイント：文字列連結はDateTypeへの変換にならない。"], "suggested_causes": ["api", "unknown", "api", "api"], "stem_ja": "tsはTimestampTypeの列です。開発者はF.date_format('ts', 'yyyy-MM-dd')でpartition_dayを作成します。スキーマのチェックでは、partition_dayがStringTypeではなくDateTypeである必要があります。tsから必要な日付列を直接生成する式はどれですか？", "options_ja": ["F.col('ts').cast('string')", "F.to_date('ts')", "F.date_format('ts', 'yyyy-MM-dd')", "F.concat_ws('-', F.year('ts'), F.month('ts'), F.dayofmonth('ts'))"]}, {"id": "T007", "domain": "DataFrame", "topic": "正規表現の不一致とCOUNT", "objective": "空文字とNULLの差を処理結果から判断する", "difficulty": "applied", "stem": "The non-null strings in ref are 'AB-09' and 'bad'. The program runs:\n\nparsed = df.select(F.regexp_extract('ref', r'AB-(\\d+)', 1).alias('code'))\nparsed.agg(F.count('code').alias('n')).first()['n']\n\nWhat integer is returned?", "options": ["0", "An exception is always raised for a non-matching string", "2", "1"], "correct": 2, "explanation_ja": "regexp_extractは一致しなかった場合に空文字を返す。空文字はNULLではないため、09と空文字の両方がcount(code)で数えられる。必要なら空文字を明示的に除外する。", "distractors_ja": ["一致した09は少なくとも1件の非NULL値。", "パターンに一致しないだけでは例外にならない。", "正答", "一致しない文字列の結果をNULLと取り違えている。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.regexp_extract.html", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "string-date-functions", "concept_label": "文字列・日付関数", "misconception_tags": ["確認ポイント：一致した09は少なくとも1件の非NULL値。", "確認ポイント：パターンに一致しないだけでは例外にならない。", "", "確認ポイント：一致しない文字列の結果をNULLと取り違えている。"], "suggested_causes": ["boundary", "boundary", "unknown", "boundary"], "stem_ja": "refのNULLではない文字列は'AB-09'と'bad'です。プログラムが次を実行します。\n\nparsed = df.select(F.regexp_extract('ref', r'AB-(\\d+)', 1).alias('code'))\nparsed.agg(F.count('code').alias('n')).first()['n']\n\n返される整数はいくつですか？", "options_ja": ["0", "一致しない文字列に対しては必ず例外が発生します", "2", "1"]}, {"id": "T008", "domain": "DataFrame", "topic": "不正なcast後の欠損補完", "objective": "ANSI設定と後段の補完を通して値を追う", "difficulty": "applied", "stem": "spark.sql.ansi.enabled is false. The string column raw_units contains '4' and 'broken'. An engineer runs:\n\nout = df.select(F.col('raw_units').cast('int').alias('units')).fillna({'units': 0})\n\nIgnoring row order, which values does units contain?", "options": ["[4, NULL]", "[4, \"broken\"]", "The query must fail on \"broken\" even with ANSI disabled", "[4, 0]"], "correct": 3, "explanation_ja": "ANSI無効では不正な整数castはNULLになる。後段のfillnaはそのNULLを0へ補完する。これで元の破損値は見えなくなるため、品質確認ではcast前の値も必要に応じて保持する。", "distractors_ja": ["cast後にfillnaで補完している。", "整数型にcastした列に元の文字列は残らない。", "指定されたANSI無効という条件を踏まえる。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-ref-ansi-compliance.html", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "schema-types", "concept_label": "スキーマ・型の確認", "misconception_tags": ["確認ポイント：cast後にfillnaで補完している。", "確認ポイント：整数型にcastした列に元の文字列は残らない。", "確認ポイント：指定されたANSI無効という条件を踏まえる。", ""], "suggested_causes": ["boundary", "api", "boundary", "unknown"], "stem_ja": "spark.sql.ansi.enabledはfalseです。文字列列raw_unitsには'4'と'broken'が入っています。エンジニアが次を実行します。\n\nout = df.select(F.col('raw_units').cast('int').alias('units')).fillna({'units': 0})\n\n行の順序を無視した場合、unitsに含まれる値はどれですか？", "options_ja": ["[4, NULL]", "[4, \"broken\"]", "ANSIが無効でも、クエリは\"broken\"で必ず失敗します", "[4, 0]"]}, {"id": "T009", "domain": "Architecture", "topic": "cacheの寿命", "objective": "アプリケーションをまたぐ永続保存とcacheを区別する", "difficulty": "applied", "stem": "A nightly Spark application calls enriched.cache(), fully materializes it, and then exits normally. The next morning a new, independent Spark application starts. The team wants to load the previous enriched result without re-reading its original sources. No files or tables were written. Which statement is correct?", "options": ["The previous cache is not a durable dataset for the new application; persist the result to external storage for that requirement", "cache() creates a permanent table that every application can open by variable name", "Calling cache() in the new application automatically restores the old cached blocks", "Changing cache() to MEMORY_AND_DISK guarantees reuse after the original application exits"], "correct": 0, "explanation_ja": "cache/persistは実行中のアプリケーション内での再利用に使う。別アプリケーションから後日読み出す成果物が必要なら、ファイルやテーブルとして外部ストレージへ書き出す。ディスクを含む保存レベルも外部データ保存の代わりにはならない。", "distractors_ja": ["正答", "Python変数名で参照できる永続テーブルは作られない。", "新しいアプリケーションは前日のcacheを自動復元しない。", "executor上のディスクcacheは外部への永続保存ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/cluster-overview.html", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "cache-persist", "concept_label": "cache・persist・再利用", "misconception_tags": ["", "確認ポイント：Python変数名で参照できる永続テーブルは作られない。", "確認ポイント：新しいアプリケーションは前日のcacheを自動復元しない。", "確認ポイント：executor上のディスクcacheは外部への永続保存ではない。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "夜間に実行されるSparkアプリケーションがenriched.cache()を呼び出し、結果を完全に実体化してから正常終了します。翌朝、新しい独立したSparkアプリケーションが起動します。チームは、元のソースを読み直さずに、前回のenrichedの結果を読み込みたいと考えています。ファイルやテーブルへの書き込みは行っていません。正しい説明はどれですか？", "options_ja": ["前回のキャッシュは新しいアプリケーション向けの永続的なデータセットではありません。その要件を満たすには、結果を外部ストレージに保存します", "cache()は、すべてのアプリケーションから変数名で開ける永続テーブルを作成します", "新しいアプリケーションでcache()を呼び出すと、以前のキャッシュブロックが自動的に復元されます", "cache()をMEMORY_AND_DISKに変更すれば、元のアプリケーション終了後も再利用できることが保証されます"]}, {"id": "T010", "domain": "Architecture", "topic": "task数と同時実行数", "objective": "パーティション数とCPU割当から2つの数を区別する", "difficulty": "applied", "stem": "A stage must process ten partitions. The application has three executors with four CPU cores each, spark.task.cpus=2, no resource constraints other than CPU, no failures, and no speculation. What are (total tasks for the stage, maximum simultaneously running tasks)?", "options": ["(12, 10)", "(10, 6)", "(6, 6)", "(10, 12)"], "correct": 1, "explanation_ja": "対象の10パーティションには10タスクが必要。各executorでは4÷2=2タスク、3台で最大6タスクが同時に動く。総タスク数と同時実行枠を分けて考える。", "distractors_ja": ["割当コア数は総タスク数を決めない。", "正答", "同時実行枠が6でも、未処理の4パーティション用タスクは残る。", "1タスクが2CPUを必要とする条件を反映していない。"], "source_url": "https://spark.apache.org/docs/3.5.6/configuration.html#scheduling", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "cluster-resources", "concept_label": "driver・executor・並列資源", "misconception_tags": ["確認ポイント：割当コア数は総タスク数を決めない。", "", "確認ポイント：同時実行枠が6でも、未処理の4パーティション用タスクは残る。", "確認ポイント：1タスクが2CPUを必要とする条件を反映していない。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "boundary"], "stem_ja": "あるステージでは10個のパーティションを処理する必要があります。アプリケーションには、それぞれ4つのCPUコアを持つエグゼキューターが3つあり、spark.task.cpus=2です。CPU以外のリソース制約はなく、失敗も投機的実行もありません。(ステージの総タスク数, 同時に実行できる最大タスク数)はどれですか？", "options_ja": ["(12, 10)", "(10, 6)", "(6, 6)", "(10, 12)"]}, {"id": "T011", "domain": "Architecture", "topic": "複数actionと再計算", "objective": "遅延評価と再利用の関係を理解する", "difficulty": "applied", "stem": "A deterministic transformation clean is built from an unchanged file source. No caching or checkpointing is used. A program executes clean.count(), then clean.write.parquet(new_path). Both actions succeed. Which statement is safest?", "options": ["The write is a transformation and therefore cannot trigger computation", "Exactly two stages must exist because exactly two actions appear in the source code", "The second action may execute the upstream transformations again; the Python variable alone does not preserve their materialized result", "The first action permanently stores all clean rows for every later action"], "correct": 2, "explanation_ja": "DataFrame変数は計画を参照するもので、評価済みの全行を保持することを意味しない。actionをまたいで中間結果を再利用したい場合は、cache等を適切な位置へ置く。action数からstage数を固定することもできない。", "distractors_ja": ["ファイルへのwriteは計算を実行する。", "stage数はshuffleや実行計画等にも依存する。", "正答", "countの実行だけでは一般的な永続cacheにならない。"], "source_url": "https://spark.apache.org/docs/3.5.6/rdd-programming-guide.html", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "execution-model", "concept_label": "遅延評価・action・実行単位", "misconception_tags": ["確認ポイント：ファイルへのwriteは計算を実行する。", "確認ポイント：stage数はshuffleや実行計画等にも依存する。", "", "確認ポイント：countの実行だけでは一般的な永続cacheにならない。"], "suggested_causes": ["knowledge", "knowledge", "unknown", "knowledge"], "stem_ja": "変更されていないファイルソースから、決定的な変換であるcleanを定義しています。キャッシュやチェックポイントは使用していません。プログラムはclean.count()を実行し、続いてclean.write.parquet(new_path)を実行します。どちらのアクションも成功します。最も確実に言える説明はどれですか？", "options_ja": ["書き込みは変換なので、計算を開始することはありません", "ソースコードにちょうど2つのアクションがあるため、ステージも必ずちょうど2つです", "2つ目のアクションで、上流の変換が再実行される可能性があります。Python変数だけでは、実体化された結果は保持されません", "最初のアクションが、以降のすべてのアクションのためにcleanの全行を永久に保存します"]}, {"id": "T012", "domain": "Architecture", "topic": "別セッションからのビュー参照", "objective": "local viewとglobal viewの寿命・参照方法を適用する", "difficulty": "applied", "stem": "Within one classic Spark application, s1 registers a local temporary view local_rates and a global temporary view shared_rates. The global temporary database has its default name. Then s2 = s1.newSession() is created. No persistent tables have either name. Which SQL in s2 can resolve a view created by s1?", "options": ["s2.sql('SELECT * FROM local_rates')", "s2.sql('SELECT * FROM shared_rates')", "s2.sql('SELECT * FROM global_temp.local_rates')", "s2.sql('SELECT * FROM global_temp.shared_rates')"], "correct": 3, "explanation_ja": "local temporary viewは作成したセッションに属する。global temporary viewは同一アプリケーション内で共有でき、既定ではglobal_tempで修飾して参照する。newSessionはlocal viewを共有しない。", "distractors_ja": ["別セッションはs1のlocal temporary viewを共有しない。", "global temporary viewには既定データベース名による修飾が必要。", "local viewをglobal_tempで修飾してもglobal viewにはならない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-getting-started.html#global-temporary-view", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "sessions-views", "concept_label": "セッション・ビューの共有範囲", "misconception_tags": ["確認ポイント：別セッションはs1のlocal temporary viewを共有しない。", "確認ポイント：global temporary viewには既定データベース名による修飾が必要。", "確認ポイント：local viewをglobal_tempで修飾してもglobal viewにはならない。", ""], "suggested_causes": ["knowledge", "api", "api", "unknown"], "stem_ja": "1つの従来型Sparkアプリケーション内で、s1がローカル一時ビューlocal_ratesとグローバル一時ビューshared_ratesを登録します。グローバル一時データベースの名前は既定値です。その後、s2 = s1.newSession()を作成します。どちらの名前の永続テーブルも存在しません。s2で実行するSQLのうち、s1で作成したビューを解決できるものはどれですか？", "options_ja": ["s2.sql('SELECT * FROM local_rates')", "s2.sql('SELECT * FROM shared_rates')", "s2.sql('SELECT * FROM global_temp.local_rates')", "s2.sql('SELECT * FROM global_temp.shared_rates')"]}, {"id": "T013", "domain": "Structured Streaming", "topic": "watermarkと壁時計", "objective": "イベント時刻基準の進行を診断する", "difficulty": "applied", "stem": "A single-input event-time aggregation uses withWatermark('event_ts', '10 minutes'). The newest observed event time is 12:30. No events with a newer event time arrive while the wall clock advances to 15:00. Which assumption is unsafe?", "options": ["The watermark must advance to 14:50 solely because the wall clock is now 15:00", "Watermark progress depends on event-time information observed by the query", "An idle source can delay event-time state cleanup", "Processing-time passage and event-time progress are different concepts"], "correct": 0, "explanation_ja": "watermarkは処理時の壁時計から単純に遅延幅を引く仕組みではない。観測したイベント時刻の進行が関係するため、3時間待っただけで14:50へ進むとはいえない。", "distractors_ja": ["正答", "これは正しい説明なのでunsafeという問いの答えではない。", "これは起こり得るためunsafeな仮定ではない。", "両者を区別する説明は正しい。"], "source_url": "https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html#handling-late-data-and-watermarking", "validation": "Spark 3.5.6公式資料で仕様を再確認・4択の整合性を静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "stream-watermark", "concept_label": "イベント時刻・watermark・状態", "misconception_tags": ["", "確認ポイント：これは正しい説明なのでunsafeという問いの答えではない。", "確認ポイント：これは起こり得るためunsafeな仮定ではない。", "確認ポイント：両者を区別する説明は正しい。"], "suggested_causes": ["unknown", "knowledge", "knowledge", "knowledge"], "stem_ja": "入力が1つのイベント時刻集約で、withWatermark('event_ts', '10 minutes')を使用しています。観測された最新のイベント時刻は12:30です。実際の時計が15:00まで進む間、これより新しいイベント時刻を持つイベントは到着しません。適切でない仮定はどれですか？", "options_ja": ["実際の時計が15:00になったという理由だけで、ウォーターマークは必ず14:50まで進みます", "ウォーターマークの進行は、クエリが観測したイベント時刻の情報に依存します", "入力がないソースでは、イベント時刻に基づく状態のクリーンアップが遅れる可能性があります", "処理時刻の経過とイベント時刻の進行は、異なる概念です"]}, {"id": "T014", "domain": "Structured Streaming", "topic": "複数sinkへのforeachBatch", "objective": "再実行で片方だけが重複する問題を防ぐ", "difficulty": "applied", "stem": "A foreachBatch callback writes the same batch to databases A and B. It succeeds in A, fails before completing B, and is retried with the same batchId. Neither database transaction spans both systems. Which design directly addresses duplicate side effects during retries?", "options": ["Record completion in A before inserting rows into either database and skip all later work if A has that marker", "Make each database write independently idempotent using the query identity and batchId, with its completion marker committed atomically with its rows", "Use append for both writes because foreachBatch guarantees one callback invocation per batch", "Create a fresh checkpoint directory on every retry"], "correct": 1, "explanation_ja": "foreachBatchの再実行を考慮し、各書込先で重複処理を避ける必要がある。書込と完了記録を同じトランザクションにし、別queryのbatchIdと混ざらない識別子も使う。この設計でも2つのDBの同時可視性までは保証しない。", "distractors_ja": ["Aだけの記録でBをskipすると未完了のBが欠落する。", "正答", "callbackの再実行があり得るので単純appendは重複を生む。", "checkpointを変えることは重複副作用の解決にならない。"], "source_url": "https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html#using-foreach-and-foreachbatch", "validation": "Spark 3.5.6公式資料で仕様を再確認・4択の整合性を静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "stream-reliability", "concept_label": "ストリーム再開・再実行の保証", "misconception_tags": ["確認ポイント：Aだけの記録でBをskipすると未完了のBが欠落する。", "", "確認ポイント：callbackの再実行があり得るので単純appendは重複を生む。", "確認ポイント：checkpointを変えることは重複副作用の解決にならない。"], "suggested_causes": ["boundary", "unknown", "knowledge", "knowledge"], "stem_ja": "foreachBatchコールバックが、同じバッチをデータベースAとBに書き込みます。Aへの書き込みは成功し、Bへの書き込み完了前に失敗した後、同じbatchIdで再試行されます。どちらのデータベースのトランザクションも両方のシステムにはまたがりません。再試行中に副作用が重複する問題に直接対処する設計はどれですか？", "options_ja": ["どちらのデータベースにも行を挿入する前にAに完了を記録し、Aにそのマーカーがあれば以後の処理をすべてスキップします", "クエリの識別子とbatchIdを使用し、各データベースへの書き込みをそれぞれ独立して冪等にします。完了マーカーは、その行と同じ処理単位で原子的にコミットします", "foreachBatchはバッチごとにコールバックが1回だけ呼び出されることを保証するため、両方の書き込みにappendを使用します", "再試行のたびに新しいチェックポイントディレクトリを作成します"]}, {"id": "T015", "domain": "Structured Streaming", "topic": "Update出力のsink側解釈", "objective": "更新された合計値と差分を区別する", "difficulty": "applied", "stem": "An update-mode aggregation calculates total sales by product. The previously emitted result for P is 20. A later micro-batch adds 5 to P and the query emits (P, 25). An external sink currently stores 20 for P. How should it interpret the emitted 25 to maintain the same aggregate?", "options": ["As only the new input row count, so store 5", "As a signal that every unchanged product must be deleted", "As the new aggregate value for P, so replace/upsert P with 25", "As a delta to add to the stored value, producing 45"], "correct": 2, "explanation_ja": "Updateモードは更新された結果行を出力する。今回の25は新しい集約値であり差分5ではない。sinkが加算すると20+25=45となって二重計上するため、キーに対して値を更新する。", "distractors_ja": ["salesの集約値を行数へ読み替えられない。", "出力されなかったキーは削除指示ではない。", "正答", "出力値は差分ではなく現在の集約値。"], "source_url": "https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html#output-modes", "validation": "Spark 3.5.6公式資料で仕様を再確認・4択の整合性を静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "stream-modes", "concept_label": "ストリーミング出力モード", "misconception_tags": ["確認ポイント：salesの集約値を行数へ読み替えられない。", "確認ポイント：出力されなかったキーは削除指示ではない。", "", "確認ポイント：出力値は差分ではなく現在の集約値。"], "suggested_causes": ["boundary", "boundary", "unknown", "boundary"], "stem_ja": "updateモードの集約が、商品ごとの売上合計を計算します。Pについて前回出力された結果は20です。その後のマイクロバッチでPに5が加わり、クエリは(P, 25)を出力します。外部シンクには現在、Pについて20が保存されています。同じ集約結果を維持するには、出力された25をどのように解釈すべきですか？", "options_ja": ["新しい入力行数だけを表すものとして、5を保存します", "変更のないすべての商品を削除すべきという指示として解釈します", "Pの新しい集約値として、Pを25で置換またはupsertします", "保存済みの値に加算する差分として解釈し、45にします"]}, {"id": "T016", "domain": "Structured Streaming", "topic": "処理時間triggerと処理遅延", "objective": "長いmicro-batchの後の起動を判断する", "difficulty": "applied", "stem": "A Spark 3.5 micro-batch query uses trigger(processingTime='2 seconds'). A batch starts at t=0 and finishes at t=5 seconds. There is still input available. Ignore scheduling overhead. What does the configured trigger do next?", "options": ["Start overlapping batches at t=2 and t=4 even though the first is still running", "Wait until t=7 because every batch completion must be followed by a two-second sleep", "Cancel the current batch as soon as it exceeds two seconds", "Start the next batch as soon as the previous batch finishes"], "correct": 3, "explanation_ja": "processingTimeは処理時間の上限や重複実行の指定ではない。前のmicro-batchが指定間隔を超えたときは、終了後に次のmicro-batchを開始する。", "distractors_ja": ["同じqueryのmicro-batchをこの設定で重複起動しない。", "間隔超過時に必ず追加の2秒待機する仕様ではない。", "2秒を超えること自体は取消条件ではない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html#triggers", "validation": "Spark 3.5.6公式資料で仕様を再確認・4択の整合性を静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "stream-lifecycle", "concept_label": "ストリーム入力・開始・停止・trigger", "misconception_tags": ["確認ポイント：同じqueryのmicro-batchをこの設定で重複起動しない。", "確認ポイント：間隔超過時に必ず追加の2秒待機する仕様ではない。", "確認ポイント：2秒を超えること自体は取消条件ではない。", ""], "suggested_causes": ["knowledge", "knowledge", "knowledge", "unknown"], "stem_ja": "Spark 3.5のマイクロバッチクエリがtrigger(processingTime='2 seconds')を使用しています。バッチはt=0に開始し、t=5秒に終了します。処理可能な入力はまだ残っています。スケジューリングのオーバーヘッドは無視します。設定されたトリガーは、次に何をしますか？", "options_ja": ["最初のバッチがまだ実行中でも、t=2とt=4で重複するバッチを開始します", "各バッチの完了後は必ず2秒間スリープするため、t=7まで待ちます", "現在のバッチが2秒を超えると直ちにキャンセルします", "前のバッチが終了すると、すぐに次のバッチを開始します"]}, {"id": "T017", "domain": "Spark Connect", "topic": "JVM内部APIを使うツールの移行", "objective": "公開DataFrame APIと内部JVMアクセスを区別する", "difficulty": "applied", "stem": "A helper for classic PySpark prints a DataFrame plan by accessing df._jdf and calling JVM methods. The application is moved to a Spark Connect 3.5 client. The only required output is a human-readable query plan. Which migration is appropriate?", "options": ["Replace the private JVM access with the supported DataFrame.explain() API", "Keep df._jdf; Connect exposes the same local Py4J JVM object", "Create spark.sparkContext in the Connect client and fetch the remote JVM through it", "Convert df to df.rdd first because RDD is the required Connect transport"], "correct": 0, "explanation_ja": "Spark Connectではclassic PySparkの内部JVMオブジェクトへの直接アクセスを前提にできない。実行計画の表示には対応している公開DataFrame APIを使う。SparkContext/RDDを経由する回避策も3.5 Connectでは使えない。", "distractors_ja": ["正答", "Connectは同じローカルPy4J構成ではない。", "SparkContextはConnectの対応APIではない。", "RDDはConnectの転送APIではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/spark-connect-overview.html", "validation": "Spark 3.5.6公式資料で仕様を再確認・4択の整合性を静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "connect-api", "concept_label": "Spark Connectの接続方法・制約", "misconception_tags": ["", "確認ポイント：Connectは同じローカルPy4J構成ではない。", "確認ポイント：SparkContextはConnectの対応APIではない。", "確認ポイント：RDDはConnectの転送APIではない。"], "suggested_causes": ["unknown", "api", "api", "api"], "additional_source_urls": ["https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.explain.html"], "stem_ja": "従来型PySparkのヘルパーが、df._jdfにアクセスしてJVMメソッドを呼び出すことで、DataFrameのプランを表示しています。アプリケーションをSpark Connect 3.5クライアントへ移行します。必要な出力は、人が読める形式のクエリプランだけです。適切な移行方法はどれですか？", "options_ja": ["非公開のJVMアクセスを、サポートされているDataFrame.explain() APIに置き換えます", "Connectは同じローカルのPy4J JVMオブジェクトを公開するため、df._jdfを維持します", "Connectクライアントでspark.sparkContextを作成し、それを通じてリモートのJVMを取得します", "RDDはConnectの必須の転送方式なので、最初にdfをdf.rddへ変換します"]}, {"id": "T018", "domain": "Spark Connect", "topic": "remote実行後の大量collect", "objective": "リモート計算とクライアント収集の境界を理解する", "difficulty": "applied", "stem": "A small laptop uses Spark Connect to run a query on a large remote cluster. Distributed processing succeeds, but the laptop runs out of memory when Python executes rows = result.collect(). Which change directly addresses the stated problem while still producing a large report?", "options": ["Increase only the remote driver heap because the client never holds result rows", "Write the large result through a supported distributed sink, and collect only a small summary if needed", "Add executors but continue collecting the entire report into the same laptop process", "Assume Arrow transport automatically makes collect keep its rows distributed"], "correct": 1, "explanation_ja": "リモートで計算してもcollectは結果をクライアント側のPythonへ取り込む。大量レポートは分散書込し、手元に必要な小さな要約だけ収集する。Arrowによる転送形式は無制限のローカルメモリを提供しない。", "distractors_ja": ["この問題で不足しているのはクライアント側のメモリ。", "正答", "executorの追加ではノートPCへ全件収集する問題を直接解決しない。", "collect後の行はクライアント側に集まる。"], "source_url": "https://spark.apache.org/docs/3.5.6/spark-connect-overview.html", "validation": "Spark 3.5.6公式資料で仕様を再確認・4択の整合性を静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "connect-protocol", "concept_label": "Spark Connectの構成・通信", "misconception_tags": ["確認ポイント：この問題で不足しているのはクライアント側のメモリ。", "", "確認ポイント：executorの追加ではノートPCへ全件収集する問題を直接解決しない。", "確認ポイント：collect後の行はクライアント側に集まる。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "stem_ja": "小型のノートPCがSpark Connectを使い、大規模なリモートクラスターでクエリを実行しています。分散処理は成功しますが、Pythonでrows = result.collect()を実行するとノートPCのメモリが不足します。大規模なレポートを引き続き作成しながら、この問題に直接対処する変更はどれですか？", "options_ja": ["クライアントは結果行を保持しないため、リモートドライバーのヒープだけを増やします", "サポートされている分散シンクを通じて大きな結果を書き込み、必要に応じて小さな要約だけを収集します", "エグゼキューターを追加し、引き続き同じノートPCのプロセスにレポート全体を収集します", "Arrowによる転送では、collectの結果行が自動的に分散したまま保持されると考えます"]}, {"id": "T019", "domain": "Spark Connect", "topic": "clientとserverの構成分離", "objective": "ConnectでローカルSpark driverが必要か判断する", "difficulty": "applied", "stem": "A Python service uses a compatible Spark Connect client package and can reach an already-running remote Connect server. A review proposes launching a second local Spark driver solely to enable the client to send DataFrame plans. Which assessment is correct?", "options": ["Connect only works when the client and server are in the same JVM", "A local SparkContext is required to serialize every Connect DataFrame operation", "A second local Spark driver is not required for this purpose; the client sends plans to the remote server over the Connect protocol", "Every Connect client must run its own local Spark driver and executors"], "correct": 2, "explanation_ja": "ConnectはクライアントとSpark driverを分離する。対応クライアントは計画をプロトコル経由で既存serverへ送り、処理はserver側で行う。その送信のためだけに別のローカルdriverを立てる必要はない。", "distractors_ja": ["クライアントとserverは別プロセス・別ホストに置ける。", "ConnectクライアントはSparkContext経由で計画を送らない。", "正答", "各clientでローカルdriverとexecutorを起動する構成は必須ではない。"], "source_url": "https://spark.apache.org/docs/3.5.6/spark-connect-overview.html", "validation": "Spark 3.5.6公式資料で仕様を再確認・4択の整合性を静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "connect-protocol", "concept_label": "Spark Connectの構成・通信", "misconception_tags": ["確認ポイント：クライアントとserverは別プロセス・別ホストに置ける。", "確認ポイント：ConnectクライアントはSparkContext経由で計画を送らない。", "", "確認ポイント：各clientでローカルdriverとexecutorを起動する構成は必須ではない。"], "suggested_causes": ["knowledge", "api", "unknown", "knowledge"], "stem_ja": "Pythonサービスは互換性のあるSpark Connectクライアントパッケージを使用し、すでに稼働しているリモートのConnectサーバーに到達できます。レビューで、クライアントがDataFrameのプランを送信できるようにすることだけを目的として、2つ目のローカルSparkドライバーを起動する案が出ました。正しい評価はどれですか？", "options_ja": ["Connectは、クライアントとサーバーが同じJVM内にある場合にのみ動作します", "すべてのConnect DataFrame操作をシリアライズするには、ローカルのSparkContextが必要です", "この目的で2つ目のローカルSparkドライバーを用意する必要はありません。クライアントはConnectプロトコルを通じてリモートサーバーにプランを送信します", "すべてのConnectクライアントは、それぞれ専用のローカルSparkドライバーとエグゼキューターを実行する必要があります"]}, {"id": "T020", "domain": "Pandas API", "topic": "可変行数のpandasバッチ処理", "objective": "scalar pandas UDFとmapInPandasを選び分ける", "difficulty": "applied", "stem": "A batch-based Python algorithm receives pandas DataFrames and removes invalid records. A batch of 1,000 input rows may produce 620 output rows. The result must remain a Spark DataFrame with an explicit schema. Which API is designed to accept an iterator of pandas DataFrames and return an iterator with potentially different total row counts?", "options": ["A Series-to-Series scalar pandas UDF that returns only 620 values for 1,000 input values", "df.toPandas() followed by returning the local pandas object as though it were still distributed", "df.select(clean_batches) with the ordinary Python function passed as a column", "df.mapInPandas(clean_batches, schema=output_schema)"], "correct": 3, "explanation_ja": "mapInPandasはpandas DataFrameのイテレータを受け取り、行数が変わり得る結果をイテレータで返す処理に使える。Series-to-Series scalar pandas UDFは入力と出力の長さを一致させる契約がある。", "distractors_ja": ["scalar pandas UDFでは入力と出力の長さの契約を破っている。", "toPandasはローカルへ収集するため指定の分散結果APIではない。", "Python関数をそのままColumnとしてselectへ渡せない。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/user_guide/sql/arrow_pandas.html#map", "validation": "Spark 3.5.6公式資料で仕様を再確認・4択の整合性を静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "pandas-udfs", "concept_label": "pandas UDF・バッチ・グループ", "misconception_tags": ["確認ポイント：scalar pandas UDFでは入力と出力の長さの契約を破っている。", "確認ポイント：toPandasはローカルへ収集するため指定の分散結果APIではない。", "確認ポイント：Python関数をそのままColumnとしてselectへ渡せない。", ""], "suggested_causes": ["api", "api", "api", "unknown"], "stem_ja": "バッチ単位で処理するPythonアルゴリズムが、pandas DataFrameを受け取って不正なレコードを削除します。1,000行の入力バッチから620行が出力される場合があります。結果は、明示的なスキーマを持つSpark DataFrameのままである必要があります。pandas DataFrameのイテレーターを受け取り、総行数が異なる可能性のあるイテレーターを返すためのAPIはどれですか？", "options_ja": ["1,000個の入力値に対して620個の値だけを返す、Series-to-Series形式のスカラーpandas UDF", "df.toPandas()の後、ローカルのpandasオブジェクトをまだ分散しているかのように返す方法", "通常のPython関数を列として渡すdf.select(clean_batches)", "df.mapInPandas(clean_batches, schema=output_schema)"]}, {"id": "T021", "domain": "Pandas API", "topic": "grouped aggregate pandas UDFの結果", "objective": "グループごとに1値を返す関数の作用範囲を追う", "difficulty": "applied", "stem": "pandas is imported as pd. The DataFrame has (team, score) rows ('A', 2.0), ('A', 8.0), and ('B', 5.0). Consider this grouped aggregate pandas UDF:\n\n@pandas_udf('double')\ndef spread(s: pd.Series) -> float:\n    return float(s.max() - s.min())\n\nresult = df.groupBy('team').agg(spread('score').alias('range'))\n\nWhich rows result, ignoring row order?", "options": ["('A', 6.0) and ('B', 0.0)", "('A', 6.0), ('A', 6.0), and ('B', 0.0)", "('A', 6.0) and ('B', 6.0)", "The return value must be a Series with one value per input row"], "correct": 0, "explanation_ja": "この型注釈はSeriesからscalarへのgrouped aggregate pandas UDFを示す。Aのグループでは8−2=6、Bでは5−5=0で、各グループが1行になる。scalar Series-to-Series UDFとは返却契約が異なる。", "distractors_ja": ["正答", "groupByの集約はAの入力2行を1つの結果にまとめる。", "チームをまたいで最大値・最小値を求める処理ではない。", "grouped aggregateではグループに対するscalarを返す。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/user_guide/sql/arrow_pandas.html#series-to-scalar", "validation": "Spark 3.5.6公式資料で仕様を再確認・4択の整合性を静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "pandas-udfs", "concept_label": "pandas UDF・バッチ・グループ", "misconception_tags": ["", "確認ポイント：groupByの集約はAの入力2行を1つの結果にまとめる。", "確認ポイント：チームをまたいで最大値・最小値を求める処理ではない。", "確認ポイント：grouped aggregateではグループに対するscalarを返す。"], "suggested_causes": ["unknown", "api", "boundary", "api"], "additional_source_urls": ["https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.pandas_udf.html"], "stem_ja": "pandasはpdとしてインポート済みです。DataFrameには、(team, score)の行として('A', 2.0)、('A', 8.0)、('B', 5.0)が入っています。次のグループ集約pandas UDFについて考えます。\n\n@pandas_udf('double')\ndef spread(s: pd.Series) -> float:\n    return float(s.max() - s.min())\n\nresult = df.groupBy('team').agg(spread('score').alias('range'))\n\n行の順序を無視した場合、結果の行はどれですか？", "options_ja": ["('A', 6.0)と('B', 0.0)", "('A', 6.0)、('A', 6.0)、('B', 0.0)", "('A', 6.0)と('B', 6.0)", "戻り値は、入力行ごとに1つの値を持つSeriesでなければなりません"]}, {"id": "T022", "domain": "Pandas API", "topic": "集約してからpandasへ収集", "objective": "分散演算を保ちながら小さな可視化データを得る", "difficulty": "applied", "stem": "A pandas-on-Spark DataFrame psdf has 300 million sales rows, a non-null STRING region column with at most 20 distinct values, and a non-null DOUBLE revenue column. A local plotting library requires a pandas DataFrame containing only total revenue by region. Which approach best limits local materialization?", "options": ["Enable Arrow and then collect all 300 million rows because Arrow removes local memory limits", "psdf.groupby('region')[['revenue']].sum().to_pandas()", "psdf.to_pandas().groupby('region')[['revenue']].sum()", "psdf.to_pandas() first, because a pandas-on-Spark groupBy must run on the laptop"], "correct": 1, "explanation_ja": "分散側で地域ごとに集約してからto_pandasすれば、最大20地域分の結果だけがローカルへ集まる。全明細を先に収集すると小さな図を描くために大量のローカルメモリが必要になる。", "distractors_ja": ["Arrowを使っても収集結果が使うメモリは必要。", "正答", "集約前に全明細をローカルへ取り込んでいる。", "pandas-on-Sparkの集約は分散処理に利用できる。"], "source_url": "https://spark.apache.org/docs/3.5.6/api/python/user_guide/pandas_on_spark/best_practices.html", "validation": "Spark 3.5.6公式資料で仕様を再確認・4択の整合性を静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "pandas-distributed", "concept_label": "pandas系APIの分散処理と収集", "misconception_tags": ["確認ポイント：Arrowを使っても収集結果が使うメモリは必要。", "", "確認ポイント：集約前に全明細をローカルへ取り込んでいる。", "確認ポイント：pandas-on-Sparkの集約は分散処理に利用できる。"], "suggested_causes": ["knowledge", "unknown", "knowledge", "knowledge"], "additional_source_urls": ["https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.pandas/api/pyspark.pandas.DataFrame.to_pandas.html", "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.pandas/groupby.html"], "stem_ja": "pandas-on-SparkのDataFrameであるpsdfには、3億行の売上データがあります。regionはNULLではないSTRING列で、値の種類数は最大20です。revenueはNULLではないDOUBLE列です。ローカルの描画ライブラリは、地域ごとの収益合計だけを含むpandas DataFrameを必要としています。ローカルに実体化するデータ量を最も抑えられる方法はどれですか？", "options_ja": ["Arrowはローカルメモリの制限をなくすため、Arrowを有効にしてから3億行すべてを収集します", "psdf.groupby('region')[['revenue']].sum().to_pandas()", "psdf.to_pandas().groupby('region')[['revenue']].sum()", "pandas-on-SparkのgroupByはノートPC上で実行する必要があるため、最初にpsdf.to_pandas()を実行します"]}, {"id": "T023", "domain": "Spark SQL", "topic": "NOT INに含まれるNULL", "objective": "SQLの3値論理を除外条件へ適用する", "difficulty": "applied", "stem": "View candidates contains non-null integer id values 1, 2, and 3. What rows are returned by the following Spark SQL query?\n\nSELECT id FROM candidates WHERE id NOT IN (1, NULL)", "options": ["Only the row with id 1", "All three rows", "No rows", "Rows with id 2 and 3"], "correct": 2, "explanation_ja": "1は除外される。2と3はNULLを含むNOT INの評価がUNKNOWNとなり、WHEREのTRUE条件を満たさない。NULLを含む除外集合では意図と結果が異なることがある。", "distractors_ja": ["1はINがTRUEなのでNOT INはFALSE。", "WHEREはFALSEやUNKNOWNの行を残さない。", "正答", "NULLを単なる無視できる一覧要素として扱っている。"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-ref-null-semantics.html", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "null-semantics", "concept_label": "NULL・欠損値の扱い", "misconception_tags": ["確認ポイント：1はINがTRUEなのでNOT INはFALSE。", "確認ポイント：WHEREはFALSEやUNKNOWNの行を残さない。", "", "確認ポイント：NULLを単なる無視できる一覧要素として扱っている。"], "suggested_causes": ["boundary", "boundary", "unknown", "boundary"], "stem_ja": "ビューcandidatesには、NULLではない整数idの値1、2、3が含まれています。次のSpark SQLクエリは、どの行を返しますか？\n\nSELECT id FROM candidates WHERE id NOT IN (1, NULL)", "options_ja": ["idが1の行のみ", "3行すべて", "行を返しません", "idが2と3の行"]}, {"id": "T024", "domain": "Spark SQL", "topic": "WHEREとHAVINGの順序", "objective": "行条件とグループ集計条件を分ける", "difficulty": "applied", "stem": "View readings contains zone STRING, valid BOOLEAN, and kwh DOUBLE. A report must first discard invalid readings, then keep only zones whose remaining total kwh exceeds 20. Which query implements both requirements?", "options": ["SELECT zone, SUM(kwh) AS total FROM readings WHERE valid = true AND SUM(kwh) > 20 GROUP BY zone", "SELECT zone, SUM(kwh) AS total FROM readings WHERE kwh > 20 GROUP BY zone", "SELECT zone, SUM(kwh) AS total FROM readings GROUP BY zone HAVING SUM(kwh) > 20", "SELECT zone, SUM(kwh) AS total FROM readings WHERE valid = true GROUP BY zone HAVING SUM(kwh) > 20"], "correct": 3, "explanation_ja": "WHEREで集約前の有効行を選び、GROUP BYで集約してからHAVINGでグループの合計を判定する。個々の行のkwhを20と比較する条件では合計値の要件を表せない。", "distractors_ja": ["集約関数によるグループ条件をWHEREには置けない。", "有効性を判定せず、個別行の値で絞っている。", "無効なreadingを合計へ混ぜている。", "正答"], "source_url": "https://spark.apache.org/docs/3.5.6/sql-ref-syntax-qry-select-having.html", "validation": "公式資料参照・選択肢の静的確認済み・Spark未実行。理解の転移を確認する新作演習", "concept": "aggregation", "concept_label": "集約・統計・近似値", "misconception_tags": ["確認ポイント：集約関数によるグループ条件をWHEREには置けない。", "確認ポイント：有効性を判定せず、個別行の値で絞っている。", "確認ポイント：無効なreadingを合計へ混ぜている。", ""], "suggested_causes": ["api", "boundary", "boundary", "unknown"], "stem_ja": "ビューreadingsには、zone STRING、valid BOOLEAN、kwh DOUBLEの各列があります。レポートでは、最初に無効な測定値を除外し、その後、残ったkwhの合計が20を超えるzoneだけを残す必要があります。両方の要件を実装するクエリはどれですか？", "options_ja": ["SELECT zone, SUM(kwh) AS total FROM readings WHERE valid = true AND SUM(kwh) > 20 GROUP BY zone", "SELECT zone, SUM(kwh) AS total FROM readings WHERE kwh > 20 GROUP BY zone", "SELECT zone, SUM(kwh) AS total FROM readings GROUP BY zone HAVING SUM(kwh) > 20", "SELECT zone, SUM(kwh) AS total FROM readings WHERE valid = true GROUP BY zone HAVING SUM(kwh) > 20"]}], "drills": [{"id": "R01", "domain": "DataFrame", "prompt": "amountが[8, NULL, 12]の3行。count(\"*\")、count(\"amount\")、sum(\"amount\")の値を答える。", "answer": "3、2、20。行数と非NULL値の個数を区別する。", "pitfall": "count(column)はNULLを数えない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/dataframe.html"}, {"id": "R02", "domain": "DataFrame", "prompt": "id=[1,2,3]、status=[\"ok\",NULL,\"bad\"]。filter(col(\"status\") != \"bad\")で残るidと、NULLも残す条件を答える。", "answer": "残るのは1。NULLも残すには(col(\"status\") != \"bad\") | col(\"status\").isNull()。", "pitfall": "NULLとの比較はTrueではない。PythonのorでColumnを結合しない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/dataframe.html"}, {"id": "R03", "domain": "DataFrame", "prompt": "左表のkey=4が3行、右表のkey=4が2行。他のキーなし。inner joinとleft_semi joinの行数を答える。", "answer": "innerは6行、left_semiは左表の3行。", "pitfall": "semi joinは左行の存在判定であり、右側一致数で増殖しない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/dataframe.html"}, {"id": "R04", "domain": "DataFrame", "prompt": "左(id,city)と右(city,id)を列名で対応させて縦結合したい。両列の型は一致。使うAPIと、重複行が消えるかを答える。", "answer": "left.unionByName(right)。重複行は保持される。重複除去は別にdistinct等を使う。", "pitfall": "DataFrame.unionは位置で対応。SQL UNIONの重複除去と混同しない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/dataframe.html"}, {"id": "R05", "domain": "DataFrame", "prompt": "batch DataFrameからuser_idごとに最大event_tsの行を1つ残す。event_tsの同値時は最大event_idを選ぶ。方針をコードで示す。", "answer": "w = Window.partitionBy(\"user_id\").orderBy(col(\"event_ts\").desc(), col(\"event_id\").desc())\ndf.withColumn(\"rn\", row_number().over(w)).filter(col(\"rn\") == 1).drop(\"rn\")\n各user_id内の(event_ts,event_id)は一意とする。", "pitfall": "dropDuplicates([\"user_id\"])では最新行を指定できない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/dataframe.html"}, {"id": "R06", "domain": "DataFrame", "prompt": "配列itemsが[\"x\",\"y\"]、[]、NULLの3行。explodeで何行になるか。元の空・NULL行も残すAPIは何か。", "answer": "explodeは2行。explode_outerなら空とNULLの元行をNULL値で残す。", "pitfall": "配列内のNULL要素と配列そのものがNULLであることを区別する。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/dataframe.html"}, {"id": "R07", "domain": "DataFrame", "prompt": "整数pointsが[2,5,9]。2以上5以下を選ぶColumn条件を2通り示す。", "answer": "col(\"points\").between(2,5)\n(col(\"points\") >= 2) & (col(\"points\") <= 5)", "pitfall": "betweenは両端を含む。条件ごとの括弧が必要。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/dataframe.html"}, {"id": "R08", "domain": "DataFrame", "prompt": "schemaにa,b,cがある。aをaccount_idに改名し、bだけを削除する式を書く。", "answer": "df.withColumnRenamed(\"a\",\"account_id\").drop(\"b\")", "pitfall": "withColumnRenamedの引数は旧名、新名の順。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/dataframe.html"}, {"id": "R09", "domain": "DataFrame", "prompt": "\"2026-04-18\"という文字列をDateTypeに変え、その月だけを整数で取り出す。", "answer": "df.withColumn(\"d\", to_date(\"raw\", \"yyyy-MM-dd\")).withColumn(\"m\", month(\"d\"))", "pitfall": "date_formatは文字列。monthは月の数値。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.to_date.html"}, {"id": "R10", "domain": "DataFrame", "prompt": "df.sample(withReplacement=False, fraction=0.25, seed=9)は元の行数の正確に25%になるか。", "answer": "保証されない。各行を選ぶ確率を指定しており、行数は確率的に変動する。", "pitfall": "seed指定は正確な抽出行数を保証しない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.sample.html"}, {"id": "R11", "domain": "DataFrame", "prompt": "salaryの大きい順で同額には同順位を与え、次の順位を飛ばさない関数は何か。給与[90,90,70]の順位も答える。", "answer": "dense_rank。順位は1,1,2。", "pitfall": "rankは1,1,3。row_numberは各行を別順位にする。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/dataframe.html"}, {"id": "R12", "domain": "DataFrame", "prompt": "Python関数clean_nameをSQLのSELECTで呼び出したい。戻り値はstring。登録とSQL呼び出しを書く。", "answer": "spark.udf.register(\"clean_name\", clean_name, \"string\")\nspark.sql(\"SELECT clean_name(name) FROM people\")", "pitfall": "関数定義だけではSQL名として登録されない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.UDFRegistration.register.html"}, {"id": "R13", "domain": "Architecture", "prompt": "driver、executor、cluster managerの主な役割を、それぞれ1文で説明する。", "answer": "driverはアプリケーションを調整しタスクをスケジュールする。executorはタスクを実行しアプリケーションのデータを保持する。cluster managerは資源を割り当てる。", "pitfall": "worker nodeとexecutor processは同じ概念ではない。", "source_url": "https://spark.apache.org/docs/3.5.6/cluster-overview.html"}, {"id": "R14", "domain": "Architecture", "prompt": "Sparkでtransformationを3つ連結した直後、全データの計算が3回完了していると言えるか。", "answer": "言えない。transformationは遅延評価され、action時に必要な処理が実行される。入力メタデータ取得等の先行処理とは区別する。", "pitfall": "API呼び出しの個数とjob/stage数は一致しない。", "source_url": "https://spark.apache.org/docs/3.5.6/cluster-overview.html"}, {"id": "R15", "domain": "Architecture", "prompt": "job・stage・taskの関係を、shuffle境界とpartitionに触れて説明する。", "answer": "jobはstageへ分割され、通常shuffle依存がstage境界になる。stageの各partitionをtaskが処理する。再試行や最適化で実行回数は変わる。", "pitfall": "1つのDataFrame演算が必ず1つのstageになるわけではない。", "source_url": "https://spark.apache.org/docs/3.5.6/cluster-overview.html"}, {"id": "R16", "domain": "Architecture", "prompt": "4台のworkerに各3executor、各executor2coresが割り当てられる。総executor core数は。1task=1coreなら同時実行枠の上限は。", "answer": "4×3×2=24cores。指定条件で最大24task枠。実際の並列数は利用可能task数等でも制限される。", "pitfall": "workerの全coreを自動的に使用すると仮定しない。", "source_url": "https://spark.apache.org/docs/3.5.6/cluster-overview.html"}, {"id": "R17", "domain": "Architecture", "prompt": "単純な行filterと、キーの再配置が必要なgroupBy集約の違いをネットワーク移動で説明する。", "answer": "単純なfilterはpartition内で処理できる。必要な分割がないgroupByは同じキーを集めるためshuffleを必要とする。", "pitfall": "すべてのselectがnarrow、すべての集約が必ずshuffleという無条件断定は避ける。", "source_url": "https://spark.apache.org/docs/3.5.6/cluster-overview.html"}, {"id": "R18", "domain": "Architecture", "prompt": "df.cache()を呼んだだけで、全行がすでにcacheに保存されるか。", "answer": "通常はされない。cache対象として指定し、必要なpartitionがactionで計算された際に保存される。", "pitfall": "cache指定とcache materializationを区別する。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.cache.html"}, {"id": "R19", "domain": "Architecture", "prompt": "PySpark 3.5のDataFrame.cache()の既定StorageLevelを答える。", "answer": "MEMORY_AND_DISK_DESER。", "pitfall": "RDDの既定cache levelやScala/Pythonの名前を混同しない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.cache.html"}, {"id": "R20", "domain": "Architecture", "prompt": "executorが失われ、cacheしたpartitionも失われた。再計算可能な決定的入力が残る場合のSparkの回復方針は。", "answer": "残っている入力とlineageを使って失われたpartitionを再計算できる。", "pitfall": "cacheだけを永続バックアップやcheckpointと同一視しない。", "source_url": "https://spark.apache.org/docs/3.5.6/rdd-programming-guide.html"}, {"id": "R21", "domain": "Architecture", "prompt": "PySparkのDataFrameとScalaのtyped Datasetは同じ型検査機能をPythonで提供するか。", "answer": "提供しない。PythonではJVM言語のtyped Dataset APIを同じ形で使わず、DataFrameとschemaを使う。", "pitfall": "DataFrameにschemaがあることと、typed Datasetのコンパイル時型検査は別。", "source_url": "https://spark.apache.org/docs/3.5.6/sql-programming-guide.html"}, {"id": "R22", "domain": "Architecture", "prompt": "spark.newSession()で作った別Sessionは、元Sessionのtemporary viewをその名前のまま参照できるか。", "answer": "通常のtemp viewはSessionごとで参照できない。global temp viewは共有アプリケーション内でglobal_temp名を使う。", "pitfall": "新Sessionを必ず別アプリケーション・別SparkContextとみなさない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.SparkSession.newSession.html"}, {"id": "R23", "domain": "Spark Connect", "prompt": "Connect clientはどんな計画をserverへ送り、どちらが実行計画の解決と実行を担うか。", "answer": "clientが未解決の論理計画を送り、server側が解決・最適化してSparkで実行する。", "pitfall": "clientのローカルPython processですべてのデータを計算するわけではない。", "source_url": "https://spark.apache.org/docs/3.5.6/spark-connect-overview.html"}, {"id": "R24", "domain": "Spark Connect", "prompt": "稼働中のSpark Connect server sc://lab:15002へ接続するSparkSession生成コードを書く。", "answer": "SparkSession.builder.remote(\"sc://lab:15002\").getOrCreate()", "pitfall": "従来のspark://master URLやbuilder.masterと混同しない。", "source_url": "https://spark.apache.org/docs/3.5.6/spark-connect-overview.html"}, {"id": "R25", "domain": "Spark Connect", "prompt": "PySpark shellからConnect serverへ接続するCLI引数を書く。", "answer": "pyspark --remote \"sc://lab:15002\"", "pitfall": "--spark-connectという架空オプションを覚えない。", "source_url": "https://spark.apache.org/docs/3.5.6/spark-connect-overview.html"}, {"id": "R26", "domain": "Spark Connect", "prompt": "従来のSparkアプリをclient modeで実行する場合とcluster modeで実行する場合のdriverの場所を答える。", "answer": "client modeでは送信側client processにdriver。cluster modeではcluster側でdriverを起動する。", "pitfall": "この区分とSpark Connectのclient/server分離は同じ分類ではない。", "source_url": "https://spark.apache.org/docs/3.5.6/submitting-applications.html"}, {"id": "R27", "domain": "Spark Connect", "prompt": "local[3]を指定した学習用Sparkの実行場所と並列性を説明する。", "answer": "ローカルのprocess上で3worker threadsを使用するlocal mode。3台のworker nodeを要求する設定ではない。", "pitfall": "角括弧内はworker node数ではない。", "source_url": "https://spark.apache.org/docs/3.5.6/submitting-applications.html"}, {"id": "R28", "domain": "Spark Connect", "prompt": "Spark 3.5 Connectへの移行で、df.rddやspark.sparkContextを使うコードはそのまま使えるか。", "answer": "そのまま使えるとは限らない。ConnectではRDD/SparkContext依存を避け、対応するDataFrame APIへ書き換える。", "pitfall": "同じSparkSession風の操作感でも全API互換ではない。", "source_url": "https://spark.apache.org/docs/3.5.6/spark-connect-overview.html"}, {"id": "R29", "domain": "Pandas API", "prompt": "pandas.DataFrameとpyspark.pandas.DataFrameのデータ処理の場所の違いを説明する。", "answer": "通常pandasはローカルprocess中心。pandas API on SparkはSpark上で分散処理するpandasに似たAPI。", "pitfall": "APIが似ていてもコストや全挙動が同じではない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/user_guide/pandas_on_spark/index.html"}, {"id": "R30", "domain": "Pandas API", "prompt": "pandas-on-Sparkの大きいDataFrameにto_pandas()を呼ぶときの主要リスクは。", "answer": "全結果をローカルのpandasへ集めるためdriver側メモリに収まらない可能性がある。", "pitfall": "元データが分散されていることは変換後のメモリ安全性を保証しない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.pandas/api/pyspark.pandas.DataFrame.to_pandas.html"}, {"id": "R31", "domain": "Pandas API", "prompt": "pandas-on-Spark DataFrame psdfをPySpark DataFrameへ変換するAPIと、indexの扱いの注意点を答える。", "answer": "psdf.to_spark()。indexを列として残したい場合はindex_colを指定するなど、変換仕様を確認する。", "pitfall": "to_pandas()は別の変換。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.pandas/api/pyspark.pandas.DataFrame.to_spark.html"}, {"id": "R32", "domain": "Pandas API", "prompt": "scalar Pandas UDFがpandas.Seriesを受け取りSeriesを返すとき、入力と出力の長さの要件は。", "answer": "各入力batchに対して同じ長さのSeriesを返す。", "pitfall": "group aggregate Pandas UDF等の別形式の要件と混ぜない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.pandas_udf.html"}, {"id": "R33", "domain": "Pandas API", "prompt": "double列xへ0.5を加えるscalar Pandas UDFを、戻り型を明示して定義する。", "answer": "@pandas_udf(\"double\")\ndef add_half(s: pd.Series) -> pd.Series:\n    return s + 0.5\nresult = df.withColumn(\"adjusted\", add_half(\"x\"))", "pitfall": "関数内部はSeries演算。単一Python値用UDFのコードと区別。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.functions.pandas_udf.html"}, {"id": "R34", "domain": "Pandas API", "prompt": "Pandas UDFが速くなり得る理由と、常に組込みSpark関数より速いと言えない理由を答える。", "answer": "Arrowでbatch転送しvectorized計算できる。一方でPythonとの転送などの費用があり、組込み関数はSparkの最適化を受けられる。", "pitfall": "Pandas UDF採用だけで性能向上を保証しない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/user_guide/sql/arrow_pandas.html"}, {"id": "R35", "domain": "Structured Streaming", "prompt": "結果表の新規行、変更行、全体を出力するモード名を順に答える。", "answer": "Append、Update、Complete。使えるmodeはqueryとsinkの組合せで決まる。", "pitfall": "Incremental/Full modeという架空名は使わない。", "source_url": "https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html"}, {"id": "R36", "domain": "Structured Streaming", "prompt": "event_tsに20分のwatermarkを設定するコードを書く。処理時計から20分で必ず消えるという意味か。", "answer": "events.withWatermark(\"event_ts\", \"20 minutes\")。最大観測event time等に基づき進み、単純な壁時計タイマーではない。", "pitfall": "streamが止まるとwatermarkも期待どおり進むとは限らない。", "source_url": "https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html"}, {"id": "R37", "domain": "Structured Streaming", "prompt": "10分のwatermarkを使うと、10分を超えて遅れたイベントはすべて必ず破棄されると一般化できるか。", "answer": "一般にはできない。保証内の遅延データは落とさないという片側保証であり、それより古いデータは処理される場合もされない場合もある。", "pitfall": "特定演算のdrop条件とエンジンの一般的保証を混同しない。", "source_url": "https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html"}, {"id": "R38", "domain": "Structured Streaming", "prompt": "Spark3.5でevent_idの重複をevent_tsのwatermark内で除去するコードを書く。", "answer": "events.withWatermark(\"event_ts\", \"15 minutes\").dropDuplicatesWithinWatermark([\"event_id\"])", "pitfall": "時間列を第2引数に渡さない。適切な遅延閾値を選ぶ。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.dropDuplicatesWithinWatermark.html"}, {"id": "R39", "domain": "Structured Streaming", "prompt": "foreachBatchで外部DBへ書くとき、checkpointだけで任意の副作用のexactly-onceが保証されるか。", "answer": "保証されない。batchが再実行され得るため、batchIdでの重複防止や冪等な書き込みを設計する。", "pitfall": "source・engine・sink全体の条件を確認する。", "source_url": "https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html"}, {"id": "R40", "domain": "Structured Streaming", "prompt": "event-timeの10分窓を2分ずつずらし、countしたい。Window指定を書く。", "answer": "events.groupBy(window(col(\"event_ts\"), \"10 minutes\", \"2 minutes\")).count()", "pitfall": "triggerの間隔とwindowの長さ・slideは別。", "source_url": "https://spark.apache.org/docs/3.5.6/structured-streaming-programming-guide.html"}, {"id": "R41", "domain": "Spark SQL", "prompt": "JDBC URL、table、properties辞書で読む式を書く。propertiesを第3位置引数に置けるか。", "answer": "spark.read.jdbc(url, table, properties=properties)。第3位置引数はcolumnなので辞書を置かない。", "pitfall": "必須引数だけ見て位置を推測しない。", "source_url": "https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrameReader.jdbc.html"}, {"id": "R42", "domain": "Spark SQL", "prompt": "save modeのappend、overwrite、ignore、errorifexistsを既存出力がある場合の挙動で区別する。", "answer": "appendは追加、overwriteは上書き、ignoreは処理を行わず既存出力を保つ、errorifexistsは失敗する。", "pitfall": "modeはWriterの設定。Reader.loadと混ぜない。", "source_url": "https://spark.apache.org/docs/3.5.6/sql-data-sources.html"}], "m4_revision": "2026-10-17"};
